	private void OnNewGameCreated(CampaignGameStarter starter)
	{
		ResetRuntimeForLoadedSave("new_game_created");
	}

	private void OnGameLoaded(CampaignGameStarter starter)
	{
		ResetRuntimeForLoadedSave("game_loaded");
	}

	private void ResetRuntimeForLoadedSave(string reason)
	{
		try
		{
			SaveRuntimeGuard.AdvanceGeneration(reason);
			ResetLocalTransientRuntimeForLoadedSave(reason);
			ShoutBehavior.ResetTransientRuntimeForLoadedSaveExternal(reason);
			CourierDeliveryBehavior.ResetTransientRuntimeForLoadedSaveExternal(reason);
			AIConfigHandler.ClearLatestAuxiliaryMentionedEntitiesForExternal();
		}
		catch (Exception ex)
		{
			Logger.Log("SaveRuntimeGuard", "[WARN] reset runtime failed reason=" + (reason ?? "") + " error=" + ex.Message);
		}
	}

	private void ResetLocalTransientRuntimeForLoadedSave(string reason)
	{
		try
		{
			List<PendingWeeklyReportCommitContext> abandonedWeeklyReportCommits;
			ClearRuleStickyCarry();
			_playerDefeatedHeroBattleFactKeys.Clear();
			_memorySummaryProcessing = false;
			_memorySummaryFailurePopupActive = false;
			_lastMemoryMaintenanceObservedGameDay = -1;
			_nativeConversationMemorySessionCounter = 0;
			_activeNativeConversationMemorySessionId = -1;
			_pendingWeeklyMemoryMaterialTriggers.Clear();
			_pendingAutoWeeklyReportBuild = null;
			_weeklyReportGenerationInProgress = false;
			_pendingAutoWeeklyReportWeek = 0;
			ResetPendingWeeklyKingdomRebellionMaintenance();
			lock (_pendingWeeklyReportCommitLock)
			{
				abandonedWeeklyReportCommits = _pendingWeeklyReportCommits.ToList();
				_pendingWeeklyReportCommits.Clear();
				Volatile.Write(ref _hasPendingWeeklyReportCommits, 0);
			}
			foreach (PendingWeeklyReportCommitContext context in abandonedWeeklyReportCommits)
			{
				CompletePendingWeeklyReportCommit(context, new WeeklyReportGenerationResult());
			}
			_dailyMaintenanceQueue.Clear();
			_dailyMaintenanceJobKeys.Clear();
			ResetDailyMemoryDraftSealSliceState();
			_destroyedPartyMemoryCleanupDedup.Clear();
			_dirtyMemoryOverviewIds.Clear();
			_pendingMemoryOverviewCandidateScanIds.Clear();
			_pendingMemoryOverviewCandidateScanIdSet.Clear();
			lock (_npcPersonaAutoGenLock)
			{
				_npcPersonaAutoGenInFlight.Clear();
				_npcPersonaAutoGenRetryAfterUtcTicks.Clear();
			}
			Logger.Log("SaveRuntimeGuard", "local_transient_cleared reason=" + (reason ?? ""));
		}
		catch (Exception ex)
		{
			Logger.Log("SaveRuntimeGuard", "[WARN] local transient clear failed: " + ex.Message);
		}
	}

	private void OnHeroComesOfAge(Hero hero)
	{
		try
		{
			if (!ShouldAutoGeneratePersonaForAdultHero(hero))
			{
				return;
			}
			Logger.Log("NpcPersona", "Adult hero persona auto-generation queued hero=" + (hero.StringId ?? "") + " name=" + (hero.Name?.ToString() ?? ""));
			_ = EnsureNpcPersonaGeneratedAsync(hero);
		}
		catch (Exception ex)
		{
			Logger.Log("NpcPersona", "[WARN] Adult hero persona auto-generation queue failed: " + ex.Message);
		}
	}

	private bool ShouldAutoGeneratePersonaForAdultHero(Hero hero)
	{
		if (hero == null || hero == Hero.MainHero || string.IsNullOrWhiteSpace(hero.StringId))
		{
			return false;
		}
		DuelSettings settings = DuelSettings.GetSettings();
		if (settings != null && !settings.EnableAdultHeroPersonaAutoGeneration)
		{
			return false;
		}
		try
		{
			if (!hero.IsAlive || hero.IsChild)
			{
				return false;
			}
		}
		catch
		{
			return false;
		}
		return NeedsNpcPersonaGeneration(hero) && !IsNpcPersonaGenerationInFlight(hero);
	}

	private void OnMapEventEnded(MapEvent mapEvent)
	{
		try
		{
			if (mapEvent != null && mapEvent.IsPlayerMapEvent && mapEvent.HasWinner && mapEvent.WinningSide == mapEvent.PlayerSide)
			{
				MapEventSide mapEventSide = ((mapEvent.PlayerSide == BattleSideEnum.Attacker) ? mapEvent.DefenderSide : mapEvent.AttackerSide);
				foreach (MapEventParty party in mapEventSide.Parties)
				{
					Hero hero = party.Party?.LeaderHero;
					if (hero != null && hero != Hero.MainHero && hero.IsLord)
					{
						RecordPlayerDefeatedHeroBattleFact(mapEvent, mapEventSide, hero, "map_event_ended");
					}
				}
			}
		}
		catch (Exception ex)
		{
			Logger.Log("BattleStatus", "[ERROR] OnMapEventEnded: " + ex.Message);
		}
		try
		{
			RecordPlayerBattleDefeatRecentAction(mapEvent);
		}
		catch (Exception ex2)
		{
			Logger.Log("NpcAction", "[ERROR] RecordPlayerBattleDefeatRecentAction: " + ex2.Message);
		}
		try
		{
			TrackNpcActionsFromMapEvent(mapEvent);
		}
		catch (Exception ex3)
		{
			Logger.Log("NpcAction", "[ERROR] TrackNpcActionsFromMapEvent: " + ex3.Message);
		}
		try
		{
			RecordPlayerRoutineBanditDefeatRecentAction(mapEvent);
		}
		catch (Exception ex4)
		{
			Logger.Log("NpcAction", "[ERROR] RecordPlayerRoutineBanditDefeatRecentAction: " + ex4.Message);
		}
		try
		{
			RecordPlayerHideoutClearRecentAction(mapEvent);
		}
		catch (Exception ex5)
		{
			Logger.Log("NpcAction", "[ERROR] RecordPlayerHideoutClearRecentAction: " + ex5.Message);
		}
	}

	private void OnPlayerBattleEndForDefeatMemory(MapEvent mapEvent)
	{
		try
		{
			if (mapEvent == null || !mapEvent.IsPlayerMapEvent || !mapEvent.HasWinner || mapEvent.WinningSide != mapEvent.PlayerSide)
			{
				return;
			}
			MapEventSide defeatedSide = GetMapEventDefeatedSide(mapEvent);
			if (defeatedSide?.Parties == null)
			{
				return;
			}
			foreach (MapEventParty party in defeatedSide.Parties)
			{
				Hero hero = party?.Party?.LeaderHero;
				if (hero != null && hero != Hero.MainHero && hero.IsLord)
				{
					RecordPlayerDefeatedHeroBattleFact(mapEvent, defeatedSide, hero, "player_battle_end");
				}
			}
		}
		catch (Exception ex)
		{
			Logger.Log("BattleStatus", "[ERROR] OnPlayerBattleEndForDefeatMemory: " + ex.Message);
		}
	}

	private void RecordPlayerDefeatedHeroBattleFact(MapEvent mapEvent, MapEventSide defeatedSide, Hero defeatedHero, string reason)
	{
		if (mapEvent == null || defeatedHero == null || defeatedHero == Hero.MainHero || string.IsNullOrWhiteSpace(defeatedHero.StringId) || !mapEvent.IsPlayerMapEvent || !mapEvent.HasWinner || mapEvent.WinningSide != mapEvent.PlayerSide)
		{
			return;
		}
		defeatedSide ??= GetMapEventDefeatedSide(mapEvent);
		if (defeatedSide == null)
		{
			return;
		}
		string locationLabel = GetMapEventLocationLabel(mapEvent);
		string stableKey = BuildPlayerDefeatedHeroBattleFactKey(mapEvent, defeatedSide, defeatedHero, locationLabel);
		if (!_playerDefeatedHeroBattleFactKeys.Add(stableKey))
		{
			return;
		}
		_recentlyDefeatedByPlayer.Add(defeatedHero.StringId);
		Logger.Log("BattleStatus", "玩家击败领主事实写入 reason=" + (reason ?? "") + " hero=" + defeatedHero.StringId + " name=" + (defeatedHero.Name?.ToString() ?? ""));
		AppendExternalDialogueHistory(defeatedHero, null, null, BuildPlayerDefeatedHeroDialogueFact(mapEvent, defeatedSide, locationLabel));
		RecordNpcDefeatedByPlayerRecentAction(mapEvent, defeatedSide, defeatedHero);
	}

