	private void OnKingdomDecisionConcluded(KingdomDecision decision, DecisionOutcome chosenOutcome, bool isPlayerInvolved)
	{
		try
		{
			if (decision == null)
			{
				return;
			}
			if (VoteDealBehavior.IsBilateralDiplomacyMemoryHandledDecision(decision))
			{
				Logger.Log("NpcAction", "Skipped generic kingdom decision memory because bilateral diplomacy state was recorded explicitly: " + (decision.GetGeneralTitle()?.ToString() ?? decision.GetType().Name));
				return;
			}
			string text = BuildKingdomDecisionStableKey(decision);
			string text2 = BuildKingdomDecisionNarrative(decision, chosenOutcome, isPlayerInvolved, forProposer: true);
			Hero leader = decision.ProposerClan?.Leader;
			if (ShouldTrackNpcActionHero(leader))
			{
				NpcActionFacts npcActionFacts = CreateNpcActionFacts("kingdom_decision_concluded", leader);
				AddUniqueId(npcActionFacts.RelatedClanIds, GetClanId(decision.ProposerClan));
				AddUniqueId(npcActionFacts.RelatedKingdomIds, GetKingdomId(decision.Kingdom));
				ApplyKingdomDecisionSpecificFacts(npcActionFacts, decision, chosenOutcome);
				RecordNpcMajorAction(leader, text2, text + ":proposer", npcActionFacts);
				RecordNpcRecentAction(leader, text2, text + ":proposer", facts: npcActionFacts);
			}
			Hero leader2 = decision.DetermineChooser()?.Leader;
			if (ShouldTrackNpcActionHero(leader2) && !string.Equals(GetHeroId(leader2), GetHeroId(leader), StringComparison.OrdinalIgnoreCase))
			{
				NpcActionFacts npcActionFacts2 = CreateNpcActionFacts("kingdom_decision_concluded", leader2);
				AddUniqueId(npcActionFacts2.RelatedClanIds, GetClanId(decision.ProposerClan));
				AddUniqueId(npcActionFacts2.RelatedKingdomIds, GetKingdomId(decision.Kingdom));
				ApplyKingdomDecisionSpecificFacts(npcActionFacts2, decision, chosenOutcome);
				string text3 = BuildKingdomDecisionNarrative(decision, chosenOutcome, isPlayerInvolved, forProposer: false);
				RecordNpcMajorAction(leader2, text3, text + ":chooser", npcActionFacts2);
				RecordNpcRecentAction(leader2, text3, text + ":chooser", facts: npcActionFacts2);
			}
			string text4 = BuildKingdomDecisionSupporterSummary(decision, chosenOutcome);
			string text5 = BuildKingdomDecisionPoliticalTriggerReason(decision, chosenOutcome);
			text4 = AppendEventMaterialSentence(text4, text5);
			if (!string.IsNullOrWhiteSpace(text4))
			{
				string kingdomId = GetKingdomId(decision.Kingdom);
				string labelPrefix = string.IsNullOrWhiteSpace(text5) ? "决议支持明细" : "决议支持与触发原因";
				RecordEventSourceMaterial("kingdom_decision_support", labelPrefix + " - " + GetKingdomDisplayName(decision.Kingdom, "该王国"), text4, text + ":supporters", kingdomId, "", includeInWorld: false, includeInKingdom: true);
			}
			if (isPlayerInvolved)
			{
				Hero targetHero = ResolveKingdomDecisionActionTargetHero(decision, chosenOutcome);
				string playerText = BuildPlayerKingdomDecisionActionText(decision, chosenOutcome);
				RecordExternalPlayerAction(playerText, text + ":player", "kingdom_decision_player_involved", isMajor: true, targetHero: targetHero, settlement: null, locationText: GetKingdomDisplayName(decision.Kingdom, ""), won: null);
			}
		}
		catch (Exception ex)
		{
			Logger.Log("NpcAction", "[ERROR] OnKingdomDecisionConcluded: " + ex.Message);
		}
	}

	private void OnRulingClanChanged(Kingdom kingdom, Clan eventRulingClan)
	{
		try
		{
			// Bannerlord 1.3 passes the new ruling clan here, while 1.4.5 passes the old one.
			// Always read the post-change value from the kingdom so the behavior stays version-neutral.
			Clan rulingClan = kingdom?.RulingClan;
			TrySyncModCreatedRebelKingdomBannerToRulingClan(kingdom, eventRulingClan, "ruling_clan_changed");
			string text = "ruling_clan_changed:" + GetKingdomId(kingdom) + ":" + GetClanId(rulingClan);
			string text2 = "你所在的" + GetClanDisplayName(rulingClan) + "家族已成为" + GetKingdomDisplayName(kingdom, "该王国") + "的执政家族。";
			foreach (Hero item in GetTrackedLordsForClan(rulingClan))
			{
				NpcActionFacts npcActionFacts = CreateNpcActionFacts("ruling_clan_changed", item);
				AddUniqueId(npcActionFacts.RelatedClanIds, GetClanId(rulingClan));
				AddUniqueId(npcActionFacts.RelatedKingdomIds, GetKingdomId(kingdom));
				RecordNpcMajorAction(item, text2, text, npcActionFacts);
				RecordNpcRecentAction(item, text2, text, facts: npcActionFacts);
			}
		}
		catch (Exception ex)
		{
			Logger.Log("NpcAction", "[ERROR] OnRulingClanChanged: " + ex.Message);
		}
	}

	private void OnSettlementOwnerChanged(Settlement settlement, bool openToClaim, Hero newOwner, Hero oldOwner, Hero capturerHero, ChangeOwnerOfSettlementAction.ChangeOwnerOfSettlementDetail detail)
	{
		try
		{
			Kingdom oldOwnerKingdom = oldOwner?.Clan?.Kingdom;
			string text = BuildSettlementOwnerChangedStableKey(settlement, newOwner, oldOwner, detail);
			string text2 = GetSettlementDisplayName(settlement);
			if (ShouldTrackNpcActionHero(newOwner))
			{
				NpcActionFacts npcActionFacts = CreateNpcActionFacts("settlement_owner_changed_gain", newOwner);
				ApplyTargetFacts(npcActionFacts, oldOwner);
				ApplySettlementFacts(npcActionFacts, settlement, newOwner, oldOwner);
				RecordNpcMajorAction(newOwner, "你获得了" + text2 + "的所有权（方式：" + GetSettlementOwnerChangeDetailLabel(detail) + "）。", text + ":gain", npcActionFacts);
				RecordNpcRecentAction(newOwner, "你获得了" + text2 + "的所有权（方式：" + GetSettlementOwnerChangeDetailLabel(detail) + "）。", text + ":gain", facts: npcActionFacts);
			}
			if (ShouldTrackNpcActionHero(oldOwner))
			{
				NpcActionFacts npcActionFacts2 = CreateNpcActionFacts("settlement_owner_changed_loss", oldOwner);
				ApplyTargetFacts(npcActionFacts2, newOwner);
				ApplySettlementFacts(npcActionFacts2, settlement, newOwner, oldOwner);
				RecordNpcMajorAction(oldOwner, "你失去了" + text2 + "的所有权（方式：" + GetSettlementOwnerChangeDetailLabel(detail) + "）。", text + ":loss", npcActionFacts2);
				RecordNpcRecentAction(oldOwner, "你失去了" + text2 + "的所有权（方式：" + GetSettlementOwnerChangeDetailLabel(detail) + "）。", text + ":loss", facts: npcActionFacts2);
			}
			if (ShouldTrackNpcActionHero(capturerHero) && !string.Equals(GetHeroId(capturerHero), GetHeroId(newOwner), StringComparison.OrdinalIgnoreCase))
			{
				NpcActionFacts npcActionFacts3 = CreateNpcActionFacts("settlement_owner_changed_capture", capturerHero);
				ApplyTargetFacts(npcActionFacts3, newOwner);
				ApplySettlementFacts(npcActionFacts3, settlement, newOwner, oldOwner);
				RecordNpcMajorAction(capturerHero, "你促成了" + text2 + "的易主，新的所有者是" + GetHeroDisplayName(newOwner) + "。", text + ":capture", npcActionFacts3);
				RecordNpcRecentAction(capturerHero, "你促成了" + text2 + "的易主，新的所有者是" + GetHeroDisplayName(newOwner) + "。", text + ":capture", facts: npcActionFacts3);
			}
			TryDiscontinueLandlessModRebelKingdom(oldOwnerKingdom, "settlement_owner_changed:" + GetSettlementId(settlement));
		}
		catch (Exception ex)
		{
			Logger.Log("NpcAction", "[ERROR] OnSettlementOwnerChanged: " + ex.Message);
		}
	}

	private void OnHeroKilled(Hero victim, Hero killer, KillCharacterAction.KillCharacterActionDetail detail, bool showNotification)
	{
		try
		{
			if (victim == null)
			{
				return;
			}
			string text = "hero_killed:" + GetHeroId(victim) + ":" + detail;
			if (ShouldTrackNpcActionHero(killer))
			{
				NpcActionFacts npcActionFacts = CreateNpcActionFacts("hero_killed", killer);
				ApplyTargetFacts(npcActionFacts, victim);
				RecordNpcMajorAction(killer, "你" + GetHeroKilledVerb(detail) + GetHeroDisplayName(victim) + "。", text + ":killer", npcActionFacts);
				RecordNpcRecentAction(killer, "你" + GetHeroKilledVerb(detail) + GetHeroDisplayName(victim) + "。", text + ":killer", facts: npcActionFacts);
			}
			if (IsExecutionKillDetail(detail))
			{
				RecordExecutedVictimAction(victim, killer, detail, text);
				RecordPlayerExecutionWeeklyMaterial(victim, killer, detail, text);
			}
			Hero leader = victim.Clan?.Leader;
			if (ShouldTrackNpcActionHero(leader) && !string.Equals(GetHeroId(leader), GetHeroId(victim), StringComparison.OrdinalIgnoreCase))
			{
				NpcActionFacts npcActionFacts2 = CreateNpcActionFacts("clan_member_killed", leader);
				ApplyTargetFacts(npcActionFacts2, victim);
				if (killer != null)
				{
					AddUniqueId(npcActionFacts2.RelatedHeroIds, GetHeroId(killer));
					AddUniqueId(npcActionFacts2.RelatedClanIds, GetClanId(killer.Clan));
					AddUniqueId(npcActionFacts2.RelatedKingdomIds, GetKingdomId(killer.MapFaction));
				}
				string text2 = "你所在的" + GetClanDisplayName(victim.Clan) + "家族失去了" + GetHeroDisplayName(victim) + "。";
				RecordNpcMajorAction(leader, text2, text + ":clan", npcActionFacts2);
				RecordNpcRecentAction(leader, text2, text + ":clan", facts: npcActionFacts2);
			}
			// Death/removal can leave persisted daily jobs behind. Keep raw history and weekly material,
			// but cancel deferred LLM work before it can issue another request for this Hero.
			CancelUnavailableHeroCompressionWorkById(GetMemoryHeroId(victim), "hero_killed");
		}
		catch (Exception ex)
		{
			Logger.Log("NpcAction", "[ERROR] OnHeroKilled: " + ex.Message);
		}
	}

	private void RecordExecutedVictimAction(Hero victim, Hero killer, KillCharacterAction.KillCharacterActionDetail detail, string stablePrefix)
	{
		if (victim == null || !ShouldTrackNpcActionHero(victim, allowNonLordHero: true))
		{
			return;
		}
		NpcActionFacts facts = CreateNpcActionFacts("hero_executed_victim", victim);
		ApplyTargetFacts(facts, killer);
		Settlement settlement = ResolveHeroExecutionSettlement(victim, killer);
		string locationText = ResolveHeroExecutionLocationText(settlement, victim, killer);
		if (settlement != null)
		{
			ApplySettlementFacts(facts, settlement, locationText: locationText);
			AddRelatedFactionFacts(facts, settlement.MapFaction);
		}
		else
		{
			facts.LocationText = locationText;
		}
		facts.Won = false;
		string text = BuildExecutedVictimActionText(killer, detail);
		string key = (string.IsNullOrWhiteSpace(stablePrefix) ? ("hero_killed:" + GetHeroId(victim) + ":" + detail) : stablePrefix.Trim()) + ":victim";
		RecordNpcMajorAction(victim, text, key, facts, allowNonLordHero: true);
		RecordNpcRecentAction(victim, text, key, dedupeAcrossWindow: true, facts, allowNonLordHero: true);
	}

	private void RecordPlayerExecutionWeeklyMaterial(Hero victim, Hero killer, KillCharacterAction.KillCharacterActionDetail detail, string stablePrefix)
	{
		Hero player = Hero.MainHero;
		if (player == null || (victim != player && killer != player))
		{
			return;
		}
		int day = GetCurrentGameDayIndexSafe();
		string gameDate = GetCurrentGameDateTextSafe();
		Settlement settlement = ResolveHeroExecutionSettlement(victim, killer);
		string settlementId = GetSettlementId(settlement);
		string locationText = ResolveHeroExecutionLocationText(settlement, victim, killer);
		Kingdom victimKingdom = ResolveHeroKingdomForWeeklyMaterial(victim);
		Kingdom killerKingdom = ResolveHeroKingdomForWeeklyMaterial(killer);
		string victimKingdomId = GetKingdomId(victimKingdom);
		string killerKingdomId = GetKingdomId(killerKingdom);
		string primaryKingdomId = !string.IsNullOrWhiteSpace(victimKingdomId) ? victimKingdomId : killerKingdomId;
		if (string.IsNullOrWhiteSpace(primaryKingdomId))
		{
			Logger.Log("EventWeeklyReport", "[PlayerExecution][SKIP] kingdom_missing victim=" + GetHeroId(victim) + " killer=" + GetHeroId(killer));
			return;
		}
		string snapshot = BuildPlayerExecutionWeeklySnapshot(victim, killer, detail, victimKingdom, killerKingdom, locationText, gameDate);
		if (string.IsNullOrWhiteSpace(snapshot))
		{
			return;
		}
		string baseKey = "player_execution:" + NormalizeNpcActionStableKey(stablePrefix, GetHeroId(victim) + ":" + GetHeroId(killer) + ":" + detail);
		string label = victim == player ? "玩家被处决 - " + GetHeroDisplayName(killer) : "玩家处决英雄 - " + GetHeroDisplayName(victim);
		RecordEventSourceMaterial(
			"player_execution",
			label,
			snapshot,
			baseKey + ":victim_kingdom",
			primaryKingdomId,
			settlementId,
			includeInWorld: true,
			includeInKingdom: true,
			actorHeroId: GetHeroId(killer),
			actorKingdomId: killerKingdomId,
			dayOverride: day,
			gameDateOverride: gameDate);
		if (!string.IsNullOrWhiteSpace(killerKingdomId) && !string.Equals(killerKingdomId, primaryKingdomId, StringComparison.OrdinalIgnoreCase))
		{
			RecordEventSourceMaterial(
				"player_execution",
				label,
				snapshot,
				baseKey + ":killer_kingdom",
				killerKingdomId,
				settlementId,
				includeInWorld: false,
				includeInKingdom: true,
				actorHeroId: GetHeroId(killer),
				actorKingdomId: killerKingdomId,
				dayOverride: day,
				gameDateOverride: gameDate);
		}
		Logger.Log("EventWeeklyReport", "[PlayerExecution] source_material_recorded day=" + day + " victim=" + GetHeroId(victim) + " killer=" + GetHeroId(killer) + " kingdom=" + primaryKingdomId + " key=" + baseKey);
	}

