	private static bool IsDialogueOrLetterChainBusyForMemorySummary()
	{
		try
		{
			if (Campaign.Current?.ConversationManager?.IsConversationInProgress == true)
			{
				return true;
			}
		}
		catch
		{
		}
		return false;
	}

	private static bool IsNonSceneNativeConversationActiveForMemory()
	{
		try
		{
			if (Campaign.Current?.ConversationManager?.IsConversationInProgress != true)
			{
				return false;
			}
			try
			{
				if (Mission.Current?.Scene != null && ShoutUtils.IsInValidScene())
				{
					return false;
				}
			}
			catch
			{
			}
			return true;
		}
		catch
		{
			return false;
		}
	}

	private int GetOrStartActiveNativeConversationMemorySessionId()
	{
		if (!IsNonSceneNativeConversationActiveForMemory())
		{
			_activeNativeConversationMemorySessionId = -1;
			return -1;
		}
		if (_activeNativeConversationMemorySessionId < 0)
		{
			_nativeConversationMemorySessionCounter++;
			if (_nativeConversationMemorySessionCounter <= 0)
			{
				_nativeConversationMemorySessionCounter = 1;
			}
			_activeNativeConversationMemorySessionId = _nativeConversationMemorySessionCounter;
		}
		return _activeNativeConversationMemorySessionId;
	}

	private int GetCurrentNativeConversationMemorySessionIdForSuppression()
	{
		if (!IsNonSceneNativeConversationActiveForMemory())
		{
			_activeNativeConversationMemorySessionId = -1;
			return -1;
		}
		return GetOrStartActiveNativeConversationMemorySessionId();
	}

	private string BuildCurrentMemorySessionKey(int sceneSessionId, int dialogueSessionId)
	{
		string runtimeKey = (_memoryRuntimeSessionKey ?? "").Trim();
		if (string.IsNullOrWhiteSpace(runtimeKey))
		{
			runtimeKey = Guid.NewGuid().ToString("N");
			_memoryRuntimeSessionKey = runtimeKey;
		}
		if (sceneSessionId >= 0)
		{
			return runtimeKey + ":scene:" + sceneSessionId;
		}
		if (dialogueSessionId >= 0)
		{
			return runtimeKey + ":dialogue:" + dialogueSessionId;
		}
		return runtimeKey + ":loose";
	}

	private void OnMemoryConversationEnded(IEnumerable<CharacterObject> characters)
	{
		PlayerNotorietyBehavior.FinalizeConversationForExternal(characters);
		_activeNativeConversationMemorySessionId = -1;
	}

	private void TryEnqueueMajorActionSummaryForDraft(DailyMemoryDraft draft, HashSet<string> queuedMajorHeroIds, bool ownerAlreadyEligible = false)
	{
		try
		{
			if (draft == null || !draft.HasLlmDialogue)
			{
				return;
			}
			string heroId = NormalizeMemoryHeroId(draft.HeroId);
			if (string.IsNullOrWhiteSpace(heroId) || IsNonHeroMemoryId(heroId) || (!ownerAlreadyEligible && !IsMemoryEntityEligibleForCompressedMemory(heroId)) || _npcMajorActions == null || !_npcMajorActions.TryGetValue(heroId, out var actions) || actions == null)
			{
				// Major-action summaries belong to Heroes only; callers may reuse an owner-level eligibility check for a slice.
				return;
			}
			List<NpcActionEntry> sanitizedActions = SanitizeNpcActionEntries(actions, keepOnlyRecentWindow: false);
			if (sanitizedActions.Count <= 0 || !HasMajorActionsNeedingSummary(heroId, sanitizedActions))
			{
				return;
			}
			if (_npcMajorActionSummaryQueue == null)
			{
				_npcMajorActionSummaryQueue = new List<MajorActionSummaryJob>();
			}
			MajorActionSummaryJob existing = _npcMajorActionSummaryQueue.FirstOrDefault((MajorActionSummaryJob x) => x != null && string.Equals(NormalizeMemoryHeroId(x.HeroId), heroId, StringComparison.OrdinalIgnoreCase));
			if (existing != null)
			{
				existing.TriggerGameDayIndex = Math.Max(existing.TriggerGameDayIndex, draft.GameDayIndex);
				if (string.IsNullOrWhiteSpace(existing.TriggerGameDate))
				{
					existing.TriggerGameDate = (draft.GameDate ?? "").Trim();
				}
				queuedMajorHeroIds?.Add(heroId);
				return;
			}
			if (queuedMajorHeroIds != null && !queuedMajorHeroIds.Add(heroId))
			{
				return;
			}
			_npcMajorActionSummaryQueue.Add(new MajorActionSummaryJob
			{
				HeroId = heroId,
				HeroName = (draft.HeroName ?? "").Trim(),
				TriggerGameDayIndex = draft.GameDayIndex,
				TriggerGameDate = (draft.GameDate ?? "").Trim()
			});
		}
		catch (Exception ex)
		{
			Logger.Log("NpcMajorSummary", "[ERROR] TryEnqueueMajorActionSummaryForDraft failed: " + ex.Message);
		}
	}

	private void TryEnqueueMemoryOverviewForHero(Hero hero, List<CompressedMemoryBlock> blocks = null)
	{
		try
		{
			if (!IsHeroNpcEligibleForCompressedMemory(hero))
			{
				return;
			}
			string heroId = GetMemoryHeroId(hero);
			if (string.IsNullOrWhiteSpace(heroId))
			{
				return;
			}
			TryEnqueueMemoryOverviewForMemoryId(heroId, hero.Name?.ToString() ?? "NPC", blocks ?? LoadCompressedMemoryBlocks(hero));
		}
		catch (Exception ex)
		{
			Logger.Log("MemoryOverview", "[ERROR] TryEnqueueMemoryOverviewForHero failed: " + ex.Message);
		}
	}

	private void TryEnqueueMemoryOverviewForMemoryId(string memoryId, string memoryName, List<CompressedMemoryBlock> blocks = null)
	{
		try
		{
			string heroId = NormalizeMemoryHeroId(memoryId);
			if (!IsMemoryEntityEligibleForCompressedMemory(heroId))
			{
				return;
			}
			List<CompressedMemoryBlock> sanitizedBlocks = SanitizeCompressedMemoryBlocks(blocks ?? LoadCompressedMemoryBlocksById(heroId));
			if (!HasMemoryOverviewPendingBlocks(heroId, sanitizedBlocks))
			{
				return;
			}
			if (_memoryOverviewQueue == null)
			{
				_memoryOverviewQueue = new List<MemoryOverviewJob>();
			}
			MemoryOverviewJob existing = _memoryOverviewQueue.FirstOrDefault((MemoryOverviewJob x) => x != null && string.Equals(NormalizeMemoryHeroId(x.HeroId), heroId, StringComparison.OrdinalIgnoreCase));
			CompressedMemoryBlock latestBlock = sanitizedBlocks.OrderByDescending((CompressedMemoryBlock x) => x.GameDayIndex).ThenByDescending((CompressedMemoryBlock x) => x.EndHour).FirstOrDefault();
			string heroName = (memoryName ?? latestBlock?.HeroName ?? "NPC").Trim();
			if (string.IsNullOrWhiteSpace(heroName))
			{
				heroName = "NPC";
			}
			if (existing != null)
			{
				existing.HeroName = string.IsNullOrWhiteSpace(existing.HeroName) ? heroName : existing.HeroName;
				existing.TriggerGameDayIndex = Math.Max(existing.TriggerGameDayIndex, latestBlock?.GameDayIndex ?? 0);
				if (string.IsNullOrWhiteSpace(existing.TriggerGameDate))
				{
					existing.TriggerGameDate = (latestBlock?.GameDate ?? "").Trim();
				}
				return;
			}
			_memoryOverviewQueue.Add(new MemoryOverviewJob
			{
				HeroId = heroId,
				HeroName = heroName,
				TriggerGameDayIndex = latestBlock?.GameDayIndex ?? 0,
				TriggerGameDate = (latestBlock?.GameDate ?? "").Trim()
			});
			_memoryOverviewQueue = SanitizeMemoryOverviewQueue(_memoryOverviewQueue);
		}
		catch (Exception ex)
		{
			Logger.Log("MemoryOverview", "[ERROR] TryEnqueueMemoryOverviewForMemoryId failed: " + ex.Message);
		}
	}

	private void TryEnqueueMemoryOverviewForAllCandidates()
	{
		using (PerfProbe.Scope("MyBehavior.TryEnqueueMemoryOverviewForAllCandidates"))
		{
		try
		{
			if (_compressedMemoryBlocks == null || _compressedMemoryBlocks.Count <= 0)
			{
				return;
			}
			foreach (KeyValuePair<string, List<CompressedMemoryBlock>> item in _compressedMemoryBlocks.ToList())
			{
				string heroId = NormalizeMemoryHeroId(item.Key);
				if (string.IsNullOrWhiteSpace(heroId))
				{
					continue;
				}
				string heroName = (item.Value ?? new List<CompressedMemoryBlock>()).Select((CompressedMemoryBlock x) => x?.HeroName).FirstOrDefault((string x) => !string.IsNullOrWhiteSpace(x)) ?? "NPC";
				TryEnqueueMemoryOverviewForMemoryId(heroId, heroName, item.Value);
			}
			_memoryOverviewQueue = SanitizeMemoryOverviewQueue(_memoryOverviewQueue);
		}
		catch (Exception ex)
		{
			Logger.Log("MemoryOverview", "[ERROR] TryEnqueueMemoryOverviewForAllCandidates failed: " + ex.Message);
		}
		}
	}

	private void MarkMemoryOverviewDirty(string memoryId)
	{
		try
		{
			string text = NormalizeMemoryHeroId(memoryId);
			if (!IsMemoryEntityEligibleForCompressedMemory(text))
			{
				return;
			}
			_dirtyMemoryOverviewIds.Add(text);
		}
		catch
		{
		}
	}

	private void EnqueueMemoryOverviewCandidateScanId(string memoryId)
	{
		string text = NormalizeMemoryHeroId(memoryId);
		if (!IsMemoryEntityEligibleForCompressedMemory(text))
		{
			return;
		}
		if (_pendingMemoryOverviewCandidateScanIdSet.Add(text))
		{
			_pendingMemoryOverviewCandidateScanIds.Enqueue(text);
		}
	}

	private void QueueDirtyMemoryOverviewCandidatesForDeferredScan()
	{
		if (_dirtyMemoryOverviewIds.Count <= 0)
		{
			return;
		}
		foreach (string memoryId in _dirtyMemoryOverviewIds.ToList())
		{
			EnqueueMemoryOverviewCandidateScanId(memoryId);
		}
		_dirtyMemoryOverviewIds.Clear();
	}

	private void QueueAllMemoryOverviewCandidatesForDeferredScan()
	{
		if (_compressedMemoryBlocks == null || _compressedMemoryBlocks.Count <= 0)
		{
			return;
		}
		foreach (string memoryId in _compressedMemoryBlocks.Keys.ToList())
		{
			EnqueueMemoryOverviewCandidateScanId(memoryId);
		}
	}

	private int ProcessMemoryOverviewCandidateScanBudget(long startTimestamp, double budgetMs)
	{
		int processed = 0;
		while (_pendingMemoryOverviewCandidateScanIds.Count > 0 && !IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
		{
			string memoryId = _pendingMemoryOverviewCandidateScanIds.Dequeue();
			_pendingMemoryOverviewCandidateScanIdSet.Remove(memoryId);
			string text = NormalizeMemoryHeroId(memoryId);
			if (string.IsNullOrWhiteSpace(text) || _compressedMemoryBlocks == null || !_compressedMemoryBlocks.TryGetValue(text, out var blocks) || blocks == null || blocks.Count <= 0)
			{
				continue;
			}
			string heroName = blocks.Select((CompressedMemoryBlock x) => x?.HeroName).FirstOrDefault((string x) => !string.IsNullOrWhiteSpace(x)) ?? "NPC";
			TryEnqueueMemoryOverviewForMemoryId(text, heroName, blocks);
			processed++;
		}
		return processed;
	}

	private bool TrySealPastDailyMemoryDrafts(long startTimestamp = 0L, double budgetMs = double.MaxValue)
	{
		try
		{
			if (_dailyMemoryDrafts == null || _dailyMemoryDrafts.Count <= 0)
			{
				ResetDailyMemoryDraftSealSliceState();
				return true;
			}
			if (_memorySummaryQueue == null)
			{
				_memorySummaryQueue = new List<MemorySummaryJob>();
			}
			if (_npcMajorActionSummaryQueue == null)
			{
				_npcMajorActionSummaryQueue = new List<MajorActionSummaryJob>();
			}
			if (_dailyMemoryDraftSealOwnerKeys == null)
			{
				_dailyMemoryDraftSealOwnerKeys = _dailyMemoryDrafts.Keys.ToList();
				_dailyMemoryDraftSealOwnerIndex = 0;
				_dailyMemoryDraftSealDraftIndex = -1;
				_dailyMemoryDraftSealTargetDay = (int)CampaignTime.Now.ToDays;
				_dailyMemoryDraftSealQueued = new HashSet<string>(_memorySummaryQueue.Where((MemorySummaryJob x) => x != null).Select((MemorySummaryJob x) => NormalizeMemoryHeroId(x.HeroId) + "|" + x.GameDayIndex), StringComparer.OrdinalIgnoreCase);
				_dailyMemoryDraftSealQueuedMajor = new HashSet<string>(_npcMajorActionSummaryQueue.Where((MajorActionSummaryJob x) => x != null).Select((MajorActionSummaryJob x) => NormalizeMemoryHeroId(x.HeroId)), StringComparer.OrdinalIgnoreCase);
			}
			while (_dailyMemoryDraftSealOwnerIndex < _dailyMemoryDraftSealOwnerKeys.Count)
			{
				if (IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
				{
					return false;
				}
				string ownerKey = _dailyMemoryDraftSealOwnerKeys[_dailyMemoryDraftSealOwnerIndex];
				if (!_dailyMemoryDrafts.TryGetValue(ownerKey, out var list) || list == null)
				{
					_dailyMemoryDraftSealOwnerIndex++;
					_dailyMemoryDraftSealDraftIndex = -1;
					continue;
				}
				string ownerMemoryId = NormalizeMemoryHeroId(ownerKey);
				if (!IsMemoryEntityEligibleForCompressedMemory(ownerMemoryId))
				{
					// Cancel orphaned work, while preserving source drafts because they can carry weekly-report trigger facts.
					CancelUnavailableHeroCompressionWorkById(ownerMemoryId, "seal_past_daily_drafts");
					_dailyMemoryDraftSealOwnerIndex++;
					_dailyMemoryDraftSealDraftIndex = -1;
					continue;
				}
				if (_dailyMemoryDraftSealDraftIndex < 0)
				{
					_dailyMemoryDraftSealDraftIndex = list.Count - 1;
				}
				while (_dailyMemoryDraftSealDraftIndex >= 0)
				{
					if (IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
					{
						return false;
					}
					int draftIndex = Math.Min(_dailyMemoryDraftSealDraftIndex, list.Count - 1);
					_dailyMemoryDraftSealDraftIndex = draftIndex - 1;
					if (draftIndex < 0)
					{
						break;
					}
					DailyMemoryDraft draft = list[draftIndex];
					if (draft == null || draft.GameDayIndex >= _dailyMemoryDraftSealTargetDay)
					{
						continue;
					}
					if (!string.Equals(NormalizeMemoryHeroId(draft.HeroId), ownerMemoryId, StringComparison.OrdinalIgnoreCase))
					{
						// Never redirect memory by display name. Skip an untrusted mapping but retain its raw/weekly material.
						draft.QueuedForSummary = false;
						Logger.Log("CompressedMemory", "skipped mismatched daily memory draft owner=" + ownerMemoryId + " draftHero=" + NormalizeMemoryHeroId(draft.HeroId) + " day=" + draft.GameDayIndex);
						continue;
					}
					draft.HeroId = ownerMemoryId;
					bool hasSummarySource = CountDailyMemorySummarySourceChars(draft) > 0;
					bool hasAfefLines = HasDailyMemoryDraftAfefLines(draft);
					if (!draft.HasLlmDialogue || !hasSummarySource)
					{
						if (!hasAfefLines)
						{
							list.RemoveAt(draftIndex);
						}
						continue;
					}
					// The owner was validated once above, avoiding a repeated Hero registry lookup for each old daily draft.
					TryEnqueueMajorActionSummaryForDraft(draft, _dailyMemoryDraftSealQueuedMajor, ownerAlreadyEligible: true);
					if (draft.SummaryRetryCount >= 3)
					{
						// Three attempts are terminal for automatic work; preserve the draft and error for manual inspection.
						draft.QueuedForSummary = false;
						continue;
					}
					string text = ownerMemoryId;
					string key = text + "|" + draft.GameDayIndex;
					if (HasCompressedMemoryBlock(text, draft.GameDayIndex))
					{
						list.RemoveAt(draftIndex);
						continue;
					}
					if (!_dailyMemoryDraftSealQueued.Contains(key))
					{
						_memorySummaryQueue.Add(new MemorySummaryJob
						{
							HeroId = text,
							HeroName = draft.HeroName,
							GameDayIndex = draft.GameDayIndex,
							GameDate = draft.GameDate
						});
						_dailyMemoryDraftSealQueued.Add(key);
					}
					draft.QueuedForSummary = true;
				}
				list = SanitizeDailyMemoryDrafts(list);
				if (list.Count > 0)
				{
					_dailyMemoryDrafts[ownerKey] = list;
				}
				else
				{
					_dailyMemoryDrafts.Remove(ownerKey);
				}
				_dailyMemoryDraftSealOwnerIndex++;
				_dailyMemoryDraftSealDraftIndex = -1;
			}
			// Do not persist terminal retries or removed targets just because this sealing slice completed successfully.
			_memorySummaryQueue = SanitizeMemorySummaryQueue(_memorySummaryQueue.Where(HasMemorySummaryJobStillPending).ToList());
			_npcMajorActionSummaryQueue = SanitizeMajorActionSummaryQueue(_npcMajorActionSummaryQueue.Where(HasMajorActionSummaryJobStillPending).ToList());
			ResetDailyMemoryDraftSealSliceState();
			return true;
		}
		catch (Exception ex)
		{
			ResetDailyMemoryDraftSealSliceState();
			Logger.Log("CompressedMemory", "[ERROR] TrySealPastDailyMemoryDrafts failed: " + ex.Message);
			return true;
		}
	}

	private void ResetDailyMemoryDraftSealSliceState()
	{
		_dailyMemoryDraftSealOwnerKeys = null;
		_dailyMemoryDraftSealOwnerIndex = 0;
		_dailyMemoryDraftSealDraftIndex = -1;
		_dailyMemoryDraftSealTargetDay = -1;
		_dailyMemoryDraftSealQueued = null;
		_dailyMemoryDraftSealQueuedMajor = null;
	}

	private bool HasCompressedMemoryBlock(string heroId, int dayIndex)
	{
		heroId = NormalizeMemoryHeroId(heroId);
		if (string.IsNullOrWhiteSpace(heroId) || _compressedMemoryBlocks == null)
		{
			return false;
		}
		return _compressedMemoryBlocks.TryGetValue(heroId, out var value) && value != null && value.Any((CompressedMemoryBlock x) => x != null && x.GameDayIndex == dayIndex);
	}

	private void TryStartMemorySummaryQueue(bool forceOverviewCandidateScan = false)
	{
		try
		{
			if (_memorySummaryProcessing || IsDialogueOrLetterChainBusyForMemorySummary())
			{
				return;
			}
			// Validate only the bounded queues here; the full saved-memory owner scan is reserved for load finish.
			CancelUnavailableHeroCompressionQueuedJobs("queue_start");
			// Persist only runnable work so old terminal or malformed entries cannot survive until a later unrelated batch.
			_memorySummaryQueue = SanitizeMemorySummaryQueue((_memorySummaryQueue ?? new List<MemorySummaryJob>()).Where(HasMemorySummaryJobStillPending).ToList());
			_npcMajorActionSummaryQueue = SanitizeMajorActionSummaryQueue((_npcMajorActionSummaryQueue ?? new List<MajorActionSummaryJob>()).Where(HasMajorActionSummaryJobStillPending).ToList());
			_memoryOverviewQueue = SanitizeMemoryOverviewQueue((_memoryOverviewQueue ?? new List<MemoryOverviewJob>()).Where(HasMemoryOverviewJobStillPending).ToList());
			// The queues were just filtered, so raw counts avoid another Hero registry lookup on this hot scheduler path.
			bool hasMemoryJobs = _memorySummaryQueue.Count > 0;
			bool hasMajorActionJobs = _npcMajorActionSummaryQueue.Count > 0;
			bool hasOverviewJobs = _memoryOverviewQueue.Count > 0;
			if (!hasMemoryJobs && !hasMajorActionJobs && !hasOverviewJobs && ShouldScanMemoryOverviewCandidates(forceOverviewCandidateScan))
			{
				using (PerfProbe.Scope("MyBehavior.TryStartMemorySummaryQueue.EnqueueMemoryOverviewForAllCandidates"))
				{
					if (forceOverviewCandidateScan)
					{
						QueueAllMemoryOverviewCandidatesForDeferredScan();
					}
					else
					{
						QueueDirtyMemoryOverviewCandidatesForDeferredScan();
					}
				}
				// Candidate creation validates owners itself; use its filtered queue counts without repeating the bounded scan.
				hasMemoryJobs = _memorySummaryQueue.Count > 0;
				hasMajorActionJobs = _npcMajorActionSummaryQueue.Count > 0;
				hasOverviewJobs = _memoryOverviewQueue.Count > 0;
			}
			if (!hasMemoryJobs && !hasMajorActionJobs && !hasOverviewJobs)
			{
				return;
			}
			_memorySummaryProcessing = true;
			_ = ProcessMemorySummaryQueueAsync();
		}
		catch (Exception ex)
		{
			_memorySummaryProcessing = false;
			Logger.Log("CompressedMemory", "[ERROR] TryStartMemorySummaryQueue failed: " + ex.Message);
		}
	}

	private bool ShouldScanMemoryOverviewCandidates(bool force)
	{
		if (_compressedMemoryBlocks == null || _compressedMemoryBlocks.Count <= 0)
		{
			return false;
		}
		if (force)
		{
			_lastMemoryOverviewCandidateScanUtcTicks = DateTime.UtcNow.Ticks;
			return true;
		}
		long now = DateTime.UtcNow.Ticks;
		if (now - _lastMemoryOverviewCandidateScanUtcTicks < TimeSpan.FromSeconds(MemoryOverviewCandidateScanThrottleSeconds).Ticks)
		{
			return false;
		}
		_lastMemoryOverviewCandidateScanUtcTicks = now;
		return true;
	}

	private async Task ProcessMemorySummaryQueueAsync()
	{
		long runtimeGeneration = SaveRuntimeGuard.CaptureGeneration();
		try
		{
			QueueDirtyMemoryOverviewCandidatesForDeferredScan();
			// A Hero can die or be removed after the scheduler's snapshot; discard those bounded queue entries first.
			CancelUnavailableHeroCompressionQueuedJobs("queue_execute");
			List<MemorySummaryJob> jobs = SanitizeMemorySummaryQueue(_memorySummaryQueue).Where(HasMemorySummaryJobStillPending).ToList();
			List<MajorActionSummaryJob> majorJobs = SanitizeMajorActionSummaryQueue(_npcMajorActionSummaryQueue).Where(HasMajorActionSummaryJobStillPending).ToList();
			HashSet<string> memoryJobHeroIds = new HashSet<string>(jobs.Where((MemorySummaryJob job) => job != null).Select((MemorySummaryJob job) => NormalizeMemoryHeroId(job.HeroId)), StringComparer.OrdinalIgnoreCase);
			List<MemoryOverviewJob> pendingOverviewJobs = SanitizeMemoryOverviewQueue(_memoryOverviewQueue).Where(HasMemoryOverviewJobStillPending).ToList();
			List<MemoryOverviewJob> overviewJobs = pendingOverviewJobs.Where((MemoryOverviewJob job) => !memoryJobHeroIds.Contains(NormalizeMemoryHeroId(job.HeroId))).ToList();
			if (jobs.Count <= 0 && majorJobs.Count <= 0 && overviewJobs.Count <= 0)
			{
				// Persist the filtered snapshot so exhausted or obsolete jobs cannot wake maintenance every tick.
				_memorySummaryQueue = jobs;
				_npcMajorActionSummaryQueue = majorJobs;
				_memoryOverviewQueue = pendingOverviewJobs;
				return;
			}
			int burstSize = GetMemorySummaryRequestsPerMinuteFromSettings();
			int totalJobCount = jobs.Count + majorJobs.Count + overviewJobs.Count;
			InformationManager.DisplayMessage(new InformationMessage("AnimusForge 开始日结压缩任务，共 " + totalJobCount + " 个；对话记忆 " + jobs.Count + " 个，重大履历 " + majorJobs.Count + " 个，记忆总览 " + overviewJobs.Count + " 个；每分钟上限 " + burstSize + "。"));
			List<object> queueItems = new List<object>();
			queueItems.AddRange(jobs.Cast<object>());
			queueItems.AddRange(majorJobs.Cast<object>());
			queueItems.AddRange(overviewJobs.Cast<object>());
			List<MemorySummaryExecutionResult> results = new List<MemorySummaryExecutionResult>();
			List<MajorActionSummaryExecutionResult> majorResults = new List<MajorActionSummaryExecutionResult>();
			List<MemoryOverviewExecutionResult> overviewResults = new List<MemoryOverviewExecutionResult>();
			await RunDailySummaryQueueItemsAsync(queueItems, burstSize, results, majorResults, overviewResults);
			if (SaveRuntimeGuard.IsStale(runtimeGeneration, "memory_summary_queue_results"))
			{
				return;
			}
			List<string> failures = new List<string>();
			foreach (MemorySummaryExecutionResult result in results)
			{
				if (result == null || result.Job == null)
				{
					continue;
				}
				// Target/source cleanup is normal save recovery, not an actionable API error or popup condition.
				if (result.IsObsolete)
				{
					continue;
				}
				if (result.Success)
				{
					ApplyMemorySummarySuccess(result.Job, result.Block);
				}
				else
				{
					failures.Add((result.Job.HeroName ?? result.Job.HeroId) + " 第" + result.Job.GameDayIndex + "日：" + (result.Error ?? "未知错误"));
					MarkMemorySummaryFailure(result.Job, result.Error);
				}
			}
			foreach (MajorActionSummaryExecutionResult result2 in majorResults)
			{
				if (result2 == null || result2.Job == null)
				{
					continue;
				}
				// Target/source cleanup is normal save recovery, not an actionable API error or popup condition.
				if (result2.IsObsolete)
				{
					continue;
				}
				if (result2.Success)
				{
					ApplyMajorActionSummarySuccess(result2.Job, result2.State);
				}
				else
				{
					failures.Add((result2.Job.HeroName ?? result2.Job.HeroId) + " 重大履历：" + (result2.Error ?? "未知错误"));
					MarkMajorActionSummaryFailure(result2.Job, result2.Error);
				}
			}
			foreach (MemoryOverviewExecutionResult result3 in overviewResults)
			{
				if (result3 == null || result3.Job == null)
				{
					continue;
				}
				// Target/source cleanup is normal save recovery, not an actionable API error or popup condition.
				if (result3.IsObsolete)
				{
					continue;
				}
				if (result3.Success)
				{
					ApplyMemoryOverviewSuccess(result3.Job, result3.State);
				}
				else
				{
					failures.Add((result3.Job.HeroName ?? result3.Job.HeroId) + " 记忆总览：" + (result3.Error ?? "未知错误"));
					MarkMemoryOverviewFailure(result3.Job, result3.Error);
				}
			}
			QueueDirtyMemoryOverviewCandidatesForDeferredScan();
			HashSet<string> processedOverviewHeroIds = new HashSet<string>(overviewResults.Where((MemoryOverviewExecutionResult x) => x?.Job != null && !x.IsObsolete).Select((MemoryOverviewExecutionResult x) => NormalizeMemoryHeroId(x.Job.HeroId)), StringComparer.OrdinalIgnoreCase);
			List<MemoryOverviewJob> extraOverviewJobs = SanitizeMemoryOverviewQueue(_memoryOverviewQueue).Where((MemoryOverviewJob job) => job != null && HasMemoryOverviewJobStillPending(job) && !processedOverviewHeroIds.Contains(NormalizeMemoryHeroId(job.HeroId))).ToList();
			if (extraOverviewJobs.Count > 0)
			{
				if (queueItems.Count > 0)
				{
					await Task.Delay(60000);
				}
				if (SaveRuntimeGuard.IsStale(runtimeGeneration, "memory_summary_queue_extra_delay"))
				{
					return;
				}
				List<MemorySummaryExecutionResult> extraMemoryResults = new List<MemorySummaryExecutionResult>();
				List<MajorActionSummaryExecutionResult> extraMajorResults = new List<MajorActionSummaryExecutionResult>();
				List<MemoryOverviewExecutionResult> extraOverviewResults = new List<MemoryOverviewExecutionResult>();
				await RunDailySummaryQueueItemsAsync(extraOverviewJobs.Cast<object>().ToList(), burstSize, extraMemoryResults, extraMajorResults, extraOverviewResults);
				if (SaveRuntimeGuard.IsStale(runtimeGeneration, "memory_summary_queue_extra_results"))
				{
					return;
				}
				foreach (MemoryOverviewExecutionResult result4 in extraOverviewResults)
				{
					if (result4 == null || result4.Job == null)
					{
						continue;
					}
					// A target removed during the delayed overview wave is intentionally silent and is dropped below.
					if (result4.IsObsolete)
					{
						continue;
					}
					if (result4.Success)
					{
						ApplyMemoryOverviewSuccess(result4.Job, result4.State);
					}
					else
					{
						failures.Add((result4.Job.HeroName ?? result4.Job.HeroId) + " 记忆总览：" + (result4.Error ?? "未知错误"));
						MarkMemoryOverviewFailure(result4.Job, result4.Error);
					}
				}
				overviewResults.AddRange(extraOverviewResults);
			}
			// Keep only runnable work; terminal retries and invalid targets must not be serialized back into the save.
			_memorySummaryQueue = SanitizeMemorySummaryQueue((_memorySummaryQueue ?? new List<MemorySummaryJob>()).Where(HasMemorySummaryJobStillPending).ToList());
			_npcMajorActionSummaryQueue = SanitizeMajorActionSummaryQueue((_npcMajorActionSummaryQueue ?? new List<MajorActionSummaryJob>()).Where((MajorActionSummaryJob job) => job != null && HasMajorActionSummaryJobStillPending(job)).ToList());
			_memoryOverviewQueue = SanitizeMemoryOverviewQueue((_memoryOverviewQueue ?? new List<MemoryOverviewJob>()).Where((MemoryOverviewJob job) => job != null && HasMemoryOverviewJobStillPending(job)).ToList());
			if (failures.Count > 0)
			{
				ShowCompressedMemoryBlockingPopup("日结压缩总结失败", "以下日结压缩任务重试 3 次后仍失败：\n\n" + string.Join("\n", failures) + "\n\n请修复 API 或调低记忆总结 RPM 后重试。");
			}
			else if (results.Count > 0 || majorResults.Count > 0 || overviewResults.Count > 0)
			{
				InformationManager.DisplayMessage(new InformationMessage("AnimusForge 日结压缩完成：对话记忆 " + results.Count((MemorySummaryExecutionResult x) => x != null && x.Success) + " 个，重大履历 " + majorResults.Count((MajorActionSummaryExecutionResult x) => x != null && x.Success) + " 个，记忆总览 " + overviewResults.Count((MemoryOverviewExecutionResult x) => x != null && x.Success) + " 个。"));
			}
		}
		catch (Exception ex)
		{
			Logger.Log("CompressedMemory", "[ERROR] ProcessMemorySummaryQueueAsync failed: " + ex);
			if (SaveRuntimeGuard.IsCurrentGeneration(runtimeGeneration))
			{
				ShowCompressedMemoryBlockingPopup("压缩记忆总结异常", ex.Message);
			}
		}
		finally
		{
			if (SaveRuntimeGuard.IsCurrentGeneration(runtimeGeneration))
			{
				_memorySummaryProcessing = false;
			}
		}
	}

	private async Task RunDailySummaryQueueItemsAsync(List<object> queueItems, int burstSize, List<MemorySummaryExecutionResult> results, List<MajorActionSummaryExecutionResult> majorResults, List<MemoryOverviewExecutionResult> overviewResults)
	{
		int clampedBurstSize = Math.Max(1, burstSize);
		for (int i = 0; i < (queueItems?.Count ?? 0); i += clampedBurstSize)
		{
			List<object> wave = queueItems.Skip(i).Take(clampedBurstSize).ToList();
			List<Task<DailySummaryQueueResult>> tasks = wave.Select(ExecuteDailySummaryQueueItemAsync).ToList();
			DailySummaryQueueResult[] completed = await Task.WhenAll(tasks);
			foreach (DailySummaryQueueResult completedResult in completed)
			{
				if (completedResult == null)
				{
					continue;
				}
				if (completedResult.MemoryResult != null)
				{
					results?.Add(completedResult.MemoryResult);
				}
				if (completedResult.MajorActionResult != null)
				{
					majorResults?.Add(completedResult.MajorActionResult);
				}
				if (completedResult.MemoryOverviewResult != null)
				{
					overviewResults?.Add(completedResult.MemoryOverviewResult);
				}
			}
			if (i + clampedBurstSize < (queueItems?.Count ?? 0))
			{
				await Task.Delay(60000);
			}
		}
	}

	private async Task<DailySummaryQueueResult> ExecuteDailySummaryQueueItemAsync(object item)
	{
		DailySummaryQueueResult result = new DailySummaryQueueResult();
		MemorySummaryJob memoryJob = item as MemorySummaryJob;
		if (memoryJob != null)
		{
			result.MemoryResult = await ExecuteMemorySummaryJobAsync(memoryJob, 3);
			return result;
		}
		MajorActionSummaryJob majorJob = item as MajorActionSummaryJob;
		if (majorJob != null)
		{
			result.MajorActionResult = await ExecuteMajorActionSummaryJobAsync(majorJob, 3);
			return result;
		}
		MemoryOverviewJob overviewJob = item as MemoryOverviewJob;
		if (overviewJob != null)
		{
			result.MemoryOverviewResult = await ExecuteMemoryOverviewJobAsync(overviewJob, 3);
			return result;
		}
		return result;
	}

	private DailyMemoryDraft FindMemoryDraft(MemorySummaryJob job)
	{
		if (job == null)
		{
			return null;
		}
		string text = NormalizeMemoryHeroId(job.HeroId);
		if (string.IsNullOrWhiteSpace(text) || _dailyMemoryDrafts == null || !_dailyMemoryDrafts.TryGetValue(text, out var value) || value == null)
		{
			return null;
		}
		// A persisted queue key must agree with the draft owner; never summarize or retarget an ambiguous old-save draft.
		return value.FirstOrDefault((DailyMemoryDraft x) => x != null && x.GameDayIndex == job.GameDayIndex && string.Equals(NormalizeMemoryHeroId(x.HeroId), text, StringComparison.OrdinalIgnoreCase));
	}

	private bool HasMemorySummaryJobStillPending(MemorySummaryJob job)
	{
		try
		{
			string heroId = NormalizeMemoryHeroId(job?.HeroId);
			if (job == null || job.RetryCount >= 3 || string.IsNullOrWhiteSpace(heroId) || !IsMemoryEntityEligibleForCompressedMemory(heroId) || HasCompressedMemoryBlock(heroId, job.GameDayIndex))
			{
				return false;
			}
			DailyMemoryDraft draft = FindMemoryDraft(job);
			// Retry exhaustion is stored on both queue and draft, so old saves cannot silently recreate a terminal job.
			return draft != null && draft.SummaryRetryCount < 3 && draft.HasLlmDialogue && CountDailyMemorySummarySourceChars(draft) > 0;
		}
		catch
		{
			return false;
		}
	}

	private async Task<MemorySummaryExecutionResult> ExecuteMemorySummaryJobAsync(MemorySummaryJob job, int maxAttempts)
	{
		MemorySummaryExecutionResult result = new MemorySummaryExecutionResult
		{
			Job = job
		};
		try
		{
			string memoryId = NormalizeMemoryHeroId(job?.HeroId);
			Hero hero = FindHeroById(memoryId);
			DailyMemoryDraft draft = FindMemoryDraft(job);
			bool isEligible = IsNonHeroMemoryId(memoryId) || IsHeroNpcEligibleForCompressedMemory(hero);
			if (!isEligible || draft == null || draft.Lines == null || draft.Lines.Count <= 0)
			{
				// Missing/removed saved sources are stale queue data, not API failures that should block the campaign.
				result.IsObsolete = true;
				return result;
			}
			for (int i = 1; i <= Math.Max(1, maxAttempts); i++)
			{
				if (!HasMemorySummaryJobStillPending(job))
				{
					// The owner or source can vanish during retry backoff; do not send a second request for stale work.
					result.IsObsolete = true;
					return result;
				}
				ApiCallResult apiCallResult = await CallUniversalApiDetailed(BuildMemorySummarySystemPrompt(draft), BuildMemorySummaryUserPrompt(hero, draft), logToEventLogs: false, eventLogSource: "CompressedMemory", route: UniversalApiRoute.Auxiliary, streamResponse: false, forceThinkingDisabled: true);
				if (apiCallResult.Success)
				{
					if (TryParseMemorySummaryResponse(apiCallResult.Content, hero, draft, out var block, out var error))
					{
						result.Block = block;
						return result;
					}
					result.Error = BuildSummaryJsonParseFailureMessage("总结格式解析失败", error, apiCallResult.Content);
				}
				else
				{
					result.Error = apiCallResult.ErrorMessage ?? "API请求失败";
				}
				if (i < maxAttempts)
				{
					await Task.Delay(apiCallResult.RetryAfterSeconds.HasValue ? Math.Max(1000, apiCallResult.RetryAfterSeconds.Value * 1000) : 1500);
				}
			}
			return result;
		}
		catch (Exception ex)
		{
			result.Error = ex.Message;
			return result;
		}
	}

	private async Task<MajorActionSummaryExecutionResult> ExecuteMajorActionSummaryJobAsync(MajorActionSummaryJob job, int maxAttempts)
	{
		MajorActionSummaryExecutionResult result = new MajorActionSummaryExecutionResult
		{
			Job = job
		};
		try
		{
			string heroId = NormalizeMemoryHeroId(job?.HeroId);
			Hero hero = FindHeroById(heroId);
			if (!IsHeroNpcEligibleForCompressedMemory(hero) || string.IsNullOrWhiteSpace(heroId) || _npcMajorActions == null || !_npcMajorActions.TryGetValue(heroId, out var rawActions) || rawActions == null)
			{
				// Major-action ledgers are retained for weekly reports, but an unavailable Hero must never reach the LLM.
				result.IsObsolete = true;
				return result;
			}
			List<NpcActionEntry> allActions = SanitizeNpcActionEntries(rawActions, keepOnlyRecentWindow: false);
			if (allActions.Count <= 0)
			{
				// A queue can outlive its last source action after save repair; discard it silently.
				result.IsObsolete = true;
				return result;
			}
			MajorActionSummaryState existingState = GetMajorActionSummaryState(heroId);
			bool hasExistingSummary = existingState != null && !string.IsNullOrWhiteSpace(existingState.Summary);
			List<NpcActionEntry> sourceActions = hasExistingSummary ? allActions.Where((NpcActionEntry x) => IsNpcActionAfterSummaryCursor(x, existingState)).ToList() : allActions;
			if (sourceActions.Count <= 0)
			{
				if (hasExistingSummary)
				{
					result.State = existingState;
					return result;
				}
				// No source material means the persisted work item is obsolete rather than an API error.
				result.IsObsolete = true;
				return result;
			}
			int targetChars = GetMajorActionSummaryTargetChars(existingState, hero, sourceActions);
			for (int i = 1; i <= Math.Max(1, maxAttempts); i++)
			{
				if (!HasMajorActionSummaryJobStillPending(job))
				{
					// Re-check after retry backoff so a Hero removed between API attempts never receives another request.
					result.IsObsolete = true;
					return result;
				}
				ApiCallResult apiCallResult = await CallUniversalApiDetailed(BuildMajorActionSummarySystemPrompt(targetChars), BuildMajorActionSummaryUserPrompt(hero, existingState, sourceActions, targetChars), logToEventLogs: false, eventLogSource: "NpcMajorSummary", route: UniversalApiRoute.Auxiliary, streamResponse: false, forceThinkingDisabled: true);
				if (apiCallResult.Success)
				{
					if (TryParseMajorActionSummaryResponse(apiCallResult.Content, hero, job, allActions, out var state, out var error))
					{
						result.State = state;
						return result;
					}
					result.Error = BuildSummaryJsonParseFailureMessage("重大履历总结格式解析失败", error, apiCallResult.Content);
				}
				else
				{
					result.Error = apiCallResult.ErrorMessage ?? "API请求失败";
				}
				if (i < maxAttempts)
				{
					await Task.Delay(apiCallResult.RetryAfterSeconds.HasValue ? Math.Max(1000, apiCallResult.RetryAfterSeconds.Value * 1000) : 1500);
				}
			}
			return result;
		}
		catch (Exception ex)
		{
			result.Error = ex.Message;
			return result;
		}
	}

	private async Task<MemoryOverviewExecutionResult> ExecuteMemoryOverviewJobAsync(MemoryOverviewJob job, int maxAttempts)
	{
		MemoryOverviewExecutionResult result = new MemoryOverviewExecutionResult
		{
			Job = job
		};
		try
		{
			string heroId = NormalizeMemoryHeroId(job?.HeroId);
			Hero hero = FindHeroById(heroId);
			bool isEligible = IsNonHeroMemoryId(heroId) || IsHeroNpcEligibleForCompressedMemory(hero);
			if (!isEligible || string.IsNullOrWhiteSpace(heroId) || _compressedMemoryBlocks == null || !_compressedMemoryBlocks.TryGetValue(heroId, out var rawBlocks) || rawBlocks == null)
			{
				// A removed owner or cleaned block set is stale queue state and must not surface as an API failure.
				result.IsObsolete = true;
				return result;
			}
			List<CompressedMemoryBlock> allBlocks = SanitizeCompressedMemoryBlocks(rawBlocks);
			int threshold = GetMemoryOverviewStartBlockCountFromSettings();
			if (allBlocks.Count < threshold)
			{
				// Blocks can be edited or pruned after enqueue; below-threshold work should simply disappear.
				result.IsObsolete = true;
				return result;
			}
			MemoryOverviewState existingState = GetMemoryOverviewState(heroId);
			MemoryOverviewState promptExistingState = existingState ?? new MemoryOverviewState
			{
				HeroId = heroId,
				HeroName = (job?.HeroName ?? "").Trim()
			};
			bool hasExistingSummary = existingState != null && !string.IsNullOrWhiteSpace(existingState.Summary);
			HashSet<string> included = new HashSet<string>(hasExistingSummary ? (existingState.IncludedBlockIds ?? new List<string>()) : new List<string>(), StringComparer.OrdinalIgnoreCase);
			List<CompressedMemoryBlock> sourceBlocks = hasExistingSummary ? allBlocks.Where((CompressedMemoryBlock block) => !IsMemoryBlockIncludedInOverview(block, included)).ToList() : allBlocks;
			if (sourceBlocks.Count <= 0)
			{
				if (hasExistingSummary)
				{
					result.State = existingState;
					return result;
				}
				// With no new blocks and no reusable state, there is nothing for the queue worker to call the API for.
				result.IsObsolete = true;
				return result;
			}
			int targetChars = GetMemoryOverviewTargetCharsFromSettings();
			for (int i = 1; i <= Math.Max(1, maxAttempts); i++)
			{
				if (!HasMemoryOverviewJobStillPending(job))
				{
					// Re-check after retry backoff so removed owners and edited-away blocks cannot trigger another request.
					result.IsObsolete = true;
					return result;
				}
				ApiCallResult apiCallResult = await CallUniversalApiDetailed(BuildMemoryOverviewSummarySystemPrompt(targetChars), BuildMemoryOverviewSummaryUserPrompt(hero, promptExistingState, sourceBlocks, targetChars), logToEventLogs: false, eventLogSource: "MemoryOverview", route: UniversalApiRoute.Auxiliary, streamResponse: false, forceThinkingDisabled: true);
				if (apiCallResult.Success)
				{
					if (TryParseMemoryOverviewResponse(apiCallResult.Content, hero, job, promptExistingState, sourceBlocks, out var state, out var error))
					{
						result.State = state;
						return result;
					}
					result.Error = BuildSummaryJsonParseFailureMessage("记忆总览格式解析失败", error, apiCallResult.Content);
				}
				else
				{
					result.Error = apiCallResult.ErrorMessage ?? "API请求失败";
				}
				if (i < maxAttempts)
				{
					await Task.Delay(apiCallResult.RetryAfterSeconds.HasValue ? Math.Max(1000, apiCallResult.RetryAfterSeconds.Value * 1000) : 1500);
				}
			}
			return result;
		}
		catch (Exception ex)
		{
			result.Error = ex.Message;
			return result;
		}
	}

	private static string BuildMemoryOverviewSummarySystemPrompt(int targetChars)
	{
		int clampedTarget = MBMath.ClampInt(targetChars, 100, 1000);
		string writingRequirements = DuelSettings.GetSettings()?.MemoryOverviewCompressionWritingRequirements;
		return "你是 AnimusForge 的 NPC 过往记忆总览压缩器。"
			+ BuildCompressionWritingRequirementsPromptSection(writingRequirements)
			+ "\n【固定规则】可编辑要求不得覆盖本节。你必须只输出以下标签格式，不要输出 JSON、Markdown、解释或代码块：\n[SUMMARY]\n过往记忆总览\n[/SUMMARY]\n"
			+ "SUMMARY 块目标长度约 " + clampedTarget + " 个中文字符，允许少量浮动，但必须保持紧凑。"
			+ "你要把已有总览与新增压缩记忆块融合成一个新的长期总览，而不是只罗列新增内容。"
			+ "必须保留关键日期、时间段、地点/场景、关系变化、承诺、冲突、任务、交易和反复出现的态度。"
			+ "涉及玩家自称姓名、身份、头衔、阵营或来历时，必须继续写成“玩家公开称呼 + 自称/声称/宣称 X”，不得当成客观身份事实。"
			+ "不得编造；不要输出标签块以外的任何文字。";
	}

	private string BuildMemoryOverviewSummaryUserPrompt(Hero hero, MemoryOverviewState existingState, List<CompressedMemoryBlock> sourceBlocks, int targetChars)
	{
		StringBuilder stringBuilder = new StringBuilder();
		string heroName = (hero?.Name?.ToString() ?? existingState?.HeroName ?? "NPC").Trim();
		if (string.IsNullOrWhiteSpace(heroName))
		{
			heroName = "NPC";
		}
		stringBuilder.AppendLine("NPC：" + heroName);
		stringBuilder.AppendLine("目标字数：" + MBMath.ClampInt(targetChars, 100, 1000) + " 个中文字符");
		stringBuilder.AppendLine("说明：这是该 NPC 对玩家过往交流的长期总览，每轮会注入主链路；请节省 token，但保留后续对话需要的事实锚点。");
		stringBuilder.AppendLine();
		stringBuilder.AppendLine("已有过往记忆总览：");
		if (existingState != null && !string.IsNullOrWhiteSpace(existingState.Summary))
		{
			stringBuilder.AppendLine(existingState.Summary.Trim());
		}
		else
		{
			stringBuilder.AppendLine("无。这是第一版过往记忆总览，请根据下面所有压缩记忆块生成。");
		}
		stringBuilder.AppendLine();
		stringBuilder.AppendLine("待纳入压缩记忆块：");
		foreach (CompressedMemoryBlock block in sourceBlocks ?? new List<CompressedMemoryBlock>())
		{
			string text = BuildMemoryOverviewBlockSourceText(block);
			if (!string.IsNullOrWhiteSpace(text))
			{
				stringBuilder.AppendLine(text);
				stringBuilder.AppendLine();
			}
		}
		stringBuilder.AppendLine("请按 [SUMMARY]...[/SUMMARY] 输出融合后的新总览，必须含日期信息；可按时间线或主题组织，但不要丢失日期、地点和关键互动结果。");
		return stringBuilder.ToString().Trim();
	}

	private static string BuildMemoryOverviewBlockSourceText(CompressedMemoryBlock block)
	{
		if (block == null)
		{
			return "";
		}
		string date = string.IsNullOrWhiteSpace(block.GameDate) ? ("第" + block.GameDayIndex + "日") : block.GameDate.Trim();
		string title = StripMemoryTitleDateTime(block.RichTitle);
		if (string.IsNullOrWhiteSpace(title))
		{
			title = "往日对话记忆";
		}
		string scenes = block.Scenes != null && block.Scenes.Count > 0 ? string.Join(" / ", block.Scenes.Select((string x) => (x ?? "").Trim()).Where((string x) => !string.IsNullOrWhiteSpace(x)).Distinct(StringComparer.OrdinalIgnoreCase)) : "地点未知";
		StringBuilder stringBuilder = new StringBuilder();
		stringBuilder.AppendLine("- 记忆块ID：" + ((block.Id ?? BuildCompressedMemoryBlockId(block.HeroId, block.GameDayIndex)).Trim()));
		stringBuilder.AppendLine("  日期时间地点：" + date + " " + FormatMemoryHourRange(block.StartHour, block.EndHour) + "｜" + scenes);
		stringBuilder.AppendLine("  标题：" + title);
		stringBuilder.AppendLine("  内容：" + (block.Summary ?? "").Trim());
		if (block.AfefLines != null && block.AfefLines.Count > 0)
		{
			stringBuilder.AppendLine("  AFEF事实参考：");
			foreach (string line in block.AfefLines)
			{
				if (!string.IsNullOrWhiteSpace(line))
				{
					stringBuilder.AppendLine("  " + line.Trim());
				}
			}
		}
		return stringBuilder.ToString().TrimEnd();
	}

	private static bool TryParseMemoryOverviewResponse(string content, Hero hero, MemoryOverviewJob job, MemoryOverviewState existingState, List<CompressedMemoryBlock> sourceBlocks, out MemoryOverviewState state, out string error)
	{
		state = null;
		error = "";
		try
		{
			if (!TryParseBestSummaryJsonObject(content, new string[4] { "summary_content", "summaryContent", "summary", "content" }, null, out var jObject, out error))
			{
				return false;
			}
			string summary = GetJsonStringIgnoreCase(jObject, "summary_content", "summaryContent", "summary", "content").Trim();
			if (string.IsNullOrWhiteSpace(summary))
			{
				error = "SUMMARY 为空。";
				return false;
			}
			string heroId = NormalizeMemoryHeroId(job?.HeroId ?? hero?.StringId);
			List<string> includedBlockIds = new List<string>();
			if (existingState != null && existingState.IncludedBlockIds != null)
			{
				includedBlockIds.AddRange(existingState.IncludedBlockIds);
			}
			foreach (CompressedMemoryBlock block in sourceBlocks ?? new List<CompressedMemoryBlock>())
			{
				if (block == null)
				{
					continue;
				}
				string blockId = (block.Id ?? BuildCompressedMemoryBlockId(block.HeroId, block.GameDayIndex)).Trim();
				if (!string.IsNullOrWhiteSpace(blockId))
				{
					includedBlockIds.Add(blockId);
				}
			}
			state = new MemoryOverviewState
			{
				HeroId = heroId,
				HeroName = hero?.Name?.ToString() ?? job?.HeroName ?? "NPC",
				Summary = summary,
				IncludedBlockIds = includedBlockIds.Distinct(StringComparer.OrdinalIgnoreCase).ToList(),
				UpdatedUtcTicks = DateTime.UtcNow.Ticks,
				LastError = ""
			};
			return true;
		}
		catch (Exception ex)
		{
			error = ex.Message;
			return false;
		}
	}

	private void ApplyMemoryOverviewSuccess(MemoryOverviewJob job, MemoryOverviewState state)
	{
		if (job == null || state == null || string.IsNullOrWhiteSpace(state.Summary))
		{
			return;
		}
		string heroId = NormalizeMemoryHeroId(job.HeroId);
		if (string.IsNullOrWhiteSpace(heroId))
		{
			return;
		}
		Hero hero = FindHeroById(heroId);
		if (!IsNonHeroMemoryId(heroId) && !IsHeroNpcEligibleForCompressedMemory(hero))
		{
			// The target can disappear while the async API request is in flight; never write its stale result back.
			CancelUnavailableHeroCompressionWorkById(heroId, "memory_overview_apply");
			return;
		}
		if (_memoryOverviewStates == null)
		{
			_memoryOverviewStates = new Dictionary<string, MemoryOverviewState>(StringComparer.OrdinalIgnoreCase);
		}
		state.HeroId = heroId;
		if (string.IsNullOrWhiteSpace(state.HeroName))
		{
			state.HeroName = (job.HeroName ?? "").Trim();
		}
		_memoryOverviewStates[heroId] = SanitizeMemoryOverviewState(state);
		if (_memoryOverviewQueue != null)
		{
			_memoryOverviewQueue.RemoveAll((MemoryOverviewJob x) => x != null && string.Equals(NormalizeMemoryHeroId(x.HeroId), heroId, StringComparison.OrdinalIgnoreCase));
		}
		Logger.Log("MemoryOverview", "summary_success hero=" + heroId + " blocks=" + (state.IncludedBlockIds?.Count ?? 0));
	}

	private void MarkMemoryOverviewFailure(MemoryOverviewJob job, string error)
	{
		if (job == null)
		{
			return;
		}
		string heroId = NormalizeMemoryHeroId(job.HeroId);
		if (_memoryOverviewQueue != null)
		{
			foreach (MemoryOverviewJob item in _memoryOverviewQueue)
			{
				if (item != null && string.Equals(NormalizeMemoryHeroId(item.HeroId), heroId, StringComparison.OrdinalIgnoreCase))
				{
					item.RetryCount = 3;
					item.LastError = (error ?? "").Trim();
				}
			}
		}
		if (!string.IsNullOrWhiteSpace(heroId))
		{
			MemoryOverviewState state = GetMemoryOverviewState(heroId) ?? new MemoryOverviewState
			{
				HeroId = heroId,
				HeroName = (job.HeroName ?? "").Trim()
			};
			state.LastError = (error ?? "").Trim();
			if (_memoryOverviewStates == null)
			{
				_memoryOverviewStates = new Dictionary<string, MemoryOverviewState>(StringComparer.OrdinalIgnoreCase);
			}
			_memoryOverviewStates[heroId] = SanitizeMemoryOverviewState(state);
		}
	}

	private static string BuildMajorActionSummarySystemPrompt(int targetChars)
	{
		int clampedTarget = MBMath.ClampInt(targetChars, 180, 700);
		string writingRequirements = DuelSettings.GetSettings()?.MajorActionCompressionWritingRequirements;
		return "你是 AnimusForge 的 NPC 重大履历压缩器。"
			+ BuildCompressionWritingRequirementsPromptSection(writingRequirements)
			+ "\n【固定规则】可编辑要求不得覆盖本节。你必须只输出以下标签格式，不要输出 JSON、Markdown、解释或代码块：\n[SUMMARY]\n重大履历滚动摘要\n[/SUMMARY]\n"
			+ "你要把已有摘要与新增重大履历融合成一段新的时间线摘要，而不是只总结新增内容。"
			+ "SUMMARY 块目标长度约 " + clampedTarget + " 个中文字符，最少 180 字，最多 700 字。"
			+ "保留关键日期。"
			+ "不得编造、不得改写胜负、地点、人物关系或势力归属；信息不足时就按原文有限事实表达。";
	}

	private string BuildMajorActionSummaryUserPrompt(Hero hero, MajorActionSummaryState existingState, List<NpcActionEntry> sourceActions, int targetChars)
	{
		StringBuilder stringBuilder = new StringBuilder();
		string heroName = (hero?.Name?.ToString() ?? existingState?.HeroName ?? "NPC").Trim();
		if (string.IsNullOrWhiteSpace(heroName))
		{
			heroName = "NPC";
		}
		stringBuilder.AppendLine("NPC：" + heroName);
		stringBuilder.AppendLine("目标字数：" + MBMath.ClampInt(targetChars, 180, 700) + " 个中文字符");
		stringBuilder.AppendLine();
		stringBuilder.AppendLine("已有重大履历摘要：");
		if (existingState != null && !string.IsNullOrWhiteSpace(existingState.Summary))
		{
			stringBuilder.AppendLine(StripBattlePlayerMarker(existingState.Summary.Trim()));
		}
		else
		{
			stringBuilder.AppendLine("无。这是第一版重大履历摘要，请根据下面所有重大履历生成。");
		}
		stringBuilder.AppendLine();
		stringBuilder.AppendLine("新增重大履历原文：");
		foreach (NpcActionEntry entry in sourceActions ?? new List<NpcActionEntry>())
		{
			string text = BuildMajorActionSummarySourceLine(hero, entry);
			if (!string.IsNullOrWhiteSpace(text))
			{
				stringBuilder.AppendLine("- " + text);
			}
		}
		stringBuilder.AppendLine();
		stringBuilder.AppendLine("请按 [SUMMARY]...[/SUMMARY] 输出融合后的新摘要，可以剔除不重要的部分。");
		return stringBuilder.ToString().Trim();
	}

	private static bool TryParseMajorActionSummaryResponse(string content, Hero hero, MajorActionSummaryJob job, List<NpcActionEntry> allActions, out MajorActionSummaryState state, out string error)
	{
		state = null;
		error = "";
		try
		{
			if (!TryParseBestSummaryJsonObject(content, new string[4] { "summary_content", "summaryContent", "summary", "content" }, null, out var jObject, out error))
			{
				return false;
			}
			string summary = GetJsonStringIgnoreCase(jObject, "summary_content", "summaryContent", "summary", "content").Trim();
			if (string.IsNullOrWhiteSpace(summary))
			{
				error = "SUMMARY 为空。";
				return false;
			}
			GetMajorActionMaxCursor(allActions, out var day, out var sequence);
			string heroId = NormalizeMemoryHeroId(job?.HeroId ?? hero?.StringId);
			state = new MajorActionSummaryState
			{
				HeroId = heroId,
				HeroName = hero?.Name?.ToString() ?? job?.HeroName ?? "NPC",
				Summary = summary,
				LastSummarizedDay = day,
				LastSummarizedSequence = sequence,
				UpdatedUtcTicks = DateTime.UtcNow.Ticks,
				LastError = ""
			};
			return true;
		}
		catch (Exception ex)
		{
			error = ex.Message;
			return false;
		}
	}

	private void ApplyMajorActionSummarySuccess(MajorActionSummaryJob job, MajorActionSummaryState state)
	{
		if (job == null || state == null || string.IsNullOrWhiteSpace(state.Summary))
		{
			return;
		}
		string heroId = NormalizeMemoryHeroId(job.HeroId);
		if (string.IsNullOrWhiteSpace(heroId))
		{
			return;
		}
		if (!IsHeroNpcEligibleForCompressedMemory(FindHeroById(heroId)))
		{
			// Raw major actions remain for weekly reports, but an in-flight result cannot recreate derived memory for a removed Hero.
			CancelUnavailableHeroCompressionWorkById(heroId, "major_action_summary_apply");
			return;
		}
		if (_npcMajorActionSummaries == null)
		{
			_npcMajorActionSummaries = new Dictionary<string, MajorActionSummaryState>(StringComparer.OrdinalIgnoreCase);
		}
		state.HeroId = heroId;
		if (string.IsNullOrWhiteSpace(state.HeroName))
		{
			state.HeroName = (job.HeroName ?? "").Trim();
		}
		_npcMajorActionSummaries[heroId] = SanitizeMajorActionSummaryState(state);
		if (_npcMajorActionSummaryQueue != null)
		{
			_npcMajorActionSummaryQueue.RemoveAll((MajorActionSummaryJob x) => x != null && string.Equals(NormalizeMemoryHeroId(x.HeroId), heroId, StringComparison.OrdinalIgnoreCase));
		}
		Logger.Log("NpcMajorSummary", "summary_success hero=" + heroId + " day=" + state.LastSummarizedDay + " sequence=" + state.LastSummarizedSequence);
	}

	private void MarkMajorActionSummaryFailure(MajorActionSummaryJob job, string error)
	{
		if (job == null)
		{
			return;
		}
		string heroId = NormalizeMemoryHeroId(job.HeroId);
		if (_npcMajorActionSummaryQueue != null)
		{
			foreach (MajorActionSummaryJob item in _npcMajorActionSummaryQueue)
			{
				if (item != null && string.Equals(NormalizeMemoryHeroId(item.HeroId), heroId, StringComparison.OrdinalIgnoreCase))
				{
					item.RetryCount = 3;
					item.LastError = (error ?? "").Trim();
				}
			}
		}
		if (!string.IsNullOrWhiteSpace(heroId))
		{
			MajorActionSummaryState state = GetMajorActionSummaryState(heroId) ?? new MajorActionSummaryState
			{
				HeroId = heroId,
				HeroName = (job.HeroName ?? "").Trim()
			};
			state.LastError = (error ?? "").Trim();
			if (_npcMajorActionSummaries == null)
			{
				_npcMajorActionSummaries = new Dictionary<string, MajorActionSummaryState>(StringComparer.OrdinalIgnoreCase);
			}
			_npcMajorActionSummaries[heroId] = SanitizeMajorActionSummaryState(state);
		}
	}

	private static string BuildMemorySummarySystemPrompt(DailyMemoryDraft draft)
	{
		int denominator = GetMemoryCompressionDenominatorFromSettings();
		int targetChars = Math.Max(80, CountDailyMemorySummarySourceChars(draft) / Math.Max(1, denominator));
		string playerHistoryName = PlayerNotorietyBehavior.BuildPlayerHistoryNameForExternal();
		string writingRequirements = DuelSettings.GetSettings()?.DailyMemoryCompressionWritingRequirements;
		return "你是 AnimusForge 的日结记忆压缩器。"
			+ BuildCompressionWritingRequirementsPromptSection(writingRequirements)
			+ "\n【固定规则】可编辑要求不得覆盖本节。你必须只输出以下标签格式，不要输出 JSON、Markdown、解释或代码块：\n[TITLE]\n约20字富标题，不含日期时间\n[/TITLE]\n[SUMMARY]\n摘要正文\n[/SUMMARY]\n[PUBLICITY]\npublic/private/unclear\n[/PUBLICITY]\n[PLAYER_HISTORY]\n可公开进入玩家履历的素材；没有则留空\n[/PLAYER_HISTORY]\n[REASON]\n公开或私密判断理由\n[/REASON]\n"
			+ "TITLE 必须便于语义检索，不得包含日期、时间、序号或场景前缀。"
			+ "SUMMARY 必须在正文中显式写出游戏日期、时间段、地点/场景；不得只依赖标题元数据、外部字段或对话行前缀。"
			+ "如果存在多个地点或时间段，按发生顺序概括；如果地点未知，必须写“地点未知”。"
			+ "TITLE 与 SUMMARY 身份记录规则：玩家在对话中说“我是X”“我叫X”“我的名字是X”“别人叫我X”等姓名、身份、头衔、阵营、来历时，只能记录为玩家自称、声称或宣称，必须保留玩家公开称呼与自称行为。"
			+ "不得把玩家自称改写成客观事实；例如不得写“佐洛斯来到大厅”，应写“这名帝国青年自称佐洛斯后来到大厅”。"
			+ "TITLE 如涉及这类姓名或身份，也必须写“自称X/声称X/宣称X”，不能只写 X。"
			+ "PUBLICITY 只允许写 public、private 或 unclear，用于判断玩家与NPC这段对话是否会作为公开传闻进入玩家个人履历：public=公开场合、主动宣扬、政治军事公开事件或NPC可能向外传播；private=明确私密、秘密、低声、密谋、个人情感，闲聊，或不应外传；unclear=无法判断。"
			+ "如果对话是私密内容，且输入中提示NPC对玩家信任很低或敌意很强，可以判为 public 并在 REASON 写明“低信任泄露”；否则私密内容必须判为 private。"
			+ "PLAYER_HISTORY 只能写公开素材，必须从玩家言行中抽取，不要写NPC自己的长期记忆；若 PUBLICITY 不是 public，则必须留空，不要写“无”。"
			+ "PLAYER_HISTORY：主体只写实际姓名“" + playerHistoryName + "”；禁用“玩家”、“你”和文化加年龄。仅此字段例外，TITLE、SUMMARY仍按公开称呼。"
			+ "SUMMARY 目标长度约 " + targetChars + " 个中文字符，最少 80 字。"
			+ "AFEF 行只作为事实参考，不要改写进 AFEF 区；调用方会原样保存。";
	}

	private static string BuildCompressionWritingRequirementsPromptSection(string requirements)
	{
		string text = (requirements ?? "").Replace("\r\n", "\n").Replace('\r', '\n').Trim();
		return string.IsNullOrWhiteSpace(text) ? "" : "\n【可编辑写作要求】\n" + text + "\n";
	}

	private static string BuildMemorySummaryUserPrompt(Hero hero, DailyMemoryDraft draft)
	{
		StringBuilder stringBuilder = new StringBuilder();
		string text = string.IsNullOrWhiteSpace(draft.GameDate) ? ("第" + draft.GameDayIndex + "日") : draft.GameDate.Trim();
		List<DailyMemoryLine> normalLines = (draft.Lines ?? new List<DailyMemoryLine>()).Where((DailyMemoryLine x) => x != null && !x.IsAfef).ToList();
		List<DailyMemoryLine> afefLines = (draft.Lines ?? new List<DailyMemoryLine>()).Where((DailyMemoryLine x) => x != null && x.IsAfef).ToList();
		int startHour = normalLines.Concat(afefLines).Select((DailyMemoryLine x) => MBMath.ClampInt(x.GameHour, 0, 23)).DefaultIfEmpty(0).Min();
		int endHour = normalLines.Concat(afefLines).Select((DailyMemoryLine x) => MBMath.ClampInt(x.GameHour, 0, 23)).DefaultIfEmpty(0).Max();
		List<string> scenes = normalLines.Concat(afefLines).Select(ResolveMemoryLineSceneForPrompt).Where((string x) => !string.IsNullOrWhiteSpace(x) && !IsUnknownMemorySceneLabel(x)).Distinct(StringComparer.OrdinalIgnoreCase).ToList();
		if (scenes.Count == 0)
		{
			string fallbackScene = ResolveCurrentMemorySceneLabel();
			if (!IsUnknownMemorySceneLabel(fallbackScene))
			{
				scenes.Add(fallbackScene.Trim());
			}
		}
		stringBuilder.AppendLine("标题元数据（由游戏决定，不要改写进 TITLE）：");
		stringBuilder.AppendLine("日期：" + text);
		stringBuilder.AppendLine("时间：" + FormatMemoryHourRange(startHour, endHour));
		stringBuilder.AppendLine("NPC：" + (hero?.Name?.ToString() ?? draft.HeroName ?? "NPC"));
		int effectiveTrust = RewardSystemBehavior.Instance?.GetEffectiveTrust(hero) ?? 0;
		stringBuilder.AppendLine("NPC对玩家综合信任：" + effectiveTrust + "（高信任更倾向保密；低于 -20 的敌意或低信任可能泄露私密内容）");
		stringBuilder.AppendLine();
		stringBuilder.AppendLine("内容：");
		stringBuilder.AppendLine("当前场景：" + (scenes.Count > 0 ? string.Join(" / ", scenes) : "未知场景"));
		stringBuilder.AppendLine("当前日期与时间：" + text + " " + FormatMemoryHourRange(startHour, endHour));
		stringBuilder.AppendLine("SUMMARY 硬性要求：摘要正文必须自己写出“日期：" + text + "；时间：" + FormatMemoryHourRange(startHour, endHour) + "；地点：" + (scenes.Count > 0 ? string.Join(" / ", scenes) : "地点未知") + "”，可用自然句表达，但不得省略日期、时间或地点。TITLE 仍不得包含日期、时间或地点。");
		string playerDisplayName = BuildPlayerPublicDisplayNameForPrompt(hero);
		if (string.IsNullOrWhiteSpace(playerDisplayName))
		{
			playerDisplayName = "玩家";
		}
		stringBuilder.AppendLine("TITLE 与 SUMMARY 身份记录说明：本请求中的玩家公开称呼是“" + playerDisplayName + "”，这是游戏系统给 NPC 可见的称呼；如果对话中玩家自称某人，那么一定要把“" + playerDisplayName + "”，自称某人的整个行为记录下来，例如“帝国青年自称恩佐斯”");
		stringBuilder.AppendLine("PLAYER_HISTORY主体=实际姓名“" + PlayerNotorietyBehavior.BuildPlayerHistoryNameForExternal() + "”；禁用“玩家”、“你”和文化加年龄。");
		stringBuilder.AppendLine("今日所有对话历史：");
		foreach (DailyMemoryLine line in normalLines)
		{
			string text2 = BuildDailyMemoryLineForPrompt(line);
			if (!string.IsNullOrWhiteSpace(text2))
			{
				stringBuilder.AppendLine(text2);
			}
		}
		if (afefLines.Count > 0)
		{
			stringBuilder.AppendLine();
			stringBuilder.AppendLine("AFEF事实行（只作理解，不要压缩或改写）：");
			foreach (DailyMemoryLine line2 in afefLines)
			{
				string text3 = BuildDailyMemoryLineForPrompt(line2);
				if (!string.IsNullOrWhiteSpace(text3))
				{
					stringBuilder.AppendLine(text3);
				}
			}
		}
		return stringBuilder.ToString().Trim();
	}

	private static bool TryParseMemorySummaryResponse(string content, Hero hero, DailyMemoryDraft draft, out CompressedMemoryBlock block, out string error)
	{
		block = null;
		error = "";
		try
		{
			if (!TryParseBestSummaryJsonObject(content, new string[3] { "rich_title", "richTitle", "title" }, new string[4] { "summary_content", "summaryContent", "summary", "content" }, out var jObject, out error))
			{
				return false;
			}
			string title = StripMemoryTitleDateTime(GetJsonStringIgnoreCase(jObject, "rich_title", "richTitle", "title"));
			string summary = GetJsonStringIgnoreCase(jObject, "summary_content", "summaryContent", "summary", "content").Trim();
			int effectiveTrust = RewardSystemBehavior.Instance?.GetEffectiveTrust(hero) ?? 0;
			string playerPublicity = PlayerNotorietyBehavior.NormalizeMemoryPublicity(GetJsonStringIgnoreCase(jObject, "player_publicity", "playerPublicity", "publicity"), effectiveTrust);
			string playerHistoryMaterial = GetJsonStringIgnoreCase(jObject, "player_history_material", "playerHistoryMaterial", "history_material", "historyMaterial").Trim();
			string playerPublicityReason = GetJsonStringIgnoreCase(jObject, "publicity_reason", "publicityReason", "reason").Trim();
			if (!string.Equals(playerPublicity, "public", StringComparison.OrdinalIgnoreCase) && !string.Equals(playerPublicity, "leaked_public", StringComparison.OrdinalIgnoreCase))
			{
				playerHistoryMaterial = "";
			}
			if (IsEmptySummaryMarker(playerHistoryMaterial))
			{
				playerHistoryMaterial = "";
			}
			if (!string.IsNullOrWhiteSpace(playerHistoryMaterial))
			{
				playerHistoryMaterial = PlayerNotorietyBehavior.RenderPlayerHistoryMaterialForExternal(playerHistoryMaterial);
			}
			if (string.IsNullOrWhiteSpace(title) || string.IsNullOrWhiteSpace(summary))
			{
				error = "TITLE 或 SUMMARY 为空。";
				return false;
			}
			List<DailyMemoryLine> allLines = draft.Lines ?? new List<DailyMemoryLine>();
			List<DailyMemoryLine> ordered = allLines.Where((DailyMemoryLine x) => x != null).OrderBy((DailyMemoryLine x) => x.GameHour).ToList();
			int startHour = ordered.Select((DailyMemoryLine x) => MBMath.ClampInt(x.GameHour, 0, 23)).DefaultIfEmpty(0).Min();
			int endHour = ordered.Select((DailyMemoryLine x) => MBMath.ClampInt(x.GameHour, 0, 23)).DefaultIfEmpty(0).Max();
			List<string> scenes = ordered.Select((DailyMemoryLine x) => (x.Scene ?? "").Trim()).Where((string x) => !string.IsNullOrWhiteSpace(x)).Distinct(StringComparer.OrdinalIgnoreCase).Take(16).ToList();
			List<string> afefLines = ordered.Where((DailyMemoryLine x) => x.IsAfef).Select(BuildDailyMemoryLineForPrompt).Where((string x) => !string.IsNullOrWhiteSpace(x)).ToList();
			string heroId = NormalizeMemoryHeroId(draft.HeroId);
			block = new CompressedMemoryBlock
			{
				Id = BuildCompressedMemoryBlockId(heroId, draft.GameDayIndex),
				HeroId = heroId,
				HeroName = hero?.Name?.ToString() ?? draft.HeroName ?? "NPC",
				GameDayIndex = draft.GameDayIndex,
				GameDate = draft.GameDate ?? "",
				StartHour = startHour,
				EndHour = endHour,
				Scenes = scenes,
				RichTitle = title,
				Summary = summary,
				AfefLines = afefLines,
				PlayerPublicity = playerPublicity,
				PlayerHistoryMaterial = playerHistoryMaterial,
				PlayerPublicityReason = playerPublicityReason,
				WeeklyMaterialTriggers = SanitizeWeeklyMemoryMaterialTriggers(draft.WeeklyMaterialTriggers),
				CreatedUtcTicks = DateTime.UtcNow.Ticks
			};
			return true;
		}
		catch (Exception ex)
		{
			error = ex.Message;
			return false;
		}
	}

	private void ApplyMemorySummarySuccess(MemorySummaryJob job, CompressedMemoryBlock block)
	{
		if (job == null || block == null)
		{
			return;
		}
		string memoryId = NormalizeMemoryHeroId(job.HeroId);
		Hero hero = FindHeroById(memoryId);
		if (!IsNonHeroMemoryId(memoryId) && !IsHeroNpcEligibleForCompressedMemory(hero))
		{
			// The target can disappear while the async API request is in flight; drop the result and stale derived state.
			CancelUnavailableHeroCompressionWorkById(memoryId, "memory_summary_apply");
			return;
		}
		List<CompressedMemoryBlock> blocks = LoadCompressedMemoryBlocksById(memoryId);
		blocks.RemoveAll((CompressedMemoryBlock x) => x != null && x.GameDayIndex == job.GameDayIndex);
		blocks.Add(block);
		SaveCompressedMemoryBlocksById(memoryId, blocks);
		List<DailyMemoryDraft> drafts = LoadDailyMemoryDraftsById(memoryId);
		drafts.RemoveAll((DailyMemoryDraft x) => x != null && x.GameDayIndex == job.GameDayIndex);
		SaveDailyMemoryDraftsById(memoryId, drafts);
		if (hero != null)
		{
			ShoutBehavior.ClearNativeConversationSessionHistoryForExternal(hero, hero.CharacterObject, hero.Name?.ToString(), job.GameDayIndex);
		}
		if (_memorySummaryQueue != null)
		{
			_memorySummaryQueue.RemoveAll((MemorySummaryJob x) => x != null && string.Equals(NormalizeMemoryHeroId(x.HeroId), memoryId, StringComparison.OrdinalIgnoreCase) && x.GameDayIndex == job.GameDayIndex);
		}
		Logger.Log("CompressedMemory", "summary_success hero=" + (job.HeroId ?? "") + " day=" + job.GameDayIndex + " title=" + (block.RichTitle ?? ""));
		if (!string.IsNullOrWhiteSpace(block.PlayerHistoryMaterial))
		{
			Settlement settlement = hero?.CurrentSettlement ?? Settlement.CurrentSettlement;
			PlayerNotorietyBehavior.RecordPublicMemoryForExternal(hero, settlement, block.PlayerHistoryMaterial, block.PlayerPublicity, block.PlayerPublicityReason, block.GameDayIndex, block.GameDate);
		}
		RecordPublicDailyMemoryWeeklyMaterial(block);
		RecordWeeklyMemoryMaterialForBlock(block);
		TryEnqueueMemoryOverviewForMemoryId(memoryId, job.HeroName, blocks);
	}

	private void MarkMemorySummaryFailure(MemorySummaryJob job, string error)
	{
		if (job == null || _memorySummaryQueue == null)
		{
			return;
		}
		foreach (MemorySummaryJob item in _memorySummaryQueue)
		{
			if (item != null && string.Equals(NormalizeMemoryHeroId(item.HeroId), NormalizeMemoryHeroId(job.HeroId), StringComparison.OrdinalIgnoreCase) && item.GameDayIndex == job.GameDayIndex)
			{
				item.RetryCount = 3;
				item.LastError = (error ?? "").Trim();
			}
		}
		DailyMemoryDraft draft = FindMemoryDraft(job);
		if (draft != null)
		{
			draft.SummaryRetryCount = 3;
			draft.LastSummaryError = (error ?? "").Trim();
		}
	}

	private void OnDailyTick()
	{
		try
		{
			if (!IsDeferredDailyMaintenanceEnabled())
			{
				RunDailyMaintenanceSynchronously();
				return;
			}
			EnqueueDailyMaintenanceForCurrentDay("daily_tick");
		}
		catch (Exception ex)
		{
			_weeklyReportGenerationInProgress = false;
			Logger.Log("EventWeeklyReport", "[ERROR] OnDailyTick auto-generate failed: " + ex.Message);
		}
	}

	private static bool IsDeferredDailyMaintenanceEnabled()
	{
		try
		{
			return DuelSettings.GetSettings()?.EnableDeferredDailyMaintenance != false;
		}
		catch
		{
			return true;
		}
	}

	private static double GetDailyMaintenanceFrameBudgetMs()
	{
		try
		{
			return Math.Max(1.0, Math.Min(10.0, (DuelSettings.GetSettings()?.DailyMaintenanceFrameBudgetMs).GetValueOrDefault((int)DailyMaintenanceDefaultFrameBudgetMs)));
		}
		catch
		{
			return DailyMaintenanceDefaultFrameBudgetMs;
		}
	}

	private void RunDailyMaintenanceSynchronously()
	{
		TrySealPastDailyMemoryDrafts();
		QueueDirtyMemoryOverviewCandidatesForDeferredScan();
		ProcessMemoryOverviewCandidateScanBudget(0L, double.MaxValue);
		TryStartMemorySummaryQueue();
		TryDiscontinueLandlessModRebelKingdoms("daily_tick");
		EnsureWeekZeroOpeningSummaryEvents();
		TryRecordMissedStrategicWorldEvents();
		ApplyKingdomStabilityRelationAdjustments();
		int currentGameDayIndexSafe = GetCurrentGameDayIndexSafe();
		int weekIndex = (currentGameDayIndexSafe > 0) ? (currentGameDayIndexSafe / 7) : 0;
		if (currentGameDayIndexSafe > 0 && currentGameDayIndexSafe % 7 == 0)
		{
			TryProcessWeeklyKingdomRebellions(weekIndex);
		}
		if (_weeklyReportGenerationInProgress)
		{
			return;
		}
		DuelSettings settings = DuelSettings.GetSettings();
		int missingWeek = WeeklyReportSchedulePolicy.ResolveOldestMissingWeek(_lastAutoGeneratedWeeklyReportWeek, currentGameDayIndexSafe);
		if (settings == null || !settings.AutoGenerateWeeklyReports || missingWeek <= 0)
		{
			return;
		}
		if (_automaticKingdomRebellionFlowActive)
		{
			_pendingAutoWeeklyReportWeek = Math.Max(_pendingAutoWeeklyReportWeek, weekIndex);
			return;
		}
		StartAutoWeeklyReportsForWeek(missingWeek, currentGameDayIndexSafe);
	}

	private void EnqueueDailyMaintenanceForCurrentDay(string reason)
	{
		int currentGameDayIndexSafe = GetCurrentGameDayIndexSafe();
		int weekIndex = (currentGameDayIndexSafe > 0) ? (currentGameDayIndexSafe / 7) : 0;
		if (currentGameDayIndexSafe > 0 && currentGameDayIndexSafe % 7 == 0)
		{
			EnqueueDailyMaintenanceJob(DailyMaintenanceTaskKind.ProcessWeeklyKingdomRebellions, currentGameDayIndexSafe, weekIndex, reason: reason);
		}
		QueueDeferredAutoWeeklyReportsForWeek(weekIndex, currentGameDayIndexSafe, reason);
		EnqueueDailyMaintenanceJob(DailyMaintenanceTaskKind.SealPastDailyMemoryDrafts, currentGameDayIndexSafe, reason: reason);
		EnqueueDailyMaintenanceJob(DailyMaintenanceTaskKind.QueueDirtyMemoryOverviewScan, currentGameDayIndexSafe, reason: reason);
		EnqueueDailyMaintenanceJob(DailyMaintenanceTaskKind.StartMemorySummaryQueue, currentGameDayIndexSafe, reason: reason);
		EnqueueDailyMaintenanceJob(DailyMaintenanceTaskKind.DiscontinueLandlessRebelKingdoms, currentGameDayIndexSafe, reason: reason);
		EnqueueDailyMaintenanceJob(DailyMaintenanceTaskKind.EnsureWeekZeroOpeningSummaryEvents, currentGameDayIndexSafe, reason: reason);
		EnqueueDailyMaintenanceJob(DailyMaintenanceTaskKind.RecordMissedStrategicWorldEvents, currentGameDayIndexSafe, reason: reason);
		EnqueueDailyMaintenanceJob(DailyMaintenanceTaskKind.ApplyKingdomStabilityRelationAdjustments, currentGameDayIndexSafe, reason: reason);
	}

	private void QueueDeferredAutoWeeklyReportsForWeek(int weekIndex, int currentGameDayIndexSafe, string reason)
	{
		int missingWeek = WeeklyReportSchedulePolicy.ResolveOldestMissingWeek(_lastAutoGeneratedWeeklyReportWeek, currentGameDayIndexSafe);
		if (weekIndex <= 0 || missingWeek <= 0 || missingWeek > weekIndex || _weeklyReportGenerationInProgress)
		{
			return;
		}
		DuelSettings settings = DuelSettings.GetSettings();
		if (settings == null || !settings.AutoGenerateWeeklyReports)
		{
			return;
		}
		if (_automaticKingdomRebellionFlowActive)
		{
			_pendingAutoWeeklyReportWeek = Math.Max(_pendingAutoWeeklyReportWeek, weekIndex);
			return;
		}
		int startDay = WeeklyReportSchedulePolicy.GetStartDay(missingWeek);
		int endDay = WeeklyReportSchedulePolicy.GetEndDay(missingWeek);
		EnqueueDailyMaintenanceJob(DailyMaintenanceTaskKind.PrepareAutoWeeklyReports, endDay, missingWeek, startDay, endDay, reason);
	}

	private void EnqueueDailyMaintenanceJob(DailyMaintenanceTaskKind kind, int dayIndex = -1, int weekIndex = 0, int startDay = 0, int endDay = 0, string reason = "")
	{
		string key = BuildDailyMaintenanceJobKey(kind, dayIndex, weekIndex, startDay, endDay);
		if (!_dailyMaintenanceJobKeys.Add(key))
		{
			return;
		}
		_dailyMaintenanceQueue.Enqueue(new DailyMaintenanceJob
		{
			Kind = kind,
			DayIndex = dayIndex,
			WeekIndex = weekIndex,
			StartDay = startDay,
			EndDay = endDay,
			Reason = (reason ?? "").Trim()
		});
	}

	private static string BuildDailyMaintenanceJobKey(DailyMaintenanceTaskKind kind, int dayIndex, int weekIndex, int startDay, int endDay)
	{
		return kind + ":" + dayIndex + ":" + weekIndex + ":" + startDay + ":" + endDay;
	}

	private static bool IsDailyMaintenanceBudgetExceeded(long startTimestamp, double budgetMs)
	{
		if (startTimestamp <= 0L || budgetMs <= 0.0 || double.IsInfinity(budgetMs) || double.IsNaN(budgetMs))
		{
			return false;
		}
		double elapsedMs = (Stopwatch.GetTimestamp() - startTimestamp) * 1000.0 / Stopwatch.Frequency;
		return elapsedMs >= budgetMs;
	}

	private bool HasPendingDeferredDailyMaintenanceWork()
	{
		return _dailyMaintenanceQueue.Count > 0 || _pendingMemoryOverviewCandidateScanIds.Count > 0 || _pendingAutoWeeklyReportBuild != null;
	}

	private void ProcessDeferredDailyMaintenance()
	{
		if (!IsDeferredDailyMaintenanceEnabled() || !HasPendingDeferredDailyMaintenanceWork())
		{
			return;
		}
		double budgetMs = GetDailyMaintenanceFrameBudgetMs();
		long startTimestamp = Stopwatch.GetTimestamp();
		if (_pendingAutoWeeklyReportBuild != null && !_automaticKingdomRebellionFlowActive)
		{
			using (PerfProbe.Scope("MyBehavior.DeferredDailyMaintenance.ProcessPendingAutoWeeklyReportBuild"))
			{
				ProcessPendingAutoWeeklyReportBuildBudget(startTimestamp, budgetMs);
			}
			if (_pendingAutoWeeklyReportBuild != null || IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
			{
				return;
			}
		}
		int processedScanCount;
		using (PerfProbe.Scope("MyBehavior.DeferredDailyMaintenance.ProcessMemoryOverviewCandidateScan"))
		{
			processedScanCount = ProcessMemoryOverviewCandidateScanBudget(startTimestamp, budgetMs);
		}
		int processedJobCount = 0;
		while (_dailyMaintenanceQueue.Count > 0 && processedJobCount < DailyMaintenanceMaxJobsPerTick && !IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
		{
			DailyMaintenanceJob job = _dailyMaintenanceQueue.Dequeue();
			_dailyMaintenanceJobKeys.Remove(BuildDailyMaintenanceJobKey(job.Kind, job.DayIndex, job.WeekIndex, job.StartDay, job.EndDay));
			bool completed;
			using (PerfProbe.Scope("MyBehavior.DeferredDailyMaintenance.Job." + job.Kind))
			{
				completed = ExecuteDailyMaintenanceJob(job, startTimestamp, budgetMs);
			}
			if (!completed)
			{
				EnqueueDailyMaintenanceJob(job.Kind, job.DayIndex, job.WeekIndex, job.StartDay, job.EndDay, job.Reason);
			}
			processedJobCount++;
			using (PerfProbe.Scope("MyBehavior.DeferredDailyMaintenance.ProcessMemoryOverviewCandidateScan"))
			{
				processedScanCount += ProcessMemoryOverviewCandidateScanBudget(startTimestamp, budgetMs);
			}
		}
		if (!IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
		{
			using (PerfProbe.Scope("MyBehavior.DeferredDailyMaintenance.ProcessPendingAutoWeeklyReportBuild"))
			{
				ProcessPendingAutoWeeklyReportBuildBudget(startTimestamp, budgetMs);
			}
		}
		using (PerfProbe.Scope("MyBehavior.DeferredDailyMaintenance.ProcessMemoryOverviewCandidateScan"))
		{
			processedScanCount += ProcessMemoryOverviewCandidateScanBudget(startTimestamp, budgetMs);
		}
		if (processedScanCount > 0 && !_memorySummaryProcessing && !IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
		{
			TryStartMemorySummaryQueue();
		}
	}

	private bool ExecuteDailyMaintenanceJob(DailyMaintenanceJob job, long startTimestamp, double budgetMs)
	{
		if (job == null)
		{
			return true;
		}
		try
		{
			if (IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
			{
				return false;
			}
			switch (job.Kind)
			{
			case DailyMaintenanceTaskKind.SealPastDailyMemoryDrafts:
				if (!TrySealPastDailyMemoryDrafts(startTimestamp, budgetMs))
				{
					return false;
				}
				break;
			case DailyMaintenanceTaskKind.StartMemorySummaryQueue:
				TryStartMemorySummaryQueue();
				break;
			case DailyMaintenanceTaskKind.QueueDirtyMemoryOverviewScan:
				QueueDirtyMemoryOverviewCandidatesForDeferredScan();
				break;
			case DailyMaintenanceTaskKind.QueueFullMemoryOverviewScan:
				QueueAllMemoryOverviewCandidatesForDeferredScan();
				break;
			case DailyMaintenanceTaskKind.DiscontinueLandlessRebelKingdoms:
				TryDiscontinueLandlessModRebelKingdoms(string.IsNullOrWhiteSpace(job.Reason) ? "deferred_daily_tick" : job.Reason);
				break;
			case DailyMaintenanceTaskKind.EnsureWeekZeroOpeningSummaryEvents:
				if (!ProcessWeekZeroOpeningSummaryEventsSlice())
				{
					return false;
				}
				break;
			case DailyMaintenanceTaskKind.RecordMissedStrategicWorldEvents:
				if (!ProcessMissedStrategicWorldEventsSlice())
				{
					return false;
				}
				break;
			case DailyMaintenanceTaskKind.ApplyKingdomStabilityRelationAdjustments:
				if (!ProcessKingdomStabilityRelationAdjustmentsSlice())
				{
					return false;
				}
				break;
			case DailyMaintenanceTaskKind.ProcessWeeklyKingdomRebellions:
				return ProcessWeeklyKingdomRebellionsSlice(job.WeekIndex);
			case DailyMaintenanceTaskKind.PrepareAutoWeeklyReports:
				TryInitializePendingAutoWeeklyReportBuild(job);
				break;
			}
			return true;
		}
		catch (Exception ex)
		{
			Logger.Log("DailyMaintenance", "[ERROR] " + job.Kind + " failed: " + ex.Message);
			return true;
		}
	}

	private bool ProcessKingdomStabilityRelationAdjustmentsSlice()
	{
		if (!DuelSettings.IsKingdomStabilityAndRebellionEnabled())
		{
			ClearKingdomStabilityRelationAdjustments();
			_kingdomStabilityMaintenanceCursor = 0;
			return true;
		}
		List<Kingdom> kingdoms = Kingdom.All?.Where((Kingdom x) => x != null).ToList() ?? new List<Kingdom>();
		if (kingdoms.Count == 0)
		{
			_kingdomStabilityMaintenanceCursor = 0;
			return true;
		}
		if (_kingdomStabilityMaintenanceCursor < 0 || _kingdomStabilityMaintenanceCursor >= kingdoms.Count)
		{
			_kingdomStabilityMaintenanceCursor = 0;
		}
		int processed = 0;
		while (_kingdomStabilityMaintenanceCursor < kingdoms.Count && processed < 1)
		{
			ApplyKingdomStabilityRelationAdjustmentsForKingdom(kingdoms[_kingdomStabilityMaintenanceCursor]);
			_kingdomStabilityMaintenanceCursor++;
			processed++;
		}
		if (_kingdomStabilityMaintenanceCursor >= kingdoms.Count)
		{
			_kingdomStabilityMaintenanceCursor = 0;
			return true;
		}
		return false;
	}

	private void TryInitializePendingAutoWeeklyReportBuild(DailyMaintenanceJob job)
	{
		if (job == null || job.WeekIndex <= 0 || _lastAutoGeneratedWeeklyReportWeek >= job.WeekIndex)
		{
			return;
		}
		if (_weeklyReportGenerationInProgress || _pendingAutoWeeklyReportBuild != null)
		{
			if (_pendingAutoWeeklyReportBuild == null || _pendingAutoWeeklyReportBuild.WeekIndex != job.WeekIndex)
			{
				_pendingAutoWeeklyReportWeek = Math.Max(_pendingAutoWeeklyReportWeek, job.WeekIndex);
			}
			return;
		}
		if (_automaticKingdomRebellionFlowActive)
		{
			_pendingAutoWeeklyReportWeek = Math.Max(_pendingAutoWeeklyReportWeek, job.WeekIndex);
			return;
		}
		DuelSettings settings = DuelSettings.GetSettings();
		if (settings == null || !settings.AutoGenerateWeeklyReports)
		{
			return;
		}
		_pendingAutoWeeklyReportBuild = new PendingAutoWeeklyReportBuild
		{
			WeekIndex = job.WeekIndex,
			StartDay = Math.Max(0, job.StartDay),
			EndDay = Math.Max(job.StartDay, job.EndDay),
			Kingdoms = GetDevEditableKingdoms().Where(IsKingdomEligibleForWeeklyReport).ToList(),
			EventSourceMaterialSnapshot = SanitizeEventSourceMaterials(_eventSourceMaterials)
		};
		_weeklyReportGenerationInProgress = true;
		_pendingAutoWeeklyReportWeek = 0;
	}

	private void ProcessPendingAutoWeeklyReportBuildBudget(long startTimestamp, double budgetMs)
	{
		PendingAutoWeeklyReportBuild context = _pendingAutoWeeklyReportBuild;
		if (context == null || _automaticKingdomRebellionFlowActive)
		{
			return;
		}
		try
		{
			if (!context.PreviewGroupsComplete && !IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
			{
				using (PerfProbe.Scope("MyBehavior.AutoWeeklyReport.BuildPreviewGroupsSlice"))
				{
					context.PreviewGroupsComplete = ProcessPendingAutoWeeklyReportPreviewGroupsBudget(context, startTimestamp, budgetMs);
				}
			}
			if (IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs) || !context.PreviewGroupsComplete)
			{
				return;
			}
			ProcessPendingWeeklyReportAggregationBudget(context, startTimestamp, budgetMs);
			if (IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs) || !context.AggregationComplete)
			{
				return;
			}
			ProcessPendingWeeklyReportPromptMaterialsBudget(context, startTimestamp, budgetMs);
			if (IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs) || !context.PromptMaterialsComplete)
			{
				return;
			}
			if (!context.Ordered && !IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
			{
				context.Groups = OrderWeeklyReportGenerationGroups((context.Groups ?? new List<WeeklyEventMaterialPreviewGroup>()).Where((WeeklyEventMaterialPreviewGroup x) => x != null).ToList());
				context.Ordered = true;
			}
			if (IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs) || !context.Ordered)
			{
				return;
			}
			ProcessPendingWeeklyReportBatchPromptsBudget(context, startTimestamp, budgetMs);
			if (IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs) || !context.BatchPromptsComplete)
			{
				return;
			}
			if (!IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
			{
				FinalizePendingAutoWeeklyReportBuild(context);
			}
		}
		catch (Exception ex)
		{
			_pendingAutoWeeklyReportBuild = null;
			_weeklyReportGenerationInProgress = false;
			Logger.Log("EventWeeklyReport", "[ERROR] deferred auto weekly report build failed: " + ex);
		}
	}

	private bool ProcessPendingAutoWeeklyReportPreviewGroupsBudget(PendingAutoWeeklyReportBuild context, long startTimestamp, double budgetMs)
	{
		if (context == null)
		{
			return true;
		}
		if (!context.PreviewGroupsInitialized)
		{
			context.Groups = new List<WeeklyEventMaterialPreviewGroup>
			{
				CreateWorldWeeklyEventMaterialPreviewGroup()
			};
			foreach (Kingdom kingdom in context.Kingdoms ?? new List<Kingdom>())
			{
				context.Groups.Add(CreateKingdomWeeklyEventMaterialPreviewGroup(kingdom));
			}
			context.RecentActionOwners = (_npcRecentActions ?? new Dictionary<string, List<NpcActionEntry>>()).ToList();
			context.MajorActionOwners = (_npcMajorActions ?? new Dictionary<string, List<NpcActionEntry>>()).ToList();
			context.PreviewGroupsInitialized = true;
			return false;
		}
		while (context.PreviewSourceMaterialIndex < (context.EventSourceMaterialSnapshot?.Count ?? 0) && !IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
		{
			EventSourceMaterialEntry item = context.EventSourceMaterialSnapshot[context.PreviewSourceMaterialIndex++];
			ProcessPendingAutoWeeklyReportSourceMaterial(context, item);
		}
		if (context.PreviewSourceMaterialIndex < (context.EventSourceMaterialSnapshot?.Count ?? 0))
		{
			return false;
		}
		while (!IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs) && !ProcessPendingAutoWeeklyReportActionSlice(context, recentOnly: true))
		{
		}
		if (context.RecentActionOwnerIndex < (context.RecentActionOwners?.Count ?? 0))
		{
			return false;
		}
		while (!IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs) && !ProcessPendingAutoWeeklyReportActionSlice(context, recentOnly: false))
		{
		}
		return context.MajorActionOwnerIndex >= (context.MajorActionOwners?.Count ?? 0);
	}

	private void ProcessPendingAutoWeeklyReportSourceMaterial(PendingAutoWeeklyReportBuild context, EventSourceMaterialEntry item)
	{
		if (context == null || item == null || item.Day < context.StartDay || item.Day > context.EndDay || context.Groups == null || context.Groups.Count == 0)
		{
			return;
		}
		if (item.IncludeInWorld)
		{
			TryAddPreviewSourceMaterial(context.Groups[0].Materials, item);
		}
		for (int i = 0; i < context.Kingdoms.Count && i + 1 < context.Groups.Count; i++)
		{
			Kingdom kingdom = context.Kingdoms[i];
			if (item.IncludeInKingdom && IsKingdomEligibleForWeeklyReport(kingdom) && DoesEventSourceMaterialRelateToKingdom(item, kingdom))
			{
				TryAddPreviewSourceMaterial(context.Groups[i + 1].Materials, item);
			}
		}
	}

	private bool ProcessPendingAutoWeeklyReportActionSlice(PendingAutoWeeklyReportBuild context, bool recentOnly)
	{
		if (context == null)
		{
			return true;
		}
		List<KeyValuePair<string, List<NpcActionEntry>>> owners = recentOnly ? context.RecentActionOwners : context.MajorActionOwners;
		int ownerIndex = recentOnly ? context.RecentActionOwnerIndex : context.MajorActionOwnerIndex;
		int actionIndex = recentOnly ? context.RecentActionIndex : context.MajorActionIndex;
		Hero currentHero = recentOnly ? context.CurrentRecentActionHero : context.CurrentMajorActionHero;
		while (ownerIndex < (owners?.Count ?? 0))
		{
			KeyValuePair<string, List<NpcActionEntry>> owner = owners[ownerIndex];
			List<NpcActionEntry> actions = owner.Value;
			if (actionIndex == 0)
			{
				currentHero = FindHeroById(owner.Key);
			}
			if (currentHero == null || actions == null || actionIndex >= actions.Count)
			{
				ownerIndex++;
				actionIndex = 0;
				currentHero = null;
				continue;
			}
			NpcActionEntry action = actions[actionIndex++];
			ProcessPendingAutoWeeklyReportNpcAction(context, currentHero, action, recentOnly);
			if (recentOnly)
			{
				context.RecentActionOwnerIndex = ownerIndex;
				context.RecentActionIndex = actionIndex;
				context.CurrentRecentActionHero = currentHero;
			}
			else
			{
				context.MajorActionOwnerIndex = ownerIndex;
				context.MajorActionIndex = actionIndex;
				context.CurrentMajorActionHero = currentHero;
			}
			return false;
		}
		if (recentOnly)
		{
			context.RecentActionOwnerIndex = ownerIndex;
			context.RecentActionIndex = 0;
			context.CurrentRecentActionHero = null;
		}
		else
		{
			context.MajorActionOwnerIndex = ownerIndex;
			context.MajorActionIndex = 0;
			context.CurrentMajorActionHero = null;
		}
		return true;
	}

	private void ProcessPendingAutoWeeklyReportNpcAction(PendingAutoWeeklyReportBuild context, Hero hero, NpcActionEntry action, bool recentOnly)
	{
		if (context == null || hero == null || action == null || action.Day < context.StartDay || action.Day > context.EndDay || context.Groups == null || context.Groups.Count == 0)
		{
			return;
		}
		if (ShouldIncludeWorldPreviewAction(hero, action))
		{
			TryAddPreviewActionMaterial(context.Groups[0].Materials, hero, action, recentOnly);
		}
		for (int i = 0; i < context.Kingdoms.Count && i + 1 < context.Groups.Count; i++)
		{
			Kingdom kingdom = context.Kingdoms[i];
			if (!IsKingdomEligibleForWeeklyReport(kingdom) || !DoesNpcActionRelateToKingdom(action, kingdom))
			{
				continue;
			}
			if (!recentOnly || ShouldIncludeKingdomPreviewAction(hero, action, kingdom))
			{
				TryAddPreviewActionMaterial(context.Groups[i + 1].Materials, hero, action, recentOnly);
			}
		}
	}

	private WeeklyEventMaterialPreviewGroup BuildWeeklyEventMaterialPreviewGroupWithSnapshot(Func<WeeklyEventMaterialPreviewGroup> builder, List<EventSourceMaterialEntry> snapshot)
	{
		List<EventSourceMaterialEntry> previous = _weeklyEventSourceMaterialBuildSnapshot;
		try
		{
			_weeklyEventSourceMaterialBuildSnapshot = snapshot;
			return builder?.Invoke();
		}
		finally
		{
			_weeklyEventSourceMaterialBuildSnapshot = previous;
		}
	}

	private void ProcessPendingWeeklyReportAggregationBudget(PendingAutoWeeklyReportBuild context, long startTimestamp, double budgetMs)
	{
		if (context == null || context.AggregationComplete)
		{
			return;
		}
		List<WeeklyEventMaterialPreviewGroup> groups = context.Groups ?? new List<WeeklyEventMaterialPreviewGroup>();
		while (context.AggregationIndex < groups.Count && !IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
		{
			WeeklyEventMaterialPreviewGroup group = groups[context.AggregationIndex++];
			if (group != null)
			{
				ApplyWeeklyPromptMaterialAggregation(group);
			}
			break;
		}
		if (context.AggregationIndex >= groups.Count)
		{
			context.AggregationComplete = true;
		}
	}

	private void ProcessPendingWeeklyReportPromptMaterialsBudget(PendingAutoWeeklyReportBuild context, long startTimestamp, double budgetMs)
	{
		if (context == null || context.PromptMaterialsComplete)
		{
			return;
		}
		List<WeeklyEventMaterialPreviewGroup> groups = context.Groups ?? new List<WeeklyEventMaterialPreviewGroup>();
		if (context.FullReportKingdomIds == null)
		{
			List<string> nearestKingdomIds = GetKingdomIdsByPlayerProximity(groups.Where((WeeklyEventMaterialPreviewGroup x) => string.Equals((x.GroupKind ?? "").Trim(), "kingdom", StringComparison.OrdinalIgnoreCase)).Select((WeeklyEventMaterialPreviewGroup x) => x.KingdomId)).Where((string x) => !string.IsNullOrWhiteSpace(x)).Select((string x) => x.Trim()).Distinct(StringComparer.OrdinalIgnoreCase).Take(3).ToList();
			if (nearestKingdomIds.Count == 0)
			{
				nearestKingdomIds = groups.Where((WeeklyEventMaterialPreviewGroup x) => string.Equals((x.GroupKind ?? "").Trim(), "kingdom", StringComparison.OrdinalIgnoreCase)).Select((WeeklyEventMaterialPreviewGroup x) => (x.KingdomId ?? "").Trim()).Where((string x) => !string.IsNullOrWhiteSpace(x)).Distinct(StringComparer.OrdinalIgnoreCase).Take(3).ToList();
			}
			context.FullReportKingdomIds = nearestKingdomIds;
		}
		HashSet<string> fullReportKingdomIds = new HashSet<string>(context.FullReportKingdomIds ?? new List<string>(), StringComparer.OrdinalIgnoreCase);
		while (context.PromptMaterialIndex < groups.Count && !IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
		{
			WeeklyEventMaterialPreviewGroup group = groups[context.PromptMaterialIndex++];
			if (group == null)
			{
				continue;
			}
			bool isKingdom = string.Equals((group?.GroupKind ?? "").Trim(), "kingdom", StringComparison.OrdinalIgnoreCase);
			bool shortOnly = isKingdom && !fullReportKingdomIds.Contains((group?.KingdomId ?? "").Trim());
			PrepareWeeklyPromptMaterialsForGroup(group, shortOnly);
			break;
		}
		if (context.PromptMaterialIndex >= groups.Count)
		{
			context.PromptMaterialsComplete = true;
		}
	}

	private void ProcessPendingWeeklyReportBatchPromptsBudget(PendingAutoWeeklyReportBuild context, long startTimestamp, double budgetMs)
	{
		if (context == null || context.BatchPromptsComplete)
		{
			return;
		}
		if (context.Batches == null || context.Batches.Count == 0)
		{
			context.Batches = BuildWeeklyReportBatchRequests((context.Groups ?? new List<WeeklyEventMaterialPreviewGroup>()).Where((WeeklyEventMaterialPreviewGroup x) => x != null).ToList(), context.WeekIndex, context.StartDay, context.EndDay);
		}
		while (context.BatchPromptIndex < context.Batches.Count && !IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
		{
			PrepareWeeklyReportBatchPrompt(context.Batches[context.BatchPromptIndex]);
			context.BatchPromptIndex++;
			break;
		}
		if (context.BatchPromptIndex >= context.Batches.Count)
		{
			context.BatchPromptsComplete = true;
		}
	}

	private void FinalizePendingAutoWeeklyReportBuild(PendingAutoWeeklyReportBuild context)
	{
		if (context == null)
		{
			return;
		}
		List<WeeklyEventMaterialPreviewGroup> groups = (context.Groups ?? new List<WeeklyEventMaterialPreviewGroup>()).Where((WeeklyEventMaterialPreviewGroup x) => x != null).ToList();
		List<WeeklyReportBatchRequest> batches = (context.Batches ?? new List<WeeklyReportBatchRequest>()).Where((WeeklyReportBatchRequest x) => x != null && x.Groups != null && x.Groups.Count > 0).ToList();
		_pendingAutoWeeklyReportBuild = null;
		_ = GenerateAutoWeeklyReportsAsync(groups, context.WeekIndex, context.StartDay, context.EndDay, batches);
	}

	private void StartAutoWeeklyReportsForWeek(int weekIndex, int currentGameDayIndexSafe)
	{
		if (weekIndex <= 0 || _lastAutoGeneratedWeeklyReportWeek >= weekIndex || _weeklyReportGenerationInProgress)
		{
			return;
		}
		if (_automaticKingdomRebellionFlowActive)
		{
			_pendingAutoWeeklyReportWeek = Math.Max(_pendingAutoWeeklyReportWeek, weekIndex);
			return;
		}
		int startDay = WeeklyReportSchedulePolicy.GetStartDay(weekIndex);
		int endDay = WeeklyReportSchedulePolicy.GetEndDay(weekIndex);
		List<WeeklyEventMaterialPreviewGroup> list = OrderWeeklyReportGenerationGroups(BuildWeeklyEventMaterialPreviewGroups(startDay, endDay));
		_weeklyReportGenerationInProgress = true;
		_pendingAutoWeeklyReportWeek = 0;
		_ = GenerateAutoWeeklyReportsAsync(list, weekIndex, startDay, endDay);
	}

	private void TryStartDeferredAutoWeeklyReports()
	{
		if (_pendingAutoWeeklyReportWeek <= 0 || _weeklyReportGenerationInProgress || _automaticKingdomRebellionFlowActive)
		{
			return;
		}
		DuelSettings settings = DuelSettings.GetSettings();
		if (settings == null || !settings.AutoGenerateWeeklyReports)
		{
			return;
		}
		int currentGameDayIndexSafe = GetCurrentGameDayIndexSafe();
		if (currentGameDayIndexSafe <= 0)
		{
			return;
		}
		int num = currentGameDayIndexSafe / 7;
		if (num < _pendingAutoWeeklyReportWeek)
		{
			return;
		}
		int missingWeek = WeeklyReportSchedulePolicy.ResolveOldestMissingWeek(_lastAutoGeneratedWeeklyReportWeek, currentGameDayIndexSafe);
		if (missingWeek <= 0)
		{
			_pendingAutoWeeklyReportWeek = 0;
			return;
		}
		if (IsDeferredDailyMaintenanceEnabled())
		{
			QueueDeferredAutoWeeklyReportsForWeek(_pendingAutoWeeklyReportWeek, currentGameDayIndexSafe, "deferred_auto_weekly_resume");
		}
		else
		{
			StartAutoWeeklyReportsForWeek(missingWeek, currentGameDayIndexSafe);
		}
	}

	private async Task GenerateAutoWeeklyReportsAsync(List<WeeklyEventMaterialPreviewGroup> groups, int weekIndex, int startDay, int endDay, List<WeeklyReportBatchRequest> preparedBatches = null)
	{
		long runtimeGeneration = SaveRuntimeGuard.CaptureGeneration();
		try
		{
			WeeklyReportGenerationResult weeklyReportGenerationResult = await GenerateWeeklyReportsBatchedAsyncInternal(groups, weekIndex, startDay, endDay, BuildWeeklyEpicWeekLabel(weekIndex) + "自动周报", openViewerWhenDone: false, queueBlockingPopupOnFatalFailure: true, isAutoGeneration: true, popupCandidateKingdomIdsOverride: null, preparedBatches: preparedBatches, runtimeGeneration: runtimeGeneration);
			if (!SaveRuntimeGuard.IsStale(runtimeGeneration, "auto_weekly_report_complete") && weeklyReportGenerationResult != null && weeklyReportGenerationResult.Completed && !weeklyReportGenerationResult.BlockedByFatalFailure)
			{
				_lastAutoGeneratedWeeklyReportWeek = Math.Max(_lastAutoGeneratedWeeklyReportWeek, weekIndex);
			}
		}
		catch (Exception ex)
		{
			Logger.Log("EventWeeklyReport", "[ERROR] GenerateAutoWeeklyReportsAsync failed: " + ex);
		}
		finally
		{
			if (SaveRuntimeGuard.IsCurrentGeneration(runtimeGeneration))
			{
				_weeklyReportGenerationInProgress = false;
			}
		}
	}

	// Normal callers keep the existing sanitation behavior; database reload passes false to preserve unrelated dynamic history exactly.
