	private static string BuildTownChangeQualitativeLine(string label, float delta, float threshold)
	{
		string text = (label ?? "").Trim();
		string intensity = MathF.Abs(delta) >= Math.Max(threshold * 3f, threshold + 0.001f) ? "明显" : "小幅";
		bool rise = delta > 0f;
		switch (text)
		{
		case "繁荣":
			return text + intensity + (rise ? "扩张" : "回落");
		case "忠诚度":
			return text + intensity + (rise ? "改善" : "走低");
		case "治安":
			return text + intensity + (rise ? "改善" : "恶化");
		case "粮食":
			return text + intensity + (rise ? "恢复" : "吃紧");
		case "民兵":
		case "驻军":
			return text + intensity + (rise ? "增加" : "减少");
		default:
			return text + intensity + (rise ? "改善" : "走低");
		}
	}

	private static NpcActionEntry CreateNpcActionEntry(Hero hero, string text, string stableKey, int day, int order, int sequence, NpcActionFacts facts, bool isMajor)
	{
		NpcActionFacts npcActionFacts = facts ?? CreateNpcActionFacts("", hero);
		if (string.IsNullOrWhiteSpace(npcActionFacts.ActorHeroId))
		{
			ApplyActorFacts(npcActionFacts, hero);
		}
		npcActionFacts.IsMajor = isMajor;
		NpcActionEntry npcActionEntry = new NpcActionEntry
		{
			Day = Math.Max(0, day),
			Order = Math.Max(1, order),
			Sequence = Math.Max(0, sequence),
			GameDate = GetCurrentGameDateTextSafe(),
			Text = (text ?? "").Trim(),
			StableKey = NormalizeNpcActionStableKey(stableKey, text),
			ActionKind = (npcActionFacts.ActionKind ?? "").Trim(),
			ActorHeroId = (npcActionFacts.ActorHeroId ?? "").Trim(),
			ActorClanId = (npcActionFacts.ActorClanId ?? "").Trim(),
			ActorKingdomId = (npcActionFacts.ActorKingdomId ?? "").Trim(),
			TargetHeroId = (npcActionFacts.TargetHeroId ?? "").Trim(),
			TargetClanId = (npcActionFacts.TargetClanId ?? "").Trim(),
			TargetKingdomId = (npcActionFacts.TargetKingdomId ?? "").Trim(),
			SettlementId = (npcActionFacts.SettlementId ?? "").Trim(),
			SettlementName = (npcActionFacts.SettlementName ?? "").Trim(),
			SettlementOwnerHeroId = (npcActionFacts.SettlementOwnerHeroId ?? "").Trim(),
			SettlementOwnerClanId = (npcActionFacts.SettlementOwnerClanId ?? "").Trim(),
			SettlementOwnerKingdomId = (npcActionFacts.SettlementOwnerKingdomId ?? "").Trim(),
			PreviousSettlementOwnerHeroId = (npcActionFacts.PreviousSettlementOwnerHeroId ?? "").Trim(),
			PreviousSettlementOwnerClanId = (npcActionFacts.PreviousSettlementOwnerClanId ?? "").Trim(),
			PreviousSettlementOwnerKingdomId = (npcActionFacts.PreviousSettlementOwnerKingdomId ?? "").Trim(),
			LocationText = (npcActionFacts.LocationText ?? "").Trim(),
			Won = npcActionFacts.Won,
			IsMajor = isMajor
		};
		CopyFactIds(npcActionFacts.RelatedHeroIds, npcActionEntry.RelatedHeroIds);
		CopyFactIds(npcActionFacts.RelatedClanIds, npcActionEntry.RelatedClanIds);
		CopyFactIds(npcActionFacts.RelatedKingdomIds, npcActionEntry.RelatedKingdomIds);
		return npcActionEntry;
	}

	private static string RepairLegacyVillageRaidDefenseActionText(NpcActionEntry entry, string sourceText)
	{
		string text = (sourceText ?? "").Trim();
		if (!IsLegacyVillageRaidDefenseAction(entry, text, out bool isAftermath))
		{
			return text;
		}
		string place = (entry?.LocationText ?? "").Trim();
		if (string.IsNullOrWhiteSpace(place))
		{
			place = (entry?.SettlementName ?? "").Trim();
		}
		if (string.IsNullOrWhiteSpace(place))
		{
			place = "当地村庄";
		}
		bool? won = entry?.Won;
		string corrected = isAftermath
			? (won == true
				? (place + "的袭掠已经结束，你协助守军击退了袭掠者，正在整顿部队。")
				: (won == false
					? (place + "的袭掠已经结束，袭掠者已经得手；你正在收拢部队并处理残局。")
					: (place + "的袭掠已经结束，你正在协助守军整顿部队。")))
			: (won == true
				? ("你在" + place + "参与村庄保卫战，击退了袭掠者。")
				: (won == false
					? ("你在" + place + "参与村庄保卫战时失利，未能阻止袭掠者。")
					: ("你在" + place + "参与了村庄保卫战。")));
		int sentenceEnd = text.IndexOf('。');
		if (sentenceEnd < 0 || sentenceEnd >= text.Length - 1)
		{
			return corrected;
		}
		string detail = text.Substring(sentenceEnd + 1).Trim();
		return string.IsNullOrWhiteSpace(detail) ? corrected : (corrected + " " + detail);
	}

	private static bool IsLegacyVillageRaidDefenseAction(NpcActionEntry entry, string text, out bool isAftermath)
	{
		isAftermath = false;
		string stableKey = (entry?.StableKey ?? "").Trim();
		if (stableKey.IndexOf(":side:defender:hero:", StringComparison.OrdinalIgnoreCase) < 0)
		{
			return false;
		}
		string actionKind = (entry?.ActionKind ?? "").Trim();
		isAftermath = string.Equals(actionKind, "map_event_aftermath", StringComparison.OrdinalIgnoreCase)
			|| stableKey.StartsWith("mapevent_aftermath:", StringComparison.OrdinalIgnoreCase);
		bool isMapEvent = string.Equals(actionKind, "map_event", StringComparison.OrdinalIgnoreCase)
			|| stableKey.StartsWith("mapevent:", StringComparison.OrdinalIgnoreCase);
		if (!isMapEvent && !isAftermath)
		{
			return false;
		}
		if (isAftermath)
		{
			return text.IndexOf("的袭掠已经结束", StringComparison.OrdinalIgnoreCase) >= 0
				&& (text.IndexOf("清点缴获", StringComparison.OrdinalIgnoreCase) >= 0 || text.IndexOf("收拢部队并处理残局", StringComparison.OrdinalIgnoreCase) >= 0);
		}
		return text.IndexOf("发动的袭掠中", StringComparison.OrdinalIgnoreCase) >= 0;
	}

	private static List<NpcActionEntry> SanitizeNpcActionEntries(List<NpcActionEntry> source, bool keepOnlyRecentWindow)
	{
		List<NpcActionEntry> list = new List<NpcActionEntry>();
		if (source == null || source.Count <= 0)
		{
			return list;
		}
		int num = GetCurrentGameDayIndexSafe();
		int num2 = num - RecentNpcActionWindowDays + 1;
		int num3 = 0;
		int num4 = 0;
		foreach (NpcActionEntry item in source)
		{
			if (item == null)
			{
				continue;
			}
			string text = RepairLegacyVillageRaidDefenseActionText(item, (item.Text ?? "").Trim());
			if (string.IsNullOrWhiteSpace(text))
			{
				continue;
			}
			if (keepOnlyRecentWindow && item.Day < num2)
			{
				continue;
			}
			if (!keepOnlyRecentWindow && ShouldSuppressNpcMajorAction(item.ActionKind, item.StableKey, text))
			{
				continue;
			}
			list.Add(new NpcActionEntry
			{
				Day = Math.Max(0, item.Day),
				Order = ((item.Order > 0) ? item.Order : (++num3)),
				Sequence = ((item.Sequence > 0) ? item.Sequence : (++num4)),
				GameDate = (item.GameDate ?? "").Trim(),
				Text = text,
				StableKey = NormalizeNpcActionStableKey(item.StableKey, text),
				ActionKind = (item.ActionKind ?? "").Trim(),
				ActorHeroId = (item.ActorHeroId ?? "").Trim(),
				ActorClanId = (item.ActorClanId ?? "").Trim(),
				ActorKingdomId = (item.ActorKingdomId ?? "").Trim(),
				TargetHeroId = (item.TargetHeroId ?? "").Trim(),
				TargetClanId = (item.TargetClanId ?? "").Trim(),
				TargetKingdomId = (item.TargetKingdomId ?? "").Trim(),
				SettlementId = (item.SettlementId ?? "").Trim(),
				SettlementName = (item.SettlementName ?? "").Trim(),
				SettlementOwnerHeroId = (item.SettlementOwnerHeroId ?? "").Trim(),
				SettlementOwnerClanId = (item.SettlementOwnerClanId ?? "").Trim(),
				SettlementOwnerKingdomId = (item.SettlementOwnerKingdomId ?? "").Trim(),
				PreviousSettlementOwnerHeroId = (item.PreviousSettlementOwnerHeroId ?? "").Trim(),
				PreviousSettlementOwnerClanId = (item.PreviousSettlementOwnerClanId ?? "").Trim(),
				PreviousSettlementOwnerKingdomId = (item.PreviousSettlementOwnerKingdomId ?? "").Trim(),
				LocationText = (item.LocationText ?? "").Trim(),
				Won = item.Won,
				IsMajor = item.IsMajor
			});
			CopyFactIds(item.RelatedHeroIds, list[list.Count - 1].RelatedHeroIds);
			CopyFactIds(item.RelatedClanIds, list[list.Count - 1].RelatedClanIds);
			CopyFactIds(item.RelatedKingdomIds, list[list.Count - 1].RelatedKingdomIds);
		}
		return list.OrderBy((NpcActionEntry x) => x.Day).ThenBy((NpcActionEntry x) => (x.Sequence > 0) ? x.Sequence : int.MaxValue).ThenBy((NpcActionEntry x) => x.Order).ThenBy((NpcActionEntry x) => x.GameDate ?? "", StringComparer.Ordinal).ToList();
	}

	private static bool ShouldSuppressNpcMajorAction(string actionKind, string stableKey, string text)
	{
		string text2 = (actionKind ?? "").Trim().ToLowerInvariant();
		switch (text2)
		{
		case "prisoner_taken_captor":
		case "prisoner_taken_prisoner":
		case "prisoner_released_captor":
		case "prisoner_released_prisoner":
		case "army_create":
		case "army_join":
			return true;
		}
		string text3 = (stableKey ?? "").Trim().ToLowerInvariant();
		if (text3.StartsWith("prisoner_taken:", StringComparison.OrdinalIgnoreCase) || text3.StartsWith("prisoner_released:", StringComparison.OrdinalIgnoreCase) || text3.StartsWith("army_create:", StringComparison.OrdinalIgnoreCase) || text3.StartsWith("army_join:", StringComparison.OrdinalIgnoreCase))
		{
			return true;
		}
		string text4 = (text ?? "").Trim();
		return (text4.IndexOf("俘虏了", StringComparison.OrdinalIgnoreCase) >= 0 || text4.IndexOf("被", StringComparison.OrdinalIgnoreCase) >= 0 && text4.IndexOf("俘虏", StringComparison.OrdinalIgnoreCase) >= 0 || text4.IndexOf("获释", StringComparison.OrdinalIgnoreCase) >= 0 || text4.IndexOf("成功逃脱", StringComparison.OrdinalIgnoreCase) >= 0 || text4.IndexOf("不再是你的囚犯", StringComparison.OrdinalIgnoreCase) >= 0 || text4.IndexOf("组建并统领了", StringComparison.OrdinalIgnoreCase) >= 0 || text4.IndexOf("加入了", StringComparison.OrdinalIgnoreCase) >= 0 && text4.IndexOf("军团", StringComparison.OrdinalIgnoreCase) >= 0);
	}

	private void RecordNpcMajorAction(Hero hero, string text, string stableKey, NpcActionFacts facts = null, bool allowNonLordHero = false)
	{
		if (ShouldSuppressNpcMajorAction(facts?.ActionKind, stableKey, text))
		{
			return;
		}
		RecordNpcActionInternal(_npcMajorActions, hero, text, stableKey, keepOnlyRecentWindow: false, dedupeAcrossWindow: false, MaxMajorNpcActionEntriesPerHero, facts, isMajor: true, allowNonLordHero);
	}

	private void RecordNpcRecentAction(Hero hero, string text, string stableKey, bool dedupeAcrossWindow = false, NpcActionFacts facts = null, bool allowNonLordHero = false)
	{
		RecordNpcActionInternal(_npcRecentActions, hero, text, stableKey, keepOnlyRecentWindow: true, dedupeAcrossWindow, MaxRecentNpcActionEntriesPerHero, facts, isMajor: false, allowNonLordHero);
	}

	private void RecordPlayerNotorietyActionFromNpcAction(string text, string stableKey, NpcActionFacts facts, bool isMajor)
	{
		try
		{
			string normalizedText = (text ?? "").Replace("\r", " ").Replace("\n", " ").Trim();
			if (string.IsNullOrWhiteSpace(normalizedText))
			{
				return;
			}
			int day = GetCurrentGameDayIndexSafe();
			int sequence = ++_npcActionGlobalOrderCounter;
			string actionKind = (facts?.ActionKind ?? "").Trim();
			string settlementId = (facts?.SettlementId ?? "").Trim();
			string settlementName = (facts?.SettlementName ?? "").Trim();
			string locationText = (facts?.LocationText ?? "").Trim();
			Settlement settlement = ResolveSettlementById(settlementId);
			string settlementCultureId = settlement?.Culture?.StringId ?? "";
			string actorCultureId = Hero.MainHero?.Culture?.StringId ?? "";
			string targetCultureId = ResolveHeroCultureId(facts?.TargetHeroId);
			PlayerNotorietyBehavior.RecordPlayerActionForExternal(normalizedText, stableKey, actionKind, isMajor, day, GetCurrentGameDateTextSafe(), sequence, settlementId, settlementName, locationText, actorCultureId, targetCultureId, settlementCultureId, facts?.Won);
		}
		catch (Exception ex)
		{
			Logger.Log("PlayerNotoriety", "RecordPlayerNotorietyActionFromNpcAction failed: " + ex.Message);
		}
	}

	private static string ResolveHeroCultureId(string heroId)
	{
		try
		{
			return (FindHeroById(heroId)?.Culture?.StringId ?? "").Trim();
		}
		catch
		{
			return "";
		}
	}

	private static Settlement ResolveSettlementById(string settlementId)
	{
		string text = (settlementId ?? "").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return null;
		}
		try
		{
			return Settlement.Find(text) ?? Settlement.All.FirstOrDefault((Settlement x) => x != null && string.Equals((x.StringId ?? "").Trim(), text, StringComparison.OrdinalIgnoreCase));
		}
		catch
		{
			return null;
		}
	}

	private void RecordNpcActionInternal(Dictionary<string, List<NpcActionEntry>> storage, Hero hero, string text, string stableKey, bool keepOnlyRecentWindow, bool dedupeAcrossWindow, int maxEntries, NpcActionFacts facts, bool isMajor, bool allowNonLordHero = false)
	{
		try
		{
			if (storage == null || !ShouldTrackNpcActionHero(hero, allowNonLordHero))
			{
				return;
			}
			if (hero == Hero.MainHero)
			{
				RecordPlayerNotorietyActionFromNpcAction(text, stableKey, facts, isMajor);
				return;
			}
			string npcActionHeroKey = GetNpcActionHeroKey(hero);
			string text2 = (text ?? "").Replace("\r", " ").Replace("\n", " ").Trim();
			if (string.IsNullOrWhiteSpace(npcActionHeroKey) || string.IsNullOrWhiteSpace(text2))
			{
				return;
			}
			string text3 = NormalizeNpcActionStableKey(stableKey, text2);
			int currentGameDayIndexSafe = GetCurrentGameDayIndexSafe();
			if (!storage.TryGetValue(npcActionHeroKey, out var value) || value == null)
			{
				value = new List<NpcActionEntry>();
				storage[npcActionHeroKey] = value;
			}
			bool entriesChanged = RemoveInvalidNpcActionEntries(value, keepOnlyRecentWindow ? currentGameDayIndexSafe - RecentNpcActionWindowDays + 1 : int.MinValue, keepOnlyRecentWindow);
			if (keepOnlyRecentWindow && entriesChanged)
			{
				RefreshNpcRecentActionStableKeyIndexForHero(npcActionHeroKey, value);
			}
			if (dedupeAcrossWindow)
			{
				if ((keepOnlyRecentWindow && IsNpcRecentActionStableKeyKnown(npcActionHeroKey, text3)) || ContainsNpcActionStableKey(value, text3))
				{
					return;
				}
			}
			else if (ContainsNpcActionForDay(value, currentGameDayIndexSafe, text3, text2))
			{
				return;
			}
			int order = GetNextNpcActionOrder(value, currentGameDayIndexSafe);
			int sequence = ++_npcActionGlobalOrderCounter;
			NpcActionEntry npcActionEntry = CreateNpcActionEntry(hero, text2, text3, currentGameDayIndexSafe, order, sequence, facts, isMajor);
			value.Add(npcActionEntry);
			if (value.Count > 1 && CompareNpcActionTimeline(value[value.Count - 2], npcActionEntry) > 0)
			{
				value.Sort(CompareNpcActionTimeline);
			}
			if (maxEntries > 0 && value.Count > maxEntries)
			{
				value.RemoveRange(0, value.Count - maxEntries);
			}
			if (keepOnlyRecentWindow)
			{
				RefreshNpcRecentActionStableKeyIndexForHero(npcActionHeroKey, value);
			}
		}
		catch (Exception ex)
		{
			Logger.Log("NpcAction", "[ERROR] RecordNpcActionInternal: " + ex.Message);
		}
	}

	private bool HasRecentNpcActionStableKeyWithinWindow(Hero hero, string stableKey, int currentDay)
	{
		string heroKey = GetNpcActionHeroKey(hero);
		string normalizedStableKey = NormalizeNpcActionStableKey(stableKey, "");
		if (string.IsNullOrWhiteSpace(heroKey)
			|| string.IsNullOrWhiteSpace(normalizedStableKey)
			|| _npcRecentActions == null
			|| !_npcRecentActions.TryGetValue(heroKey, out List<NpcActionEntry> entries)
			|| entries == null)
		{
			return false;
		}
		int minimumDay = currentDay - RecentNpcActionWindowDays + 1;
		for (int index = entries.Count - 1; index >= 0; index--)
		{
			NpcActionEntry entry = entries[index];
			if (entry != null
				&& entry.Day >= minimumDay
				&& !string.IsNullOrWhiteSpace(entry.Text)
				&& string.Equals(entry.StableKey ?? "", normalizedStableKey, StringComparison.OrdinalIgnoreCase))
			{
				return true;
			}
		}
		return false;
	}

	private static bool RemoveInvalidNpcActionEntries(List<NpcActionEntry> entries, int minimumDay, bool keepOnlyRecentWindow)
	{
		if (entries == null || entries.Count == 0)
		{
			return false;
		}
		bool removedAny = false;
		for (int index = entries.Count - 1; index >= 0; index--)
		{
			NpcActionEntry entry = entries[index];
			if (entry == null || string.IsNullOrWhiteSpace(entry.Text) || (keepOnlyRecentWindow && entry.Day < minimumDay))
			{
				entries.RemoveAt(index);
				removedAny = true;
			}
		}
		return removedAny;
	}

	private static bool ContainsNpcActionStableKey(List<NpcActionEntry> entries, string stableKey)
	{
		if (entries == null)
		{
			return false;
		}
		for (int index = 0; index < entries.Count; index++)
		{
			NpcActionEntry entry = entries[index];
			if (entry != null && string.Equals(entry.StableKey ?? "", stableKey, StringComparison.OrdinalIgnoreCase))
			{
				return true;
			}
		}
		return false;
	}

	private static bool ContainsNpcActionForDay(List<NpcActionEntry> entries, int day, string stableKey, string text)
	{
		if (entries == null)
		{
			return false;
		}
		for (int index = 0; index < entries.Count; index++)
		{
			NpcActionEntry entry = entries[index];
			if (entry != null
				&& entry.Day == day
				&& (string.Equals(entry.StableKey ?? "", stableKey, StringComparison.OrdinalIgnoreCase) || string.Equals((entry.Text ?? "").Trim(), text, StringComparison.Ordinal)))
			{
				return true;
			}
		}
		return false;
	}

	private static int GetNextNpcActionOrder(List<NpcActionEntry> entries, int day)
	{
		int highestOrder = 0;
		if (entries != null)
		{
			for (int index = 0; index < entries.Count; index++)
			{
				NpcActionEntry entry = entries[index];
				if (entry != null && entry.Day == day && entry.Order > highestOrder)
				{
					highestOrder = entry.Order;
				}
			}
		}
		return highestOrder + 1;
	}

	private static int CompareNpcActionTimeline(NpcActionEntry left, NpcActionEntry right)
	{
		if (ReferenceEquals(left, right))
		{
			return 0;
		}
		if (left == null)
		{
			return -1;
		}
		if (right == null)
		{
			return 1;
		}
		int result = left.Day.CompareTo(right.Day);
		if (result != 0)
		{
			return result;
		}
		result = (left.Sequence > 0 ? left.Sequence : int.MaxValue).CompareTo(right.Sequence > 0 ? right.Sequence : int.MaxValue);
		if (result != 0)
		{
			return result;
		}
		result = left.Order.CompareTo(right.Order);
		return result != 0 ? result : string.Compare(left.GameDate ?? "", right.GameDate ?? "", StringComparison.Ordinal);
	}

	private static string GetArmyDisplayName(Army army)
	{
		string text = army?.Name?.ToString();
		if (!string.IsNullOrWhiteSpace(text))
		{
			return text.Trim();
		}
		Hero hero = army?.ArmyOwner ?? army?.LeaderParty?.LeaderHero;
		string text2 = hero?.Name?.ToString();
		return string.IsNullOrWhiteSpace(text2) ? "一支军团" : (text2.Trim() + "的军团");
	}

	private static Settlement ResolveSiegeSettlement(SiegeEvent siegeEvent)
	{
		if (siegeEvent == null)
		{
			return null;
		}
		try
		{
			foreach (Settlement item in Settlement.All)
			{
				if (item?.SiegeEvent == siegeEvent)
				{
					return item;
				}
			}
		}
		catch
		{
		}
		return null;
	}

	private static IEnumerable<Hero> GetHeroesFromSiegeEventSide(SiegeEvent siegeEvent, BattleSideEnum side)
	{
		HashSet<string> hashSet = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		List<Hero> list = new List<Hero>();
		if (siegeEvent == null)
		{
			return list;
		}
		try
		{
			foreach (PartyBase involvedPartiesForEventType in siegeEvent.GetInvolvedPartiesForEventType(MapEvent.BattleTypes.Siege))
			{
				if (involvedPartiesForEventType == null || involvedPartiesForEventType.Side != side)
				{
					continue;
				}
				Hero leaderHero = involvedPartiesForEventType.LeaderHero;
				string npcActionHeroKey = (leaderHero == Hero.MainHero) ? "__player__" : GetNpcActionHeroKey(leaderHero);
				if (ShouldMentionBattleHero(leaderHero) && hashSet.Add(npcActionHeroKey))
				{
					list.Add(leaderHero);
				}
			}
		}
		catch
		{
		}
		return list;
	}

	private static string GetMapEventLocationLabel(MapEvent mapEvent)
	{
		string text = mapEvent?.MapEventSettlement?.Name?.ToString();
		return string.IsNullOrWhiteSpace(text) ? "野外" : text.Trim();
	}

	private static string GetPrimaryOtherSideLabel(MapEventSide side)
	{
		string text = side?.LeaderParty?.LeaderHero?.Name?.ToString();
		if (!string.IsNullOrWhiteSpace(text))
		{
			return text.Trim();
		}
		text = BuildMapEventNonLordPartyListText(side, 3, includeCounts: false);
		if (!string.IsNullOrWhiteSpace(text))
		{
			return text.Trim();
		}
		text = side?.LeaderParty?.Name?.ToString();
		if (!string.IsNullOrWhiteSpace(text))
		{
			return text.Trim();
		}
		text = side?.MapFaction?.Name?.ToString();
		return string.IsNullOrWhiteSpace(text) ? "敌军" : text.Trim();
	}

	private static string BuildMapEventSideNarrativeLabel(MapEventSide side)
	{
		if (side == null)
		{
			return "敌军";
		}
		if (CountTrackedLordParties(side) > 0)
		{
			return GetFactionDisplayName(side.MapFaction, GetPrimaryOtherSideLabel(side));
		}
		string text = BuildMapEventNonLordPartyListText(side, 3, includeCounts: false);
		if (!string.IsNullOrWhiteSpace(text))
		{
			return text.Trim();
		}
		return GetFactionDisplayName(side.MapFaction, GetPrimaryOtherSideLabel(side));
	}

	private static string BuildMapEventNonLordPartyListText(MapEventSide side, int maxCount = 5, bool includeCounts = true)
	{
		if (side?.Parties == null)
		{
			return "";
		}
		List<string> list = new List<string>();
		HashSet<string> hashSet = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		try
		{
			foreach (MapEventParty party in side.Parties)
			{
				PartyBase partyBase = party?.Party;
				if (partyBase == null || ShouldMentionBattleHero(partyBase.LeaderHero))
				{
					continue;
				}
				string text = BuildMapEventNonLordPartyDisplayText(partyBase, party, includeCounts);
				if (string.IsNullOrWhiteSpace(text) || !hashSet.Add(text))
				{
					continue;
				}
				list.Add(text);
			}
		}
		catch
		{
		}
		if (list.Count == 0)
		{
			return "";
		}
		int count = Math.Max(1, maxCount);
		if (list.Count <= count)
		{
			return string.Join("、", list);
		}
		return string.Join("、", list.Take(count)) + "等" + list.Count + "支";
	}

	private static string BuildMapEventNonLordPartyDisplayText(PartyBase partyBase, MapEventParty party, bool includeCounts)
	{
		if (partyBase == null)
		{
			return "";
		}
		string text = GetPartyBaseDisplayName(partyBase);
		string text2 = GetMapEventNonLordPartyTypeLabel(partyBase);
		if (string.IsNullOrWhiteSpace(text))
		{
			text = string.IsNullOrWhiteSpace(text2) ? "非领主部队" : text2;
			text2 = "";
		}
		List<string> list = new List<string>();
		if (!string.IsNullOrWhiteSpace(text2) && text.IndexOf(text2, StringComparison.OrdinalIgnoreCase) < 0)
		{
			list.Add(text2);
		}
		if (includeCounts)
		{
			int mapEventPartyCommittedTroopCount = GetMapEventPartyCommittedTroopCount(party);
			if (mapEventPartyCommittedTroopCount > 0)
			{
				list.Add("约" + mapEventPartyCommittedTroopCount + "人");
			}
		}
		return list.Count > 0 ? (text.Trim() + "（" + string.Join("，", list) + "）") : text.Trim();
	}

	private static string GetPartyBaseDisplayName(PartyBase partyBase)
	{
		if (partyBase == null)
		{
			return "";
		}
		try
		{
			string text = partyBase.Name?.ToString();
			if (!string.IsNullOrWhiteSpace(text))
			{
				return text.Trim();
			}
			text = partyBase.MobileParty?.Name?.ToString();
			if (!string.IsNullOrWhiteSpace(text))
			{
				return text.Trim();
			}
			text = partyBase.MobileParty?.StringId;
			return string.IsNullOrWhiteSpace(text) ? "" : text.Trim();
		}
		catch
		{
			return "";
		}
	}

	private static string GetMapEventNonLordPartyTypeLabel(PartyBase partyBase)
	{
		try
		{
			MobileParty mobileParty = partyBase?.MobileParty;
			if (mobileParty == null)
			{
				return "";
			}
			if (mobileParty.IsVillager || mobileParty.PartyComponent is VillagerPartyComponent)
			{
				return "村民队";
			}
			if (mobileParty.IsCaravan || mobileParty.PartyComponent is CaravanPartyComponent)
			{
				return "商队";
			}
			if (mobileParty.IsPatrolParty || mobileParty.PartyComponent is PatrolPartyComponent)
			{
				return "巡逻队";
			}
			if (mobileParty.IsMilitia || mobileParty.PartyComponent is MilitiaPartyComponent)
			{
				return "民兵队";
			}
			if (mobileParty.IsGarrison || mobileParty.PartyComponent is GarrisonPartyComponent)
			{
				return "驻军";
			}
			if (IsBanditOrOutlawPartyBase(partyBase) || mobileParty.PartyComponent is BanditPartyComponent)
			{
				return "匪帮";
			}
			if (mobileParty.PartyComponent is CustomPartyComponent)
			{
				return "自定义部队";
			}
		}
		catch
		{
		}
		return "非领主部队";
	}

	private static int GetMapEventTroopCount(MapEvent mapEvent)
	{
		int num = GetMapEventSideCommittedTroopCount(mapEvent?.AttackerSide) + GetMapEventSideCommittedTroopCount(mapEvent?.DefenderSide);
		if (num > 0)
		{
			return num;
		}
		try
		{
			return Math.Max(0, mapEvent?.GetNumberOfInvolvedMen() ?? 0);
		}
		catch
		{
			return 0;
		}
	}

	private static int CountTrackedLordParties(MapEventSide side)
	{
		int num = 0;
		try
		{
			if (side?.Parties == null)
			{
				return 0;
			}
			foreach (MapEventParty party in side.Parties)
			{
				if (ShouldTrackNpcActionHero(party?.Party?.LeaderHero))
				{
					num++;
				}
			}
		}
		catch
		{
		}
		return num;
	}

	private static int GetPartyBaseTroopCount(PartyBase party)
	{
		try
		{
			return Math.Max(0, party?.MemberRoster?.TotalManCount ?? 0);
		}
		catch
		{
			return 0;
		}
	}

	private static int GetSiegeEventTroopCount(SiegeEvent siegeEvent)
	{
		if (siegeEvent == null)
		{
			return 0;
		}
		int num = 0;
		HashSet<PartyBase> hashSet = new HashSet<PartyBase>();
		try
		{
			foreach (PartyBase involvedPartiesForEventType in siegeEvent.GetInvolvedPartiesForEventType(MapEvent.BattleTypes.Siege))
			{
				if (involvedPartiesForEventType != null && hashSet.Add(involvedPartiesForEventType))
				{
					num += GetPartyBaseTroopCount(involvedPartiesForEventType);
				}
			}
		}
		catch
		{
		}
		return Math.Max(0, num);
	}

	private static bool ShouldRecordMajorBattleAction(int troopCount)
	{
		return troopCount > MajorNpcBattleTroopThreshold;
	}

	private static int GetTroopRosterTotalManCount(TroopRoster roster)
	{
		try
		{
			return Math.Max(0, roster?.TotalManCount ?? 0);
		}
		catch
		{
			return 0;
		}
	}

	private static string GetFactionDisplayName(IFaction faction, string fallback = "某势力")
	{
		string text = faction?.Name?.ToString();
		return string.IsNullOrWhiteSpace(text) ? fallback : text.Trim();
	}

	private static string GetHeroFactionDisplayName(Hero hero, IFaction fallbackFaction = null)
	{
		return GetFactionDisplayName(hero?.MapFaction ?? fallbackFaction, "某势力");
	}

	private static string BuildBattleHeroDisplayName(Hero hero, bool isHighlighted, string highlightTag)
	{
		string text = hero?.Name?.ToString()?.Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			text = (hero == Hero.MainHero) ? "玩家" : "";
		}
		if (string.IsNullOrWhiteSpace(text))
		{
			return "";
		}
		if (isHighlighted && !string.IsNullOrWhiteSpace(highlightTag))
		{
			text += "（" + highlightTag + "）";
		}
		return text;
	}

	private static string StripBattlePlayerMarker(string text)
	{
		return (text ?? "").Replace("\uFF08player\uFF09", "").Replace("(player)", "").Trim();
	}

	private static string BuildTrackedHeroListText(IEnumerable<Hero> heroes, Hero highlightedHero, string highlightTag, int maxCount = 5)
	{
		if (heroes == null)
		{
			return "";
		}
		HashSet<string> hashSet = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		List<string> list = new List<string>();
		foreach (Hero item in heroes.Where(ShouldMentionBattleHero).OrderByDescending((Hero x) => x == highlightedHero))
		{
			string text = BuildBattleHeroDisplayName(item, item == highlightedHero, highlightTag);
			string npcActionHeroKey = (item == Hero.MainHero) ? "__player__" : GetNpcActionHeroKey(item);
			if (string.IsNullOrWhiteSpace(text) || !hashSet.Add(npcActionHeroKey))
			{
				continue;
			}
			list.Add(text);
		}
		if (list.Count <= 0)
		{
			return "";
		}
		if (list.Count <= maxCount)
		{
			return string.Join("、", list);
		}
		return string.Join("、", list.Take(maxCount)) + "等" + list.Count + "人";
	}

	private static string BuildTrackedHeroListText(IEnumerable<Hero> heroes, int maxCount = 5)
	{
		return BuildTrackedHeroListText(heroes, null, "", maxCount);
	}

	private static string BuildTrackedHeroListText(MapEventSide side, int maxCount = 5)
	{
		if (side?.Parties == null)
		{
			return "";
		}
		return BuildTrackedHeroListText(side.Parties.Select((MapEventParty x) => x?.Party?.LeaderHero), side.LeaderParty?.LeaderHero, "统帅", maxCount);
	}

	private static string BuildTrackedHeroListText(SiegeEvent siegeEvent, BattleSideEnum side, int maxCount = 5)
	{
		Hero highlightedHero = ((side == BattleSideEnum.Attacker) ? (siegeEvent?.BesiegerCamp?.LeaderParty?.LeaderHero) : (siegeEvent?.BesiegedSettlement?.OwnerClan?.Leader));
		return BuildTrackedHeroListText(GetHeroesFromSiegeEventSide(siegeEvent, side), highlightedHero, "统帅", maxCount);
	}

	private static string BuildMapEventCasualtyText(MapEventSide side)
	{
		if (side?.Parties == null)
		{
			return "";
		}
		int num = 0;
		int num2 = 0;
		try
		{
			foreach (MapEventParty party in side.Parties)
			{
				num += GetTroopRosterTotalManCount(party?.DiedInBattle);
				num2 += GetTroopRosterTotalManCount(party?.WoundedInBattle);
			}
		}
		catch
		{
		}
		return "阵亡" + num + "、负伤" + num2;
	}

	private static int GetMapEventSideCasualtyCount(MapEventSide side)
	{
		if (side?.Parties == null)
		{
			return 0;
		}
		int num = 0;
		try
		{
			foreach (MapEventParty party in side.Parties)
			{
				num += GetTroopRosterTotalManCount(party?.DiedInBattle);
				num += GetTroopRosterTotalManCount(party?.WoundedInBattle);
			}
		}
		catch
		{
		}
		return Math.Max(0, num);
	}

	private static int GetMapEventPartyCommittedTroopCount(MapEventParty party)
	{
		if (party == null)
		{
			return 0;
		}
		int troopRosterTotalManCount = GetTroopRosterTotalManCount(party.Party?.MemberRoster);
		int troopRosterTotalManCount2 = GetTroopRosterTotalManCount(party.DiedInBattle);
		int troopRosterTotalManCount3 = GetTroopRosterTotalManCount(party.WoundedInBattle);
		return Math.Max(0, troopRosterTotalManCount + troopRosterTotalManCount2 + troopRosterTotalManCount3);
	}

	private static int GetMapEventSideCommittedTroopCount(MapEventSide side)
	{
		if (side?.Parties == null)
		{
			return 0;
		}
		int num = 0;
		try
		{
			foreach (MapEventParty party in side.Parties)
			{
				num += GetMapEventPartyCommittedTroopCount(party);
			}
		}
		catch
		{
		}
		return Math.Max(0, num);
	}

	private static string BuildMapEventCommittedTroopText(MapEventSide side)
	{
		int mapEventSideCommittedTroopCount = GetMapEventSideCommittedTroopCount(side);
		return (mapEventSideCommittedTroopCount > 0) ? (mapEventSideCommittedTroopCount + "人") : "";
	}

	private static string BuildMapEventStandoutText(MapEventSide side, MapEventSide oppositeSide = null)
	{
		if (side?.Parties == null)
		{
			return "";
		}
		if (oppositeSide != null && CountTrackedLordParties(oppositeSide) <= 0 && !string.IsNullOrWhiteSpace(BuildMapEventNonLordPartyListText(oppositeSide, 1, includeCounts: false)))
		{
			return "";
		}
		List<MapEventParty> list = side.Parties.Where((MapEventParty x) => ShouldMentionBattleHero(x?.Party?.LeaderHero)).ToList();
		if (list.Count <= 4)
		{
			return "";
		}
		MapEventParty mapEventParty = list.OrderByDescending((MapEventParty x) => x.ContributionToBattle).FirstOrDefault();
		if (mapEventParty == null || mapEventParty.ContributionToBattle <= 0)
		{
			return "";
		}
		int num = list.Sum((MapEventParty x) => Math.Max(0, x.ContributionToBattle));
		Hero leaderHero = mapEventParty.Party?.LeaderHero;
		string text = BuildBattleHeroDisplayName(leaderHero, side.LeaderParty?.LeaderHero == leaderHero, "统帅");
		if (string.IsNullOrWhiteSpace(text))
		{
			return "";
		}
		if (num <= 0)
		{
			return text + "战场贡献最突出。";
		}
		int num2 = (int)Math.Round((double)(100 * mapEventParty.ContributionToBattle) / (double)num);
		if (num2 < 30)
		{
			return "";
		}
		string text2 = GetFactionDisplayName(leaderHero?.MapFaction ?? side.MapFaction, "某势力");
		if (num2 > 90)
		{
			return "万军辟易！这根本不是一场战争，而是" + text2 + "的" + text + "与他部队的专属杀戮秀！敌人在他面前如同草芥一般不堪一击！";
		}
		if (num2 > 75)
		{
			return text2 + "的" + text + "几乎包揽了绝大多数的战果！他的大军如同利刃般撕裂敌阵，所向披靡！";
		}
		if (num2 > 50)
		{
			return text2 + "的" + text + "与他的部队在战场上战无不胜！他是" + text2 + "的英雄！";
		}
		return text2 + "的" + text + "与他的部队是我方的中流砥柱！他拥有最高的贡献！";
	}

	private static string BuildMapEventAftermathText(MapEvent mapEvent, MapEventSide side, bool won, string locationLabel)
	{
		if (mapEvent == null || side == null)
		{
			return "";
		}
		if (mapEvent.IsSiegeAssault || mapEvent.IsSiegeOutside || mapEvent.IsSallyOut)
		{
			return "";
		}
		if (mapEvent.IsRaid)
		{
			string raidLocation = string.IsNullOrWhiteSpace(locationLabel) ? "某处村庄" : locationLabel.Trim();
			if (side.MissionSide == BattleSideEnum.Attacker)
			{
				return won ? (raidLocation + "的袭掠已经结束，你正在清点缴获并整顿部队。") : (raidLocation + "的袭掠已经结束，你的袭掠未能得手，正在收拢部队并处理残局。");
			}
			if (side.MissionSide == BattleSideEnum.Defender)
			{
				return won ? (raidLocation + "的袭掠已经结束，你协助守军击退了袭掠者，正在整顿部队。") : (raidLocation + "的袭掠已经结束，袭掠者已经得手；你正在收拢部队并处理残局。");
			}
			return won ? (raidLocation + "的村庄袭掠冲突已经结束，你正在整顿部队。") : (raidLocation + "的村庄袭掠冲突已经结束，你正在收拢部队并处理残局。");
		}
		return won ? ("这场发生在" + locationLabel + "的战斗已经结束，你正在整顿部队并清点战果。") : ("这场发生在" + locationLabel + "的战斗已经结束，你正在收拢残部并处理败战残局。");
	}

	private static string BuildArmyCommandClause(MapEventSide side, Hero actorHero)
	{
		Hero leaderHero = side?.LeaderParty?.LeaderHero;
		string text = leaderHero?.Name?.ToString()?.Trim();
		if (string.IsNullOrWhiteSpace(text) || leaderHero == actorHero)
		{
			return "";
		}
		return text + "统帅的军团";
	}

	private static string BuildMapEventActorRoleClause(Hero actorHero, MapEventSide side)
	{
		string text = GetHeroFactionDisplayName(actorHero, side?.MapFaction);
		if (actorHero?.IsLord == true)
		{
			return "你作为" + text + "的领主";
		}
		if (!string.IsNullOrWhiteSpace(text) && !string.Equals(text, "某势力", StringComparison.OrdinalIgnoreCase))
		{
			return "你作为" + text + "的一员";
		}
		return "你作为参战者";
	}

	private static string BuildMapEventNarrative(MapEvent mapEvent, MapEventSide side, Hero actorHero, bool won, string locationLabel)
	{
		if (mapEvent == null || side == null)
		{
			return "";
		}
		string text = BuildMapEventActorRoleClause(actorHero, side);
		string text2 = BuildMapEventSideNarrativeLabel(side.OtherSide);
		Settlement mapEventSettlement = mapEvent.MapEventSettlement;
		string text3 = BuildArmyCommandClause(side, actorHero);
		string text4;
		if (mapEvent.IsSiegeAssault || mapEvent.IsSiegeOutside || mapEvent.IsSallyOut)
		{
			string text5 = mapEventSettlement?.Name?.ToString();
			if (string.IsNullOrWhiteSpace(text5))
			{
				text5 = locationLabel;
			}
			string text6 = GetFactionDisplayName(side.OtherSide?.MapFaction, text2);
			text4 = ((side.MissionSide == BattleSideEnum.Attacker) ? (won ? (text + "，在" + (string.IsNullOrWhiteSpace(text3) ? "对" : (text3 + "对")) + text6 + "的领土" + text5.Trim() + "的围城战中获胜。") : (text + "，在" + (string.IsNullOrWhiteSpace(text3) ? "对" : (text3 + "对")) + text6 + "的领土" + text5.Trim() + "的围攻中失利。")) : (won ? (text + "，在" + (string.IsNullOrWhiteSpace(text3) ? "" : (text3 + "参与的")) + text5.Trim() + "保卫战中击退了" + text6 + "。") : (text + "，在" + (string.IsNullOrWhiteSpace(text3) ? "" : (text3 + "参与的")) + text5.Trim() + "保卫战中败给了" + text6 + "。")));
		}
		else if (mapEvent.IsRaid)
		{
			string raidLocation = string.IsNullOrWhiteSpace(locationLabel) ? "某处村庄" : locationLabel.Trim();
			string raidCommandPrefix = string.IsNullOrWhiteSpace(text3) ? "在" : ("随" + text3 + "在");
			if (side.MissionSide == BattleSideEnum.Attacker)
			{
				text4 = won ? (text + "，" + raidCommandPrefix + raidLocation + "对" + text2 + "发动的袭掠中得手。") : (text + "，" + raidCommandPrefix + raidLocation + "对" + text2 + "发动的袭掠中失利。");
			}
			else if (side.MissionSide == BattleSideEnum.Defender)
			{
				text4 = won ? (text + "，" + raidCommandPrefix + raidLocation + "保卫村庄，击退了" + text2 + "的袭掠。") : (text + "，" + raidCommandPrefix + raidLocation + "保卫村庄时失利，未能阻止" + text2 + "的袭掠。");
			}
			else
			{
				text4 = won ? (text + "，" + raidCommandPrefix + raidLocation + "的村庄袭掠冲突中获胜。") : (text + "，" + raidCommandPrefix + raidLocation + "的村庄袭掠冲突中失利。");
			}
		}
		else
		{
			text4 = (won ? (text + "，在" + (string.IsNullOrWhiteSpace(text3) ? "" : (text3 + "于")) + locationLabel + "击败了" + text2 + "。") : (text + "，在" + (string.IsNullOrWhiteSpace(text3) ? "" : (text3 + "于")) + locationLabel + "败给了" + text2 + "。"));
		}
		StringBuilder stringBuilder = new StringBuilder(text4);
		string text7 = BuildTrackedHeroListText(side, 5);
		string text8 = BuildTrackedHeroListText(side.OtherSide, 5);
		string text9 = BuildMapEventNonLordPartyListText(side, 5);
		string text10 = BuildMapEventNonLordPartyListText(side.OtherSide, 5);
		if (!string.IsNullOrWhiteSpace(text7))
		{
			stringBuilder.Append(" 我方领主：").Append(text7).Append('。');
		}
		if (!string.IsNullOrWhiteSpace(text8))
		{
			stringBuilder.Append(" 敌方领主：").Append(text8).Append('。');
		}
		if (!string.IsNullOrWhiteSpace(text9))
		{
			stringBuilder.Append(" 我方非领主部队：").Append(text9).Append('。');
		}
		if (!string.IsNullOrWhiteSpace(text10))
		{
			stringBuilder.Append(" 敌方非领主部队：").Append(text10).Append('。');
		}
		string text11 = BuildMapEventCommittedTroopText(side);
		string text12 = BuildMapEventCommittedTroopText(side.OtherSide);
		if (!string.IsNullOrWhiteSpace(text11) || !string.IsNullOrWhiteSpace(text12))
		{
			stringBuilder.Append(" 战前投入兵力：我方").Append(string.IsNullOrWhiteSpace(text11) ? "不详" : text11);
			stringBuilder.Append("；敌方").Append(string.IsNullOrWhiteSpace(text12) ? "不详" : text12).Append('。');
		}
		string text13 = BuildMapEventStandoutText(side, side.OtherSide);
		string text14 = BuildMapEventCasualtyText(side);
		string text15 = BuildMapEventCasualtyText(side.OtherSide);
		stringBuilder.Append(" 我方死伤：").Append(text14);
		stringBuilder.Append("；敌方死伤：").Append(text15).Append('。');
		if (!string.IsNullOrWhiteSpace(text13))
		{
			stringBuilder.Append(" ：").Append(text13);
		}
		return stringBuilder.ToString();
	}

	private static string BuildMapEventStableKey(MapEvent mapEvent, string locationLabel)
	{
		if (mapEvent == null)
		{
			return "";
		}
		List<string> list = new List<string>
		{
			GetCurrentGameDayIndexSafe().ToString(),
			NormalizeWeeklyPromptKeyPart(locationLabel),
			GetHeroId(mapEvent.AttackerSide?.LeaderParty?.LeaderHero),
			GetHeroId(mapEvent.DefenderSide?.LeaderParty?.LeaderHero),
			BuildMapEventNonLordPartyListText(mapEvent.AttackerSide, 3, includeCounts: false),
			BuildMapEventNonLordPartyListText(mapEvent.DefenderSide, 3, includeCounts: false),
			BuildMapEventCommittedTroopText(mapEvent.AttackerSide),
			BuildMapEventCommittedTroopText(mapEvent.DefenderSide),
			BuildMapEventCasualtyText(mapEvent.AttackerSide),
			BuildMapEventCasualtyText(mapEvent.DefenderSide)
		};
		string text = string.Join("~", list.Select(NormalizeWeeklyPromptKeyPart)).Trim('~');
		if (string.IsNullOrWhiteSpace(text))
		{
			text = NormalizeWeeklyPromptKeyPart(mapEvent.StringId ?? locationLabel);
		}
		return "mapevent:" + text;
	}

	private static string BuildRoutineBanditDefeatStableKey(MapEvent mapEvent, MapEventSide defeatedSide, string locationLabel)
	{
		List<string> list = new List<string>
		{
			GetCurrentGameDayIndexSafe().ToString(),
			NormalizeWeeklyPromptKeyPart(mapEvent?.StringId),
			NormalizeWeeklyPromptKeyPart(locationLabel),
			NormalizeWeeklyPromptKeyPart(GetPrimaryOtherSideLabel(defeatedSide)),
			GetMapEventSideCommittedTroopCount(defeatedSide).ToString(),
			NormalizeWeeklyPromptKeyPart(BuildMapEventCasualtyText(defeatedSide)),
			NormalizeWeeklyPromptKeyPart(BuildMapEventStableKey(mapEvent, locationLabel))
		};
		return "wild_party_defeated:" + string.Join(":", list.Where((string x) => !string.IsNullOrWhiteSpace(x)));
	}

	private static string NormalizeWeeklyPromptKeyPart(string value)
	{
		string text = (value ?? "").Trim().ToLowerInvariant();
		if (string.IsNullOrWhiteSpace(text))
		{
			return "";
		}
		return Regex.Replace(text, "[\\s:|]+", "_");
	}

	private static void ApplyMapEventOppositeSideFacts(NpcActionFacts facts, MapEventSide oppositeSide)
	{
		if (facts == null || oppositeSide == null)
		{
			return;
		}
		AddRelatedFactionFacts(facts, oppositeSide.MapFaction);
		Hero leaderHero = oppositeSide.LeaderParty?.LeaderHero;
		if (leaderHero != null)
		{
			if (string.IsNullOrWhiteSpace(facts.TargetHeroId))
			{
				facts.TargetHeroId = GetHeroId(leaderHero);
			}
			if (string.IsNullOrWhiteSpace(facts.TargetClanId))
			{
				facts.TargetClanId = GetClanId(leaderHero.Clan);
			}
			if (string.IsNullOrWhiteSpace(facts.TargetKingdomId))
			{
				facts.TargetKingdomId = GetKingdomId(leaderHero.MapFaction);
			}
			AddUniqueId(facts.RelatedHeroIds, facts.TargetHeroId);
			AddUniqueId(facts.RelatedClanIds, facts.TargetClanId);
			AddUniqueId(facts.RelatedKingdomIds, facts.TargetKingdomId);
		}
		foreach (MapEventParty party in oppositeSide.Parties ?? Enumerable.Empty<MapEventParty>())
		{
			Hero hero = party?.Party?.LeaderHero;
			if (hero == null)
			{
				continue;
			}
			AddUniqueId(facts.RelatedHeroIds, GetHeroId(hero));
			AddUniqueId(facts.RelatedClanIds, GetClanId(hero.Clan));
			AddUniqueId(facts.RelatedKingdomIds, GetKingdomId(hero.MapFaction));
		}
	}

