	private static string NormalizePlayerHistoryLineForPrompt(string line, string targetDisplayName, bool addressToYou = true)
	{
		string text = (line ?? "").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return "";
		}
		TryStripSceneSessionHistoryMarker(text, out text, out var _);
		string firstMeetingFact = NormalizeFirstMeetingNpcFactForPrompt(text);
		if (!string.IsNullOrWhiteSpace(firstMeetingFact))
		{
			return firstMeetingFact;
		}
		if (!TryStripPlayerSpeechPrefix(text, out var stripped))
		{
			return text;
		}
		string text2 = BuildPlayerPublicDisplayNameForPrompt();
		string text3 = addressToYou ? "你" : ((targetDisplayName ?? "").Trim());
		if (string.IsNullOrWhiteSpace(text3))
		{
			text3 = "该NPC";
		}
		return text2 + "对" + text3 + "说: " + stripped;
	}

	private static bool TryStripPlayerSpeechPrefix(string line, out string stripped)
	{
		stripped = "";
		string text = (line ?? "").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return false;
		}
		TryStripSceneSessionHistoryMarker(text, out text, out var _);
		if (text.StartsWith("玩家:", StringComparison.Ordinal))
		{
			stripped = text.Substring("玩家:".Length).Trim();
			return true;
		}
		if (text.StartsWith("玩家：", StringComparison.Ordinal))
		{
			stripped = text.Substring("玩家：".Length).Trim();
			return true;
		}
		int num = text.IndexOf("（player）对", StringComparison.Ordinal);
		if (num >= 0)
		{
			int num2 = text.IndexOf("说:", num, StringComparison.Ordinal);
			if (num2 < 0)
			{
				num2 = text.IndexOf("说：", num, StringComparison.Ordinal);
			}
			if (num2 >= 0)
			{
				stripped = text.Substring(num2 + 2).Trim();
				return true;
			}
		}
		return false;
	}

	private static string BuildSiegeStartNarrative(Settlement settlement, bool isAttacker, SiegeEvent siegeEvent)
	{
		string text = settlement?.Name?.ToString() ?? "某处要塞";
		string text2 = GetFactionDisplayName(settlement?.MapFaction, "守军");
		string text3 = GetFactionDisplayName(siegeEvent?.BesiegerCamp?.LeaderParty?.MapFaction, "攻方");
		StringBuilder stringBuilder = new StringBuilder(isAttacker ? ("你参与了对" + text2 + "领土" + text + "的围攻。") : ("你参与了" + text + "的守城，对抗" + text3 + "。"));
		string text4 = BuildTrackedHeroListText(siegeEvent, BattleSideEnum.Attacker, 5);
		string text5 = BuildTrackedHeroListText(siegeEvent, BattleSideEnum.Defender, 5);
		if (!string.IsNullOrWhiteSpace(text4))
		{
			stringBuilder.Append(" 攻方领主：").Append(text4).Append('。');
		}
		if (!string.IsNullOrWhiteSpace(text5))
		{
			stringBuilder.Append(" 守方领主：").Append(text5).Append('。');
		}
		return stringBuilder.ToString();
	}

	private void TrackNpcActionsFromMapEvent(MapEvent mapEvent)
	{
		if (mapEvent == null || !mapEvent.HasWinner)
		{
			return;
		}
		if (mapEvent.IsHideoutBattle)
		{
			return;
		}
		if (ShouldSkipRoutineBanditDefeatMapEvent(mapEvent))
		{
			return;
		}
		bool hasBanditSide = IsBanditOrMonsterMapEvent(mapEvent);
		int mapEventTroopCount = GetMapEventTroopCount(mapEvent);
		bool isMajor = ShouldRecordMajorBattleAction(mapEventTroopCount);
		string mapEventLocationLabel = GetMapEventLocationLabel(mapEvent);
		string mapEventStableKey = BuildMapEventStableKey(mapEvent, mapEventLocationLabel);
		TrackNpcActionsFromMapEventSide(mapEvent, mapEvent.AttackerSide, mapEvent.WinningSide == mapEvent.AttackerSide?.MissionSide, isMajor, mapEventLocationLabel, mapEventStableKey, hasBanditSide);
		TrackNpcActionsFromMapEventSide(mapEvent, mapEvent.DefenderSide, mapEvent.WinningSide == mapEvent.DefenderSide?.MissionSide, isMajor, mapEventLocationLabel, mapEventStableKey, hasBanditSide);
	}

	private static bool ShouldSkipRoutineBanditDefeatMapEvent(MapEvent mapEvent)
	{
		if (mapEvent == null || !mapEvent.HasWinner)
		{
			return false;
		}
		if (mapEvent.IsSiegeAssault || mapEvent.IsSiegeOutside || mapEvent.IsSallyOut || mapEvent.IsRaid)
		{
			return false;
		}
		MapEventSide defeatedSide = GetMapEventDefeatedSide(mapEvent);
		return IsRoutineBanditMapEventSide(defeatedSide);
	}

	private static MapEventSide GetMapEventDefeatedSide(MapEvent mapEvent)
	{
		if (mapEvent == null)
		{
			return null;
		}
		if (mapEvent.WinningSide == BattleSideEnum.Attacker)
		{
			return mapEvent.DefenderSide;
		}
		if (mapEvent.WinningSide == BattleSideEnum.Defender)
		{
			return mapEvent.AttackerSide;
		}
		return null;
	}

	private static bool IsRoutineBanditMapEventSide(MapEventSide side)
	{
		if (side == null)
		{
			return false;
		}
		try
		{
			if (ShouldMentionBattleHero(side.LeaderParty?.LeaderHero))
			{
				return false;
			}
			bool hasBanditParty = IsBanditOrOutlawPartyBase(side.LeaderParty) || side.MapFaction?.IsBanditFaction == true;
			foreach (MapEventParty party in side.Parties ?? Enumerable.Empty<MapEventParty>())
			{
				PartyBase partyBase = party?.Party;
				if (ShouldMentionBattleHero(partyBase?.LeaderHero))
				{
					return false;
				}
				if (IsBanditOrOutlawPartyBase(partyBase))
				{
					hasBanditParty = true;
				}
			}
			return hasBanditParty;
		}
		catch
		{
			return false;
		}
	}

	private static bool IsBanditOrOutlawPartyBase(PartyBase party)
	{
		if (party == null)
		{
			return false;
		}
		try
		{
			MobileParty mobileParty = party.MobileParty;
			return party.MapFaction?.IsBanditFaction == true
				|| mobileParty?.IsBandit == true
				|| mobileParty?.MapFaction?.IsBanditFaction == true
				|| mobileParty?.ActualClan?.IsBanditFaction == true
				|| party.Owner?.MapFaction?.IsBanditFaction == true;
		}
		catch
		{
			return false;
		}
	}

	private static bool IsBanditOrMonsterMapEvent(MapEvent mapEvent)
	{
		return IsBanditOrMonsterMapEventSide(mapEvent?.AttackerSide) || IsBanditOrMonsterMapEventSide(mapEvent?.DefenderSide);
	}

	private static bool IsBanditOrMonsterMapEventSide(MapEventSide side)
	{
		if (side == null)
		{
			return false;
		}
		try
		{
			if (side.MapFaction?.IsBanditFaction == true || side.LeaderParty?.MapFaction?.IsBanditFaction == true)
			{
				return true;
			}
			foreach (MapEventParty party in side.Parties ?? Enumerable.Empty<MapEventParty>())
			{
				if (party?.Party?.MapFaction?.IsBanditFaction == true || party?.Party?.MobileParty?.MapFaction?.IsBanditFaction == true || party?.Party?.Owner?.MapFaction?.IsBanditFaction == true)
				{
					return true;
				}
			}
		}
		catch
		{
		}
		return false;
	}

	private void TrackNpcActionsFromMapEventSide(MapEvent mapEvent, MapEventSide side, bool won, bool isMajor, string locationLabel, string mapEventStableKey, bool allowNonLordHero = false)
	{
		if (mapEvent == null || side?.Parties == null)
		{
			return;
		}
		foreach (MapEventParty party in side.Parties)
		{
			Hero leaderHero = party?.Party?.LeaderHero;
			if (!ShouldTrackNpcActionHero(leaderHero, allowNonLordHero))
			{
				continue;
			}
			if (!won && mapEvent.IsPlayerMapEvent && mapEvent.HasWinner && mapEvent.WinningSide == mapEvent.PlayerSide && HasRecordedPlayerDefeatedHeroBattleFact(mapEvent, side, leaderHero))
			{
				continue;
			}
			string text = BuildMapEventNarrative(mapEvent, side, leaderHero, won, locationLabel);
			string text2 = (string.IsNullOrWhiteSpace(mapEventStableKey) ? BuildMapEventStableKey(mapEvent, locationLabel) : mapEventStableKey) + ":side:" + side.MissionSide + ":hero:" + (leaderHero.StringId ?? "");
			NpcActionFacts npcActionFacts = CreateNpcActionFacts("map_event", leaderHero);
			npcActionFacts.LocationText = locationLabel;
			npcActionFacts.Won = won;
			ApplySettlementFacts(npcActionFacts, mapEvent.MapEventSettlement, locationText: locationLabel);
			ApplyMapEventOppositeSideFacts(npcActionFacts, side.OtherSide);
			if (isMajor)
			{
				RecordNpcMajorAction(leaderHero, text, text2, npcActionFacts, allowNonLordHero);
			}
			RecordNpcRecentAction(leaderHero, text, text2, facts: npcActionFacts, allowNonLordHero: allowNonLordHero);
			string text3 = BuildMapEventAftermathText(mapEvent, side, won, locationLabel);
			if (!string.IsNullOrWhiteSpace(text3))
			{
				NpcActionFacts npcActionFacts2 = CreateNpcActionFacts("map_event_aftermath", leaderHero);
				npcActionFacts2.LocationText = locationLabel;
				npcActionFacts2.Won = won;
				ApplySettlementFacts(npcActionFacts2, mapEvent.MapEventSettlement, locationText: locationLabel);
				ApplyMapEventOppositeSideFacts(npcActionFacts2, side.OtherSide);
				RecordNpcRecentAction(leaderHero, text3, "mapevent_aftermath:" + (string.IsNullOrWhiteSpace(mapEventStableKey) ? BuildMapEventStableKey(mapEvent, locationLabel) : mapEventStableKey).Substring("mapevent:".Length) + ":side:" + side.MissionSide + ":hero:" + (leaderHero.StringId ?? ""), facts: npcActionFacts2, allowNonLordHero: allowNonLordHero);
			}
		}
	}

	private static string GetNearestSettlementNameForParty(MobileParty party)
	{
		Settlement settlement = party?.BesiegedSettlement ?? ResolveSiegeSettlement(party?.SiegeEvent);
		if (settlement == null)
		{
			settlement = party?.Army?.LeaderParty?.BesiegedSettlement ?? ResolveSiegeSettlement(party?.Army?.LeaderParty?.SiegeEvent);
		}
		string text = settlement?.Name?.ToString();
		if (!string.IsNullOrWhiteSpace(text))
		{
			return text.Trim();
		}
		text = party?.Army?.LeaderParty?.TargetSettlement?.Name?.ToString();
		if (!string.IsNullOrWhiteSpace(text))
		{
			return text.Trim();
		}
		text = party?.TargetSettlement?.Name?.ToString();
		if (!string.IsNullOrWhiteSpace(text))
		{
			return text.Trim();
		}
		text = party?.CurrentSettlement?.Name?.ToString();
		if (!string.IsNullOrWhiteSpace(text))
		{
			return text.Trim();
		}
		text = party?.LastVisitedSettlement?.Name?.ToString();
		if (!string.IsNullOrWhiteSpace(text))
		{
			return text.Trim();
		}
		text = party?.BesiegedSettlement?.Name?.ToString();
		return string.IsNullOrWhiteSpace(text) ? "附近一带" : text.Trim();
	}

