	private string BuildNpcMajorActionsRuntimeInstruction(Hero hero, CharacterObject targetCharacter = null, int targetAgentIndex = -1)
	{
		Hero observerHero = hero ?? targetCharacter?.HeroObject;
		string text = BuildNpcActionSummary(observerHero, recentOnly: false);
		string playerMajor = observerHero != null
			? PlayerNotorietyBehavior.BuildPlayerMajorRuntimeInstructionForExternal(observerHero)
			: PlayerNotorietyBehavior.BuildPlayerMajorRuntimeInstructionForExternal(BuildRuleTargetKeyForExternal(null, targetCharacter, targetAgentIndex), targetCharacter?.Culture?.StringId);
		if (!string.IsNullOrWhiteSpace(playerMajor))
		{
			text = string.IsNullOrWhiteSpace(text) ? playerMajor.Trim() : text.Trim() + "\n\n" + playerMajor.Trim();
		}
		string stateKey = (string.IsNullOrWhiteSpace(text) ? "no_data" : "has_data");
		Dictionary<string, string> dictionary = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
		{
			["majorActionSummary"] = text ?? ""
		};
		return AIConfigHandler.ResolveRuleRuntimeText("npc_major_actions", stateKey, forConstraint: false, dictionary);
	}

	private string BuildResidentRecentActionsPrompt(Hero hero, CharacterObject targetCharacter = null, int targetAgentIndex = -1)
	{
		Hero observerHero = hero ?? targetCharacter?.HeroObject;
		if (observerHero == null && targetCharacter == null)
		{
			return "";
		}
		string npcRecent = BuildNpcActionSummary(observerHero, recentOnly: true);
		string playerRecent = observerHero != null
			? PlayerNotorietyBehavior.BuildPlayerRecentRuntimeInstructionForExternal(observerHero)
			: PlayerNotorietyBehavior.BuildPlayerRecentRuntimeInstructionForExternal(BuildRuleTargetKeyForExternal(null, targetCharacter, targetAgentIndex), targetCharacter?.Culture?.StringId);
		StringBuilder stringBuilder = new StringBuilder();
		stringBuilder.AppendLine("【NPC近期行动（近10天，常驻）】");
		if (string.IsNullOrWhiteSpace(npcRecent))
		{
			stringBuilder.AppendLine("当前没有可确认记录；不得编造。");
		}
		else
		{
			stringBuilder.AppendLine(npcRecent.Trim());
		}
		stringBuilder.Append("边界：这里只表示近10天事实，不代表完整履历；未列出的近期行动不得编造。");
		if (!string.IsNullOrWhiteSpace(playerRecent))
		{
			stringBuilder.AppendLine().AppendLine().Append(playerRecent.Trim());
		}
		return stringBuilder.ToString().Trim();
	}

	private string BuildNpcActionsRuntimeConstraintHint(Hero hero, bool recentOnly, CharacterObject targetCharacter = null, int targetAgentIndex = -1)
	{
		if (recentOnly)
		{
			return "";
		}
		Hero observerHero = hero ?? targetCharacter?.HeroObject;
		string text = BuildNpcActionSummary(observerHero, recentOnly: false);
		string observerKey = BuildRuleTargetKeyForExternal(null, targetCharacter, targetAgentIndex);
		string observerCultureId = targetCharacter?.Culture?.StringId;
		string playerText = observerHero != null
			? PlayerNotorietyBehavior.BuildPlayerMajorRuntimeInstructionForExternal(observerHero)
			: PlayerNotorietyBehavior.BuildPlayerMajorRuntimeInstructionForExternal(observerKey, observerCultureId);
		if (!string.IsNullOrWhiteSpace(playerText))
		{
			text = string.IsNullOrWhiteSpace(text) ? playerText.Trim() : text.Trim() + "\n\n" + playerText.Trim();
		}
		if (!string.IsNullOrWhiteSpace(text))
		{
			return "";
		}
		return AIConfigHandler.ResolveRuleRuntimeText("npc_major_actions", "no_data", forConstraint: true, new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase));
	}

	private string BuildNpcCurrentActionFact(Hero hero)
	{
		try
		{
			if (hero == null)
			{
				return "";
			}
			string text = BuildRecentPartyBehaviorText(hero.PartyBelongedTo);
			if (string.IsNullOrWhiteSpace(text))
			{
				string text2 = (hero.CurrentSettlement?.Name?.ToString() ?? "").Trim();
				if (!string.IsNullOrWhiteSpace(text2))
				{
					text = "你当前在" + text2 + "停留。";
				}
			}
			if (string.IsNullOrWhiteSpace(text))
			{
				string npcActionHeroKey = GetNpcActionHeroKey(hero);
				if (!string.IsNullOrWhiteSpace(npcActionHeroKey) && _npcRecentActions != null && _npcRecentActions.TryGetValue(npcActionHeroKey, out var value) && value != null)
				{
					NpcActionEntry npcActionEntry = SanitizeNpcActionEntries(value, keepOnlyRecentWindow: true).LastOrDefault();
					if (npcActionEntry != null && npcActionEntry.Day >= GetCurrentGameDayIndexSafe() - 1)
					{
						text = npcActionEntry.Text;
					}
				}
			}
			text = RenderNpcActionPromptText(hero, text);
			return string.IsNullOrWhiteSpace(text) ? "" : (text);
		}
		catch
		{
			return "";
		}
	}

	private void OnCampaignTick(float dt)
	{
		using (PerfProbe.Scope("MyBehavior.OnCampaignTick"))
		{
		try
		{
			bool processedWeeklyReportCommits = false;
			if (Volatile.Read(ref _hasPendingWeeklyReportCommits) != 0)
			{
				using (PerfProbe.Scope("MyBehavior.OnCampaignTick.ProcessPendingWeeklyReportCommits"))
				{
					processedWeeklyReportCommits = ProcessPendingWeeklyReportCommits();
				}
			}
			using (PerfProbe.Scope("MyBehavior.OnCampaignTick.TryRunCampaignMemoryMaintenance"))
			{
				TryRunCampaignMemoryMaintenance();
			}
			if (!processedWeeklyReportCommits && HasPendingDeferredDailyMaintenanceWork())
			{
				using (PerfProbe.Scope("MyBehavior.OnCampaignTick.ProcessDeferredDailyMaintenance"))
				{
					ProcessDeferredDailyMaintenance();
				}
			}
			using (PerfProbe.Scope("MyBehavior.OnCampaignTick.CachePlayerClanTier"))
			{
				int num = 0;
				try
				{
					num = Clan.PlayerClan?.Tier ?? 0;
				}
				catch
				{
				}
				if (num <= 0)
				{
					try
					{
						num = (Hero.MainHero?.Clan?.Tier).GetValueOrDefault();
					}
					catch
					{
					}
				}
				_cachedPlayerClanTier = num;
				_cachedPlayerClanTierUtcTicks = DateTime.UtcNow.Ticks;
			}
		}
		catch
		{
		}
		}
	}

	private void TryRunCampaignMemoryMaintenance()
	{
		if (_memorySummaryProcessing)
		{
			return;
		}
		int currentDay = 0;
		try
		{
			currentDay = (int)CampaignTime.Now.ToDays;
		}
		catch
		{
			currentDay = 0;
		}
		// Queues are small and bounded; check runnable work so exhausted stale items cannot trigger per-tick maintenance.
		bool hasQueuedWork = (_memorySummaryQueue != null && _memorySummaryQueue.Any(HasMemorySummaryJobStillPending)) || (_npcMajorActionSummaryQueue != null && _npcMajorActionSummaryQueue.Any(HasMajorActionSummaryJobStillPending)) || (_memoryOverviewQueue != null && _memoryOverviewQueue.Any(HasMemoryOverviewJobStillPending));
		if (!hasQueuedWork && currentDay == _lastMemoryMaintenanceObservedGameDay)
		{
			return;
		}
		if (IsDialogueOrLetterChainBusyForMemorySummary())
		{
			return;
		}
		_lastMemoryMaintenanceObservedGameDay = currentDay;
		bool hasPastDrafts = HasPastDailyMemoryDrafts(currentDay);
		if (!hasPastDrafts && !hasQueuedWork)
		{
			return;
		}
		long startTimestamp = Stopwatch.GetTimestamp();
		double budgetMs = GetDailyMaintenanceFrameBudgetMs();
		if (hasPastDrafts)
		{
			using (PerfProbe.Scope("MyBehavior.TryRunCampaignMemoryMaintenance.TrySealPastDailyMemoryDrafts"))
			{
				TrySealPastDailyMemoryDrafts(startTimestamp, budgetMs);
			}
		}
		if (!IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
		{
			using (PerfProbe.Scope("MyBehavior.TryRunCampaignMemoryMaintenance.TryStartMemorySummaryQueue"))
			{
				TryStartMemorySummaryQueue();
			}
		}
	}

	private bool HasPastDailyMemoryDrafts(int currentDay)
	{
		if (_dailyMemoryDrafts == null || _dailyMemoryDrafts.Count <= 0 || currentDay <= 0)
		{
			return false;
		}
		try
		{
			foreach (KeyValuePair<string, List<DailyMemoryDraft>> item in _dailyMemoryDrafts)
			{
				string ownerMemoryId = NormalizeMemoryHeroId(item.Key);
				if (!IsMemoryEntityEligibleForCompressedMemory(ownerMemoryId))
				{
					// Validate each owner once; a stale owner must not make every stored draft wake maintenance.
					continue;
				}
				List<DailyMemoryDraft> drafts = item.Value;
				if (drafts == null || drafts.Count <= 0)
				{
					continue;
				}
				for (int i = 0; i < drafts.Count; i++)
				{
					DailyMemoryDraft draft = drafts[i];
					if (draft != null && string.Equals(NormalizeMemoryHeroId(draft.HeroId), ownerMemoryId, StringComparison.OrdinalIgnoreCase) && draft.SummaryRetryCount < 3 && draft.GameDayIndex < currentDay && draft.HasLlmDialogue && CountDailyMemorySummarySourceChars(draft) > 0 && !HasCompressedMemoryBlock(ownerMemoryId, draft.GameDayIndex))
					{
						return true;
					}
				}
			}
		}
		catch
		{
		}
		return false;
	}

