	private static string GetClanTierReputationLabel(int tier)
	{
		int num = Math.Max(0, tier);
		if (num <= 0)
		{
			return "身份低微";
		}
		return num switch
		{
			1 => "小有名气", 
			2 => "崭露新贵", 
			3 => "声名清贵", 
			4 => "门第高华", 
			5 => "威权显赫", 
			_ => "贵不可言", 
		};
	}

	private static string BuildAgeBracketLabel(float age)
	{
		if (age >= 60f)
		{
			return "老年";
		}
		if (age >= 46f)
		{
			return "中年";
		}
		if (age >= 30f)
		{
			return "壮年";
		}
		if (age >= 18f)
		{
			return "青年";
		}
		if (age > 0f)
		{
			return "少年";
		}
		return "未知";
	}

	private static bool ContainsIgnoreCase(string text, string token)
	{
		if (string.IsNullOrEmpty(text) || string.IsNullOrEmpty(token))
		{
			return false;
		}
		return text.IndexOf(token, StringComparison.OrdinalIgnoreCase) >= 0;
	}

	private static bool IsShortAckForRuleFollowup(string input)
	{
		string text = (input ?? "").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return false;
		}
		if (text.Length > 20)
		{
			return false;
		}
		string[] array = new string[17]
		{
			"好", "好的", "行", "可以", "同意", "确认", "就这样", "继续", "嗯", "是",
			"对", "我选雇佣兵", "雇佣兵", "我选封臣", "封臣", "那就按这个", "那就这么办"
		};
		for (int i = 0; i < array.Length; i++)
		{
			if (ContainsIgnoreCase(text, array[i]))
			{
				return true;
			}
		}
		return false;
	}

	private static bool IsNpcAskingForConfirmation(string npcText)
	{
		string text = StripActionTags(npcText ?? "").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return false;
		}
		if (!text.Contains("？") && !text.Contains("?"))
		{
			return false;
		}
		string[] array = new string[13]
		{
			"是否", "要不要", "你要", "你是要", "确认", "同意", "愿意", "还是", "雇佣兵", "封臣",
			"成交吗", "继续吗", "要这样吗"
		};
		for (int i = 0; i < array.Length; i++)
		{
			if (ContainsIgnoreCase(text, array[i]))
			{
				return true;
			}
		}
		return false;
	}

	private static string ResolveRuleStickyTargetKey(Hero targetHero, CharacterObject targetCharacter)
	{
		string text = targetHero?.StringId ?? "";
		if (string.IsNullOrWhiteSpace(text))
		{
			text = targetCharacter?.StringId ?? "";
		}
		if (string.IsNullOrWhiteSpace(text))
		{
			text = targetCharacter?.HeroObject?.StringId ?? "";
		}
		return (text ?? "").Trim().ToLowerInvariant();
	}

	private static int GetBuiltInRuleStickyTurnLimit(string ruleId)
	{
		switch ((ruleId ?? "").Trim().ToLowerInvariant())
		{
		case "duel":
		case "reward":
			return 2;
		case "loan":
			return 3;
		default:
			return 0;
		}
	}

	private void ClearRuleStickyCarry()
	{
		_ruleStickyTargetKey = null;
		_ruleStickyDuelRoundsLeft = 0;
		_ruleStickyRewardRoundsLeft = 0;
		_ruleStickyLoanRoundsLeft = 0;
	}

	private bool TryConsumeRuleStickyCarry(Hero targetHero, CharacterObject targetCharacter, string playerInput, out bool duel, out bool reward, out bool loan)
	{
		duel = false;
		reward = false;
		loan = false;
		string text = ResolveRuleStickyTargetKey(targetHero, targetCharacter);
		if (string.IsNullOrWhiteSpace(text) || string.IsNullOrWhiteSpace(_ruleStickyTargetKey) || (_ruleStickyDuelRoundsLeft <= 0 && _ruleStickyRewardRoundsLeft <= 0 && _ruleStickyLoanRoundsLeft <= 0))
		{
			ClearRuleStickyCarry();
			return false;
		}
		if (!string.Equals(_ruleStickyTargetKey, text, StringComparison.Ordinal))
		{
			ClearRuleStickyCarry();
			return false;
		}
		if (!IsShortAckForRuleFollowup(playerInput))
		{
			ClearRuleStickyCarry();
			return false;
		}
		if (_ruleStickyDuelRoundsLeft > 0)
		{
			duel = true;
			_ruleStickyDuelRoundsLeft--;
		}
		if (_ruleStickyRewardRoundsLeft > 0)
		{
			reward = true;
			_ruleStickyRewardRoundsLeft--;
		}
		if (_ruleStickyLoanRoundsLeft > 0)
		{
			loan = true;
			_ruleStickyLoanRoundsLeft--;
		}
		if (!duel && !reward && !loan)
		{
			ClearRuleStickyCarry();
			return false;
		}
		if (_ruleStickyDuelRoundsLeft <= 0 && _ruleStickyRewardRoundsLeft <= 0 && _ruleStickyLoanRoundsLeft <= 0)
		{
			ClearRuleStickyCarry();
		}
		try
		{
			Logger.Log("GuardrailSemantic", $"builtin_rule_sticky_consume target={text} duel={duel} reward={reward} loan={loan} left=({_ruleStickyDuelRoundsLeft},{_ruleStickyRewardRoundsLeft},{_ruleStickyLoanRoundsLeft})");
		}
		catch
		{
		}
		return true;
	}

	private void UpdateRuleStickyCarryFromHits(Hero targetHero, CharacterObject targetCharacter, bool duel, bool reward, bool loan)
	{
		string text = ResolveRuleStickyTargetKey(targetHero, targetCharacter);
		if (string.IsNullOrWhiteSpace(text))
		{
			ClearRuleStickyCarry();
			return;
		}
		if (!(duel || reward || loan))
		{
			return;
		}
		_ruleStickyTargetKey = text;
		_ruleStickyDuelRoundsLeft = (duel ? GetBuiltInRuleStickyTurnLimit("duel") : 0);
		_ruleStickyRewardRoundsLeft = (reward ? GetBuiltInRuleStickyTurnLimit("reward") : 0);
		_ruleStickyLoanRoundsLeft = (loan ? GetBuiltInRuleStickyTurnLimit("loan") : 0);
		try
		{
			Logger.Log("GuardrailSemantic", $"builtin_rule_sticky_prime target={text} duel={_ruleStickyDuelRoundsLeft} reward={_ruleStickyRewardRoundsLeft} loan={_ruleStickyLoanRoundsLeft}");
		}
		catch
		{
		}
	}

	public void OnEngineTick()
	{
		try
		{
			ProcessPendingMissingOnnxGateCheck();
			ProcessMissingOnnxGateUiResume();
			ProcessPendingWeeklyReportManualRetryResult();
			ProcessWeeklyReportUiResume();
			TryPublishUnreadWeeklyReportMapNotifications();
			ProcessWeekZeroShortSummaryMainThreadActions();
			ProcessKingdomRebellionApiRepairResume();
			ProcessKingdomRebellionNamingMainThreadActions();
			ProcessPendingDevForcedKingdomRebellionResult();
			ProcessPendingAutomaticKingdomRebellionResult();
			TryStartDeferredAutoWeeklyReports();
		}
		catch
		{
		}
	}

	private void EnqueueKingdomRebellionNamingMainThreadAction(long runtimeGeneration, Action action, string source)
	{
		if (action == null)
		{
			return;
		}
		_kingdomRebellionNamingMainThreadActions.Enqueue(delegate
		{
			if (SaveRuntimeGuard.IsStale(runtimeGeneration, source))
			{
				return;
			}
			action();
		});
	}

	private void ProcessKingdomRebellionNamingMainThreadActions()
	{
		int processed = 0;
		while (processed < 16 && _kingdomRebellionNamingMainThreadActions.TryDequeue(out var action))
		{
			processed++;
			try
			{
				action?.Invoke();
			}
			catch (Exception ex)
			{
				Logger.Log("KingdomRebellion", "[ERROR] naming main-thread action failed: " + ex);
			}
		}
	}

	private void OnGameLoadFinished()
	{
		QueueMissingOnnxGateCheck(TimeSpan.Zero);
		RebuildRuntimeDerivedIndexes();
		SyncModCreatedRebelKingdomBannersOnGameLoad();
		// The campaign Hero registry is complete at this lifecycle point, so stale saved compression work can be
		// cancelled before load-finished maintenance queues any LLM request.
		CancelUnavailableHeroCompressionWorkAfterLoad();
		if (IsDeferredDailyMaintenanceEnabled())
		{
			int currentDay = GetCurrentGameDayIndexSafe();
			QueueDeferredAutoWeeklyReportsForWeek((currentDay > 0) ? (currentDay / 7) : 0, currentDay, "game_load_finished");
			EnqueueDailyMaintenanceJob(DailyMaintenanceTaskKind.DiscontinueLandlessRebelKingdoms, currentDay, reason: "game_load_finished");
			EnqueueDailyMaintenanceJob(DailyMaintenanceTaskKind.SealPastDailyMemoryDrafts, currentDay, reason: "game_load_finished");
			EnqueueDailyMaintenanceJob(DailyMaintenanceTaskKind.QueueFullMemoryOverviewScan, currentDay, reason: "game_load_finished");
			EnqueueDailyMaintenanceJob(DailyMaintenanceTaskKind.StartMemorySummaryQueue, currentDay, reason: "game_load_finished");
		}
		else
		{
			TryDiscontinueLandlessModRebelKingdoms("game_load_finished");
			TrySealPastDailyMemoryDrafts();
			QueueAllMemoryOverviewCandidatesForDeferredScan();
			ProcessMemoryOverviewCandidateScanBudget(0L, double.MaxValue);
			TryStartMemorySummaryQueue();
			int currentDay = GetCurrentGameDayIndexSafe();
			int missingWeek = WeeklyReportSchedulePolicy.ResolveOldestMissingWeek(_lastAutoGeneratedWeeklyReportWeek, currentDay);
			if (missingWeek > 0)
			{
				StartAutoWeeklyReportsForWeek(missingWeek, currentDay);
			}
		}
	}

	private void RebuildRuntimeDerivedIndexes()
	{
		RebuildEventSourceMaterialIndex();
		RebuildNpcRecentActionStableKeyIndex();
	}

	private static string BuildEventSourceMaterialIndexKey(int day, string stableKey)
	{
		string text = (stableKey ?? "").Trim();
		return Math.Max(0, day) + "|" + text;
	}

	private void RebuildEventSourceMaterialIndex()
	{
		_eventSourceMaterialIndex = new Dictionary<string, EventSourceMaterialEntry>(StringComparer.OrdinalIgnoreCase);
		foreach (EventSourceMaterialEntry item in _eventSourceMaterials ?? new List<EventSourceMaterialEntry>())
		{
			string text = (item?.StableKey ?? "").Trim();
			if (!string.IsNullOrWhiteSpace(text))
			{
				_eventSourceMaterialIndex[BuildEventSourceMaterialIndexKey(item.Day, text)] = item;
			}
		}
	}

	private void RebuildNpcRecentActionStableKeyIndex()
	{
		_npcRecentActionStableKeyIndex.Clear();
		foreach (KeyValuePair<string, List<NpcActionEntry>> pair in _npcRecentActions ?? new Dictionary<string, List<NpcActionEntry>>())
		{
			RefreshNpcRecentActionStableKeyIndexForHero(pair.Key, pair.Value);
		}
	}

	private void RefreshNpcRecentActionStableKeyIndexForHero(string heroKey, List<NpcActionEntry> entries)
	{
		string text = (heroKey ?? "").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return;
		}
		if (!_npcRecentActionStableKeyIndex.TryGetValue(text, out HashSet<string> stableKeys) || stableKeys == null)
		{
			stableKeys = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		}
		else
		{
			stableKeys.Clear();
		}
		if (entries != null)
		{
			for (int index = 0; index < entries.Count; index++)
			{
				string stableKey = (entries[index]?.StableKey ?? "").Trim();
				if (!string.IsNullOrWhiteSpace(stableKey))
				{
					stableKeys.Add(stableKey);
				}
			}
		}
		if (stableKeys.Count > 0)
		{
			_npcRecentActionStableKeyIndex[text] = stableKeys;
		}
		else
		{
			_npcRecentActionStableKeyIndex.Remove(text);
		}
	}

	private bool IsNpcRecentActionStableKeyKnown(string heroKey, string stableKey)
	{
		string text = (heroKey ?? "").Trim();
		string text2 = (stableKey ?? "").Trim();
		return !string.IsNullOrWhiteSpace(text) && !string.IsNullOrWhiteSpace(text2) && _npcRecentActionStableKeyIndex.TryGetValue(text, out var value) && value != null && value.Contains(text2);
	}

	public void QueueMissingOnnxGateCheckAfterOnboarding()
	{
		QueueMissingOnnxGateCheck(TimeSpan.FromMilliseconds(100.0));
	}

	private void QueueMissingOnnxGateCheck(TimeSpan delay)
	{
		try
		{
			_pendingMissingOnnxGateCheck = true;
			_pendingMissingOnnxGateCheckAfterUtcTicks = DateTime.UtcNow.Ticks + delay.Ticks;
		}
		catch
		{
			_pendingMissingOnnxGateCheck = true;
			_pendingMissingOnnxGateCheckAfterUtcTicks = 0L;
		}
	}

	private void ProcessPendingMissingOnnxGateCheck()
	{
		if (!_pendingMissingOnnxGateCheck)
		{
			return;
		}
		if (Campaign.Current == null || !Campaign.Current.GameStarted)
		{
			return;
		}
		if (DateTime.UtcNow.Ticks < _pendingMissingOnnxGateCheckAfterUtcTicks)
		{
			return;
		}
		_pendingMissingOnnxGateCheck = false;
		_pendingMissingOnnxGateCheckAfterUtcTicks = 0L;
		EvaluateMissingOnnxGate();
	}

	private void EvaluateMissingOnnxGate()
	{
		try
		{
			if (HasCompleteRequiredOnnxFiles())
			{
				_missingOnnxGateActive = false;
				_missingOnnxGateResumeAfterUtcTicks = 0L;
				return;
			}
			_missingOnnxGateActive = true;
			_missingOnnxGateResumeAfterUtcTicks = DateTime.UtcNow.Ticks;
			ShowMissingOnnxGatePopup();
			try
			{
				Logger.Log("OnnxGate", "campaign start blocked because required ONNX files are missing.");
			}
			catch
			{
			}
		}
		catch (Exception ex)
		{
			try
			{
				Logger.Log("OnnxGate", "failed to evaluate ONNX gate: " + ex.Message);
			}
			catch
			{
			}
		}
	}

	private void ProcessMissingOnnxGateUiResume()
	{
		if (!_missingOnnxGateActive)
		{
			return;
		}
		if (Campaign.Current == null || !Campaign.Current.GameStarted)
		{
			return;
		}
		if (InformationManager.IsAnyInquiryActive())
		{
			return;
		}
		if (DateTime.UtcNow.Ticks < _missingOnnxGateResumeAfterUtcTicks)
		{
			return;
		}
		ShowMissingOnnxGatePopup();
	}

	private void ShowMissingOnnxGatePopup()
	{
		_missingOnnxGateResumeAfterUtcTicks = DateTime.UtcNow.Ticks + TimeSpan.FromMilliseconds(100.0).Ticks;
		InformationManager.HideInquiry();
		InformationManager.ShowInquiry(new InquiryData("缺少ONNX文件", "检测到你的mod缺乏ONNX文件，请前往群文件下载RAG专用模型，并将里面的onnx拖入Mount & Blade II Bannerlord\\Modules\\AnimusForge中", isAffirmativeOptionShown: true, isNegativeOptionShown: false, "保存并退出", "", ExitCurrentGameBecauseOnnxMissing, null), pauseGameActiveState: true);
	}

	private void ExitCurrentGameBecauseOnnxMissing()
	{
		try
		{
			_missingOnnxGateActive = false;
			_missingOnnxGateResumeAfterUtcTicks = 0L;
			InformationManager.HideInquiry();
			BeginSaveAndExitCurrentGame(SaveAndExitReason.MissingOnnx);
		}
		catch (Exception ex)
		{
			HandleSaveAndExitFailure(SaveAndExitReason.MissingOnnx, "保存并退出失败：" + ex.Message);
		}
	}

	private static bool HasCompleteRequiredOnnxFiles()
	{
		try
		{
			string moduleRootPath = GetModuleRootPath();
			if (string.IsNullOrWhiteSpace(moduleRootPath))
			{
				return false;
			}
			string text = Path.Combine(moduleRootPath, "ONNX");
			string text2 = Path.Combine(text, "onnx");
			if (!Directory.Exists(text) && !Directory.Exists(text2))
			{
				return false;
			}
			string text3 = FindFirstExistingFile(Path.Combine(text, "tokenizer.json"), Path.Combine(text2, "tokenizer.json"));
			if (string.IsNullOrEmpty(text3))
			{
				return false;
			}
			string text4 = FindFirstExistingFile(Path.Combine(text, "config.json"), Path.Combine(text2, "config.json"));
			if (string.IsNullOrEmpty(text4))
			{
				return false;
			}
			string text5 = FindFirstExistingFile(Path.Combine(text2, "model_quantized.onnx"), Path.Combine(text, "model_quantized.onnx"));
			if (!string.IsNullOrEmpty(text5))
			{
				return true;
			}
			string text6 = FindFirstExistingFile(Path.Combine(text2, "model.onnx"), Path.Combine(text, "model.onnx"));
			if (string.IsNullOrEmpty(text6))
			{
				return false;
			}
			return File.Exists(text6 + "_data");
		}
		catch
		{
			return false;
		}
	}

	private static string FindFirstExistingFile(params string[] files)
	{
		try
		{
			if (files == null)
			{
				return null;
			}
			foreach (string text in files)
			{
				if (!string.IsNullOrWhiteSpace(text) && File.Exists(text))
				{
					return text;
				}
			}
		}
		catch
		{
		}
		return null;
	}

	private void ProcessPendingWeeklyReportManualRetryResult()
	{
		if (!_pendingWeeklyReportManualRetryResult)
		{
			return;
		}
		bool pendingWeeklyReportManualRetrySucceeded = _pendingWeeklyReportManualRetrySucceeded;
		string text = (_pendingWeeklyReportManualRetryMessage ?? "").Trim();
		WeeklyReportRetryContext weeklyReportRetryContext = _pendingWeeklyReportManualRetryContext;
		_pendingWeeklyReportManualRetryResult = false;
		_pendingWeeklyReportManualRetrySucceeded = false;
		_pendingWeeklyReportManualRetryMessage = "";
		_pendingWeeklyReportManualRetryContext = null;
		_weeklyReportManualRetryInProgress = false;
		InformationManager.HideInquiry();
		if (pendingWeeklyReportManualRetrySucceeded)
		{
			_weeklyReportRetryContext = null;
			_weeklyReportUiStage = WeeklyReportUiStage.None;
			if (!string.IsNullOrWhiteSpace(text))
			{
				InformationManager.DisplayMessage(new InformationMessage(text));
			}
			return;
		}
		if (weeklyReportRetryContext != null)
		{
			_weeklyReportRetryContext = weeklyReportRetryContext;
		}
		_weeklyReportUiStage = WeeklyReportUiStage.None;
		if (!string.IsNullOrWhiteSpace(text))
		{
			InformationManager.DisplayMessage(new InformationMessage(text));
		}
		QueueWeeklyReportFailurePopup(_weeklyReportRetryContext, showImmediate: true);
	}

	private void ProcessWeeklyReportUiResume()
	{
		if (_weeklyReportReopenAfterApiConfig && _weeklyReportRetryContext != null && !_pendingWeeklyReportManualRetryResult)
		{
			if (!InformationManager.IsAnyInquiryActive() && DateTime.UtcNow.Ticks >= _weeklyReportReopenAfterApiConfigUtcTicks)
			{
				_weeklyReportReopenAfterApiConfig = false;
				ShowWeeklyReportFailurePopup(ignoreDelay: true);
			}
		}
		if (_weeklyReportRetryContext == null || _pendingWeeklyReportManualRetryResult)
		{
			return;
		}
		if (_weeklyReportUiStage != WeeklyReportUiStage.Failure && _weeklyReportUiStage != WeeklyReportUiStage.RetryProgress)
		{
			return;
		}
		if (InformationManager.IsAnyInquiryActive())
		{
			return;
		}
		if (DateTime.UtcNow.Ticks < _weeklyReportUiResumeAfterUtcTicks)
		{
			return;
		}
		if (_weeklyReportUiStage == WeeklyReportUiStage.RetryProgress && _weeklyReportManualRetryInProgress)
		{
			ShowWeeklyReportRetryProgressPopup();
			return;
		}
		if (_weeklyReportUiStage == WeeklyReportUiStage.Failure)
		{
			ShowWeeklyReportFailurePopup(ignoreDelay: true);
		}
	}

	private void OpenKingdomRebellionApiRepairFlow()
	{
		_kingdomRebellionReopenAfterApiConfig = true;
		_kingdomRebellionReopenAfterApiConfigUtcTicks = DateTime.UtcNow.Ticks + TimeSpan.FromMilliseconds(300.0).Ticks;
		if (!ModOnboardingBehavior.OpenEventAndRebellionApiRepairFlow())
		{
			InformationManager.DisplayMessage(new InformationMessage("未找到 API 配置引导，请先检查 MCM 中的事件/叛乱API Base URL、API Key 与模型名。"));
		}
	}

	private void ProcessKingdomRebellionApiRepairResume()
	{
		if (!_kingdomRebellionReopenAfterApiConfig)
		{
			return;
		}
		if (InformationManager.IsAnyInquiryActive() || DateTime.UtcNow.Ticks < _kingdomRebellionReopenAfterApiConfigUtcTicks)
		{
			return;
		}
		_kingdomRebellionReopenAfterApiConfig = false;
		if (_blockedAutomaticKingdomRebellionContext != null)
		{
			PendingAutomaticKingdomRebellionContext context = _blockedAutomaticKingdomRebellionContext;
			Kingdom kingdom = FindKingdomById(context.KingdomId);
			Clan clan = FindClanById(context.ClanId);
			List<Clan> followerClans = (context.FollowerClanIds ?? new List<string>()).Select(FindClanById).Where((Clan x) => x != null && x != clan).ToList();
			ShowAutomaticKingdomRebellionNamingFailurePopup(context, kingdom, clan, followerClans, afterApiRepair: true);
			return;
		}
		if (_blockedDevForcedKingdomRebellionContext != null)
		{
			PendingDevForcedKingdomRebellionContext context2 = _blockedDevForcedKingdomRebellionContext;
			Kingdom kingdom2 = FindKingdomById(context2.KingdomId);
			Clan clan2 = FindClanById(context2.ClanId);
			List<Clan> followerClans2 = (context2.FollowerClanIds ?? new List<string>()).Select(FindClanById).Where((Clan x) => x != null && x != clan2).ToList();
			ShowDevForcedKingdomRebellionNamingFailurePopup(context2, kingdom2, clan2, followerClans2, afterApiRepair: true);
		}
	}

	private void ProcessPendingDevForcedKingdomRebellionResult()
	{
		if (!_pendingDevForcedKingdomRebellionReady)
		{
			return;
		}
		PendingDevForcedKingdomRebellionContext pendingDevForcedKingdomRebellionContext = _pendingDevForcedKingdomRebellionContext;
		_pendingDevForcedKingdomRebellionReady = false;
		_pendingDevForcedKingdomRebellionContext = null;
		_devForcedKingdomRebellionInProgress = false;
		if (!DuelSettings.IsKingdomStabilityAndRebellionEnabled())
		{
			InformationManager.HideInquiry();
			InformationManager.DisplayMessage(new InformationMessage("王国稳定度与叛乱功能已在 MCM 中关闭，已取消本次强制叛乱。"));
			return;
		}
		if (pendingDevForcedKingdomRebellionContext == null)
		{
			return;
		}
		Kingdom kingdom = FindKingdomById(pendingDevForcedKingdomRebellionContext.KingdomId);
		Clan clan = FindClanById(pendingDevForcedKingdomRebellionContext.ClanId);
		List<Clan> list = (pendingDevForcedKingdomRebellionContext.FollowerClanIds ?? new List<string>()).Select(FindClanById).Where((Clan x) => x != null).ToList();
		string text;
		bool flag;
		if (kingdom == null || clan == null)
		{
			flag = false;
			text = "叛乱命名已完成，但目标王国或家族状态已变化，无法继续执行。";
		}
		else if (PlayerKingdomRebellionImmunity.ShouldProtectKingdom(kingdom))
		{
			flag = false;
			text = GetKingdomDisplayName(kingdom, "该王国") + " 当前由玩家作为国王统治，且 MCM 已开启玩家王国稳定度叛乱免疫，本次强制稳定度叛乱已跳过。";
		}
		else
		{
			if (!IsRebelKingdomNamingSuccess(pendingDevForcedKingdomRebellionContext.NamingResult))
			{
				ShowDevForcedKingdomRebellionNamingFailurePopup(pendingDevForcedKingdomRebellionContext, kingdom, clan, list, afterApiRepair: false);
				return;
			}
			flag = TryExecuteKingdomRebellionWithNaming(clan, kingdom, pendingDevForcedKingdomRebellionContext.WeekIndex, forceTrigger: true, pendingDevForcedKingdomRebellionContext.RelationToKing, pendingDevForcedKingdomRebellionContext.TownCount, pendingDevForcedKingdomRebellionContext.CastleCount, pendingDevForcedKingdomRebellionContext.NamingResult, list, out text);
		}
		StringBuilder stringBuilder = new StringBuilder();
		if (pendingDevForcedKingdomRebellionContext.NamingResult != null)
		{
			if (!flag)
			{
				ReportRebelKingdomNamingFailure(pendingDevForcedKingdomRebellionContext.NamingResult);
			}
			AppendRebelKingdomNamingResultLines(stringBuilder, pendingDevForcedKingdomRebellionContext.NamingResult);
			stringBuilder.AppendLine();
		}
		if (list.Count > 0)
		{
			stringBuilder.AppendLine("联合响应家族：");
			stringBuilder.AppendLine("- " + string.Join("、", list.Select(GetClanDisplayName)));
			stringBuilder.AppendLine();
		}
		stringBuilder.AppendLine("执行结果：");
		stringBuilder.AppendLine((text ?? "").Trim());
		InformationManager.HideInquiry();
		InformationManager.ShowInquiry(new InquiryData(flag ? "强制叛乱执行完成" : "强制叛乱执行失败", stringBuilder.ToString().TrimEnd(), isAffirmativeOptionShown: true, isNegativeOptionShown: false, "返回详情", "", delegate
		{
			OpenDevKingdomStabilityDetailMenu(kingdom ?? FindKingdomById(pendingDevForcedKingdomRebellionContext.KingdomId));
		}, null));
	}

	private void ShowDevForcedKingdomRebellionNamingFailurePopup(PendingDevForcedKingdomRebellionContext context, Kingdom kingdom, Clan clan, List<Clan> followerClans, bool afterApiRepair)
	{
		StringBuilder stringBuilder = new StringBuilder();
		stringBuilder.AppendLine("强制叛乱已准备执行，但叛乱建国命名没有成功。系统不会使用本地国名继续建国。");
		stringBuilder.AppendLine();
		if (kingdom != null)
		{
			stringBuilder.AppendLine("王国：" + GetKingdomDisplayName(kingdom, "某王国"));
		}
		if (clan != null)
		{
			stringBuilder.AppendLine("主导家族：" + GetClanDisplayName(clan));
		}
		if (followerClans != null && followerClans.Count > 0)
		{
			stringBuilder.AppendLine("联合响应家族：" + string.Join("、", followerClans.Select(GetClanDisplayName)));
		}
		stringBuilder.AppendLine();
		ReportRebelKingdomNamingFailure(context?.NamingResult);
		AppendRebelKingdomNamingResultLines(stringBuilder, context?.NamingResult);
		stringBuilder.AppendLine();
		stringBuilder.AppendLine(afterApiRepair ? "API 配置流程已返回。请重新生成叛乱建国命名，或返回王国稳定度详情。" : "请先重新填写事件/叛乱API信息。修正后可回到这里重新生成命名。");
		InformationManager.HideInquiry();
		InformationManager.ShowInquiry(new InquiryData(afterApiRepair ? "重试叛乱建国命名" : "叛乱建国命名失败", stringBuilder.ToString().TrimEnd(), isAffirmativeOptionShown: true, isNegativeOptionShown: true, afterApiRepair ? "重新生成命名" : "调整API信息", "返回详情", delegate
		{
			if (afterApiRepair)
			{
				RetryBlockedDevForcedKingdomRebellionNaming();
			}
			else
			{
				_blockedDevForcedKingdomRebellionContext = context;
				_blockedAutomaticKingdomRebellionContext = null;
				OpenKingdomRebellionApiRepairFlow();
			}
		}, delegate
		{
			if (ReferenceEquals(_blockedDevForcedKingdomRebellionContext, context))
			{
				_blockedDevForcedKingdomRebellionContext = null;
			}
			_kingdomRebellionReopenAfterApiConfig = false;
			OpenDevKingdomStabilityDetailMenu(kingdom ?? FindKingdomById(context?.KingdomId));
		}), pauseGameActiveState: true);
	}

	private void RetryBlockedDevForcedKingdomRebellionNaming()
	{
		PendingDevForcedKingdomRebellionContext context = _blockedDevForcedKingdomRebellionContext;
		_blockedDevForcedKingdomRebellionContext = null;
		_kingdomRebellionReopenAfterApiConfig = false;
		if (context == null)
		{
			return;
		}
		Kingdom kingdom = FindKingdomById(context.KingdomId);
		Clan clan = FindClanById(context.ClanId);
		List<Clan> list = (context.FollowerClanIds ?? new List<string>()).Select(FindClanById).Where((Clan x) => x != null && x != clan).ToList();
		if (kingdom == null || clan == null)
		{
			InformationManager.DisplayMessage(new InformationMessage("叛乱命名重试前目标王国或家族状态已变化，无法继续执行。"));
			OpenDevKingdomStabilityDetailMenu(kingdom);
			return;
		}
		if (PlayerKingdomRebellionImmunity.ShouldProtectKingdom(kingdom))
		{
			InformationManager.DisplayMessage(new InformationMessage("该王国当前由玩家作为国王统治，且 MCM 已开启玩家王国稳定度叛乱免疫，不能重试强制稳定度叛乱。"));
			OpenDevKingdomStabilityDetailMenu(kingdom);
			return;
		}
		StartDevForcedKingdomRebellionAsync(kingdom, clan, context.WeekIndex, context.RelationToKing, context.TownCount, context.CastleCount, list);
	}

	private void StartDevForcedKingdomRebellionAsync(Kingdom kingdom, Clan clan, int weekIndex, int relationToKing, int townCount, int castleCount, List<Clan> followerClans)
	{
		if (!DuelSettings.IsKingdomStabilityAndRebellionEnabled())
		{
			InformationManager.DisplayMessage(new InformationMessage("王国稳定度与叛乱功能已在 MCM 中关闭，不能启动强制叛乱。"));
			return;
		}
		if (_devForcedKingdomRebellionInProgress)
		{
			InformationManager.DisplayMessage(new InformationMessage("当前已有一条强制叛乱任务正在后台运行，请稍候。"));
			return;
		}
		if (kingdom == null || clan == null)
		{
			InformationManager.DisplayMessage(new InformationMessage("无法启动强制叛乱：找不到目标王国或家族。"));
			return;
		}
		if (PlayerKingdomRebellionImmunity.ShouldProtectKingdom(kingdom))
		{
			InformationManager.DisplayMessage(new InformationMessage("该王国当前由玩家作为国王统治，且 MCM 已开启玩家王国稳定度叛乱免疫，不能启动强制稳定度叛乱。"));
			return;
		}
		List<Clan> list = followerClans?.Where((Clan x) => x != null && x != clan).GroupBy((Clan x) => GetClanId(x), StringComparer.OrdinalIgnoreCase).Select((IGrouping<string, Clan> x) => x.First()).ToList() ?? new List<Clan>();
		BuildRebelKingdomNamingRequest(clan, kingdom, weekIndex, list, out var systemPrompt, out var userPrompt);
		_devForcedKingdomRebellionInProgress = true;
		_pendingDevForcedKingdomRebellionReady = false;
		_pendingDevForcedKingdomRebellionContext = null;
		InformationManager.ShowInquiry(new InquiryData("正在生成叛乱建国命名", "系统正在后台请求 LLM 为这次叛乱生成新王国的名称与百科简介。\n\n这一步完成后，才会真正执行家族反出与建国。\n请稍候，结果完成后会自动弹出。", isAffirmativeOptionShown: false, isNegativeOptionShown: false, "", "", null, null), pauseGameActiveState: true);
		long runtimeGeneration = SaveRuntimeGuard.CaptureGeneration();
		string logTarget = "叛乱建国命名 - " + GetClanId(clan);
		PendingDevForcedKingdomRebellionContext pendingContext = new PendingDevForcedKingdomRebellionContext
		{
			KingdomId = GetKingdomId(kingdom),
			ClanId = GetClanId(clan),
			WeekIndex = weekIndex,
			RelationToKing = relationToKing,
			TownCount = townCount,
			CastleCount = castleCount,
			FollowerClanIds = list.Select(GetClanId).Where((string x) => !string.IsNullOrWhiteSpace(x)).Distinct(StringComparer.OrdinalIgnoreCase).ToList()
		};
		Task.Run(delegate
		{
			RebelKingdomNamingResult namingResult;
			try
			{
				namingResult = GenerateRebelKingdomNamingFromPrompts(systemPrompt, userPrompt, logTarget, RebelKingdomNamingMaxAttempts);
			}
			catch (Exception ex)
			{
				namingResult = BuildFailedRebelKingdomNamingResult("强制叛乱建国命名后台任务异常：" + ex.Message);
			}
			EnqueueKingdomRebellionNamingMainThreadAction(runtimeGeneration, delegate
			{
				pendingContext.NamingResult = namingResult;
				_pendingDevForcedKingdomRebellionContext = pendingContext;
				_pendingDevForcedKingdomRebellionReady = true;
			}, "dev_forced_rebellion_naming");
		});
	}

	private static bool TryResolveActiveKingdomRuledByHeroForPrompt(Hero hero, out Kingdom kingdom)
	{
		kingdom = null;
		if (hero == null)
		{
			return false;
		}
		try
		{
			kingdom = hero.Clan?.Kingdom ?? (hero.MapFaction as Kingdom);
			return kingdom != null
				&& !kingdom.IsEliminated
				&& (kingdom.Leader == hero || kingdom.RulingClan?.Leader == hero);
		}
		catch
		{
			kingdom = null;
			return false;
		}
	}

	private static string BuildHeroIdentityTitleForPrompt(Hero hero)
	{
		if (hero == null)
		{
			return "未知身份";
		}
		try
		{
			if (hero.Occupation == Occupation.Wanderer)
			{
				return "流浪者";
			}
		}
		catch
		{
		}
		try
		{
			Clan clan = hero.Clan;
			Kingdom kingdom = clan?.Kingdom;
			if (clan != null && clan.IsUnderMercenaryService && kingdom != null)
			{
				string text = (kingdom.Name?.ToString() ?? "").Trim();
				if (!string.IsNullOrWhiteSpace(text))
				{
					return text + "的雇佣兵";
				}
			}
		}
		catch
		{
		}
		try
		{
			if (TryResolveActiveKingdomRuledByHeroForPrompt(hero, out Kingdom ruledKingdom))
			{
				string kingdomName = (ruledKingdom.Name?.ToString() ?? "").Trim();
				if (!string.IsNullOrWhiteSpace(kingdomName))
				{
					return kingdomName + "的统治者";
				}
				return "统治者";
			}
			Clan clan = hero.Clan;
			if (clan != null && clan.Leader == hero)
			{
				string clanName = (clan.Name?.ToString() ?? "").Trim();
				if (string.IsNullOrWhiteSpace(clanName))
				{
					return "家族族长";
				}
				return clanName.EndsWith("家族", StringComparison.Ordinal)
					? clanName + "的族长"
					: clanName + "家族的族长";
			}
			string text2 = (hero.MapFaction?.Name?.ToString() ?? "").Trim();
			if (hero.IsLord)
			{
				if (!string.IsNullOrWhiteSpace(text2))
				{
					return text2 + "的封臣";
				}
				return "领主";
			}
			if (hero.IsWanderer)
			{
				return "流浪者";
			}
			if (hero.IsNotable)
			{
				return "地方要人";
			}
			switch (hero.Occupation)
			{
			case Occupation.Merchant:
				return "商人";
			case Occupation.Artisan:
				return "工匠";
			case Occupation.GangLeader:
				return "帮派首领";
			case Occupation.Headman:
				return "村长";
			case Occupation.Preacher:
				return "教士";
			case Occupation.RuralNotable:
				return "乡绅";
			}
		}
		catch
		{
		}
		return "普通角色";
	}

