	public static string BuildSettlementTransferRuntimeInstructionForExternal(Hero targetHero, CharacterObject targetCharacter = null)
	{
		try
		{
			Hero hero = targetHero ?? targetCharacter?.HeroObject;
			string text = BuildPlayerPublicDisplayNameForPrompt(hero);
			if (string.IsNullOrWhiteSpace(text))
			{
				text = "玩家";
			}
			Clan clan = hero?.Clan;
			Hero leader = clan?.Leader;
			if (!IsSettlementTransferLeaderEligible(hero, targetCharacter))
			{
				if (leader != null)
				{
					return $"【固定资产转移规则】你当前没有可直接转移给{text}的固定资产；若{text}想谈家族城市或城堡转移，你必须明确引导{text}去找家族族长 {leader.Name?.ToString() ?? "家族族长"}。正文只口头引导，不写资产转移标签。";
				}
				return $"【固定资产转移规则】你当前没有可直接转移给{text}的固定资产。正文只口头拒绝或引导，不写资产转移标签。";
			}
			List<SettlementTransferPromptEntry> list = BuildSettlementTransferPromptEntriesInternal(hero, targetCharacter);
			List<SettlementTransferPromptEntry> list2All = BuildDisplayIndexedSettlementTransferEntries(((RewardSystemBehavior.Instance != null) ? RewardSystemBehavior.Instance.GetAllowedNpcSettlementTransferEntriesForPlayer(hero, targetCharacter) : list.Where((SettlementTransferPromptEntry x) => x.Section == SettlementTransferEntrySection.NpcFiefs)));
			List<SettlementTransferPromptEntry> list3All = BuildDisplayIndexedSettlementTransferEntries(list.Where((SettlementTransferPromptEntry x) => x.Section == SettlementTransferEntrySection.PlayerFiefs));
			MentionedWorldEntities mentions = AIConfigHandler.GetLatestAuxiliaryMentionedEntitiesForExternal();
			int promptListMax = PromptListRetrievalService.GetMaxCandidateCount();
			List<SettlementTransferPromptEntry> list2 = PromptListRetrievalService.FilterSettlementTransferEntries(list2All, mentions, promptListMax);
			List<SettlementTransferPromptEntry> list3 = PromptListRetrievalService.FilterSettlementTransferEntries(list3All, mentions, promptListMax);
			PromptListRetrievalService.PublishSettlementTransferSnapshot(PromptListRetrievalService.SettlementTransferNpcAssetsSnapshotScope, targetHero, targetCharacter, -1, list2);
			PromptListRetrievalService.PublishSettlementTransferSnapshot(PromptListRetrievalService.SettlementTransferAllNpcAssetsSnapshotScope, targetHero, targetCharacter, -1, list2All);
			StringBuilder stringBuilder = new StringBuilder();
			string text2 = RewardSystemBehavior.Instance?.BuildSettlementTransferPromptGuidanceForAI(hero, targetCharacter);
			if (!string.IsNullOrWhiteSpace(text2))
			{
				stringBuilder.AppendLine(text2.Trim());
			}
			stringBuilder.AppendLine("【固定资产转移规则】固定资产只认本轮清单；只有你最终明确同意现在把你的清单资产转给玩家，才算真的转移。村庄不单独转移,注意，你绝不可以同意转让【你当前可转移固定资产】中不存在的资产，那会导致转让无效！");
			stringBuilder.AppendLine("当前与你谈判的人：" + text);
			AppendSettlementTransferPromptSection(stringBuilder, "【你当前可转移固定资产】：", list2, showPromptIndex: true);
			string settlementRemainder = PromptListRetrievalService.BuildRemainingSettlementTransferSummary(list2All, list2, "你");
			if (!string.IsNullOrWhiteSpace(settlementRemainder))
			{
				stringBuilder.AppendLine(settlementRemainder);
			}
			stringBuilder.Append("你全部可转固定资产: ").Append(list2All.Count).Append(" 项 | 一次结清指导总值: ").Append(CalculateSettlementTransferTotalValueForExternal(list2All)).AppendLine(" 第纳尔");
			AppendSettlementTransferPromptSection(stringBuilder, "【玩家当前可手动交付固定资产（仅供手动交付参考）】：", list3, showPromptIndex: true);
			string playerSettlementRemainder = PromptListRetrievalService.BuildRemainingSettlementTransferSummary(list3All, list3, "玩家");
			if (!string.IsNullOrWhiteSpace(playerSettlementRemainder))
			{
				stringBuilder.AppendLine(playerSettlementRemainder);
			}
			stringBuilder.Append("玩家全部可手动交付固定资产: ").Append(list3All.Count).Append(" 项 | 一次结清指导总值: ").Append(CalculateSettlementTransferTotalValueForExternal(list3All)).AppendLine(" 第纳尔");
			return stringBuilder.ToString().Trim();
		}
		catch
		{
			return "";
		}
	}

	private static void AppendPartyTransferPromptSection(StringBuilder sb, string header, IEnumerable<PartyTransferPromptEntry> entries, bool isPrisoner, bool showPromptIndex)
	{
		if (sb == null)
		{
			return;
		}
		sb.AppendLine(header);
		List<PartyTransferPromptEntry> list = (entries ?? Enumerable.Empty<PartyTransferPromptEntry>()).ToList();
		if (list.Count == 0)
		{
			sb.AppendLine("（无）");
			return;
		}
		foreach (PartyTransferPromptEntry item in list)
		{
			if (item == null)
			{
				continue;
			}
			StringBuilder stringBuilder = new StringBuilder();
			if (showPromptIndex)
			{
				stringBuilder.Append(item.PromptIndex).Append(" ");
			}
			stringBuilder.Append(item.DisplayName).Append(" | 数量 ").Append(Math.Max(0, item.Count));
			if (isPrisoner)
			{
				if (item.IsHero)
				{
					stringBuilder.Append(" | 英雄俘虏");
				}
				string sourceLabel = GetPartyTransferPrisonerSourceLabelForExternal(item);
				if (!string.IsNullOrWhiteSpace(sourceLabel))
				{
					stringBuilder.Append(" | 来源 ").Append(sourceLabel);
				}
				stringBuilder.Append(" | 购买价 ").Append(Math.Max(1, item.BuyPriceDenarsPerUnit)).Append("第纳尔/人");
			}
			else
			{
				stringBuilder.Append(" | 类型 ").Append(GetPartyTransferTroopTypeLabelForExternal(item.Character));
				if (item.Section == PartyTransferEntrySection.NpcVolunteers)
				{
					stringBuilder.Append(" | 来源 原版要人募兵");
				}
				if (item.WoundedCount > 0)
				{
					stringBuilder.Append(" | 其中伤兵 ").Append(item.WoundedCount);
				}
				stringBuilder.Append(" | 日薪 ").Append(Math.Max(1, item.WageDenarsPerDay)).Append("第纳尔/天");
				stringBuilder.Append(" | 雇佣价 ").Append(Math.Max(1, item.HirePriceDenarsPerUnit)).Append("第纳尔/人");
			}
			sb.AppendLine(stringBuilder.ToString());
		}
	}

	public static string GetPartyTransferPrisonerSourceLabelForExternal(PartyTransferPromptEntry entry)
	{
		try
		{
			string settlementName = (entry?.SourceSettlement?.Name?.ToString() ?? "").Trim();
			return string.IsNullOrWhiteSpace(settlementName) ? "" : (settlementName + "地牢");
		}
		catch
		{
			return "";
		}
	}

	internal static long CalculateSettlementTransferTotalValueForExternal(IEnumerable<SettlementTransferPromptEntry> entries)
	{
		long total = 0L;
		foreach (SettlementTransferPromptEntry entry in entries ?? Enumerable.Empty<SettlementTransferPromptEntry>())
		{
			if (!IsSettlementTransferEntryValidForExternal(entry))
			{
				continue;
			}
			total = TransferQuantitySpec.AddProduct(total, 1, Math.Max(0, entry.GuidePriceDenars));
		}
		return total;
	}

	internal static long CalculatePartyTransferTotalValueForExternal(IEnumerable<PartyTransferPromptEntry> entries, bool isPrisoner)
	{
		long total = 0L;
		foreach (PartyTransferPromptEntry entry in entries ?? Enumerable.Empty<PartyTransferPromptEntry>())
		{
			if (entry == null || entry.Character == null || entry.Count <= 0)
			{
				continue;
			}
			int unitValue = isPrisoner ? Math.Max(1, entry.BuyPriceDenarsPerUnit) : Math.Max(1, entry.HirePriceDenarsPerUnit);
			total = TransferQuantitySpec.AddProduct(total, entry.IsHero ? 1 : entry.Count, unitValue);
		}
		return total;
	}

	private static int GetPartyTransferTroopTier(PartyTransferPromptEntry entry)
	{
		return Math.Max(0, entry?.Character?.Tier ?? 0);
	}

	public static string GetPartyTransferTroopTypeLabelForExternal(CharacterObject character)
	{
		try
		{
			switch (character?.DefaultFormationClass)
			{
			case FormationClass.Ranged:
				return "弓手";
			case FormationClass.Cavalry:
				return "骑兵";
			case FormationClass.HorseArcher:
				return "骑射手";
			case FormationClass.Infantry:
			case FormationClass.HeavyInfantry:
			case FormationClass.NumberOfDefaultFormations:
				return "步兵";
			default:
				if (character != null)
				{
					if (character.IsMounted)
					{
						return character.IsRanged ? "骑射手" : "骑兵";
					}
					if (character.IsRanged)
					{
						return "弓手";
					}
				}
				return "步兵";
			}
		}
		catch
		{
			return "步兵";
		}
	}

	private static Hero ResolvePartyTransferRuleHero(Hero targetHero, CharacterObject targetCharacter)
	{
		return targetHero ?? targetCharacter?.HeroObject;
	}

	private static bool IsPartyTransferLordEligible(Hero targetHero, CharacterObject targetCharacter = null)
	{
		Hero hero = ResolvePartyTransferRuleHero(targetHero, targetCharacter);
		return hero != null && hero.IsLord;
	}

	public static bool IsPartyTransferLordEligibleForExternal(Hero targetHero, CharacterObject targetCharacter = null)
	{
		try
		{
			return IsPartyTransferLordEligible(targetHero, targetCharacter);
		}
		catch
		{
			return false;
		}
	}

	private static int ResolvePartyTransferRecruitTrustLevelIndex(Hero targetHero, CharacterObject targetCharacter)
	{
		int num = 6;
		try
		{
			Hero hero = targetHero ?? targetCharacter?.HeroObject;
			if (hero != null)
			{
				return RewardSystemBehavior.GetTrustLevelIndex(RewardSystemBehavior.Instance?.GetEffectiveTrust(hero) ?? 0);
			}
			if (targetCharacter != null && RewardSystemBehavior.Instance != null && RewardSystemBehavior.Instance.TryGetSettlementMerchantKind(targetCharacter, out var kind))
			{
				return RewardSystemBehavior.GetTrustLevelIndex(RewardSystemBehavior.Instance.GetSettlementMerchantEffectiveTrust(Settlement.CurrentSettlement, kind));
			}
		}
		catch
		{
		}
		return num;
	}

	private static int ResolvePartyTransferRecruitMaxTier(int trustLevelIndex)
	{
		if (trustLevelIndex <= 4)
		{
			return 0;
		}
		if (trustLevelIndex == 5)
		{
			return 1;
		}
		if (trustLevelIndex == 6)
		{
			return 2;
		}
		if (trustLevelIndex == 7)
		{
			return 3;
		}
		if (trustLevelIndex == 8)
		{
			return 4;
		}
		return int.MaxValue;
	}

	private static void AppendPartyTransferHiddenTroopSection(StringBuilder sb, string header, IEnumerable<PartyTransferPromptEntry> entries)
	{
		if (sb == null)
		{
			return;
		}
		List<PartyTransferPromptEntry> list = (entries ?? Enumerable.Empty<PartyTransferPromptEntry>()).Where((PartyTransferPromptEntry x) => x != null).ToList();
		if (list.Count == 0)
		{
			return;
		}
		sb.AppendLine(header);
		foreach (PartyTransferPromptEntry item in list)
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append(item.DisplayName).Append(" | 类型 ").Append(GetPartyTransferTroopTypeLabelForExternal(item.Character)).Append(" | 阶级 ").Append(GetPartyTransferTroopTier(item)).Append(" | 数量 ").Append(Math.Max(0, item.Count));
			if (item.WoundedCount > 0)
			{
				stringBuilder.Append(" | 其中伤兵 ").Append(item.WoundedCount);
			}
			sb.AppendLine(stringBuilder.ToString());
		}
	}

	private static List<PartyTransferPromptEntry> BuildDisplayIndexedPartyTransferEntries(IEnumerable<PartyTransferPromptEntry> entries)
	{
		List<PartyTransferPromptEntry> list = new List<PartyTransferPromptEntry>();
		int num = 1;
		foreach (PartyTransferPromptEntry entry in entries ?? Enumerable.Empty<PartyTransferPromptEntry>())
		{
			if (entry == null)
			{
				continue;
			}
			list.Add(new PartyTransferPromptEntry
			{
				PromptIndex = num++,
				Section = entry.Section,
				Character = entry.Character,
				DisplayName = entry.DisplayName,
				Count = entry.Count,
				WoundedCount = entry.WoundedCount,
				WageDenarsPerDay = entry.WageDenarsPerDay,
				HirePriceDenarsPerUnit = entry.HirePriceDenarsPerUnit,
				BuyPriceDenarsPerUnit = entry.BuyPriceDenarsPerUnit,
				IsHero = entry.IsHero,
				OwnerParty = entry.OwnerParty,
				SourceSettlement = entry.SourceSettlement,
				VolunteerOwner = entry.VolunteerOwner,
				VolunteerSlotIndices = entry.VolunteerSlotIndices == null ? null : new List<int>(entry.VolunteerSlotIndices)
			});
		}
		return list;
	}

	private static IEnumerable<PartyTransferPromptEntry> FilterAllowedNpcTransferTroopEntries(IEnumerable<PartyTransferPromptEntry> entries, Hero targetHero, CharacterObject targetCharacter)
	{
		List<PartyTransferPromptEntry> list = (entries ?? Enumerable.Empty<PartyTransferPromptEntry>()).Where((PartyTransferPromptEntry x) => x != null).ToList();
		int partyTransferRecruitTrustLevelIndex = ResolvePartyTransferRecruitTrustLevelIndex(targetHero, targetCharacter);
		int partyTransferRecruitMaxTier = ResolvePartyTransferRecruitMaxTier(partyTransferRecruitTrustLevelIndex);
		IEnumerable<PartyTransferPromptEntry> first = Enumerable.Empty<PartyTransferPromptEntry>();
		if (partyTransferRecruitMaxTier > 0)
		{
			first = list.Where((PartyTransferPromptEntry x) => x.Section == PartyTransferEntrySection.NpcTroops && GetPartyTransferTroopTier(x) > 0 && GetPartyTransferTroopTier(x) <= partyTransferRecruitMaxTier);
		}
		IEnumerable<PartyTransferPromptEntry> second = list.Where((PartyTransferPromptEntry x) => x.Section == PartyTransferEntrySection.NpcVolunteers);
		return first.Concat(second);
	}

	private static PartyTransferPromptEntry FindDisplayIndexedPartyTransferEntry(IEnumerable<PartyTransferPromptEntry> entries, int displayIndex)
	{
		if (displayIndex <= 0)
		{
			return null;
		}
		List<PartyTransferPromptEntry> list = (entries ?? Enumerable.Empty<PartyTransferPromptEntry>()).Where((PartyTransferPromptEntry x) => x != null).ToList();
		return list.FirstOrDefault((PartyTransferPromptEntry x) => x.PromptIndex == displayIndex) ?? list.Skip(displayIndex - 1).FirstOrDefault();
	}

	private static PartyTransferPromptEntry ResolveNpcTransferEntryByDisplayIndex(Hero targetHero, CharacterObject targetCharacter, int targetAgentIndex, PartyTransferEntrySection section, int displayIndex)
	{
		if (displayIndex <= 0)
		{
			return null;
		}
		List<PartyTransferPromptEntry> list = BuildPartyTransferPromptEntriesInternal(targetHero, targetCharacter, targetAgentIndex);
		IEnumerable<PartyTransferPromptEntry> enumerable = Enumerable.Empty<PartyTransferPromptEntry>();
		if (section == PartyTransferEntrySection.NpcTroops)
		{
			enumerable = list.Where((PartyTransferPromptEntry x) => x != null && (x.Section == PartyTransferEntrySection.NpcTroops || x.Section == PartyTransferEntrySection.NpcVolunteers));
		}
		else if (section == PartyTransferEntrySection.NpcPrisoners)
		{
			enumerable = list.Where((PartyTransferPromptEntry x) => x != null && x.Section == PartyTransferEntrySection.NpcPrisoners);
		}
		return FindDisplayIndexedPartyTransferEntry(BuildDisplayIndexedPartyTransferEntries(enumerable), displayIndex);
	}

	public static string BuildPartyTransferRuntimeInstructionForExternal(Hero targetHero, CharacterObject targetCharacter = null, int targetAgentIndex = -1)
	{
		try
		{
			List<PartyTransferPromptEntry> list = BuildPartyTransferPromptEntriesInternal(targetHero, targetCharacter, targetAgentIndex, out PartyBase wildernessNonHeroSource);
			Hero hero = ResolvePartyTransferRuleHero(targetHero, targetCharacter);
			bool flag = IsPartyTransferLordEligible(targetHero, targetCharacter);
			bool flag2 = IsPartyTransferNotableRecruitEligible(hero);
			if (!flag && !flag2 && wildernessNonHeroSource == null)
			{
				string guardrailRuleNonHeroInstruction = AIConfigHandler.GetGuardrailRuleNonHeroInstruction("party_transfer");
				return string.IsNullOrWhiteSpace(guardrailRuleNonHeroInstruction) ? "" : StripPartyTransferTags(guardrailRuleNonHeroInstruction);
			}
			string text = BuildPlayerPublicDisplayNameForPrompt();
			if (string.IsNullOrWhiteSpace(text))
			{
				text = "玩家";
			}
			int partyTransferRecruitTrustLevelIndex = ResolvePartyTransferRecruitTrustLevelIndex(targetHero, targetCharacter);
			int partyTransferRecruitMaxTier = ResolvePartyTransferRecruitMaxTier(partyTransferRecruitTrustLevelIndex);
			bool canUseCounterpartyRoster = flag || wildernessNonHeroSource != null;
			List<PartyTransferPromptEntry> list2 = list.Where((PartyTransferPromptEntry x) => x != null && x.Section == PartyTransferEntrySection.NpcTroops).ToList();
			List<PartyTransferPromptEntry> list3 = list2.Where((PartyTransferPromptEntry x) => GetPartyTransferTroopTier(x) > 0 && GetPartyTransferTroopTier(x) <= partyTransferRecruitMaxTier).ToList();
			List<PartyTransferPromptEntry> list4 = list2.Where((PartyTransferPromptEntry x) => !list3.Contains(x)).ToList();
			List<PartyTransferPromptEntry> list5 = list.Where((PartyTransferPromptEntry x) => x != null && x.Section == PartyTransferEntrySection.NpcVolunteers).ToList();
			List<PartyTransferPromptEntry> listAllTroops = BuildDisplayIndexedPartyTransferEntries(list2.Concat(list5));
			List<PartyTransferPromptEntry> list6All = BuildDisplayIndexedPartyTransferEntries(list3.Concat(list5));
			List<PartyTransferPromptEntry> authorizedAllTroops = wildernessNonHeroSource != null ? list6All : listAllTroops;
			List<PartyTransferPromptEntry> list7All = BuildDisplayIndexedPartyTransferEntries(list.Where((PartyTransferPromptEntry x) => x.Section == PartyTransferEntrySection.NpcPrisoners));
			MentionedWorldEntities mentions = AIConfigHandler.GetLatestAuxiliaryMentionedEntitiesForExternal();
			int promptListMax = PromptListRetrievalService.GetMaxCandidateCount();
			List<PartyTransferPromptEntry> list4Filtered = PromptListRetrievalService.FilterPartyTransferEntries(list4, mentions, promptListMax, isPrisoner: false);
			List<PartyTransferPromptEntry> list6 = PromptListRetrievalService.FilterPartyTransferEntries(list6All, mentions, promptListMax, isPrisoner: false);
			List<PartyTransferPromptEntry> list7 = PromptListRetrievalService.FilterPartyTransferEntries(list7All, mentions, promptListMax, isPrisoner: true);
			PromptListRetrievalService.PublishPartyTransferSnapshot(PromptListRetrievalService.PartyTransferTroopsSnapshotScope, targetHero, targetCharacter, targetAgentIndex, list6);
			PromptListRetrievalService.PublishPartyTransferSnapshot(PromptListRetrievalService.PartyTransferPrisonersSnapshotScope, targetHero, targetCharacter, targetAgentIndex, list7);
			PromptListRetrievalService.PublishPartyTransferSnapshot(PromptListRetrievalService.PartyTransferAllTroopsSnapshotScope, targetHero, targetCharacter, targetAgentIndex, authorizedAllTroops);
			PromptListRetrievalService.PublishPartyTransferSnapshot(PromptListRetrievalService.PartyTransferAllPrisonersSnapshotScope, targetHero, targetCharacter, targetAgentIndex, list7All);
			StringBuilder stringBuilder = new StringBuilder();
			if (wildernessNonHeroSource != null)
			{
				string wildernessInstruction = AIConfigHandler.ResolveRuleRuntimeText("party_transfer", "wilderness_nonhero_party", forConstraint: false, null);
				if (!string.IsNullOrWhiteSpace(wildernessInstruction))
				{
					stringBuilder.AppendLine(wildernessInstruction.Trim());
				}
			}
			string runtimeHint = flag
				? AIConfigHandler.BuildRuntimePartyTransferInstructionForExternal(targetHero, targetCharacter)
				: (wildernessNonHeroSource != null
					? AIConfigHandler.ResolveRuleRuntimeText("party_transfer", "level_" + partyTransferRecruitTrustLevelIndex, forConstraint: false, new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase) { ["playerName"] = text })
					: "");
			if (!string.IsNullOrWhiteSpace(runtimeHint))
			{
				stringBuilder.AppendLine(runtimeHint.Trim());
			}
			if (partyTransferRecruitMaxTier <= 0 && list5.Count == 0)
			{
				stringBuilder.AppendLine("【当前招募限制】你当前对" + text + "的信任不足，任何士兵都不可开放招募。本轮不要展示【你当前可转移部队】清单；正文只口头拒绝或解释。");
			}
			else if (canUseCounterpartyRoster && partyTransferRecruitMaxTier == int.MaxValue)
			{
				stringBuilder.AppendLine("【当前招募限制】你当前对" + text + "的信任已足够，所有已编号的士兵都可正常谈招募。若你最终明确同意放人，才算成交；正文只口头答应、拒绝或谈条件。");
			}
			else if (canUseCounterpartyRoster)
			{
				stringBuilder.AppendLine("【当前招募限制】你当前只可向" + text + "开放 " + partyTransferRecruitMaxTier + " 阶及以下士兵的招募。只有本轮仍带编号的这些士兵才可供讨论；正文只口头答应、拒绝或谈条件。");
			}
			if (flag2)
			{
				int maximumRecruitableVolunteerIndex = GetMaximumRecruitableVolunteerIndex(hero);
				if (maximumRecruitableVolunteerIndex >= 0)
				{
					stringBuilder.AppendLine("【原版要人募兵】你这里按原版城镇/村庄要人募兵规则实时计算；当前只开放原版允许的招募槽位（最高槽位索引 " + maximumRecruitableVolunteerIndex + "）。成交后对应槽位会立刻清空，之后仍由原版系统自然刷新。");
				}
				else
				{
					stringBuilder.AppendLine("【原版要人募兵】你这里按原版城镇/村庄要人募兵规则实时计算；由于关系、阵营或战况等原版条件，本轮没有向" + text + "开放任何招募槽位。正文只口头拒绝或解释。");
				}
			}
			if (wildernessNonHeroSource == null)
			{
				stringBuilder.AppendLine("若你明确同意移交全部士兵，全量转移不受本段信任阶级和展示上限限制，但所有Hero都会留下；正文仍只自然答复。");
			}
			stringBuilder.AppendLine("日薪表示每名士兵每天需要支付多少第纳尔；雇佣价与购买价表示当前谈判指导单价。");
			stringBuilder.AppendLine("当前与你交易的人：" + text);
			if (partyTransferRecruitMaxTier > 0 || list5.Count > 0)
			{
				AppendPartyTransferPromptSection(stringBuilder, "【你当前可转移或可招募部队】：", list6, isPrisoner: false, showPromptIndex: true);
				string troopRemainder = PromptListRetrievalService.BuildRemainingPartyTransferSummary(list6All, list6, isPrisoner: false, "你");
				if (!string.IsNullOrWhiteSpace(troopRemainder))
				{
					stringBuilder.AppendLine(troopRemainder);
				}
			}
			if (canUseCounterpartyRoster && partyTransferRecruitMaxTier > 0 && partyTransferRecruitMaxTier < int.MaxValue)
			{
				AppendPartyTransferHiddenTroopSection(stringBuilder, "【由于你对" + text + "不够信任，你当前不可向" + text + "开放招募的更高阶部队】：", list4Filtered);
			}
			string troopTotalLabel = wildernessNonHeroSource != null ? "本轮可移交的全部非Hero士兵: " : "全部非Hero士兵: ";
			stringBuilder.Append(troopTotalLabel).Append(authorizedAllTroops.Sum((PartyTransferPromptEntry x) => Math.Max(0, x?.Count ?? 0))).Append(" 人 | 雇佣指导总值: ").Append(CalculatePartyTransferTotalValueForExternal(authorizedAllTroops, isPrisoner: false)).AppendLine(" 第纳尔");
			AppendPartyTransferPromptSection(stringBuilder, "【你当前可转移俘虏】：", list7, isPrisoner: true, showPromptIndex: true);
			string prisonerRemainder = PromptListRetrievalService.BuildRemainingPartyTransferSummary(list7All, list7, isPrisoner: true, "你");
			if (!string.IsNullOrWhiteSpace(prisonerRemainder))
			{
				stringBuilder.AppendLine(prisonerRemainder);
			}
			stringBuilder.Append("全部俘虏: ").Append(list7All.Sum((PartyTransferPromptEntry x) => Math.Max(0, x?.Count ?? 0))).Append(" 人 | 购买指导总值: ").Append(CalculatePartyTransferTotalValueForExternal(list7All, isPrisoner: true)).AppendLine(" 第纳尔");
			// This text is injected into the NPC's main reply prompt. Action syntax belongs only
			// to the isolated postprocess prompt, so runtime/configuration values are sanitized here.
			return StripPartyTransferTags(stringBuilder.ToString());
		}
		catch
		{
			return "";
		}
	}

	private static int ClampWildernessNonHeroPartyTransferAmount(PartyTransferPromptEntry entry, int requestedAmount, PartyBase wildernessNonHeroSource, CharacterObject representativeCharacter)
	{
		int amount = Math.Max(0, requestedAmount);
		if (wildernessNonHeroSource == null)
		{
			return amount;
		}
		if (entry == null || entry.OwnerParty != wildernessNonHeroSource)
		{
			return 0;
		}
		if (!IsSamePartyTransferCharacter(entry.Character, representativeCharacter))
		{
			return amount;
		}
		try
		{
			TroopRoster roster = wildernessNonHeroSource.MemberRoster;
			int index = roster?.FindIndexOfTroop(entry.Character) ?? (-1);
			if (index < 0)
			{
				return 0;
			}
			int currentCount = Math.Max(0, roster.GetElementCopyAtIndex(index).Number);
			return Math.Min(amount, Math.Max(0, currentCount - 1));
		}
		catch
		{
			return 0;
		}
	}

	private static int TransferPartyMemberEntry(PartyTransferPromptEntry entry, int requestedAmount, PartyBase targetParty)
	{
		if (IsPartyTransferVolunteerEntry(entry))
		{
			return TransferPartyVolunteerEntry(entry, requestedAmount, targetParty);
		}
		if (entry == null || targetParty == null || entry.OwnerParty == null || entry.OwnerParty == targetParty || entry.Character == null || entry.Character.IsHero || entry.Character == CharacterObject.PlayerCharacter)
		{
			return 0;
		}
		TroopRoster memberRoster = entry.OwnerParty.MemberRoster;
		TroopRoster memberRoster2 = targetParty.MemberRoster;
		if (memberRoster == null || memberRoster2 == null)
		{
			return 0;
		}
		int num = memberRoster.FindIndexOfTroop(entry.Character);
		if (num < 0)
		{
			return 0;
		}
		TroopRosterElement elementCopyAtIndex = memberRoster.GetElementCopyAtIndex(num);
		int num2 = Math.Min(Math.Max(0, requestedAmount), Math.Max(0, elementCopyAtIndex.Number));
		if (num2 <= 0)
		{
			return 0;
		}
		int num3 = 0;
		if (elementCopyAtIndex.Number > 0 && elementCopyAtIndex.WoundedNumber > 0)
		{
			num3 = (num2 >= elementCopyAtIndex.Number) ? elementCopyAtIndex.WoundedNumber : Math.Min(num2, Math.Max(0, (int)Math.Round((double)elementCopyAtIndex.WoundedNumber * (double)num2 / (double)elementCopyAtIndex.Number, MidpointRounding.AwayFromZero)));
		}
		int num4 = 0;
		if (elementCopyAtIndex.Number > 0 && elementCopyAtIndex.Xp > 0)
		{
			num4 = (num2 >= elementCopyAtIndex.Number) ? elementCopyAtIndex.Xp : Math.Max(0, (int)Math.Round((double)elementCopyAtIndex.Xp * (double)num2 / (double)elementCopyAtIndex.Number, MidpointRounding.AwayFromZero));
		}
		memberRoster.AddToCounts(entry.Character, -num2, insertAtFront: false, -num3, 0, false, -1);
		if (num4 > 0)
		{
			memberRoster.AddXpToTroop(entry.Character, -num4);
		}
		memberRoster2.AddToCounts(entry.Character, num2, insertAtFront: false, num3, 0, false, -1);
		if (num4 > 0)
		{
			memberRoster2.AddXpToTroop(entry.Character, num4);
		}
		return num2;
	}

	private static int TransferPartyVolunteerEntry(PartyTransferPromptEntry entry, int requestedAmount, PartyBase targetParty)
	{
		if (!IsPartyTransferVolunteerEntry(entry) || targetParty?.MemberRoster == null || requestedAmount <= 0)
		{
			return 0;
		}
		Hero volunteerOwner = entry.VolunteerOwner;
		CharacterObject character = entry.Character;
		CharacterObject[] volunteerTypes = volunteerOwner.VolunteerTypes;
		if (volunteerTypes == null)
		{
			return 0;
		}
		int maximumRecruitableVolunteerIndex = GetMaximumRecruitableVolunteerIndex(volunteerOwner);
		if (maximumRecruitableVolunteerIndex < 0)
		{
			return 0;
		}
		int num = 0;
		int num2 = Math.Min(Math.Min(5, maximumRecruitableVolunteerIndex), volunteerTypes.Length - 1);
		for (int i = 0; i <= num2 && num < requestedAmount; i++)
		{
			if (volunteerTypes[i] != character)
			{
				continue;
			}
			volunteerTypes[i] = null;
			targetParty.MemberRoster.AddToCounts(character, 1, insertAtFront: false, 0, 0, true, -1);
			num++;
		}
		if (num > 0)
		{
			CampaignEventDispatcher.Instance.OnUnitRecruited(character, num);
		}
		return num;
	}

	private static bool IsPartyTransferDungeonSourceValid(PartyTransferPromptEntry entry, Clan expectedOwnerClan)
	{
		if (entry?.SourceSettlement == null)
		{
			return true;
		}
		Settlement sourceSettlement = entry.SourceSettlement;
		if (expectedOwnerClan == null || sourceSettlement.OwnerClan != expectedOwnerClan || !sourceSettlement.IsFortification)
		{
			return false;
		}
		if (entry.OwnerParty == sourceSettlement.Party)
		{
			return true;
		}
		try
		{
			return sourceSettlement.Parties.Any((MobileParty x) => x != null && x.IsGarrison && x.Party == entry.OwnerParty);
		}
		catch
		{
			return false;
		}
	}

	private static int TransferPartyPrisonerEntry(PartyTransferPromptEntry entry, int requestedAmount, PartyBase targetParty, Clan expectedDungeonOwnerClan = null)
	{
		if (entry == null || targetParty == null || entry.OwnerParty == null || entry.OwnerParty == targetParty || entry.Character == null)
		{
			return 0;
		}
		if (entry.Character.IsHero)
		{
			Hero heroObject = entry.Character.HeroObject;
			TroopRoster sourceRoster = entry.OwnerParty.PrisonRoster;
			if (requestedAmount <= 0 || heroObject == null || !heroObject.IsPrisoner || heroObject.PartyBelongedToAsPrisoner != entry.OwnerParty || sourceRoster == null || sourceRoster.FindIndexOfTroop(entry.Character) < 0 || !IsPartyTransferDungeonSourceValid(entry, expectedDungeonOwnerClan))
			{
				return 0;
			}
			if (targetParty.PrisonRoster?.FindIndexOfTroop(entry.Character) >= 0)
			{
				return 0;
			}
			try
			{
				TransferPrisonerAction.Apply(entry.Character, entry.OwnerParty, targetParty);
				return heroObject.PartyBelongedToAsPrisoner == targetParty && (targetParty.PrisonRoster?.FindIndexOfTroop(entry.Character) ?? (-1)) >= 0 ? 1 : 0;
			}
			catch
			{
				return 0;
			}
		}
		TroopRoster prisonRoster = entry.OwnerParty.PrisonRoster;
		if (prisonRoster == null)
		{
			return 0;
		}
		int num = prisonRoster.FindIndexOfTroop(entry.Character);
		if (num < 0)
		{
			return 0;
		}
		TroopRosterElement elementCopyAtIndex = prisonRoster.GetElementCopyAtIndex(num);
		int num2 = Math.Min(Math.Max(0, requestedAmount), Math.Max(0, elementCopyAtIndex.Number));
		if (num2 <= 0)
		{
			return 0;
		}
		int num3 = 0;
		if (elementCopyAtIndex.Number > 0 && elementCopyAtIndex.Xp > 0)
		{
			num3 = (num2 >= elementCopyAtIndex.Number) ? elementCopyAtIndex.Xp : Math.Max(0, (int)Math.Round((double)elementCopyAtIndex.Xp * (double)num2 / (double)elementCopyAtIndex.Number, MidpointRounding.AwayFromZero));
		}
		prisonRoster.AddToCounts(entry.Character, -num2, insertAtFront: false, 0, 0, false, -1);
		if (num3 > 0)
		{
			prisonRoster.AddXpToTroop(entry.Character, -num3);
		}
		targetParty.AddPrisoner(entry.Character, num2);
		if (num3 > 0)
		{
			targetParty.PrisonRoster?.AddXpToTroop(entry.Character, num3);
		}
		return num2;
	}

	private static void AppendPartyTransferFactItem(StringBuilder builder, PartyTransferPromptEntry entry, int amount)
	{
		if (builder == null || entry == null || amount <= 0)
		{
			return;
		}
		if (builder.Length > 0)
		{
			builder.Append('、');
		}
		builder.Append(entry.DisplayName).Append('x').Append(amount);
	}

	private static string StripPartyTransferTags(string text)
	{
		string result = Regex.Replace(text ?? "", "\\[ATT:[^\\]\\r\\n]*\\]", "", RegexOptions.IgnoreCase);
		return Regex.Replace(result, "\\[ATP:[^\\]\\r\\n]*\\]", "", RegexOptions.IgnoreCase).Trim();
	}

	public static bool TryApplyPartyTransferTagsForExternal(Hero targetHero, CharacterObject targetCharacter, int targetAgentIndex, ref string content, out List<string> generatedFacts, out List<string> notifications)
	{
		generatedFacts = new List<string>();
		notifications = new List<string>();
		List<string> factResults = generatedFacts;
		List<string> notificationResults = notifications;
		try
		{
			string text = content ?? "";
			Hero ruleHero = ResolvePartyTransferRuleHero(targetHero, targetCharacter);
			bool wildernessNonHeroEligible = TryResolveWildernessNonHeroPartyTransferSource(targetHero, targetCharacter, targetAgentIndex, out PartyBase wildernessNonHeroSource);
			if (!IsPartyTransferLordEligible(targetHero, targetCharacter) && !IsPartyTransferNotableRecruitEligible(ruleHero) && !wildernessNonHeroEligible)
			{
				content = StripPartyTransferTags(text);
				return false;
			}
			MatchCollection matchCollection = TransferTroopTagRegex.Matches(text);
			MatchCollection matchCollection2 = TransferPrisonerTagRegex.Matches(text);
			if ((matchCollection?.Count ?? 0) <= 0 && (matchCollection2?.Count ?? 0) <= 0)
			{
				content = StripPartyTransferTags(text);
				return false;
			}
			bool hasTroopSnapshot = PromptListRetrievalService.TryGetPartyTransferSnapshot(PromptListRetrievalService.PartyTransferTroopsSnapshotScope, targetHero, targetCharacter, targetAgentIndex, out var list2);
			bool hasPrisonerSnapshot = PromptListRetrievalService.TryGetPartyTransferSnapshot(PromptListRetrievalService.PartyTransferPrisonersSnapshotScope, targetHero, targetCharacter, targetAgentIndex, out var list3);
			bool hasAllTroopSnapshot = PromptListRetrievalService.TryGetPartyTransferSnapshot(PromptListRetrievalService.PartyTransferAllTroopsSnapshotScope, targetHero, targetCharacter, targetAgentIndex, out var allTroops);
			bool hasAllPrisonerSnapshot = PromptListRetrievalService.TryGetPartyTransferSnapshot(PromptListRetrievalService.PartyTransferAllPrisonersSnapshotScope, targetHero, targetCharacter, targetAgentIndex, out var allPrisoners);
			PartyBase party = Hero.MainHero?.PartyBelongedTo?.Party ?? MobileParty.MainParty?.Party;
			string text2 = ResolvePartyTransferTargetDisplayName(targetHero, targetCharacter, targetAgentIndex);
			bool flag = false;
			int attemptedEntries = 0;
			int successfulEntries = 0;
			int failedOrPartialEntries = 0;
			long actualUnits = 0L;
			long actualValue = 0L;
			if (party != null)
			{
				StringBuilder transferredTroopFacts = new StringBuilder();
				StringBuilder recruitedVolunteerFacts = new StringBuilder();
				StringBuilder transferredPrisonerFacts = new StringBuilder();
				void applyTroop(PartyTransferPromptEntry entry, int requested, string source)
				{
					attemptedEntries++;
					int authorizedRequested = ClampWildernessNonHeroPartyTransferAmount(entry, requested, wildernessNonHeroSource, targetCharacter);
					int applied = TransferPartyMemberEntry(entry, authorizedRequested, party);
					Logger.Log("Logic", "[PartyTransfer] ATT source=" + source + " amount=" + requested + " resolved=" + (entry?.DisplayName ?? "null") + " section=" + (entry?.Section.ToString() ?? "null") + " applied=" + applied);
					if (applied <= 0)
					{
						failedOrPartialEntries++;
						return;
					}
					flag = true;
					successfulEntries++;
					if (applied < Math.Max(0, requested))
					{
						failedOrPartialEntries++;
					}
					actualUnits = TransferQuantitySpec.AddValue(actualUnits, applied);
					actualValue = TransferQuantitySpec.AddProduct(actualValue, applied, Math.Max(1, entry?.HirePriceDenarsPerUnit ?? 0));
					bool isVolunteer = IsPartyTransferVolunteerEntry(entry);
					AppendPartyTransferFactItem(isVolunteer ? recruitedVolunteerFacts : transferredTroopFacts, entry, applied);
					notificationResults.Add((isVolunteer ? "已招募 " : "已获得 ") + applied + " 名" + entry.DisplayName);
				}
				void applyPrisoner(PartyTransferPromptEntry entry, int requested, string source)
				{
					attemptedEntries++;
					bool currentWildernessSource = wildernessNonHeroSource == null || entry?.OwnerParty == wildernessNonHeroSource;
					int applied = currentWildernessSource ? TransferPartyPrisonerEntry(entry, requested, party, ruleHero?.Clan) : 0;
					Logger.Log("Logic", "[PartyTransfer] ATP source=" + source + " amount=" + requested + " resolved=" + (entry?.DisplayName ?? "null") + " applied=" + applied);
					if (applied <= 0)
					{
						failedOrPartialEntries++;
						return;
					}
					flag = true;
					successfulEntries++;
					if (applied < Math.Max(0, requested))
					{
						failedOrPartialEntries++;
					}
					actualUnits = TransferQuantitySpec.AddValue(actualUnits, applied);
					actualValue = TransferQuantitySpec.AddProduct(actualValue, applied, Math.Max(1, entry?.BuyPriceDenarsPerUnit ?? 0));
					AppendPartyTransferFactItem(transferredPrisonerFacts, entry, applied);
					notificationResults.Add("已获得 " + (entry.IsHero ? ("俘虏" + entry.DisplayName) : (applied + " 名" + entry.DisplayName + "俘虏")));
				}
				bool troopAll = matchCollection.Cast<Match>().Any((Match x) => x.Success && (TransferQuantitySpec.IsAllValue(x.Groups[2].Value) || (TransferQuantitySpec.IsAllValue(x.Groups[1].Value) && int.TryParse(x.Groups[2].Value, out var amount) && amount > 0)));
				if (troopAll)
				{
					if (!hasAllTroopSnapshot)
					{
						attemptedEntries++;
						failedOrPartialEntries++;
						Logger.Log("Logic", "[PartyTransfer] ATT ALL rejected: authorization snapshot missing.");
					}
					foreach (PartyTransferPromptEntry entry in hasAllTroopSnapshot ? allTroops : new List<PartyTransferPromptEntry>())
					{
						applyTroop(entry, Math.Max(0, entry?.Count ?? 0), "ALL");
					}
				}
				else
				{
					if (!hasTroopSnapshot)
					{
						attemptedEntries += matchCollection?.Count ?? 0;
						failedOrPartialEntries += matchCollection?.Count ?? 0;
						Logger.Log("Logic", "[PartyTransfer] ATT rejected: authorization snapshot missing.");
					}
					foreach (Match item in hasTroopSnapshot ? matchCollection.Cast<Match>() : Enumerable.Empty<Match>())
					{
						if (item.Success && int.TryParse(item.Groups[1].Value, out var index) && int.TryParse(item.Groups[2].Value, out var amount))
						{
							applyTroop(FindDisplayIndexedPartyTransferEntry(list2, index), amount, "index=" + index);
						}
					}
				}
				bool prisonerAll = matchCollection2.Cast<Match>().Any((Match x) => x.Success && (TransferQuantitySpec.IsAllValue(x.Groups[2].Value) || (TransferQuantitySpec.IsAllValue(x.Groups[1].Value) && int.TryParse(x.Groups[2].Value, out var amount) && amount > 0)));
				if (prisonerAll)
				{
					if (!hasAllPrisonerSnapshot)
					{
						attemptedEntries++;
						failedOrPartialEntries++;
						Logger.Log("Logic", "[PartyTransfer] ATP ALL rejected: authorization snapshot missing.");
					}
					foreach (PartyTransferPromptEntry entry in hasAllPrisonerSnapshot ? allPrisoners : new List<PartyTransferPromptEntry>())
					{
						applyPrisoner(entry, Math.Max(0, entry?.Count ?? 0), "ALL");
					}
				}
				else
				{
					if (!hasPrisonerSnapshot)
					{
						attemptedEntries += matchCollection2?.Count ?? 0;
						failedOrPartialEntries += matchCollection2?.Count ?? 0;
						Logger.Log("Logic", "[PartyTransfer] ATP rejected: authorization snapshot missing.");
					}
					foreach (Match item in hasPrisonerSnapshot ? matchCollection2.Cast<Match>() : Enumerable.Empty<Match>())
					{
						if (item.Success && int.TryParse(item.Groups[1].Value, out var index) && int.TryParse(item.Groups[2].Value, out var amount))
						{
							applyPrisoner(FindDisplayIndexedPartyTransferEntry(list3, index), amount, "index=" + index);
						}
					}
				}
				string batchSummary = "部队与俘虏转移汇总：尝试项" + attemptedEntries + "，成功项" + successfulEntries + "，失败或不足项" + failedOrPartialEntries + "，实际转移" + actualUnits + "人，实际指导总值约" + actualValue + "第纳尔。";
				StringBuilder combinedFact = new StringBuilder(256);
				combinedFact.Append("[AFEF NPC行为补充] ").Append(text2).Append("已完成一次部队与俘虏转移。");
				if (transferredTroopFacts.Length > 0)
				{
					combinedFact.Append("转入玩家麾下：").Append(transferredTroopFacts).Append('。');
				}
				if (recruitedVolunteerFacts.Length > 0)
				{
					combinedFact.Append("允许玩家从原版待招募士兵中招募：").Append(recruitedVolunteerFacts).Append('。');
				}
				if (transferredPrisonerFacts.Length > 0)
				{
					combinedFact.Append("交给玩家的俘虏：").Append(transferredPrisonerFacts).Append('。');
				}
				combinedFact.Append(batchSummary);
				factResults.Add(combinedFact.ToString());
				notificationResults.Add(batchSummary);
				Logger.Log("Logic", "[PartyTransfer] batch_done troopAll=" + troopAll + " prisonerAll=" + prisonerAll + " attempted=" + attemptedEntries + " succeeded=" + successfulEntries + " failedOrPartial=" + failedOrPartialEntries + " actualUnits=" + actualUnits + " actualValue=" + actualValue);
			}
			text = StripPartyTransferTags(text);
			content = text;
			return flag;
		}
		catch
		{
			content = StripPartyTransferTags(content);
			return false;
		}
	}

	public static int TransferPlayerPartyEntryToCounterpartyForExternal(Hero targetHero, CharacterObject targetCharacter, int targetAgentIndex, PartyTransferPromptEntry entry, int amount)
	{
		if (!IsPartyTransferLordEligible(targetHero, targetCharacter))
		{
			return 0;
		}
		PartyBase partyBase = ResolvePartyTransferCounterpartyInternal(targetHero, targetCharacter, targetAgentIndex);
		if (entry == null || partyBase == null)
		{
			return 0;
		}
		if (entry.Section == PartyTransferEntrySection.PlayerTroops)
		{
			return TransferPartyMemberEntry(entry, amount, partyBase);
		}
		if (entry.Section == PartyTransferEntrySection.PlayerPrisoners)
		{
			return TransferPartyPrisonerEntry(entry, amount, partyBase, Clan.PlayerClan);
		}
		return 0;
	}

	private HeroShownRecord GetShownRecord(Hero hero)
	{
		return GetShownRecord(hero, null, createIfMissing: true);
	}

	private HeroShownRecord GetShownRecord(Hero hero, string targetKey, bool createIfMissing)
	{
		string text = ResolveShownRecordKey(hero, targetKey);
		if (string.IsNullOrWhiteSpace(text))
		{
			return null;
		}
		if (!_shownRecords.TryGetValue(text, out var value))
		{
			if (!createIfMissing)
			{
				return null;
			}
			value = new HeroShownRecord();
			_shownRecords[text] = value;
		}
		if (value.ShownItems == null)
		{
			value.ShownItems = new Dictionary<string, int>();
		}
		return value;
	}

	private void RecordShownResources(Hero hero, string targetKey, int shownGold, Dictionary<string, int> shownItems)
	{
		if (shownGold <= 0 && (shownItems == null || shownItems.Count == 0))
		{
			return;
		}
		HeroShownRecord shownRecord = GetShownRecord(hero, targetKey, createIfMissing: true);
		if (shownRecord == null)
		{
			return;
		}
		if (shownGold > 0)
		{
			shownRecord.ShownGold += shownGold;
		}
		if (shownItems == null)
		{
			return;
		}
		foreach (KeyValuePair<string, int> shownItem in shownItems)
		{
			string text = (shownItem.Key ?? "").Trim();
			if (string.IsNullOrWhiteSpace(text) || shownItem.Value <= 0)
			{
				continue;
			}
			if (!shownRecord.ShownItems.ContainsKey(text))
			{
				shownRecord.ShownItems[text] = 0;
			}
			shownRecord.ShownItems[text] += shownItem.Value;
		}
	}

	private int GetRemainingShowableGold(Hero hero, string targetKey, int currentGold)
	{
		HeroShownRecord shownRecord = GetShownRecord(hero, targetKey, createIfMissing: false);
		if (shownRecord == null)
		{
			return Math.Max(0, currentGold);
		}
		return Math.Max(0, currentGold - Math.Max(0, shownRecord.ShownGold));
	}

	private int GetRemainingShowableItemCount(Hero hero, string targetKey, string itemId, int currentAmount)
	{
		if (string.IsNullOrWhiteSpace(itemId))
		{
			return Math.Max(0, currentAmount);
		}
		HeroShownRecord shownRecord = GetShownRecord(hero, targetKey, createIfMissing: false);
		if (shownRecord == null || shownRecord.ShownItems == null || !shownRecord.ShownItems.TryGetValue(itemId, out var value))
		{
			return Math.Max(0, currentAmount);
		}
		return Math.Max(0, currentAmount - Math.Max(0, value));
	}

	private static string ResolveShownRecordKey(Hero hero, string targetKey)
	{
		string text = hero?.StringId;
		if (string.IsNullOrWhiteSpace(text))
		{
			text = targetKey;
		}
		return NormalizeShownRecordKey(text);
	}

