	private static string ResolveCurrentMemorySceneLabel()
	{
		try
		{
			string text = (ShoutUtils.GetCurrentSceneDescription() ?? "").Replace("\r", " ").Replace("\n", " ").Trim();
			if (!IsUnknownMemorySceneLabel(text))
			{
				return text;
			}
		}
		catch
		{
		}
		try
		{
			string text2 = (Settlement.CurrentSettlement?.Name?.ToString() ?? "").Trim();
			if (!string.IsNullOrWhiteSpace(text2))
			{
				return text2;
			}
		}
		catch
		{
		}
		try
		{
			string text3 = (MobileParty.MainParty?.CurrentSettlement?.Name?.ToString() ?? "").Trim();
			if (!string.IsNullOrWhiteSpace(text3))
			{
				return text3;
			}
		}
		catch
		{
		}
		try
		{
			string text4 = BuildCurrentWildernessMemorySceneLabel();
			if (!string.IsNullOrWhiteSpace(text4))
			{
				return text4;
			}
		}
		catch
		{
		}
		return "大地图或未知场景";
	}

	public static string ResolveCurrentMemorySceneLabelForExternal()
	{
		return ResolveCurrentMemorySceneLabel();
	}

	private static bool IsUnknownMemorySceneLabel(string scene)
	{
		string text = (scene ?? "").Replace("\r", " ").Replace("\n", " ").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return true;
		}
		return string.Equals(text, "未知场景", StringComparison.Ordinal)
			|| string.Equals(text, "大地图或未知场景", StringComparison.Ordinal)
			|| string.Equals(text, "某个地方", StringComparison.Ordinal);
	}

	private static string BuildCurrentWildernessMemorySceneLabel()
	{
		try
		{
			MobileParty party = MobileParty.MainParty;
			if (party == null)
			{
				return "";
			}
			Settlement settlement = Helpers.SettlementHelper.FindNearestSettlementToMobileParty(party, MobileParty.NavigationType.All, (Settlement x) => x != null && !x.IsHideout);
			string settlementName = (settlement?.Name?.ToString() ?? "").Trim();
			string terrainLabel = "";
			if (MapSeaContextGuard.IsMobilePartyAtSeaOrOnWater(party))
			{
				terrainLabel = "海上";
			}
			else
			{
				terrainLabel = MapSeaContextGuard.BuildMobilePartyLandTerrainPromptLabel(party);
				if (string.IsNullOrWhiteSpace(terrainLabel))
				{
					terrainLabel = "野外";
				}
			}
			if (string.IsNullOrWhiteSpace(settlementName))
			{
				return terrainLabel;
			}
			return settlementName + "附近的" + terrainLabel;
		}
		catch
		{
			return "";
		}
	}

	private void AppendDailyMemoryLine(Hero hero, string speaker, string text, bool isAfef, bool isLlmDialogue, int sceneSessionId = -1, int targetAgentIndex = -1, string targetName = null)
	{
		if (!IsHeroNpcEligibleForCompressedMemory(hero))
		{
			return;
		}
		string heroName = (hero.Name?.ToString() ?? "NPC").Trim();
		AppendDailyMemoryLineById(GetMemoryHeroId(hero), string.IsNullOrWhiteSpace(heroName) ? "NPC" : heroName, speaker, text, isAfef, isLlmDialogue, sceneSessionId, targetAgentIndex, targetName);
	}

	private void AppendDailyMemoryLineById(string memoryId, string memoryName, string speaker, string text, bool isAfef, bool isLlmDialogue, int sceneSessionId = -1, int targetAgentIndex = -1, string targetName = null)
	{
		string normalizedMemoryId = NormalizeMemoryHeroId(memoryId);
		if (!IsMemoryEntityEligibleForCompressedMemory(normalizedMemoryId))
		{
			return;
		}
		string text2 = (text ?? "").Trim();
		if (string.IsNullOrWhiteSpace(text2))
		{
			return;
		}
		int dayIndex = (int)CampaignTime.Now.ToDays;
		string gameDate = CampaignTime.Now.ToString();
		int hour = GetCurrentHourOfDaySafeForPrompt();
		string heroId = normalizedMemoryId;
		int dialogueSessionId = sceneSessionId >= 0 ? -1 : GetOrStartActiveNativeConversationMemorySessionId();
		List<DailyMemoryDraft> list = LoadDailyMemoryDraftsById(heroId);
		DailyMemoryDraft dailyMemoryDraft = list.FirstOrDefault((DailyMemoryDraft x) => x != null && x.GameDayIndex == dayIndex);
		if (dailyMemoryDraft == null)
		{
			dailyMemoryDraft = new DailyMemoryDraft
			{
				HeroId = heroId,
				HeroName = string.IsNullOrWhiteSpace(memoryName) ? "NPC" : memoryName.Trim(),
				GameDayIndex = dayIndex,
				GameDate = gameDate
			};
			list.Add(dailyMemoryDraft);
		}
		if (dailyMemoryDraft.Lines == null)
		{
			dailyMemoryDraft.Lines = new List<DailyMemoryLine>();
		}
		DailyMemoryLine dailyMemoryLine = new DailyMemoryLine
		{
			GameDayIndex = dayIndex,
			GameDate = gameDate,
			GameHour = hour,
			Scene = ResolveCurrentMemorySceneLabel(),
			Speaker = (speaker ?? "").Trim(),
			Text = text2,
			SceneSessionId = sceneSessionId,
			DialogueSessionId = dialogueSessionId,
			TargetAgentIndex = Math.Max(-1, targetAgentIndex),
			TargetName = (targetName ?? "").Trim(),
			MemorySessionKey = BuildCurrentMemorySessionKey(sceneSessionId, dialogueSessionId),
			IsAfef = isAfef,
			IsLlmDialogue = isLlmDialogue && !isAfef
		};
		dailyMemoryDraft.Lines.Add(dailyMemoryLine);
		if (dailyMemoryLine.IsLlmDialogue)
		{
			dailyMemoryDraft.HasLlmDialogue = true;
		}
		AttachPendingWeeklyMemoryMaterialTriggers(dailyMemoryDraft, dailyMemoryLine);
		SaveDailyMemoryDraftsById(heroId, list);
		if (dailyMemoryLine.IsLlmDialogue)
		{
			PlayerNotorietyBehavior.NoteConversationLineForExternal(heroId);
		}
		if (IsNonHeroMemoryId(heroId))
		{
			LogNonHeroMemoryTrace("stage=daily_append memoryId=" + heroId + " memoryName=" + (dailyMemoryDraft.HeroName ?? "") + " day=" + dayIndex + " drafts=" + list.Count + " lines=" + CountDailyMemoryDraftLines(list) + " speaker=" + (dailyMemoryLine.Speaker ?? "") + " isAfef=" + dailyMemoryLine.IsAfef + " isLlm=" + dailyMemoryLine.IsLlmDialogue + " sceneSession=" + sceneSessionId + " dialogueSession=" + dialogueSessionId);
		}
	}

	private List<DialogueDay> LoadDialogueHistory(Hero hero)
	{
		if (hero == null)
		{
			return new List<DialogueDay>();
		}
		return LoadDialogueHistoryById(hero.StringId);
	}

	private List<DialogueDay> LoadDialogueHistoryById(string memoryId)
	{
		if (_dialogueHistory == null)
		{
			_dialogueHistory = new Dictionary<string, List<DialogueDay>>();
		}
		string stringId = NormalizeMemoryHeroId(memoryId);
		if (string.IsNullOrEmpty(stringId))
		{
			return new List<DialogueDay>();
		}
		if (_dialogueHistory.TryGetValue(stringId, out var value) && value != null)
		{
			if (RemoveExpiredSingleUseNpcFactLines(value))
			{
				SaveDialogueHistoryById(stringId, value);
			}
			if (IsNonHeroMemoryId(stringId))
			{
				// Keep verbose-only diagnostics from adding a full history-line count to normal history opens.
				LogNonHeroMemoryTrace(() => "stage=load_dialogue_hit memoryId=" + stringId + " days=" + value.Count + " lines=" + CountDialogueHistoryLines(value));
			}
			return value;
		}
		if (IsNonHeroMemoryId(stringId))
		{
			LogNonHeroMemoryTrace("stage=load_dialogue_miss memoryId=" + stringId + " knownDialogueOwners=" + CountNonHeroDialogueHistoryOwners() + " knownDailyOwners=" + CountNonHeroDailyDraftOwners() + " sample=" + BuildNonHeroMemorySampleIds());
		}
		return new List<DialogueDay>();
	}

	private void TryEnsureFirstMeetingNpcFactForConversation(Hero hero)
	{
		GetFirstMeetingNpcFactTextForPromptIfNeededInternal(hero, persistToHistory: true);
	}

	public static string GetFirstMeetingNpcFactTextForPromptIfNeeded(Hero hero, bool persistToHistory = true)
	{
		try
		{
			return (Campaign.Current?.GetCampaignBehavior<MyBehavior>())?.GetFirstMeetingNpcFactTextForPromptIfNeededInternal(hero, persistToHistory) ?? "";
		}
		catch
		{
			return "";
		}
	}

	private string GetFirstMeetingNpcFactTextForPromptIfNeededInternal(Hero hero, bool persistToHistory)
	{
		if (hero == null || Hero.MainHero == null)
		{
			return "";
		}
		string text = BuildFirstMeetingNpcFactText(hero);
		if (string.IsNullOrWhiteSpace(text))
		{
			return "";
		}
		List<DialogueDay> list = LoadDialogueHistory(hero);
		if (HasDialogueHistoryLine(list, text) || HasMeaningfulDirectConversationHistory(list) || HasMeaningfulConversationHistoryIncludingActiveScene(list))
		{
			return "";
		}
		if (persistToHistory)
		{
			AppendDialogueHistory(hero, null, null, text);
		}
		return text;
	}

	private static string BuildFirstMeetingNpcFactText()
	{
		return BuildFirstMeetingNpcFactText(ResolveCurrentPlayerIdentityObserverForPrompt());
	}

	private static string BuildFirstMeetingNpcFactText(Hero observer)
	{
		TryBuildPlayerPublicDisplayNameForPrompt(observer, out var displayName, out var isCompleteIdentity);
		string text = (displayName ?? "").Trim();
		if (isCompleteIdentity && !string.Equals(text, "玩家", StringComparison.Ordinal))
		{
			return "[AFEF NPC行为补充] 你第一次与玩家（" + text + "）当面交谈；你已经知道他的公开身份和已公开履历，但此前没有直接见过他。";
		}
		if (!string.IsNullOrWhiteSpace(text) && !string.Equals(text, "玩家", StringComparison.Ordinal))
		{
			return "[AFEF NPC行为补充] 你第一次与面前这个" + text + "见面；你只知道他的可见外貌称呼，不知道他的真实姓名、背景和来历。";
		}
		return "[AFEF NPC行为补充] 你第一次与玩家见面；除可见外貌与装备外，你不了解他的姓名、背景和来历。";
	}

	private static bool HasDialogueHistoryLine(List<DialogueDay> records, string targetLine)
	{
		string text = (targetLine ?? "").Trim();
		if (string.IsNullOrWhiteSpace(text) || records == null || records.Count == 0)
		{
			return false;
		}
		bool isFirstMeetingFact = IsFirstMeetingNpcFactLine(text);
		foreach (DialogueDay record in records)
		{
			if (record?.Lines == null)
			{
				continue;
			}
			foreach (string line in record.Lines)
			{
				string text2 = (line ?? "").Trim();
				TryStripSceneSessionHistoryMarker(text2, out text2, out var _);
				if (string.Equals(text2, text, StringComparison.Ordinal))
				{
					return true;
				}
				if (isFirstMeetingFact && IsFirstMeetingNpcFactLine(text2))
				{
					return true;
				}
			}
		}
		return false;
	}

	private static bool HasMeaningfulDirectConversationHistory(List<DialogueDay> records)
	{
		if (records == null || records.Count == 0)
		{
			return false;
		}
		foreach (DialogueDay record in records)
		{
			if (record?.Lines == null)
			{
				continue;
			}
			foreach (string line in record.Lines)
			{
				string text = (line ?? "").Trim();
				if (!string.IsNullOrWhiteSpace(text) && !IsActiveSceneSessionHistoryLine(text) && !IsSystemFactLine(text) && !IsLoreInjectionHistoryLine(text))
				{
					return true;
				}
			}
		}
		return false;
	}

	private static bool HasMeaningfulConversationHistoryIncludingActiveScene(List<DialogueDay> records)
	{
		if (records == null || records.Count == 0)
		{
			return false;
		}
		foreach (DialogueDay record in records)
		{
			if (record?.Lines == null)
			{
				continue;
			}
			foreach (string line in record.Lines)
			{
				if (IsMeaningfulConversationLine(line, includeActiveScene: true))
				{
					return true;
				}
			}
		}
		return false;
	}

