	private void AppendDialogueHistory(Hero hero, string playerText, string aiText, string extraFact, int sceneSessionId = -1, int playerTargetAgentIndex = -1, string playerTargetName = null)
	{
		if (hero == null || (string.IsNullOrWhiteSpace(playerText) && string.IsNullOrWhiteSpace(aiText) && string.IsNullOrWhiteSpace(extraFact)))
		{
			return;
		}
		try
		{
			string npcNameForMemory = (hero.Name?.ToString() ?? "NPC").Trim();
			if (string.IsNullOrWhiteSpace(npcNameForMemory))
			{
				npcNameForMemory = "NPC";
			}
			AppendDialogueHistoryById(GetMemoryHeroId(hero), npcNameForMemory, playerText, aiText, extraFact, sceneSessionId, playerTargetAgentIndex, playerTargetName);
		}
		catch (Exception ex)
		{
			Logger.Log("DialogueHistory", "[错误] 追加失败: " + ex.Message);
		}
	}

	private void AppendDialogueHistoryById(string memoryId, string npcNameForMemory, string playerText, string aiText, string extraFact, int sceneSessionId = -1, int playerTargetAgentIndex = -1, string playerTargetName = null)
	{
		string normalizedMemoryId = NormalizeMemoryHeroId(memoryId);
		if (!IsMemoryEntityEligibleForCompressedMemory(normalizedMemoryId) || (string.IsNullOrWhiteSpace(playerText) && string.IsNullOrWhiteSpace(aiText) && string.IsNullOrWhiteSpace(extraFact)))
		{
			if (IsNonHeroMemoryId(normalizedMemoryId))
			{
				LogNonHeroMemoryTrace("stage=append_skip memoryId=" + normalizedMemoryId + " eligible=" + IsMemoryEntityEligibleForCompressedMemory(normalizedMemoryId) + " playerLen=" + ((playerText ?? "").Length) + " aiLen=" + ((aiText ?? "").Length) + " factLen=" + ((extraFact ?? "").Length));
			}
			return;
		}
		try
		{
			npcNameForMemory = (npcNameForMemory ?? "NPC").Trim();
			if (string.IsNullOrWhiteSpace(npcNameForMemory))
			{
				npcNameForMemory = "NPC";
			}
			if (!string.IsNullOrWhiteSpace(playerText))
			{
				Hero memoryHero = FindHeroById(normalizedMemoryId);
				AppendDailyMemoryLineById(normalizedMemoryId, npcNameForMemory, BuildPlayerPublicDisplayNameForPrompt(memoryHero), BuildPlayerAddressedInputForName(npcNameForMemory, playerText, memoryHero, playerTargetName), isAfef: false, isLlmDialogue: true, sceneSessionId: sceneSessionId, targetAgentIndex: playerTargetAgentIndex, targetName: playerTargetName);
			}
			if (!string.IsNullOrWhiteSpace(extraFact))
			{
				string memoryFact = extraFact.Trim();
				if (!memoryFact.StartsWith("[AFEF玩家行为补充]", StringComparison.Ordinal) && !memoryFact.StartsWith("[AFEF NPC行为补充]", StringComparison.Ordinal))
				{
					memoryFact = "[AFEF玩家行为补充] " + memoryFact;
				}
				AppendDailyMemoryLineById(normalizedMemoryId, npcNameForMemory, "AFEF", memoryFact, isAfef: true, isLlmDialogue: false, sceneSessionId: sceneSessionId);
			}
			if (!string.IsNullOrWhiteSpace(aiText))
			{
				string memoryAiText = aiText.Trim();
				if (!memoryAiText.StartsWith("[场景喊话]", StringComparison.Ordinal))
				{
					memoryAiText = npcNameForMemory + ": " + memoryAiText;
				}
				AppendDailyMemoryLineById(normalizedMemoryId, npcNameForMemory, npcNameForMemory, memoryAiText, isAfef: false, isLlmDialogue: true, sceneSessionId: sceneSessionId);
			}
			List<DialogueDay> list = LoadDialogueHistoryById(normalizedMemoryId);
			int beforeLines = CountDialogueHistoryLines(list);
			int dayIndex = (int)CampaignTime.Now.ToDays;
			string gameDate = CampaignTime.Now.ToString();
			string text = npcNameForMemory;
			DialogueDay dialogueDay = list.FirstOrDefault((DialogueDay d) => d.GameDayIndex == dayIndex);
			if (dialogueDay == null)
			{
				dialogueDay = new DialogueDay
				{
					GameDayIndex = dayIndex,
					GameDate = gameDate
				};
				list.Add(dialogueDay);
			}
			if (!string.IsNullOrWhiteSpace(playerText))
			{
				string text2 = BuildPlayerAddressedInputForName(npcNameForMemory, playerText, null, playerTargetName);
				dialogueDay.Lines.Add((sceneSessionId >= 0) ? TagSceneSessionHistoryLine(text2, sceneSessionId) : text2);
			}
			if (!string.IsNullOrWhiteSpace(extraFact))
			{
				string text3 = extraFact.Trim();
				if (text3.StartsWith("[AFEF玩家行为补充]", StringComparison.Ordinal) || text3.StartsWith("[AFEF NPC行为补充]", StringComparison.Ordinal))
				{
					dialogueDay.Lines.Add((sceneSessionId >= 0) ? TagSceneSessionHistoryLine(text3, sceneSessionId) : text3);
				}
				else
				{
					string text4 = "[AFEF玩家行为补充] " + text3;
					dialogueDay.Lines.Add((sceneSessionId >= 0) ? TagSceneSessionHistoryLine(text4, sceneSessionId) : text4);
				}
			}
			if (!string.IsNullOrWhiteSpace(aiText))
			{
				string text5 = aiText.Trim();
				if (text5.StartsWith("[场景喊话]", StringComparison.Ordinal))
				{
					dialogueDay.Lines.Add((sceneSessionId >= 0) ? TagSceneSessionHistoryLine(text5, sceneSessionId) : text5);
				}
				else
				{
					string text6 = text + ": " + text5;
					dialogueDay.Lines.Add((sceneSessionId >= 0) ? TagSceneSessionHistoryLine(text6, sceneSessionId) : text6);
				}
			}
			if (!string.IsNullOrWhiteSpace(aiText))
			{
				RemoveExpiredSingleUseNpcFactLines(list);
			}
			List<(int, string, string)> list2 = new List<(int, string, string)>();
			foreach (DialogueDay item in list)
			{
				if (item.Lines == null)
				{
					continue;
				}
				foreach (string line in item.Lines)
				{
					if (!string.IsNullOrWhiteSpace(line))
					{
						list2.Add((item.GameDayIndex, item.GameDate, line));
					}
				}
			}
			if (list2.Count > 260)
			{
				list2 = list2.Skip(list2.Count - 260).ToList();
			}
			List<DialogueDay> list3 = new List<DialogueDay>();
			foreach (var entry in list2)
			{
				DialogueDay dialogueDay2 = list3.FirstOrDefault((DialogueDay x) => x.GameDayIndex == entry.Item1);
				if (dialogueDay2 == null)
				{
					dialogueDay2 = new DialogueDay
					{
						GameDayIndex = entry.Item1,
						GameDate = entry.Item2
					};
					list3.Add(dialogueDay2);
				}
				dialogueDay2.Lines.Add(entry.Item3);
			}
			SaveDialogueHistoryById(normalizedMemoryId, list3);
			if (IsNonHeroMemoryId(normalizedMemoryId))
			{
				LogNonHeroMemoryTrace("stage=append_commit memoryId=" + normalizedMemoryId + " memoryName=" + npcNameForMemory + " beforeLines=" + beforeLines + " afterLines=" + CountDialogueHistoryLines(list3) + " days=" + list3.Count + " playerLen=" + ((playerText ?? "").Length) + " aiLen=" + ((aiText ?? "").Length) + " factLen=" + ((extraFact ?? "").Length) + " sceneSession=" + sceneSessionId);
			}
		}
		catch (Exception ex)
		{
			Logger.Log("DialogueHistory", "[错误] 追加失败: " + ex.Message);
		}
	}

	private string GetLatestNpcDialogueUtterance(Hero targetHero, CharacterObject targetCharacter = null, int targetAgentIndex = -1)
	{
		try
		{
			string sceneText = GetLatestSceneNpcDialogueUtteranceFallback(targetAgentIndex);
			if (!string.IsNullOrWhiteSpace(sceneText))
			{
				return sceneText;
			}
		}
		catch
		{
		}
		try
		{
			string nativeText = ShoutBehavior.GetLatestNativeConversationNpcUtteranceForExternal(targetHero, targetCharacter);
			if (!string.IsNullOrWhiteSpace(nativeText))
			{
				return nativeText;
			}
		}
		catch
		{
		}
		Hero hero = targetHero ?? targetCharacter?.HeroObject;
		if (hero == null)
		{
			return "";
		}
		try
		{
			List<DialogueDay> list = LoadDialogueHistory(hero);
			if (list == null || list.Count == 0)
			{
				return "";
			}
			for (int i = list.Count - 1; i >= 0; i--)
			{
				DialogueDay dialogueDay = list[i];
				if (dialogueDay?.Lines == null || dialogueDay.Lines.Count <= 0)
				{
					continue;
				}
				for (int num = dialogueDay.Lines.Count - 1; num >= 0; num--)
				{
					string text = (dialogueDay.Lines[num] ?? "").Trim();
					if (!string.IsNullOrWhiteSpace(text) && !IsActiveSceneSessionHistoryLine(text) && !IsSceneShoutObserverHistoryLine(text) && !IsLoreInjectionHistoryLine(text) && !IsSystemFactLine(text) && !IsPlayerTurnStartLine(text))
					{
						return StripSpeakerPrefixForRecall(text);
					}
				}
			}
		}
		catch
		{
		}
		return "";
	}

	private static bool IsSceneShoutObserverHistoryLine(string line)
	{
		string text = (line ?? "").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return false;
		}
		TryStripSceneSessionHistoryMarker(text, out text, out var _);
		return text.TrimStart().StartsWith("[场景喊话]", StringComparison.Ordinal);
	}

