	private static void AppendPlayerExtraFactLine(StringBuilder sb, string extraFact)
	{
		if (sb == null)
		{
			return;
		}
		string text = (extraFact ?? "").Replace("\r", " ").Replace("\n", " ").Trim();
		if (!string.IsNullOrWhiteSpace(text))
		{
			if (text.StartsWith("[AFEF玩家行为补充]", StringComparison.Ordinal) || text.StartsWith("[AFEF NPC行为补充]", StringComparison.Ordinal))
			{
				sb.AppendLine(text);
			}
			else
			{
				sb.AppendLine("[AFEF玩家行为补充] " + text);
			}
		}
	}

	private string BuildRecentNpcFactContext(Hero hero, int maxLines = 4)
	{
		if (hero == null)
		{
			return "";
		}
		try
		{
			List<DialogueDay> list = LoadDialogueHistory(hero);
			if (list == null || list.Count == 0)
			{
				return "";
			}
			List<string> list2 = new List<string>();
			foreach (DialogueDay item in list)
			{
				if (item?.Lines == null)
				{
					continue;
				}
				foreach (string line in item.Lines)
				{
					string text = (line ?? "").Trim();
					if (!string.IsNullOrWhiteSpace(text) && text.StartsWith("[AFEF NPC行为补充]", StringComparison.Ordinal))
					{
						list2.Add(text);
					}
				}
			}
			if (list2.Count <= 0)
			{
				return "";
			}
			int num = Math.Max(1, maxLines);
			if (list2.Count > num)
			{
				list2 = list2.Skip(list2.Count - num).ToList();
			}
			return string.Join("\n", list2);
		}
		catch
		{
			return "";
		}
	}

	private string BuildGuardrailSemanticContext(Hero hero, string extraFact)
	{
		try
		{
			List<string> list = new List<string>();
			if (hero != null)
			{
				List<DialogueDay> list2 = LoadDialogueHistory(hero);
				if (list2 != null && list2.Count > 0)
				{
					List<string> list3 = new List<string>();
					foreach (DialogueDay item in list2)
					{
						if (item == null || item.Lines == null)
						{
							continue;
						}
						for (int i = 0; i < item.Lines.Count; i++)
						{
							string text = (item.Lines[i] ?? "").Trim();
							if (ShouldIncludeGuardrailSemanticContextLine(text))
							{
								list3.Add(text);
							}
						}
					}
					int num = Math.Min(6, list3.Count);
					for (int j = list3.Count - num; j < list3.Count; j++)
					{
						if (j >= 0 && j < list3.Count)
						{
							string text2 = NormalizeGuardrailSemanticContextLine(list3[j]);
							list.Add(text2);
						}
					}
				}
			}
			string text3 = (extraFact ?? "").Trim();
			if (ShouldIncludeGuardrailSemanticContextLine(text3))
			{
				string text5 = NormalizeGuardrailSemanticContextLine(text3);
				if (text5.StartsWith("[AFEF玩家行为补充]", StringComparison.Ordinal) || text5.StartsWith("[AFEF NPC行为补充]", StringComparison.Ordinal))
				{
					list.Add(text5);
				}
				else
				{
					list.Add("[AFEF玩家行为补充] " + text5);
				}
			}
			string text6 = VanillaIssueOfferBridge.BuildRagSemanticStateForExternal(hero);
			if (!string.IsNullOrWhiteSpace(text6))
			{
				list.Add(text6);
			}
			if (list.Count <= 0)
			{
				return "";
			}
			return string.Join("\n", list);
		}
		catch
		{
			return "";
		}
	}

	private static string NormalizeGuardrailSemanticContextLine(string line)
	{
		string text = (line ?? "").Replace("\r\n", "\n").Replace('\r', '\n').Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return "";
		}
		string[] array = text.Split(new char[1] { '\n' }, StringSplitOptions.RemoveEmptyEntries);
		List<string> list = new List<string>();
		for (int i = 0; i < array.Length; i++)
		{
			string text2 = (array[i] ?? "").Trim();
			if (!string.IsNullOrWhiteSpace(text2))
			{
				list.Add(text2);
			}
		}
		return string.Join(" ", list).Trim();
	}

	private static bool ShouldIncludeGuardrailSemanticContextLine(string line)
	{
		string text = (line ?? "").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return false;
		}
		if (IsActiveSceneSessionHistoryLine(text) || IsLoreInjectionHistoryLine(text) || IsPlayerTurnStartLine(text))
		{
			return false;
		}
		if (text.IndexOf("参与互动让你的脑海里浮现了这些知识", StringComparison.Ordinal) >= 0)
		{
			return false;
		}
		if (text.IndexOf("【以下是关于（", StringComparison.Ordinal) >= 0)
		{
			return false;
		}
		if (text.IndexOf("【触发相关话题/背景】", StringComparison.Ordinal) >= 0)
		{
			return false;
		}
		return true;
	}

	private static string ResolveTargetKingdomIdForRules(Hero targetHero, CharacterObject targetCharacter, string kingdomIdOverride = null)
	{
		try
		{
			string text = (kingdomIdOverride ?? "").Trim();
			if (!string.IsNullOrWhiteSpace(text))
			{
				return text.ToLowerInvariant();
			}
			string text2 = (targetHero?.Clan?.Kingdom?.StringId ?? targetHero?.MapFaction?.StringId ?? "").Trim();
			if (!string.IsNullOrWhiteSpace(text2))
			{
				return text2.ToLowerInvariant();
			}
			Hero heroObject = targetCharacter?.HeroObject;
			string text3 = (heroObject?.Clan?.Kingdom?.StringId ?? heroObject?.MapFaction?.StringId ?? "").Trim();
			if (!string.IsNullOrWhiteSpace(text3))
			{
				return text3.ToLowerInvariant();
			}
			return "";
		}
		catch
		{
			return "";
		}
	}

	private static string ResolveRuleTargetKey(Hero targetHero, CharacterObject targetCharacter, int targetAgentIndex = -1)
	{
		try
		{
			string text = (targetHero?.StringId ?? targetCharacter?.HeroObject?.StringId ?? "").Trim();
			if (!string.IsNullOrWhiteSpace(text))
			{
				return "hero:" + text;
			}
			if (targetAgentIndex >= 0)
			{
				return "agent:" + targetAgentIndex;
			}
			string text2 = (targetCharacter?.StringId ?? "").Trim().ToLowerInvariant();
			if (!string.IsNullOrWhiteSpace(text2))
			{
				string text3 = (Settlement.CurrentSettlement?.StringId ?? "").Trim().ToLowerInvariant();
				return string.IsNullOrWhiteSpace(text3) ? ("troop:" + text2) : ("troop:" + text2 + "@" + text3);
			}
			return "";
		}
		catch
		{
			return "";
		}
	}

	public static string BuildRuleTargetKeyForExternal(Hero targetHero, CharacterObject targetCharacter, int targetAgentIndex = -1)
	{
		return ResolveRuleTargetKey(targetHero, targetCharacter, targetAgentIndex);
	}

	private static HashSet<string> BuildPromptRuleIdSet(IEnumerable<string> ruleIds)
	{
		HashSet<string> set = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		try
		{
			foreach (string ruleId in ruleIds ?? Enumerable.Empty<string>())
			{
				string text = (ruleId ?? "").Trim();
				if (!string.IsNullOrWhiteSpace(text))
				{
					set.Add(text);
				}
			}
		}
		catch
		{
		}
		return set;
	}

	private static bool IsPromptRuleExcluded(HashSet<string> excludedRuleIds, string ruleId)
	{
		return excludedRuleIds != null && !string.IsNullOrWhiteSpace(ruleId) && excludedRuleIds.Contains(ruleId.Trim());
	}

	private static void AddPlayerCompanionOrFamilyRuleExclusionsForTarget(HashSet<string> excludedRuleIds, Hero targetHero, CharacterObject targetCharacter = null)
	{
		if (excludedRuleIds == null)
		{
			return;
		}
		Hero hero = targetHero ?? targetCharacter?.HeroObject;
		if (AIConfigHandler.IsPlayerPartyTradeLimitedTarget(hero))
		{
			excludedRuleIds.Add("loan");
			excludedRuleIds.Add("kingdom_agenda");
			excludedRuleIds.Add("diplomacy");
			excludedRuleIds.Add("party_transfer");
			return;
		}
	}

	private static void AddWorldMapCommandRuleExclusionForTarget(HashSet<string> excludedRuleIds, Hero targetHero, CharacterObject targetCharacter = null, int targetAgentIndex = -1)
	{
		if (excludedRuleIds == null)
		{
			return;
		}
		if (ShouldExcludeWorldMapCommandRuleForTarget(targetHero, targetCharacter, targetAgentIndex))
		{
			excludedRuleIds.Add("worldmap_party_command");
		}
	}

	private static bool ShouldExcludeWorldMapCommandRuleForTarget(Hero targetHero, CharacterObject targetCharacter = null, int targetAgentIndex = -1)
	{
		try
		{
			Hero hero = targetHero ?? targetCharacter?.HeroObject;
			if (hero != null)
			{
				return hero.IsNotable
					|| hero.Occupation == Occupation.Headman
					|| hero.Occupation == Occupation.RuralNotable
					|| hero.Occupation == Occupation.GangLeader
					|| hero.Occupation == Occupation.Merchant
					|| hero.Occupation == Occupation.Artisan
					|| hero.Occupation == Occupation.Preacher;
			}
			if (targetCharacter != null && !targetCharacter.IsHero)
			{
				return !WorldMapPartyCommandBehavior.CanUseNonHeroPartyFallbackForExternal(targetCharacter, targetAgentIndex);
			}
			return false;
		}
		catch
		{
			return false;
		}
	}

	private static void AddSceneMoveRuleExclusionForCurrentMission(HashSet<string> excludedRuleIds)
	{
		if (excludedRuleIds != null && AIConfigHandler.ShouldExcludeSceneMoveRuleForCurrentMission())
		{
			excludedRuleIds.Add("scene_mechanism_actions");
		}
	}

	private static void AddPreprocessOnlyResidentRuleExclusions(HashSet<string> excludedRuleIds)
	{
		if (excludedRuleIds == null)
		{
			return;
		}
		excludedRuleIds.Add("noble_deference");
	}

	private static bool IsBuiltInPromptRuleIdForExtraInjection(string ruleId)
	{
		string id = (ruleId ?? "").Trim().ToLowerInvariant();
		return id == "duel" || id == "reward" || id == "loan" || id == "surroundings";
	}

	private static List<string> NormalizePreselectedPromptRuleIds(IEnumerable<string> ruleIds)
	{
		List<string> result = new List<string>();
		HashSet<string> seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		try
		{
			foreach (string ruleId in ruleIds ?? Enumerable.Empty<string>())
			{
				string id = (ruleId ?? "").Trim().ToLowerInvariant();
				if (!string.IsNullOrWhiteSpace(id) && seen.Add(id))
				{
					result.Add(id);
				}
			}
		}
		catch
		{
		}
		return result;
	}

	private static bool ShouldIncludeResidentKingdomEntities(bool kingdomServiceHit, IEnumerable<string> preselectedRuleIds)
	{
		if (kingdomServiceHit)
		{
			return true;
		}
		try
		{
			foreach (string ruleId in preselectedRuleIds ?? Enumerable.Empty<string>())
			{
				if (IsKingdomEntityPreprocessRuleId(ruleId))
				{
					return true;
				}
			}
		}
		catch
		{
		}
		return false;
	}

	private static bool IsKingdomEntityPreprocessRuleId(string ruleId)
	{
		string id = (ruleId ?? "").Trim();
		return string.Equals(id, "kingdom_service", StringComparison.OrdinalIgnoreCase)
			|| string.Equals(id, "kingdom_vassalage", StringComparison.OrdinalIgnoreCase);
	}

	private static bool IsRuntimeGatedPreprocessRuleId(string ruleId)
	{
		string id = (ruleId ?? "").Trim();
		return string.Equals(id, "kingdom_vassalage", StringComparison.OrdinalIgnoreCase)
			|| string.Equals(id, "diplomacy", StringComparison.OrdinalIgnoreCase)
			|| string.Equals(id, "world_diplomacy_discussion", StringComparison.OrdinalIgnoreCase)
			|| string.Equals(id, "kingdom_agenda", StringComparison.OrdinalIgnoreCase);
	}

	private string ResolvePreselectedRuleInstructionBody(string ruleId, string body, bool hasAnyHero, Hero targetHero, CharacterObject targetCharacter, int targetAgentIndex)
	{
		string id = (ruleId ?? "").Trim();
		if (string.IsNullOrWhiteSpace(id))
		{
			return "";
		}
		Hero hero = targetHero ?? targetCharacter?.HeroObject;
		string text = (body ?? "").Trim();
		if (string.Equals(id, "kingdom_service", StringComparison.OrdinalIgnoreCase))
		{
			string runtime = AIConfigHandler.BuildRuntimeKingdomServiceInstructionForExternal();
			string heroJoinRuntime = hasAnyHero ? AIConfigHandler.BuildRuntimeHeroJoinPartyInstructionForExternal(hero) : "";
			if (!string.IsNullOrWhiteSpace(runtime) || !string.IsNullOrWhiteSpace(heroJoinRuntime))
			{
				text = string.Join("\n", new string[3] { text, runtime, heroJoinRuntime }.Where((string x) => !string.IsNullOrWhiteSpace(x)).Distinct(StringComparer.OrdinalIgnoreCase)).Trim();
			}
		}
		if (hasAnyHero && string.Equals(id, "kingdom_vassalage", StringComparison.OrdinalIgnoreCase))
		{
			string runtime = VassalageBehavior.BuildRuntimeVassalageInstructionForExternal(hero, targetCharacter);
			if (!string.IsNullOrWhiteSpace(runtime))
			{
				text = runtime;
			}
		}
		if (hasAnyHero && string.Equals(id, "diplomacy", StringComparison.OrdinalIgnoreCase))
		{
			string runtime = KingdomAnnexationBehavior.BuildRuntimeAnnexationInstructionForExternal(hero, targetCharacter);
			if (!string.IsNullOrWhiteSpace(runtime))
			{
				text = string.Join("\n", new string[2] { text, runtime }.Where((string x) => !string.IsNullOrWhiteSpace(x))).Trim();
			}
		}
		if (hasAnyHero && string.Equals(id, "marriage", StringComparison.OrdinalIgnoreCase))
		{
			string runtime = RomanceSystemBehavior.Instance?.BuildMarriageRuntimeInstruction(hero) ?? "";
			if (!string.IsNullOrWhiteSpace(runtime))
			{
				text = runtime;
			}
		}
		if (hasAnyHero && string.Equals(id, "vanilla_issue", StringComparison.OrdinalIgnoreCase))
		{
			text = VanillaIssueOfferBridge.BuildRuntimePromptBlockForExternal(hero) ?? "";
		}
		if (string.Equals(id, "meeting_taunt", StringComparison.OrdinalIgnoreCase))
		{
			string runtime = SceneTauntBehavior.BuildUnifiedTauntRuntimeInstructionForExternal(hero, targetCharacter, targetAgentIndex);
			if (!string.IsNullOrWhiteSpace(runtime))
			{
				text = runtime;
			}
		}
		if (hasAnyHero && string.Equals(id, "npc_major_actions", StringComparison.OrdinalIgnoreCase))
		{
			string runtime = BuildNpcMajorActionsRuntimeInstruction(hero, targetCharacter, targetAgentIndex);
			if (!string.IsNullOrWhiteSpace(runtime))
			{
				text = runtime;
			}
		}
		if (string.Equals(id, "lords_hall_access", StringComparison.OrdinalIgnoreCase))
		{
			string runtime = AIConfigHandler.BuildRuntimeLordsHallAccessInstructionForExternal();
			if (!string.IsNullOrWhiteSpace(runtime))
			{
				text = runtime;
			}
		}
		return text;
	}

	private string BuildMatchedExtraRuleInstructionsFromPreselectedRules(IEnumerable<string> preselectedRuleIds, int maxRules, bool hasAnyHero, HashSet<string> excludedRuleIdSet, Hero targetHero, CharacterObject targetCharacter, int targetAgentIndex)
	{
		try
		{
			List<string> ruleIds = NormalizePreselectedPromptRuleIds(preselectedRuleIds);
			if (ruleIds.Count == 0)
			{
				return "";
			}
			int limit = Math.Max(1, maxRules <= 0 ? AIConfigHandler.GuardrailRuleReturnCap : maxRules);
			StringBuilder sb = new StringBuilder();
			int added = 0;
			foreach (string ruleId in ruleIds)
			{
				if (added >= limit)
				{
					break;
				}
				if (IsBuiltInPromptRuleIdForExtraInjection(ruleId) || IsPromptRuleExcluded(excludedRuleIdSet, ruleId))
				{
					continue;
				}
				if (IsRuntimeGatedPreprocessRuleId(ruleId)
					&& !AIConfigHandler.CanInjectRuleTopicIntoPreprocessForExternal(ruleId, hasAnyHero))
				{
					continue;
				}
				string body = hasAnyHero ? AIConfigHandler.GetGuardrailRuleInstruction(ruleId) : AIConfigHandler.GetGuardrailRuleNonHeroInstruction(ruleId);
				if (string.IsNullOrWhiteSpace(body))
				{
					body = AIConfigHandler.GetGuardrailRuleInstruction(ruleId);
				}
				body = ResolvePreselectedRuleInstructionBody(ruleId, body, hasAnyHero, targetHero, targetCharacter, targetAgentIndex);
				if (string.IsNullOrWhiteSpace(body))
				{
					continue;
				}
				AppendRuleBlock(sb, ruleId, body);
				added++;
			}
			return sb.ToString().Trim();
		}
		catch
		{
			return "";
		}
	}

	private string BuildExtraRuleInstructions(string input, string npcLastUtterance, Hero targetHero, bool hasAnyHero = true, CharacterObject targetCharacter = null, string kingdomIdOverride = null, int targetAgentIndex = -1, IEnumerable<string> excludedRuleIds = null, IEnumerable<string> preselectedRuleIds = null)
	{
		string text = "";
		string text2 = "";
		string encounterReleaseInstruction = "";
		string restrictedReferralHint = "";
		bool encounterReleaseRuleSelected = false;
		int num = AIConfigHandler.GuardrailRuleReturnCap;
		HashSet<string> excludedRuleIdSet = BuildPromptRuleIdSet(excludedRuleIds);
		AddPlayerCompanionOrFamilyRuleExclusionsForTarget(excludedRuleIdSet, targetHero, targetCharacter);
		AddWorldMapCommandRuleExclusionForTarget(excludedRuleIdSet, targetHero, targetCharacter, targetAgentIndex);
		AddSceneMoveRuleExclusionForCurrentMission(excludedRuleIdSet);
		string targetKingdomId = ResolveTargetKingdomIdForRules(targetHero, targetCharacter, kingdomIdOverride);
		AIConfigHandler.SetGuardrailRuntimeTargetKingdom(targetKingdomId);
		string text3 = targetHero?.StringId ?? targetCharacter?.HeroObject?.StringId ?? "";
		AIConfigHandler.SetGuardrailRuntimeTargetHero(text3);
		AIConfigHandler.SetGuardrailRuntimeTargetCharacter(targetCharacter?.StringId ?? "");
		AIConfigHandler.SetGuardrailRuntimeTargetTroop(targetCharacter?.StringId ?? "");
		AIConfigHandler.SetGuardrailRuntimeTargetUnnamedRank((targetHero == null && targetCharacter != null) ? (targetCharacter.IsSoldier ? "soldier" : "commoner") : "");
		AIConfigHandler.SetGuardrailRuntimeTargetAgentIndex(targetAgentIndex);
		try
		{
			text = preselectedRuleIds == null
				? AIConfigHandler.BuildMatchedExtraRuleInstructions(input, npcLastUtterance, AIConfigHandler.GuardrailRuleReturnCap, hasAnyHero, excludedRuleIdSet)
				: BuildMatchedExtraRuleInstructionsFromPreselectedRules(preselectedRuleIds, AIConfigHandler.GuardrailRuleReturnCap, hasAnyHero, excludedRuleIdSet, targetHero, targetCharacter, targetAgentIndex);
			encounterReleaseRuleSelected = !string.IsNullOrWhiteSpace(text) && text.IndexOf("【附加规则:encounter_release_player】", StringComparison.OrdinalIgnoreCase) >= 0;
			if (!string.IsNullOrWhiteSpace(text) && text.IndexOf("【附加规则:party_transfer】", StringComparison.OrdinalIgnoreCase) >= 0)
			{
				string partyTransferRuntimeInstructionForExternal = BuildPartyTransferRuntimeInstructionForExternal(targetHero, targetCharacter, targetAgentIndex);
				if (!string.IsNullOrWhiteSpace(partyTransferRuntimeInstructionForExternal))
				{
					text = ReplaceSingleRuleBlockBody(text, "party_transfer", partyTransferRuntimeInstructionForExternal);
				}
			}
			if (!string.IsNullOrWhiteSpace(text) && text.IndexOf("【附加规则:vanilla_issue】", StringComparison.OrdinalIgnoreCase) >= 0)
			{
				string vanillaIssueRuntimeInstruction = VanillaIssueOfferBridge.BuildRuntimePromptBlockForExternal(targetHero ?? targetCharacter?.HeroObject);
				if (!string.IsNullOrWhiteSpace(vanillaIssueRuntimeInstruction))
				{
					text = ReplaceSingleRuleBlockBody(text, "vanilla_issue", vanillaIssueRuntimeInstruction);
				}
			}
			if (!string.IsNullOrWhiteSpace(text) && text.IndexOf("【附加规则:npc_major_actions】", StringComparison.OrdinalIgnoreCase) >= 0)
			{
				string npcMajorActionsRuntimeInstruction = BuildNpcMajorActionsRuntimeInstruction(targetHero, targetCharacter, targetAgentIndex);
				if (!string.IsNullOrWhiteSpace(npcMajorActionsRuntimeInstruction))
				{
					text = ReplaceSingleRuleBlockBody(text, "npc_major_actions", npcMajorActionsRuntimeInstruction);
				}
			}
			if (!IsPromptRuleExcluded(excludedRuleIdSet, "lords_hall_access"))
			{
				// Always keep this rule present for the lords-hall gate guard, regardless of semantic hits.
				text2 = (AIConfigHandler.BuildRuntimeLordsHallAccessInstructionForExternal() ?? "").Trim();
			}
			if (!IsPromptRuleExcluded(excludedRuleIdSet, "encounter_release_player"))
			{
				encounterReleaseInstruction = (LordEncounterBehavior.BuildMeetingPlayerReleaseRuntimeInstructionForExternal(targetHero ?? targetCharacter?.HeroObject, encounterReleaseRuleSelected) ?? "").Trim();
			}
			restrictedReferralHint = BuildRestrictedRuleReferralHint(hasAnyHero, targetHero, targetCharacter, targetAgentIndex, excludedRuleIdSet);
		}
		finally
		{
			AIConfigHandler.SetGuardrailRuntimeTargetKingdom("");
			AIConfigHandler.SetGuardrailRuntimeTargetHero("");
			AIConfigHandler.SetGuardrailRuntimeTargetCharacter("");
			AIConfigHandler.SetGuardrailRuntimeTargetTroop("");
			AIConfigHandler.SetGuardrailRuntimeTargetUnnamedRank("");
			AIConfigHandler.SetGuardrailRuntimeTargetAgentIndex(-1);
		}
		if (!string.IsNullOrWhiteSpace(text2) && (string.IsNullOrWhiteSpace(text) || text.IndexOf("【附加规则:lords_hall_access】", StringComparison.OrdinalIgnoreCase) < 0) && CountInjectedRuleBlocks(text) < num)
		{
			string text4 = "【附加规则:lords_hall_access】" + Environment.NewLine + text2;
			text = string.IsNullOrWhiteSpace(text) ? text4 : (text.TrimEnd() + Environment.NewLine + text4);
		}
		bool hasEncounterReleaseRuleBlock = !string.IsNullOrWhiteSpace(text) && text.IndexOf("【附加规则:encounter_release_player】", StringComparison.OrdinalIgnoreCase) >= 0;
		if (hasEncounterReleaseRuleBlock)
		{
			if (!string.IsNullOrWhiteSpace(encounterReleaseInstruction))
			{
				text = ReplaceSingleRuleBlockBody(text, "encounter_release_player", encounterReleaseInstruction);
			}
			else
			{
				text = RemoveSingleRuleBlock(text, "encounter_release_player");
			}
		}
		else if (!string.IsNullOrWhiteSpace(encounterReleaseInstruction))
		{
			string text5 = "【附加规则:encounter_release_player】" + Environment.NewLine + encounterReleaseInstruction;
			text = string.IsNullOrWhiteSpace(text) ? text5 : (text.TrimEnd() + Environment.NewLine + text5);
		}
		string nobleDeferenceInstruction = BuildNobleDeferenceRuntimeInstruction(hasAnyHero);
		if (!string.IsNullOrWhiteSpace(nobleDeferenceInstruction) && (string.IsNullOrWhiteSpace(text) || text.IndexOf("【附加规则:noble_deference】", StringComparison.OrdinalIgnoreCase) < 0))
		{
			string text6 = "【附加规则:noble_deference】" + Environment.NewLine + nobleDeferenceInstruction;
			text = string.IsNullOrWhiteSpace(text) ? text6 : (text.TrimEnd() + Environment.NewLine + text6);
		}
		if (!string.IsNullOrWhiteSpace(restrictedReferralHint) && (string.IsNullOrWhiteSpace(text) || text.IndexOf("【转介】", StringComparison.OrdinalIgnoreCase) < 0))
		{
			text = string.IsNullOrWhiteSpace(text) ? restrictedReferralHint : (text.TrimEnd() + Environment.NewLine + restrictedReferralHint);
		}
		if (!IsPromptRuleExcluded(excludedRuleIdSet, "scene_mechanism_actions") && IsSceneFollowingAgentForRules(targetAgentIndex))
		{
			text = ReplaceSceneMechanismRuleForFollowing(text);
		}
		return PrependExtraRuleDisclaimer(text);
	}

	private static string BuildRestrictedRuleReferralHint(bool hasAnyHero, Hero targetHero, CharacterObject targetCharacter, int targetAgentIndex, HashSet<string> excludedRuleIdSet)
	{
		List<string> tips = new List<string>();
		if (AnyRestrictedReferralRuleBlocked(hasAnyHero, targetHero, targetCharacter, targetAgentIndex, excludedRuleIdSet, "diplomacy"))
		{
			AddReferralTip(tips, "外交找国王");
		}
		else if (AnyRestrictedReferralRuleBlocked(hasAnyHero, targetHero, targetCharacter, targetAgentIndex, excludedRuleIdSet, "kingdom_vassalage"))
		{
			AddReferralTip(tips, "臣属需双方国王");
		}
		if (AnyRestrictedReferralRuleBlocked(hasAnyHero, targetHero, targetCharacter, targetAgentIndex, excludedRuleIdSet, "kingdom_agenda"))
		{
			AddReferralTip(tips, "投票/提案找领主或国王");
		}
		if (AnyRestrictedReferralRuleBlocked(hasAnyHero, targetHero, targetCharacter, targetAgentIndex, excludedRuleIdSet, "worldmap_party_command"))
		{
			AddReferralTip(tips, "行军/攻击找带队英雄");
		}
		if (AnyRestrictedReferralRuleBlocked(hasAnyHero, targetHero, targetCharacter, targetAgentIndex, excludedRuleIdSet, "party_transfer"))
		{
			AddReferralTip(tips, "部队/俘虏找领主");
		}
		if (AnyRestrictedReferralRuleBlocked(hasAnyHero, targetHero, targetCharacter, targetAgentIndex, excludedRuleIdSet, "marriage"))
		{
			AddReferralTip(tips, "婚事找家主/当事人");
		}
		if (AnyRestrictedReferralRuleBlocked(hasAnyHero, targetHero, targetCharacter, targetAgentIndex, excludedRuleIdSet, "vanilla_issue"))
		{
			AddReferralTip(tips, "任务找委托人");
		}
		if (tips.Count == 0)
		{
			return "";
		}
		if (tips.Count > 4)
		{
			tips = tips.Take(4).ToList();
		}
		return "【转介】无权时简短引导：" + string.Join("；", tips) + "。";
	}

	private static bool AnyRestrictedReferralRuleBlocked(bool hasAnyHero, Hero targetHero, CharacterObject targetCharacter, int targetAgentIndex, HashSet<string> excludedRuleIdSet, params string[] ruleIds)
	{
		if (ruleIds == null)
		{
			return false;
		}
		for (int i = 0; i < ruleIds.Length; i++)
		{
			if (IsRestrictedReferralRuleBlocked(ruleIds[i], hasAnyHero, targetHero, targetCharacter, targetAgentIndex, excludedRuleIdSet))
			{
				return true;
			}
		}
		return false;
	}

	private static bool IsRestrictedReferralRuleBlocked(string ruleId, bool hasAnyHero, Hero targetHero, CharacterObject targetCharacter, int targetAgentIndex, HashSet<string> excludedRuleIdSet)
	{
		string id = (ruleId ?? "").Trim().ToLowerInvariant();
		if (string.IsNullOrWhiteSpace(id))
		{
			return false;
		}
		if (IsPromptRuleExcluded(excludedRuleIdSet, id))
		{
			return true;
		}
		Hero hero = targetHero ?? targetCharacter?.HeroObject;
		switch (id)
		{
		case "diplomacy":
		case "world_diplomacy_discussion":
		case "kingdom_vassalage":
		case "kingdom_agenda":
		case "marriage":
		case "vanilla_issue":
		case "lords_hall_access":
		case "siege_intervention_aftermath":
			return !AIConfigHandler.CanInjectRuleTopicIntoPreprocessForExternal(id, hasAnyHero);
		case "worldmap_party_command":
			return ShouldExcludeWorldMapCommandRuleForTarget(hero, targetCharacter, targetAgentIndex);
		case "party_transfer":
			return !IsPartyTransferRuleEligible(hero, targetCharacter, targetAgentIndex);
		default:
			return false;
		}
	}

	private static void AddReferralTip(List<string> tips, string tip)
	{
		string text = (tip ?? "").Trim();
		if (tips != null && !string.IsNullOrWhiteSpace(text) && !tips.Any((string x) => string.Equals((x ?? "").Trim(), text, StringComparison.OrdinalIgnoreCase)))
		{
			tips.Add(text);
		}
	}

