	public static ShoutPromptContext BuildShoutPromptContextForExternal(Hero targetHero, string input, string extraFact, string cultureIdOverride = null, bool hasAnyHero = true, CharacterObject targetCharacter = null, string kingdomIdOverride = null, int targetAgentIndex = -1, bool suppressDynamicRuleAndLore = false, bool usePrefetchedLoreContext = false, string prefetchedLoreContext = null, IEnumerable<string> excludedRuleIds = null, IEnumerable<string> preprocessExcludedRuleIds = null, IEnumerable<string> forcedPreprocessRuleIds = null, MentionedWorldEntities preprocessMentionedEntities = null, WeeklyPromptSnapshot weeklyPromptSnapshot = null)
	{
		try
		{
			MyBehavior myBehavior = (weeklyPromptSnapshot != null || !TWParallel.IsMainThread()) ? Instance : Campaign.Current?.GetCampaignBehavior<MyBehavior>();
			if (myBehavior == null)
			{
				return new ShoutPromptContext
				{
					Extras = "",
					PreprocessRuleIds = new List<string>(),
					PreprocessExcludedRuleIds = new List<string>(),
					PreprocessExcludedRuleBlock = "",
					UseDuelContext = false,
					UseRewardContext = false,
					IsLoanContext = false,
					IsQualified = true
				};
			}
			return myBehavior.BuildShoutPromptContextForExternalInternal(targetHero, input, extraFact, cultureIdOverride, hasAnyHero, targetCharacter, kingdomIdOverride, targetAgentIndex, suppressDynamicRuleAndLore, usePrefetchedLoreContext, prefetchedLoreContext, excludedRuleIds, preprocessExcludedRuleIds, forcedPreprocessRuleIds, preprocessMentionedEntities, weeklyPromptSnapshot);
		}
		catch (PreprocessFormatException)
		{
			throw;
		}
		catch
		{
			return new ShoutPromptContext
			{
				Extras = "",
				PreprocessRuleIds = new List<string>(),
				PreprocessExcludedRuleIds = new List<string>(),
				PreprocessExcludedRuleBlock = "",
				UseDuelContext = false,
				UseRewardContext = false,
				IsLoanContext = false,
				IsQualified = true
			};
		}
	}

	private static void LogShoutPromptContextStage(string stage, Stopwatch totalSw, Stopwatch stageSw, Hero targetHero, CharacterObject targetCharacter, int targetAgentIndex, string detail = null, bool immediate = true)
	{
		try
		{
			string safeStage = string.IsNullOrWhiteSpace(stage) ? "unknown" : stage.Trim();
			double stageMs = stageSw?.Elapsed.TotalMilliseconds ?? 0.0;
			double totalMs = totalSw?.Elapsed.TotalMilliseconds ?? 0.0;
			string target = targetHero?.StringId ?? targetCharacter?.StringId ?? targetCharacter?.HeroObject?.StringId ?? "unknown";
			string suffix = string.IsNullOrWhiteSpace(detail) ? "" : " " + detail.Trim();
			string message = "[NativePerf] prompt_context_stage stage=" + safeStage + " target=" + target + " agent=" + targetAgentIndex + " stageMs=" + Math.Round(stageMs, 2) + " totalMs=" + Math.Round(totalMs, 2) + suffix;
			Logger.Log("Logic", message);
			if (stageMs >= ShoutPromptContextSlowStageMs || totalMs >= ShoutPromptContextHardBudgetMs)
			{
				Logger.Log("Logic", "[NativePerf][WARN] prompt_context_slow_stage stage=" + safeStage + " target=" + target + " agent=" + targetAgentIndex + " stageMs=" + Math.Round(stageMs, 2) + " totalMs=" + Math.Round(totalMs, 2));
			}
			FreezeWatchdog.Mark("ShoutPromptContext." + safeStage, "target=" + target + " agent=" + targetAgentIndex + " stageMs=" + Math.Round(stageMs, 2) + " totalMs=" + Math.Round(totalMs, 2) + suffix, immediate: immediate);
			stageSw?.Restart();
		}
		catch
		{
		}
	}

	public static List<string> RunCourierRulePreprocessForExternal(Hero targetHero, string input, string extraFact, CharacterObject targetCharacter = null, string kingdomIdOverride = null, int targetAgentIndex = -1, IEnumerable<string> excludedRuleIds = null)
	{
		MentionedWorldEntities ignoredMentionedEntities;
		return RunCourierRulePreprocessForExternal(targetHero, input, extraFact, out ignoredMentionedEntities, targetCharacter, kingdomIdOverride, targetAgentIndex, excludedRuleIds);
	}

	public static List<string> RunCourierRulePreprocessForExternal(Hero targetHero, string input, string extraFact, out MentionedWorldEntities mentionedEntities, CharacterObject targetCharacter = null, string kingdomIdOverride = null, int targetAgentIndex = -1, IEnumerable<string> excludedRuleIds = null)
	{
		List<string> result = new List<string>();
		mentionedEntities = new MentionedWorldEntities();
		try
		{
			MyBehavior myBehavior = Campaign.Current?.GetCampaignBehavior<MyBehavior>();
			if (myBehavior == null || string.IsNullOrWhiteSpace(input))
			{
				return result;
			}
			return myBehavior.RunCourierRulePreprocessInternal(targetHero, input, extraFact, out mentionedEntities, targetCharacter, kingdomIdOverride, targetAgentIndex, excludedRuleIds);
		}
		catch (PreprocessFormatException)
		{
			throw;
		}
		catch (Exception ex)
		{
			try
			{
				Logger.Log("CourierDelivery", "[Preprocess] failed: " + ex.Message);
			}
			catch
			{
			}
			mentionedEntities = new MentionedWorldEntities();
			return result;
		}
	}

	private List<string> RunCourierRulePreprocessInternal(Hero targetHero, string input, string extraFact, out MentionedWorldEntities mentionedEntities, CharacterObject targetCharacter, string kingdomIdOverride, int targetAgentIndex, IEnumerable<string> excludedRuleIds)
	{
		List<string> result = new List<string>();
		mentionedEntities = new MentionedWorldEntities();
		HashSet<string> excludedRuleIdSet = BuildPromptRuleIdSet(excludedRuleIds);
		AddPlayerCompanionOrFamilyRuleExclusionsForTarget(excludedRuleIdSet, targetHero, targetCharacter);
		AddWorldMapCommandRuleExclusionForTarget(excludedRuleIdSet, targetHero, targetCharacter, targetAgentIndex);
		AfGcczShoutBridge.AddRuntimePreprocessRuleExclusions(excludedRuleIdSet, targetAgentIndex);
		AddPreprocessOnlyResidentRuleExclusions(excludedRuleIdSet);
		if (AfGcczShoutBridge.ShouldBypassPreprocessForActiveScene(targetAgentIndex))
		{
			Logger.Log("CourierDelivery", "[Preprocess] skipped: active GCCZ siege aftermath scene uses unconditional postprocess routing.");
			return result;
		}
		string targetKingdomId = ResolveTargetKingdomIdForRules(targetHero, targetCharacter, kingdomIdOverride);
		AIConfigHandler.SetGuardrailRuntimeTargetKingdom(targetKingdomId);
		AIConfigHandler.SetGuardrailRuntimeTargetHero(targetHero?.StringId ?? targetCharacter?.HeroObject?.StringId ?? "");
		AIConfigHandler.SetGuardrailRuntimeTargetCharacter(targetCharacter?.StringId ?? "");
		AIConfigHandler.SetGuardrailRuntimeTargetTroop(targetCharacter?.StringId ?? "");
		AIConfigHandler.SetGuardrailRuntimeTargetUnnamedRank((targetHero == null && targetCharacter != null) ? (targetCharacter.IsSoldier ? "soldier" : "commoner") : "");
		AIConfigHandler.SetGuardrailRuntimeTargetAgentIndex(targetAgentIndex);
		try
		{
			AIConfigHandler.SetGuardrailSemanticContext(BuildGuardrailSemanticContext(targetHero, extraFact));
			string npcLastUtterance = GetLatestNpcDialogueUtterance(targetHero, targetCharacter, targetAgentIndex);
			List<GuardrailRuleHit> hits = AIConfigHandler.GetGuardrailSemanticRuleHitsForPreprocess(input, npcLastUtterance, AIConfigHandler.GuardrailRuleReturnCap, includeBuiltInRules: true, excludedRuleIdSet, out mentionedEntities);
			result = (hits ?? new List<GuardrailRuleHit>())
				.Where(x => x != null && !string.IsNullOrWhiteSpace(x.RuleId))
				.OrderByDescending(x => x.Priority)
				.ThenByDescending(x => x.Score)
				.Select(x => x.RuleId.Trim().ToLowerInvariant())
				.Distinct(StringComparer.OrdinalIgnoreCase)
				.ToList();
			Logger.Log("CourierDelivery", "[Preprocess] targetHero=" + (targetHero?.StringId ?? "null") + " targetCharacter=" + (targetCharacter?.StringId ?? "null") + " npcRecall=" + (string.IsNullOrWhiteSpace(npcLastUtterance) ? "off" : "on") + " hits=" + (result.Count == 0 ? "(none)" : string.Join(",", result)));
			return result;
		}
		finally
		{
			AIConfigHandler.SetGuardrailRuntimeTargetKingdom("");
			AIConfigHandler.SetGuardrailRuntimeTargetHero("");
			AIConfigHandler.SetGuardrailRuntimeTargetCharacter("");
			AIConfigHandler.SetGuardrailRuntimeTargetTroop("");
			AIConfigHandler.SetGuardrailRuntimeTargetUnnamedRank("");
			AIConfigHandler.SetGuardrailRuntimeTargetAgentIndex(-1);
			AIConfigHandler.SetGuardrailSemanticContext("");
		}
	}

	public static string BuildHeroPrisonerStatusPromptLineForExternal(Hero hero)
	{
		try
		{
			if (hero == null || !hero.IsPrisoner)
			{
				return "";
			}
			PartyBase holder = null;
			try
			{
				holder = hero.PartyBelongedToAsPrisoner;
			}
			catch
			{
				holder = null;
			}
			string place = "";
			string captor = "";
			if (holder != null)
			{
				try
				{
					if (holder.IsSettlement && holder.Settlement != null)
					{
						Settlement settlement = holder.Settlement;
						string settlementName = (settlement.Name?.ToString() ?? settlement.StringId ?? "").Trim();
						string settlementType = settlement.IsCastle ? "城堡" : (settlement.IsTown ? "城镇" : (settlement.IsVillage ? "村庄" : "定居点"));
						if (!string.IsNullOrWhiteSpace(settlementName))
						{
							place = settlementName + "（" + settlementType + "）";
						}
						captor = (settlement.OwnerClan?.Leader?.Name?.ToString() ?? settlement.OwnerClan?.Name?.ToString() ?? settlement.MapFaction?.Name?.ToString() ?? "").Trim();
					}
					else if (holder.IsMobile && holder.MobileParty != null)
					{
						MobileParty party = holder.MobileParty;
						place = (party.Name?.ToString() ?? party.StringId ?? "一支队伍").Trim();
						captor = (party.LeaderHero?.Name?.ToString() ?? party.ActualClan?.Leader?.Name?.ToString() ?? party.ActualClan?.Name?.ToString() ?? party.MapFaction?.Name?.ToString() ?? "").Trim();
					}
				}
				catch
				{
				}
				if (string.IsNullOrWhiteSpace(captor))
				{
					try
					{
						captor = (holder.LeaderHero?.Name?.ToString() ?? holder.MapFaction?.Name?.ToString() ?? "").Trim();
					}
					catch
					{
						captor = "";
					}
				}
			}
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append("【俘虏处境】你现在是俘虏，");
			if (!string.IsNullOrWhiteSpace(place))
			{
				stringBuilder.Append("被关押在").Append(place);
			}
			else
			{
				stringBuilder.Append("正在被关押");
			}
			if (!string.IsNullOrWhiteSpace(captor))
			{
				stringBuilder.Append("，关押/控制你的人或势力是").Append(captor);
			}
			stringBuilder.Append("。这不是普通拜访、驻留或自由行军；你行动受限，不能随意离开，也不应声称自己仍能自由统领部队或处理外部事务。回应时必须承认自己被关押和被俘虏的事实。");
			return stringBuilder.ToString();
		}
		catch
		{
			return "";
		}
	}

