	public static void AppendExternalLoreHistory(Hero hero, string loreText)
	{
		try
		{
			(Campaign.Current?.GetCampaignBehavior<MyBehavior>())?.AppendLoreToHistory(hero, loreText);
		}
		catch
		{
		}
	}

	private void AppendLoreToHistory(Hero hero, string loreText)
	{
		if (hero == null)
		{
			return;
		}
		loreText = (loreText ?? "").Trim();
		if (string.IsNullOrEmpty(loreText))
		{
			return;
		}
		try
		{
			List<DialogueDay> list = LoadDialogueHistory(hero);
			int dayIndex = (int)CampaignTime.Now.ToDays;
			string gameDate = CampaignTime.Now.ToString();
			DialogueDay dialogueDay = list.FirstOrDefault((DialogueDay d) => d != null && d.GameDayIndex == dayIndex);
			if (dialogueDay == null)
			{
				dialogueDay = new DialogueDay
				{
					GameDayIndex = dayIndex,
					GameDate = gameDate
				};
				list.Add(dialogueDay);
			}
			if (dialogueDay.Lines == null)
			{
				dialogueDay.Lines = new List<string>();
			}
			string text = loreText.Replace("\r", "").Trim();
			if (string.IsNullOrEmpty(text))
			{
				return;
			}
			bool flag = text.IndexOf("【触发相关话题/背景】", StringComparison.OrdinalIgnoreCase) >= 0;
			bool flag2 = text.IndexOf("【玩家触发了（", StringComparison.OrdinalIgnoreCase) >= 0 || text.IndexOf("【以下是关于（", StringComparison.OrdinalIgnoreCase) >= 0;
			if (!flag && !flag2)
			{
				string text2 = "";
				try
				{
					text2 = (hero?.Name?.ToString() ?? "").Trim();
				}
				catch
				{
					text2 = "";
				}
				if (string.IsNullOrWhiteSpace(text2))
				{
					text2 = "该NPC";
				}
				string text4 = BuildPlayerPublicDisplayNameForPrompt(hero);
				if (string.IsNullOrWhiteSpace(text4))
				{
					text4 = "玩家";
				}
				text = "【以下是关于（相关）的背景知识，" + text2 + "可酌情参考，但不要假设" + text4 + "提起过此话题】\n" + text;
			}
			string text3 = text;
			if (dialogueDay.Lines.Count > 0)
			{
				string a = dialogueDay.Lines[dialogueDay.Lines.Count - 1] ?? "";
				if (string.Equals(a, text3, StringComparison.Ordinal))
				{
					return;
				}
			}
			dialogueDay.Lines.Add(text3);
			int num = 0;
			foreach (DialogueDay item in list)
			{
				num += (item?.Lines?.Count).GetValueOrDefault();
			}
			while (num > 260)
			{
				DialogueDay dialogueDay2 = list.FirstOrDefault((DialogueDay d) => d != null && d.Lines != null && d.Lines.Count > 0);
				if (dialogueDay2 == null)
				{
					break;
				}
				dialogueDay2.Lines.RemoveAt(0);
				num--;
				if (dialogueDay2.Lines.Count == 0 && dialogueDay2.GameDayIndex != dayIndex)
				{
					list.Remove(dialogueDay2);
				}
			}
			SaveDialogueHistory(hero, list);
		}
		catch
		{
		}
	}

	private static bool IsPlayerTurnStartLine(string line)
	{
		return TryStripPlayerSpeechPrefix(line, out var _);
	}

	private static bool IsSystemFactLine(string line)
	{
		string text = (line ?? "").TrimStart();
		TryStripSceneSessionHistoryMarker(text, out text, out var _);
		return text.StartsWith("[AFEF玩家行为补充]", StringComparison.Ordinal) || text.StartsWith("[AFEF NPC行为补充]", StringComparison.Ordinal);
	}

	private static bool IsSingleUseNpcFactLine(string line)
	{
		string text = (line ?? "").Trim();
		TryStripSceneSessionHistoryMarker(text, out text, out var _);
		if (!text.StartsWith("[AFEF NPC行为补充]", StringComparison.Ordinal))
		{
			return false;
		}
		string text2 = text.Substring("[AFEF NPC行为补充]".Length).Trim();
		if (string.IsNullOrWhiteSpace(text2))
		{
			return false;
		}
		if (IsFirstMeetingNpcFactBody(text2))
		{
			return true;
		}
		if (text2.StartsWith("今天稍早时候刚与", StringComparison.Ordinal) && text2.EndsWith("见过面。", StringComparison.Ordinal))
		{
			return true;
		}
		if (text2.StartsWith("距离你上次与", StringComparison.Ordinal) && text2.Contains("见面，已有") && text2.EndsWith("天了。", StringComparison.Ordinal))
		{
			return true;
		}
		return false;
	}

	private static bool IsFirstMeetingNpcFactLine(string line)
	{
		string text = (line ?? "").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return false;
		}
		TryStripSceneSessionHistoryMarker(text, out text, out var _);
		if (text.StartsWith("[AFEF NPC行为补充]", StringComparison.Ordinal))
		{
			text = text.Substring("[AFEF NPC行为补充]".Length).Trim();
		}
		return IsFirstMeetingNpcFactBody(text);
	}

	private static string NormalizeFirstMeetingNpcFactForPrompt(string line)
	{
		return IsFirstMeetingNpcFactLine(line) ? BuildFirstMeetingNpcFactText() : "";
	}

	private static bool IsFirstMeetingNpcFactBody(string text)
	{
		string value = (text ?? "").Trim();
		return value.StartsWith("你第一次见到", StringComparison.Ordinal)
			|| value.StartsWith("你第一次与玩家", StringComparison.Ordinal)
			|| value.StartsWith("你第一次与面前此人", StringComparison.Ordinal)
			|| value.StartsWith("你第一次与面前这个", StringComparison.Ordinal);
	}

	private static bool IsMeaningfulDirectConversationLine(string line)
	{
		return IsMeaningfulConversationLine(line, includeActiveScene: true);
	}

	private static bool IsMeaningfulConversationLine(string line, bool includeActiveScene)
	{
		string text = (line ?? "").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return false;
		}
		return (includeActiveScene || !IsActiveSceneSessionHistoryLine(text)) && !IsSystemFactLine(text) && !IsLoreInjectionHistoryLine(text);
	}

	private static bool RemoveExpiredSingleUseNpcFactLines(List<DialogueDay> records)
	{
		if (records == null || records.Count == 0)
		{
			return false;
		}
		List<(int Day, string Date, string Line)> list = new List<(int, string, string)>();
		foreach (DialogueDay record in records)
		{
			if (record?.Lines == null)
			{
				continue;
			}
			foreach (string line in record.Lines)
			{
				string text = (line ?? "").Trim();
				if (!string.IsNullOrWhiteSpace(text))
				{
					list.Add((record.GameDayIndex, record.GameDate, text));
				}
			}
		}
		if (list.Count == 0)
		{
			return false;
		}
		bool flag = false;
		bool flag2 = false;
		List<(int Day, string Date, string Line)> list2 = new List<(int, string, string)>(list.Count);
		for (int num = list.Count - 1; num >= 0; num--)
		{
			var item = list[num];
			if (flag2 && IsSingleUseNpcFactLine(item.Line))
			{
				flag = true;
				continue;
			}
			list2.Add(item);
			if (IsMeaningfulDirectConversationLine(item.Line))
			{
				flag2 = true;
			}
		}
		if (!flag)
		{
			return false;
		}
		list2.Reverse();
		records.Clear();
		foreach (var item2 in list2)
		{
			DialogueDay dialogueDay = records.FirstOrDefault((DialogueDay x) => x.GameDayIndex == item2.Day);
			if (dialogueDay == null)
			{
				dialogueDay = new DialogueDay
				{
					GameDayIndex = item2.Day,
					GameDate = item2.Date
				};
				records.Add(dialogueDay);
			}
			dialogueDay.Lines.Add(item2.Line);
		}
		return true;
	}

	private static bool IsLoreInjectionHistoryLine(string line)
	{
		string text = (line ?? "").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return false;
		}
		if (text.StartsWith("【玩家触发了（", StringComparison.Ordinal))
		{
			return true;
		}
		if (text.StartsWith("【以下是关于（", StringComparison.Ordinal))
		{
			return true;
		}
		if (text.StartsWith("【玩家外貌信息（常驻）】", StringComparison.Ordinal))
		{
			return true;
		}
		if (text.StartsWith("【触发相关话题/背景】", StringComparison.Ordinal))
		{
			return true;
		}
		if (text.IndexOf("参与互动让你的脑海里浮现了这些知识", StringComparison.Ordinal) >= 0)
		{
			return true;
		}
		if (text.IndexOf("应当知晓以下信息", StringComparison.OrdinalIgnoreCase) >= 0)
		{
			return true;
		}
		return false;
	}

	private static bool ContainsStructuredSignal(string line)
	{
		string text = (line ?? "").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return false;
		}
		string text2 = text.ToLowerInvariant();
		if (text2.Contains("债务id") || text2.Contains("欠款") || text2.Contains("还款") || text2.Contains("赊账") || text2.Contains("借款") || text2.Contains("第纳尔") || text2.Contains("价格") || text2.Contains("交易") || text2.Contains("决斗") || text2.Contains("赌注") || text2.Contains("[action:") || text2.Contains("guideprice=") || text2.Contains("|") || text2.Contains("id:"))
		{
			return true;
		}
		foreach (char c in text)
		{
			if (c >= '0' && c <= '9')
			{
				return true;
			}
		}
		return false;
	}

	private static bool IsRecallIntentQuery(string query)
	{
		string text = (query ?? "").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return false;
		}
		string text2 = text.ToLowerInvariant();
		return text2.Contains("以前") || text2.Contains("之前") || text2.Contains("上次") || text2.Contains("上回") || text2.Contains("那次") || text2.Contains("当时") || text2.Contains("还记得") || text2.Contains("你记得") || text2.Contains("你忘了") || text2.Contains("曾经") || text2.Contains("过去") || text2.Contains("前些天") || text2.Contains("前阵子") || text2.Contains("old") || text2.Contains("before") || text2.Contains("last time") || text2.Contains("remember");
	}

	private static bool ContainsLiteralKeywordHit(string input, List<string> keywords, out string matchedKeyword)
	{
		matchedKeyword = "";
		string text = (input ?? "").Trim().ToLowerInvariant();
		if (string.IsNullOrWhiteSpace(text) || keywords == null || keywords.Count <= 0)
		{
			return false;
		}
		for (int i = 0; i < keywords.Count; i++)
		{
			string text2 = (keywords[i] ?? "").Trim();
			if (!string.IsNullOrWhiteSpace(text2))
			{
				string value = text2.ToLowerInvariant();
				if (text.Contains(value))
				{
					matchedKeyword = text2;
					return true;
				}
			}
		}
		return false;
	}

	private static bool IsTermChar(char c)
	{
		return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || (c >= '\u4E00' && c <= '\u9FFF');
	}

	private static List<string> ExtractQueryTerms(string query)
	{
		List<string> terms = new List<string>();
		string text = (query ?? "").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return terms;
		}
		StringBuilder cur = new StringBuilder();
		Action action = delegate
		{
			if (cur.Length < 2)
			{
				cur.Clear();
			}
			else
			{
				string item = cur.ToString();
				if (!terms.Contains(item))
				{
					terms.Add(item);
				}
				cur.Clear();
			}
		};
		foreach (char c in text)
		{
			if (IsTermChar(c))
			{
				cur.Append(c);
			}
			else
			{
				action();
			}
		}
		action();
		if (terms.Count > 24)
		{
			terms = terms.Take(24).ToList();
		}
		return terms;
	}

	private static double ComputeLexicalOverlapScore(string text, List<string> terms)
	{
		if (string.IsNullOrWhiteSpace(text) || terms == null || terms.Count <= 0)
		{
			return 0.0;
		}
		int num = 0;
		for (int i = 0; i < terms.Count; i++)
		{
			string value = terms[i];
			if (!string.IsNullOrWhiteSpace(value) && text.IndexOf(value, StringComparison.OrdinalIgnoreCase) >= 0)
			{
				num++;
			}
		}
		if (num <= 0)
		{
			return 0.0;
		}
		double num2 = (double)num / (double)Math.Max(1, terms.Count);
		if (num2 < 0.0)
		{
			num2 = 0.0;
		}
		if (num2 > 1.0)
		{
			num2 = 1.0;
		}
		return num2;
	}

	private static string StripSpeakerPrefixForRecall(string line)
	{
		string text = (line ?? "").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return "";
		}
		TryStripSceneSessionHistoryMarker(text, out text, out var _);
		if (text.StartsWith("- ", StringComparison.Ordinal))
		{
			text = text.Substring(2).TrimStart();
		}
		if (text.StartsWith("—— ", StringComparison.Ordinal))
		{
			return "";
		}
		if (text.StartsWith("[AFEF玩家行为补充]", StringComparison.Ordinal))
		{
			return text.Substring("[AFEF玩家行为补充]".Length).Trim();
		}
		if (text.StartsWith("[AFEF NPC行为补充]", StringComparison.Ordinal))
		{
			return text.Substring("[AFEF NPC行为补充]".Length).Trim();
		}
		if (TryStripPlayerSpeechPrefix(text, out var stripped))
		{
			return stripped;
		}
		text = ShoutUtils.StripNamePrefixedLineSafely(text, 20);
		return text;
	}

	private static string NormalizeRecallLineWithSpeaker(string line)
	{
		string text = (line ?? "").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return "";
		}
		TryStripSceneSessionHistoryMarker(text, out text, out var _);
		if (text.StartsWith("- ", StringComparison.Ordinal))
		{
			text = text.Substring(2).TrimStart();
		}
		if (text.StartsWith("—— ", StringComparison.Ordinal))
		{
			return "";
		}
		if (text.StartsWith("[AFEF玩家行为补充]", StringComparison.Ordinal))
		{
			return "玩家行为记录: " + text.Substring("[AFEF玩家行为补充]".Length).Trim();
		}
		if (text.StartsWith("[AFEF NPC行为补充]", StringComparison.Ordinal))
		{
			return "NPC行为记录: " + text.Substring("[AFEF NPC行为补充]".Length).Trim();
		}
		if (TryStripPlayerSpeechPrefix(text, out var stripped))
		{
			string text2 = BuildPlayerPublicDisplayNameForPrompt();
			if (string.IsNullOrWhiteSpace(text2))
			{
				text2 = "玩家";
			}
			return text2 + "对你说: " + stripped;
		}
		if ((text.IndexOf("对", StringComparison.Ordinal) >= 0 && (text.IndexOf("说:", StringComparison.Ordinal) >= 0 || text.IndexOf("说：", StringComparison.Ordinal) >= 0)) || text.IndexOf("说:", StringComparison.Ordinal) >= 0 || text.IndexOf("说：", StringComparison.Ordinal) >= 0)
		{
			return text;
		}
		if (ShoutUtils.TrySplitNamePrefixedLineSafely(text, out var prefix, out var rest, 20))
		{
			return prefix + "说: " + rest;
		}
		return text;
	}

	private static string TrimRecallSnippet(string text, int maxChars = 80)
	{
		string text2 = (text ?? "").Replace("\r", " ").Replace("\n", " ").Trim();
		if (text2.Length <= maxChars)
		{
			return text2;
		}
		return text2.Substring(0, maxChars).TrimEnd('，', '。', '；', '、', ',', ';', '.') + "…";
	}

	private static List<string> BuildRecallToneLines(List<string> rawArchiveLines, int maxItems = 12)
	{
		List<string> list = new List<string>();
		if (rawArchiveLines == null || rawArchiveLines.Count == 0 || maxItems <= 0)
		{
			return list;
		}
		HashSet<string> hashSet = new HashSet<string>(StringComparer.Ordinal);
		string text = "";
		int num = 0;
		for (int i = 0; i < rawArchiveLines.Count; i++)
		{
			string text2 = (rawArchiveLines[i] ?? "").Trim();
			if (string.IsNullOrWhiteSpace(text2))
			{
				continue;
			}
			if (text2.StartsWith("—— ", StringComparison.Ordinal) && text2.EndsWith(" ——", StringComparison.Ordinal))
			{
				text = text2;
				continue;
			}
			if (num >= maxItems)
			{
				break;
			}
			string text3 = NormalizeRecallLineWithSpeaker(text2);
			text3 = TrimRecallSnippet(text3, 120);
			if (!string.IsNullOrWhiteSpace(text3) && hashSet.Add(text3))
			{
				string text4 = (IsSystemFactLine(text2) ? ("事实：" + text3) : ("对话：" + text3));
				string text5 = (string.IsNullOrWhiteSpace(text) ? "—— 日期未知 ——" : text);
				if (list.Count <= 0 || !string.Equals(list[list.Count - 1], text5, StringComparison.Ordinal))
				{
					list.Add(text5);
				}
				list.Add("- " + text4);
				num++;
			}
		}
		return list;
	}

	private static List<string> BuildRenderedHistoryLines(List<HistoryLineEntry> entries, string targetDisplayName = null, bool addressToYou = true)
	{
		List<string> list = new List<string>();
		if (entries == null || entries.Count == 0)
		{
			return list;
		}
		int num = -1;
		for (int i = 0; i < entries.Count; i++)
		{
			HistoryLineEntry historyLineEntry = entries[i];
			if (historyLineEntry != null && !string.IsNullOrWhiteSpace(historyLineEntry.Line))
			{
				if (historyLineEntry.Day != 0 && historyLineEntry.Day != num)
				{
					num = historyLineEntry.Day;
					string text = ((!string.IsNullOrWhiteSpace(historyLineEntry.Date)) ? historyLineEntry.Date : $"第 {historyLineEntry.Day} 日");
					list.Add("—— " + text + " ——");
				}
				list.Add(NormalizePlayerHistoryLineForPrompt(historyLineEntry.Line, targetDisplayName, addressToYou));
			}
		}
		return list;
	}

	private static List<string> TakeTailByCharBudget(List<string> lines, int budget)
	{
		List<string> list = new List<string>();
		if (lines == null || lines.Count == 0 || budget <= 0)
		{
			return list;
		}
		int num = 0;
		for (int num2 = lines.Count - 1; num2 >= 0; num2--)
		{
			string text = lines[num2] ?? "";
			if (text.Length > 0)
			{
				int num3 = text.Length + 1;
				if (num + num3 > budget && list.Count > 0)
				{
					break;
				}
				list.Add(text);
				num += num3;
			}
		}
		list.Reverse();
		return list;
	}

	private static string BuildHistoryQueryText(List<HistoryLineEntry> recent)
	{
		if (recent == null || recent.Count == 0)
		{
			return "";
		}
		int num = Math.Min(8, recent.Count);
		IEnumerable<string> values = from x in recent.Skip(recent.Count - num)
			select x?.Line ?? "" into x
			where !string.IsNullOrWhiteSpace(x)
			select x;
		return string.Join("\n", values);
	}

	private static List<string> SplitHistoryRecallIntents(string query, int maxParts = IntentQueryOptimizer.MaxCombinedIntentCount)
	{
		List<string> list = new List<string>();
		string text = (query ?? "").Replace("\r", " ").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return list;
		}
		list.Add(text);
		try
		{
			string[] array = Regex.Split(text, "[，。！？；：,.!?;:\\n]+");
			for (int i = 0; i < array.Length; i++)
			{
				string text2 = (array[i] ?? "").Trim();
				if (text2.Length >= 2 && !list.Contains(text2))
				{
					list.Add(text2);
				}
			}
		}
		catch
		{
		}
		list = IntentQueryOptimizer.OptimizeSplitIntents(list, Math.Max(1, maxParts));
		return list;
	}

	private static List<WeightedRecallQueryInput> BuildHistoryRecallQueryInputs(List<HistoryLineEntry> recent, string currentInput, string secondaryInput)
	{
		List<WeightedRecallQueryInput> list = new List<WeightedRecallQueryInput>();
		HashSet<string> hashSet = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		string text = (string.IsNullOrWhiteSpace(currentInput) ? BuildHistoryQueryText(recent) : currentInput.Trim());
		appendInputs(SplitHistoryRecallIntents(text, IntentQueryOptimizer.MaxIntentCountPerSpeaker), IntentQueryOptimizer.MaxIntentCountPerSpeaker);
		string text2 = (secondaryInput ?? "").Trim();
		if (!string.IsNullOrWhiteSpace(text2) && !string.Equals(text2, text, StringComparison.OrdinalIgnoreCase))
		{
			appendInputs(SplitHistoryRecallIntents(text2, IntentQueryOptimizer.MaxIntentCountPerSpeaker), IntentQueryOptimizer.MaxIntentCountPerSpeaker);
		}
		return list;

		void appendInputs(List<string> intents, int perSourceLimit)
		{
			if (intents == null || intents.Count <= 0 || perSourceLimit <= 0)
			{
				return;
			}
			int num = 0;
			for (int i = 0; i < intents.Count; i++)
			{
				string text3 = (intents[i] ?? "").Trim();
				if (!string.IsNullOrWhiteSpace(text3) && hashSet.Add(text3))
				{
					WeightedRecallQueryInput weightedRecallQueryInput = new WeightedRecallQueryInput
					{
						Text = text3,
						Weight = 1f
					};
					weightedRecallQueryInput.Terms = ExtractQueryTerms(text3);
					list.Add(weightedRecallQueryInput);
					num++;
					if (num >= perSourceLimit || list.Count >= IntentQueryOptimizer.MaxCombinedIntentCount)
					{
						break;
					}
				}
			}
		}
	}

	private static bool IsCurrentInputPlayerLine(string line, string currentInput)
	{
		if (string.IsNullOrWhiteSpace(line) || string.IsNullOrWhiteSpace(currentInput))
		{
			return false;
		}
		if (!TryStripPlayerSpeechPrefix(line, out var text))
		{
			return false;
		}
		string b = currentInput.Trim();
		return string.Equals(text, b, StringComparison.Ordinal);
	}

	private List<ArchiveHit> FindRelevantArchiveHits(List<HistoryLineEntry> older, List<WeightedRecallQueryInput> queryInputs, int returnCap, out bool onnxUsed, out string matchMode, out int rerankPerIntent, out int recallPerIntent)
	{
		onnxUsed = false;
		matchMode = "none";
		rerankPerIntent = 0;
		recallPerIntent = 0;
		List<ArchiveHit> list = new List<ArchiveHit>();
		try
		{
			List<WeightedRecallQueryInput> list2 = (queryInputs ?? new List<WeightedRecallQueryInput>()).Where((WeightedRecallQueryInput x) => x != null && !string.IsNullOrWhiteSpace(x.Text) && x.Weight > 0f).ToList();
			if (older == null || older.Count == 0 || returnCap <= 0 || list2.Count == 0)
			{
				return list;
			}
			List<HistoryLineEntry> list3 = older.Where((HistoryLineEntry x) => x != null && !string.IsNullOrWhiteSpace(x.Line)).ToList();
			if (list3.Count <= 0)
			{
				return list;
			}
			int num = ClampHistoryReturnCap(returnCap);
			int num2 = Math.Max(1, list2.Count);
			int historyRerankBudget = GetHistoryRerankBudget(num);
			rerankPerIntent = GetHistoryPerIntentRerank(historyRerankBudget, num2);
			recallPerIntent = GetHistoryPerIntentRecall(rerankPerIntent);
			bool flag = false;
			try
			{
				flag = OnnxCrossEncoderReranker.Instance.IsAvailable;
			}
			catch
			{
				flag = false;
			}
			matchMode = (flag ? ((num2 > 1) ? "rerank_multi" : "rerank") : ((num2 > 1) ? "semantic_multi" : "semantic"));
			Dictionary<int, HistoryRecallAggregate> dictionary = new Dictionary<int, HistoryRecallAggregate>();
			for (int i = 0; i < list2.Count; i++)
			{
				WeightedRecallQueryInput weightedRecallQueryInput = list2[i];
				List<RecallLineScore> list4 = FindHistoryCandidateScores(list3, weightedRecallQueryInput, recallPerIntent, out var onnxUsed2);
				if (onnxUsed2)
				{
					onnxUsed = true;
				}
				if (list4 == null || list4.Count <= 0)
				{
					continue;
				}
				List<RecallLineScore> list5 = RerankHistoryCandidateScores(weightedRecallQueryInput.Text, list4, rerankPerIntent, out var _, weightedRecallQueryInput.Weight);
				if (list5 == null || list5.Count <= 0)
				{
					continue;
				}
				for (int j = 0; j < list5.Count; j++)
				{
					RecallLineScore recallLineScore = list5[j];
					int num3 = recallLineScore?.Entry?.Index ?? int.MinValue;
					if (num3 == int.MinValue)
					{
						continue;
					}
					double num4 = recallLineScore.RerankScore;
					if (!dictionary.TryGetValue(num3, out var value))
					{
						value = new HistoryRecallAggregate
						{
							Hit = new ArchiveHit
							{
								Entry = recallLineScore.Entry,
								Score = num4,
								BaseScore = recallLineScore.BaseScore,
								RerankScore = recallLineScore.RerankScore
							},
							ScoreSum = num4,
							HitCount = 1,
							BestRank = j + 1,
							BestScore = recallLineScore.RerankScore
						};
						dictionary[num3] = value;
						continue;
					}
					value.ScoreSum += num4;
					value.HitCount++;
					if (j + 1 < value.BestRank)
					{
						value.BestRank = j + 1;
					}
					if (recallLineScore.RerankScore >= value.BestScore)
					{
						value.BestScore = recallLineScore.RerankScore;
						value.Hit.Entry = recallLineScore.Entry;
						value.Hit.BaseScore = recallLineScore.BaseScore;
						value.Hit.RerankScore = recallLineScore.RerankScore;
					}
					dictionary[num3] = value;
				}
			}
			if (dictionary.Count <= 0)
			{
				return list;
			}
			List<ArchiveHit> list6 = (from x in dictionary.Values
				let finalScore = Math.Min(1.0, x.ScoreSum / (double)Math.Max(1, x.HitCount) + (double)(x.HitCount - 1) * 0.08)
				orderby finalScore descending, x.BestRank, (x.Hit?.Entry != null) ? x.Hit.Entry.Index : (-1) descending
				select new ArchiveHit
				{
					Entry = x.Hit.Entry,
					Score = finalScore,
					BaseScore = x.Hit.BaseScore,
					RerankScore = x.Hit.RerankScore
				}).ToList();
			HashSet<int> hashSet = new HashSet<int>();
			for (int k = 0; k < list6.Count; k++)
			{
				ArchiveHit archiveHit = list6[k];
				int num5 = archiveHit?.Entry?.Index ?? int.MinValue;
				if (num5 != int.MinValue && !hashSet.Contains(num5))
				{
					list.Add(archiveHit);
					hashSet.Add(num5 - 1);
					hashSet.Add(num5);
					hashSet.Add(num5 + 1);
					if (list.Count >= num)
					{
						break;
					}
				}
			}
			try
			{
				Logger.Log("DialogueHistory", $"candidate_pool mode={matchMode} returnCap={num} rerankBudget={historyRerankBudget} rerankPerIntent={rerankPerIntent} recallPerIntent={recallPerIntent} intents={num2} got={list.Count}");
			}
			catch
			{
			}
		}
		catch
		{
		}
		return list;
	}

	private static string StripMemoryTitleDateTime(string title)
	{
		string text = (title ?? "").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return "";
		}
		text = Regex.Replace(text, "^\\s*[\\[【(（]?[\\d\\-/:：年月日\\s时点春夏秋冬第]+[\\]】)）]?\\s*", "", RegexOptions.CultureInvariant).Trim();
		text = Regex.Replace(text, "\\s+", " ").Trim();
		if (text.Length > 36)
		{
			text = text.Substring(0, 36).Trim();
		}
		return text;
	}

	private static string StripJsonCodeFence(string content)
	{
		string text = StripJsonResponseEnvelope(content);
		string jsonPayload = ExtractFirstJsonPayload(text);
		return string.IsNullOrWhiteSpace(jsonPayload) ? text : jsonPayload;
	}

	private static string StripJsonResponseEnvelope(string content)
	{
		string text = (content ?? "").Trim('\uFEFF', '\u200B', '\u200C', '\u200D', ' ', '\t', '\r', '\n');
		if (text.StartsWith("```", StringComparison.Ordinal))
		{
			int firstLineEnd = text.IndexOf('\n');
			if (firstLineEnd >= 0)
			{
				text = text.Substring(firstLineEnd + 1).Trim();
			}
			int lastFence = text.LastIndexOf("```", StringComparison.Ordinal);
			if (lastFence >= 0)
			{
				text = text.Substring(0, lastFence).Trim();
			}
		}
		text = Regex.Replace(text, "^(?:json)\\s*(?=[\\r\\n{\\[])", "", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant).Trim();
		return text;
	}

	private static string ExtractFirstJsonPayload(string text)
	{
		List<string> payloads = ExtractJsonObjectPayloads(text);
		if (payloads.Count > 0)
		{
			return payloads[0];
		}
		text = (text ?? "").Trim();
		if (text.StartsWith("[", StringComparison.Ordinal))
		{
			return ExtractBalancedJsonPayload(text, 0, '[', ']');
		}
		return "";
	}

	private static List<string> ExtractJsonObjectPayloads(string text)
	{
		List<string> list = new List<string>();
		text = (text ?? "").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return list;
		}
		bool inString = false;
		bool escaped = false;
		int depth = 0;
		int start = -1;
		for (int i = 0; i < text.Length; i++)
		{
			char ch = text[i];
			if (depth == 0)
			{
				if (ch == '{')
				{
					start = i;
					depth = 1;
					inString = false;
					escaped = false;
				}
				continue;
			}
			if (inString)
			{
				if (escaped)
				{
					escaped = false;
				}
				else if (ch == '\\')
				{
					escaped = true;
				}
				else if (ch == '"')
				{
					inString = false;
				}
				continue;
			}
			if (ch == '"')
			{
				inString = true;
				continue;
			}
			if (ch == '{')
			{
				depth++;
				continue;
			}
			if (ch == '}')
			{
				depth--;
				if (depth == 0)
				{
					if (start >= 0)
					{
						list.Add(text.Substring(start, i - start + 1).Trim());
					}
					start = -1;
				}
				if (depth < 0)
				{
					depth = 0;
					start = -1;
				}
			}
		}
		return list;
	}

	private static string ExtractBalancedJsonPayload(string text, int start, char open, char close)
	{
		text = text ?? "";
		if (start < 0 || start >= text.Length || text[start] != open)
		{
			return "";
		}
		bool inString = false;
		bool escaped = false;
		int depth = 0;
		for (int i = start; i < text.Length; i++)
		{
			char ch = text[i];
			if (inString)
			{
				if (escaped)
				{
					escaped = false;
				}
				else if (ch == '\\')
				{
					escaped = true;
				}
				else if (ch == '"')
				{
					inString = false;
				}
				continue;
			}
			if (ch == '"')
			{
				inString = true;
				continue;
			}
			if (ch == open)
			{
				depth++;
				continue;
			}
			if (ch == close)
			{
				depth--;
				if (depth == 0)
				{
					return text.Substring(start, i - start + 1).Trim();
				}
				if (depth < 0)
				{
					return "";
				}
			}
		}
		return "";
	}

	private static bool TryParseBestSummaryJsonObject(string content, string[] requiredPrimaryKeys, string[] requiredSecondaryKeys, out JObject obj, out string error)
	{
		obj = null;
		error = "";
		string text = StripJsonResponseEnvelope(content);
		if (TryParseTaggedSummaryObject(text, requiredPrimaryKeys, requiredSecondaryKeys, out obj))
		{
			return true;
		}
		List<string> candidates = ExtractJsonObjectPayloads(text);
		if (candidates.Count == 0 && !string.IsNullOrWhiteSpace(text))
		{
			candidates.Add(text);
		}
		Exception lastParseException = null;
		int parseFailureCount = 0;
		int validObjectCount = 0;
		foreach (string candidate in candidates)
		{
			if (string.IsNullOrWhiteSpace(candidate))
			{
				continue;
			}
			try
			{
				JObject parsed = JObject.Parse(candidate);
				validObjectCount++;
				if (HasAnyNonWhiteSpaceJsonProperty(parsed, requiredPrimaryKeys) && HasAnyNonWhiteSpaceJsonProperty(parsed, requiredSecondaryKeys))
				{
					obj = parsed;
					return true;
				}
			}
			catch (Exception ex)
			{
				lastParseException = ex;
				parseFailureCount++;
			}
		}
		if (parseFailureCount > 0 && TryParseLooseSummaryJsonObject(text, requiredPrimaryKeys, requiredSecondaryKeys, out obj))
		{
			return true;
		}
		if (validObjectCount > 0)
		{
			error = "未找到包含必需字段的 JSON 对象：" + BuildRequiredJsonFieldDescription(requiredPrimaryKeys, requiredSecondaryKeys) + "。";
			return false;
		}
		if (parseFailureCount > 0)
		{
			error = lastParseException?.Message ?? "JSON 解析失败。";
			return false;
		}
		error = "找不到 JSON 对象。";
		return false;
	}

	private static bool TryParseTaggedSummaryObject(string content, string[] requiredPrimaryKeys, string[] requiredSecondaryKeys, out JObject obj)
	{
		obj = null;
		string text = StripJsonResponseEnvelope(content);
		if (string.IsNullOrWhiteSpace(text))
		{
			return false;
		}
		JObject tagged = new JObject();
		AddTaggedSummaryProperty(text, tagged, "rich_title", new string[2] { "TITLE", "RICH_TITLE" });
		AddTaggedSummaryProperty(text, tagged, "summary_content", new string[3] { "SUMMARY", "SUMMARY_CONTENT", "CONTENT" });
		AddTaggedSummaryProperty(text, tagged, "player_publicity", new string[2] { "PUBLICITY", "PLAYER_PUBLICITY" });
		AddTaggedSummaryProperty(text, tagged, "player_history_material", new string[2] { "PLAYER_HISTORY", "PLAYER_HISTORY_MATERIAL" });
		AddTaggedSummaryProperty(text, tagged, "publicity_reason", new string[2] { "REASON", "PUBLICITY_REASON" });
		if (!HasAnyNonWhiteSpaceJsonProperty(tagged, requiredPrimaryKeys) || !HasAnyNonWhiteSpaceJsonProperty(tagged, requiredSecondaryKeys))
		{
			return false;
		}
		obj = tagged;
		return true;
	}

	private static void AddTaggedSummaryProperty(string text, JObject obj, string propertyName, string[] tagNames)
	{
		if (obj == null || string.IsNullOrWhiteSpace(propertyName) || tagNames == null)
		{
			return;
		}
		if (obj.Properties().Any((JProperty x) => string.Equals(x.Name, propertyName, StringComparison.OrdinalIgnoreCase)))
		{
			return;
		}
		foreach (string tagName in tagNames)
		{
			if (TryExtractTaggedBlock(text, tagName, out var value))
			{
				obj[propertyName] = value.Trim();
				return;
			}
		}
	}

	private static bool TryExtractTaggedBlock(string text, string tagName, out string value)
	{
		value = "";
		if (string.IsNullOrWhiteSpace(text) || string.IsNullOrWhiteSpace(tagName))
		{
			return false;
		}
		string escaped = Regex.Escape(tagName.Trim());
		RegexOptions options = RegexOptions.IgnoreCase | RegexOptions.Singleline | RegexOptions.CultureInvariant;
		Match complete = Regex.Match(text, "\\[" + escaped + "\\]\\s*(?<value>.*?)\\s*\\[/" + escaped + "\\]", options);
		if (complete.Success)
		{
			value = (complete.Groups["value"]?.Value ?? "").Trim();
			return !string.IsNullOrWhiteSpace(value);
		}
		Match open = Regex.Match(text, "\\[" + escaped + "\\]\\s*", options);
		if (!open.Success)
		{
			return false;
		}
		int start = open.Index + open.Length;
		Match next = Regex.Match(text.Substring(start), "\\r?\\n\\s*\\[[A-Z_]+\\]\\s*", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
		int end = next.Success ? start + next.Index : text.Length;
		value = text.Substring(start, Math.Max(0, end - start)).Trim();
		return !string.IsNullOrWhiteSpace(value);
	}

	private static bool TryParseLooseSummaryJsonObject(string content, string[] requiredPrimaryKeys, string[] requiredSecondaryKeys, out JObject obj)
	{
		obj = null;
		string text = StripJsonResponseEnvelope(content);
		if (string.IsNullOrWhiteSpace(text))
		{
			return false;
		}
		JObject loose = new JObject();
		AddLooseJsonStringProperties(text, loose, requiredPrimaryKeys);
		AddLooseJsonStringProperties(text, loose, requiredSecondaryKeys);
		AddLooseJsonStringProperties(text, loose, new string[9] { "player_publicity", "playerPublicity", "publicity", "player_history_material", "playerHistoryMaterial", "history_material", "historyMaterial", "publicity_reason", "publicityReason" });
		if (!HasAnyNonWhiteSpaceJsonProperty(loose, requiredPrimaryKeys) || !HasAnyNonWhiteSpaceJsonProperty(loose, requiredSecondaryKeys))
		{
			return false;
		}
		obj = loose;
		return true;
	}

	private static void AddLooseJsonStringProperties(string text, JObject obj, string[] names)
	{
		if (obj == null || names == null)
		{
			return;
		}
		foreach (string name in names)
		{
			if (string.IsNullOrWhiteSpace(name) || obj.Properties().Any((JProperty x) => string.Equals(x.Name, name, StringComparison.OrdinalIgnoreCase)))
			{
				continue;
			}
			if (TryExtractLooseJsonStringProperty(text, name.Trim(), out var value) && !string.IsNullOrWhiteSpace(value))
			{
				obj[name.Trim()] = value.Trim();
			}
		}
	}

	private static bool TryExtractLooseJsonStringProperty(string text, string propertyName, out string value)
	{
		value = "";
		if (string.IsNullOrWhiteSpace(text) || string.IsNullOrWhiteSpace(propertyName))
		{
			return false;
		}
		string key = "\"" + propertyName + "\"";
		int searchIndex = 0;
		while (searchIndex < text.Length)
		{
			int keyIndex = text.IndexOf(key, searchIndex, StringComparison.OrdinalIgnoreCase);
			if (keyIndex < 0)
			{
				return false;
			}
			int colonIndex = SkipJsonWhitespace(text, keyIndex + key.Length);
			if (colonIndex >= text.Length || text[colonIndex] != ':')
			{
				searchIndex = keyIndex + key.Length;
				continue;
			}
			int valueStart = SkipJsonWhitespace(text, colonIndex + 1);
			if (valueStart >= text.Length || text[valueStart] != '"')
			{
				searchIndex = keyIndex + key.Length;
				continue;
			}
			if (TryReadLooseJsonStringValue(text, valueStart, out value))
			{
				return true;
			}
			searchIndex = keyIndex + key.Length;
		}
		return false;
	}

	private static int SkipJsonWhitespace(string text, int index)
	{
		while (index < (text?.Length ?? 0) && char.IsWhiteSpace(text[index]))
		{
			index++;
		}
		return index;
	}

	private static bool TryReadLooseJsonStringValue(string text, int quoteIndex, out string value)
	{
		value = "";
		if (string.IsNullOrEmpty(text) || quoteIndex < 0 || quoteIndex >= text.Length || text[quoteIndex] != '"')
		{
			return false;
		}
		StringBuilder stringBuilder = new StringBuilder();
		bool escaped = false;
		for (int i = quoteIndex + 1; i < text.Length; i++)
		{
			char ch = text[i];
			if (escaped)
			{
				switch (ch)
				{
				case '"':
				case '\\':
				case '/':
					stringBuilder.Append(ch);
					break;
				case 'b':
					stringBuilder.Append('\b');
					break;
				case 'f':
					stringBuilder.Append('\f');
					break;
				case 'n':
					stringBuilder.Append('\n');
					break;
				case 'r':
					stringBuilder.Append('\r');
					break;
				case 't':
					stringBuilder.Append('\t');
					break;
				case 'u':
					if (i + 4 < text.Length && int.TryParse(text.Substring(i + 1, 4), System.Globalization.NumberStyles.HexNumber, System.Globalization.CultureInfo.InvariantCulture, out var codePoint))
					{
						stringBuilder.Append((char)codePoint);
						i += 4;
					}
					else
					{
						stringBuilder.Append(ch);
					}
					break;
				default:
					stringBuilder.Append(ch);
					break;
				}
				escaped = false;
				continue;
			}
			if (ch == '\\')
			{
				escaped = true;
				continue;
			}
			if (ch == '"')
			{
				int next = SkipJsonWhitespace(text, i + 1);
				if (next >= text.Length || text[next] == ',' || text[next] == '}' || text[next] == ']')
				{
					value = stringBuilder.ToString();
					return !string.IsNullOrWhiteSpace(value);
				}
			}
			if (ch == '\r' || ch == '\n')
			{
				stringBuilder.Append(' ');
			}
			else
			{
				stringBuilder.Append(ch);
			}
		}
		value = stringBuilder.ToString();
		return !string.IsNullOrWhiteSpace(value);
	}

	private static string BuildRequiredJsonFieldDescription(string[] primaryKeys, string[] secondaryKeys)
	{
		string text = BuildRequiredJsonFieldGroupDescription(primaryKeys);
		string text2 = BuildRequiredJsonFieldGroupDescription(secondaryKeys);
		if (string.IsNullOrWhiteSpace(text2))
		{
			return text;
		}
		return text + " + " + text2;
	}

	private static string BuildRequiredJsonFieldGroupDescription(string[] keys)
	{
		List<string> list = (keys ?? new string[0]).Where((string x) => !string.IsNullOrWhiteSpace(x)).Select((string x) => x.Trim()).Distinct(StringComparer.OrdinalIgnoreCase).ToList();
		return list.Count == 0 ? "（无）" : string.Join("/", list);
	}

	private static bool HasAnyNonWhiteSpaceJsonProperty(JObject obj, string[] names)
	{
		if (names == null || names.Length == 0)
		{
			return true;
		}
		return !string.IsNullOrWhiteSpace(GetJsonStringIgnoreCase(obj, names));
	}

	private static bool IsEmptySummaryMarker(string text)
	{
		string value = (text ?? "").Trim();
		return string.IsNullOrWhiteSpace(value) || string.Equals(value, "无", StringComparison.OrdinalIgnoreCase) || string.Equals(value, "none", StringComparison.OrdinalIgnoreCase) || string.Equals(value, "null", StringComparison.OrdinalIgnoreCase) || string.Equals(value, "n/a", StringComparison.OrdinalIgnoreCase);
	}

	private static string GetJsonStringIgnoreCase(JObject obj, params string[] names)
	{
		JToken token = GetJsonPropertyIgnoreCase(obj, names);
		return token?.ToString() ?? "";
	}

	private static JToken GetJsonPropertyIgnoreCase(JObject obj, params string[] names)
	{
		if (obj == null || names == null)
		{
			return null;
		}
		foreach (string name in names)
		{
			if (string.IsNullOrWhiteSpace(name))
			{
				continue;
			}
			JProperty prop = obj.Properties().FirstOrDefault((JProperty x) => string.Equals(x.Name, name, StringComparison.OrdinalIgnoreCase));
			if (prop != null)
			{
				return prop.Value;
			}
		}
		return null;
	}

	private static string BuildSummaryJsonParseFailureMessage(string prefix, string parseError, string content)
	{
		string detail = (parseError ?? "").Trim();
		if (string.IsNullOrWhiteSpace(detail))
		{
			detail = "未知解析错误。";
		}
		return LlmRetryPrompt.BuildFailureDetail(prefix + "：" + detail, content);
	}

	private static string FormatMemoryHourRange(int startHour, int endHour)
	{
		startHour = MBMath.ClampInt(startHour, 0, 23);
		endHour = MBMath.ClampInt(endHour, 0, 23);
		if (startHour == endHour)
		{
			return startHour + "时";
		}
		return startHour + "-" + endHour + "时";
	}

	private static string FormatCompressedMemoryAgeSuffix(CompressedMemoryBlock block)
	{
		if (block == null)
		{
			return "";
		}
		int currentDay = GetCurrentGameDayIndexSafe();
		int daysAgo = currentDay - block.GameDayIndex;
		if (daysAgo <= 0)
		{
			return "（今天）";
		}
		return "（" + daysAgo + "天前）";
	}

	private static string BuildDailyMemoryLineForPrompt(DailyMemoryLine line)
	{
		if (line == null || string.IsNullOrWhiteSpace(line.Text))
		{
			return "";
		}
		string text = (string.IsNullOrWhiteSpace(line.GameDate) ? ("第" + line.GameDayIndex + "日") : line.GameDate.Trim());
		string text2 = ResolveMemoryLineSceneForPrompt(line);
		string text3 = string.IsNullOrWhiteSpace(line.Speaker) ? (line.IsAfef ? "AFEF" : "对话") : line.Speaker.Trim();
		return "[" + text + " " + MBMath.ClampInt(line.GameHour, 0, 23) + "时｜" + text2 + "｜" + text3 + "] " + line.Text.Trim();
	}

	private static string ResolveMemoryLineSceneForPrompt(DailyMemoryLine line)
	{
		string scene = (line?.Scene ?? "").Trim();
		if (!IsUnknownMemorySceneLabel(scene))
		{
			return scene;
		}
		try
		{
			if (line != null && line.GameDayIndex == GetCurrentGameDayIndexSafe())
			{
				string fallback = ResolveCurrentMemorySceneLabel();
				if (!IsUnknownMemorySceneLabel(fallback))
				{
					return fallback.Trim();
				}
			}
		}
		catch
		{
		}
		return "未知场景";
	}

	private static int CountDailyMemorySummarySourceChars(DailyMemoryDraft draft)
	{
		if (draft?.Lines == null)
		{
			return 0;
		}
		return draft.Lines.Where((DailyMemoryLine x) => x != null && !x.IsAfef && !string.IsNullOrWhiteSpace(x.Text)).Sum((DailyMemoryLine x) => x.Text.Trim().Length);
	}

	private static bool HasDailyMemoryDraftAfefLines(DailyMemoryDraft draft)
	{
		return draft?.Lines != null && draft.Lines.Any((DailyMemoryLine x) => x != null && x.IsAfef && !string.IsNullOrWhiteSpace(x.Text));
	}

	private static string BuildMemoryRecallQueryText(Hero hero, string currentInput, string secondaryInput, IEnumerable<DailyMemoryDraft> drafts)
	{
		StringBuilder stringBuilder = new StringBuilder();
		string text = (currentInput ?? "").Trim();
		if (!string.IsNullOrWhiteSpace(text))
		{
			stringBuilder.AppendLine(text);
		}
		string text2 = (secondaryInput ?? "").Trim();
		if (!string.IsNullOrWhiteSpace(text2))
		{
			stringBuilder.AppendLine(text2);
		}
		string text3 = ResolveCurrentMemorySceneLabel();
		if (!string.IsNullOrWhiteSpace(text3))
		{
			stringBuilder.AppendLine(text3);
		}
		try
		{
			DailyMemoryDraft dailyMemoryDraft = (drafts ?? Enumerable.Empty<DailyMemoryDraft>()).OrderByDescending((DailyMemoryDraft x) => x.GameDayIndex).FirstOrDefault((DailyMemoryDraft x) => x?.Lines != null && x.Lines.Count > 0);
			if (dailyMemoryDraft?.Lines != null)
			{
				foreach (DailyMemoryLine item in dailyMemoryDraft.Lines.Where((DailyMemoryLine x) => x != null && !x.IsAfef && !string.IsNullOrWhiteSpace(x.Text)).Reverse().Take(6).Reverse())
				{
					stringBuilder.AppendLine(item.Text);
				}
			}
		}
		catch
		{
		}
		string text4 = stringBuilder.ToString().Trim();
		if (text4.Length > 1200)
		{
			text4 = text4.Substring(text4.Length - 1200);
		}
		return text4;
	}

	private bool TryBuildMemoryRecallCandidates(Hero hero, List<CompressedMemoryBlock> blocks, string currentInput, string secondaryInput, List<DailyMemoryDraft> drafts, int candidateLimit, out List<MemoryRecallCandidate> candidates, out string error)
	{
		Stopwatch sw = Stopwatch.StartNew();
		candidates = new List<MemoryRecallCandidate>();
		error = "";
		List<CompressedMemoryBlock> list = (blocks ?? new List<CompressedMemoryBlock>()).Where((CompressedMemoryBlock x) => x != null && (!string.IsNullOrWhiteSpace(x.RichTitle) || !string.IsNullOrWhiteSpace(x.Summary))).ToList();
		string debugHeroId = NormalizeMemoryHeroId(hero?.StringId ?? list.Select((CompressedMemoryBlock x) => x?.HeroId).FirstOrDefault((string x) => !string.IsNullOrWhiteSpace(x)));
		Logger.Log("Logic", "[MemoryPerf] recall_candidates_start hero=" + (debugHeroId ?? "") + " blocks=" + ((blocks ?? new List<CompressedMemoryBlock>()).Count) + " eligible=" + list.Count + " candidateLimit=" + candidateLimit + " currentLen=" + ((currentInput ?? "").Length) + " secondaryLen=" + ((secondaryInput ?? "").Length) + " drafts=" + ((drafts ?? new List<DailyMemoryDraft>()).Count));
		if (list.Count <= 0 || candidateLimit <= 0)
		{
			sw.Stop();
			Logger.Log("Logic", "[MemoryPerf] recall_candidates_done hero=" + (debugHeroId ?? "") + " mode=empty selected=0 ms=" + Math.Round(sw.Elapsed.TotalMilliseconds, 2));
			return true;
		}
		if (list.Count <= candidateLimit)
		{
			candidates = list.Select((CompressedMemoryBlock x) => new MemoryRecallCandidate
			{
				Block = x,
				Score = 1.0
			}).OrderBy((MemoryRecallCandidate x) => x.Block.GameDayIndex).ThenBy((MemoryRecallCandidate x) => x.Block.StartHour).ToList();
			AssignMemoryCandidateDisplayIds(candidates);
			sw.Stop();
			Logger.Log("Logic", "[MemoryPerf] recall_candidates_done hero=" + (debugHeroId ?? "") + " mode=direct selected=" + candidates.Count + " ms=" + Math.Round(sw.Elapsed.TotalMilliseconds, 2));
			return true;
		}
		try
		{
			OnnxEmbeddingEngine instance = OnnxEmbeddingEngine.Instance;
			string text = BuildMemoryRecallQueryText(hero, currentInput, secondaryInput, drafts);
			Stopwatch querySw = Stopwatch.StartNew();
			if (instance == null || !instance.IsAvailable || string.IsNullOrWhiteSpace(text) || !instance.TryGetEmbedding(text, out var vector) || vector == null || vector.Length == 0)
			{
				querySw.Stop();
				error = "本地 ONNX embedding 不可用，无法对超过候选上限的压缩记忆执行富标题 RAG。";
				sw.Stop();
				Logger.Log("Logic", "[MemoryPerf] recall_candidates_failed hero=" + (debugHeroId ?? "") + " reason=query_embedding_unavailable queryLen=" + ((text ?? "").Length) + " queryMs=" + Math.Round(querySw.Elapsed.TotalMilliseconds, 2) + " totalMs=" + Math.Round(sw.Elapsed.TotalMilliseconds, 2));
				ShowCompressedMemoryBlockingPopup("压缩记忆召回被阻塞", error + "\n\n请修复 embedding 模型或降低记忆块数量后重试。系统不会静默改用日期或全文兜底。");
				return false;
			}
			querySw.Stop();
			List<MemoryRecallCandidate> list2 = new List<MemoryRecallCandidate>();
			Stopwatch titleSw = Stopwatch.StartNew();
			int scanned = 0;
			int titleEmbeddingFailed = 0;
			foreach (CompressedMemoryBlock block in list)
			{
				scanned++;
				string text2 = (block.RichTitle ?? "").Trim();
				if (string.IsNullOrWhiteSpace(text2))
				{
					titleEmbeddingFailed++;
					continue;
				}
				if (!instance.TryGetEmbedding(text2, out var vector2) || vector2 == null || vector2.Length == 0)
				{
					titleEmbeddingFailed++;
					continue;
				}
				int num = Math.Min(vector.Length, vector2.Length);
				double num2 = 0.0;
				for (int i = 0; i < num; i++)
				{
					num2 += (double)vector[i] * (double)vector2[i];
				}
				list2.Add(new MemoryRecallCandidate
				{
					Block = block,
					Score = num2
				});
			}
			titleSw.Stop();
			if (list2.Count <= 0)
			{
				error = "压缩记忆富标题 embedding 全部失败。";
				sw.Stop();
				Logger.Log("Logic", "[MemoryPerf] recall_candidates_failed hero=" + (debugHeroId ?? "") + " reason=title_embedding_empty scanned=" + scanned + " failed=" + titleEmbeddingFailed + " queryMs=" + Math.Round(querySw.Elapsed.TotalMilliseconds, 2) + " titleMs=" + Math.Round(titleSw.Elapsed.TotalMilliseconds, 2) + " totalMs=" + Math.Round(sw.Elapsed.TotalMilliseconds, 2));
				ShowCompressedMemoryBlockingPopup("压缩记忆召回被阻塞", error + "\n\n请修复 embedding 模型后重试。");
				return false;
			}
			candidates = list2.OrderByDescending((MemoryRecallCandidate x) => x.Score).ThenByDescending((MemoryRecallCandidate x) => x.Block.GameDayIndex).Take(candidateLimit).OrderBy((MemoryRecallCandidate x) => x.Block.GameDayIndex).ThenBy((MemoryRecallCandidate x) => x.Block.StartHour).ToList();
			AssignMemoryCandidateDisplayIds(candidates);
			sw.Stop();
			Logger.Log("Logic", "[MemoryPerf] recall_candidates_done hero=" + (debugHeroId ?? "") + " mode=onnx eligible=" + list.Count + " scanned=" + scanned + " titleOk=" + list2.Count + " titleFail=" + titleEmbeddingFailed + " selected=" + candidates.Count + " queryMs=" + Math.Round(querySw.Elapsed.TotalMilliseconds, 2) + " titleMs=" + Math.Round(titleSw.Elapsed.TotalMilliseconds, 2) + " totalMs=" + Math.Round(sw.Elapsed.TotalMilliseconds, 2));
			return true;
		}
		catch (Exception ex)
		{
			error = ex.Message;
			sw.Stop();
			Logger.Log("Logic", "[MemoryPerf] recall_candidates_failed hero=" + (debugHeroId ?? "") + " reason=exception type=" + ex.GetType().Name + " totalMs=" + Math.Round(sw.Elapsed.TotalMilliseconds, 2) + " msg=" + ex.Message);
			ShowCompressedMemoryBlockingPopup("压缩记忆召回异常", error);
			return false;
		}
	}

	private static void AssignMemoryCandidateDisplayIds(List<MemoryRecallCandidate> candidates)
	{
		if (candidates == null)
		{
			return;
		}
		for (int i = 0; i < candidates.Count; i++)
		{
			if (candidates[i] != null)
			{
				candidates[i].DisplayId = i + 1;
			}
		}
	}

	private bool TrySelectMemoryIdsWithPreprocess(List<MemoryRecallCandidate> candidates, int finalCount, string currentInput, string secondaryInput, out List<int> selectedIds, out string error)
	{
		Stopwatch sw = Stopwatch.StartNew();
		selectedIds = new List<int>();
		error = "";
		List<MemoryRecallCandidate> list = (candidates ?? new List<MemoryRecallCandidate>()).Where((MemoryRecallCandidate x) => x?.Block != null && x.DisplayId > 0).ToList();
		string debugHeroId = NormalizeMemoryHeroId(list.Select((MemoryRecallCandidate x) => x?.Block?.HeroId).FirstOrDefault((string x) => !string.IsNullOrWhiteSpace(x)));
		if (list.Count <= 0 || finalCount <= 0)
		{
			sw.Stop();
			Logger.Log("Logic", "[MemoryPerf] memory_preprocess_done hero=" + (debugHeroId ?? "") + " mode=empty candidates=" + list.Count + " finalCount=" + finalCount + " selected=0 ms=" + Math.Round(sw.Elapsed.TotalMilliseconds, 2));
			return true;
		}
		if (list.Count <= finalCount)
		{
			selectedIds = list.Select((MemoryRecallCandidate x) => x.DisplayId).ToList();
			sw.Stop();
			Logger.Log("Logic", "[MemoryPerf] memory_preprocess_done hero=" + (debugHeroId ?? "") + " mode=direct candidates=" + list.Count + " finalCount=" + finalCount + " selected=" + selectedIds.Count + " ms=" + Math.Round(sw.Elapsed.TotalMilliseconds, 2));
			return true;
		}
		string system = AIConfigHandler.StrictPreprocessJsonSystemPrompt;
		int mode = GetMemoryPreprocessModeFromSettings();
		StringBuilder memoryCandidates = new StringBuilder();
		foreach (MemoryRecallCandidate item in list)
		{
			CompressedMemoryBlock block = item.Block;
			string text = block.GameDate;
			if (string.IsNullOrWhiteSpace(text))
			{
				text = AIConfigHandler.BuildMemoryPreprocessFallbackGameDateForExternal(block.GameDayIndex);
			}
			memoryCandidates.AppendLine(AIConfigHandler.BuildMemoryPreprocessCandidateLineForExternal(item.DisplayId, text, FormatCompressedMemoryAgeSuffix(block), FormatMemoryHourRange(block.StartHour, block.EndHour), block.RichTitle));
		}
		string user = AIConfigHandler.BuildMemoryPreprocessUserPromptForExternal(mode, finalCount, currentInput, secondaryInput, ResolveCurrentMemorySceneLabel(), memoryCandidates.ToString());
		object[] messages = new object[2]
		{
			new
			{
				role = "system",
				content = system
			},
			new
			{
				role = "user",
				content = user
			}
		};
		string content = "";
		Stopwatch apiSw = Stopwatch.StartNew();
		if (mode == 2)
		{
			string memoryError = "";
			bool memoryOk = false;
			Task memoryTask = Task.Run(delegate
			{
				memoryOk = AIConfigHandler.TryCallAuxiliarySimpleDialogue(messages, 800, 0f, out content, out memoryError);
			});
			try
			{
				memoryTask.Wait();
			}
			catch (Exception ex)
			{
				apiSw.Stop();
				sw.Stop();
				error = ex.Message;
				Logger.Log("Logic", "[MemoryPerf] memory_preprocess_failed hero=" + (debugHeroId ?? "") + " mode=" + mode + " candidates=" + list.Count + " finalCount=" + finalCount + " promptChars=" + user.Length + " apiMs=" + Math.Round(apiSw.Elapsed.TotalMilliseconds, 2) + " totalMs=" + Math.Round(sw.Elapsed.TotalMilliseconds, 2) + " reason=wait_exception type=" + ex.GetType().Name);
				ShowCompressedMemoryBlockingPopup("压缩记忆前处理失败", "记忆前处理请求异常：" + error);
				return false;
			}
			apiSw.Stop();
			if (!memoryOk)
			{
				error = memoryError;
				sw.Stop();
				Logger.Log("Logic", "[MemoryPerf] memory_preprocess_failed hero=" + (debugHeroId ?? "") + " mode=" + mode + " candidates=" + list.Count + " finalCount=" + finalCount + " promptChars=" + user.Length + " apiMs=" + Math.Round(apiSw.Elapsed.TotalMilliseconds, 2) + " totalMs=" + Math.Round(sw.Elapsed.TotalMilliseconds, 2) + " reason=api_failed error=" + (error ?? ""));
				ShowCompressedMemoryBlockingPopup("压缩记忆前处理失败", "记忆前处理没有成功：" + error + "\n\n请修复前处理 API 后重试。");
				return false;
			}
		}
		else if (!AIConfigHandler.TryCallAuxiliarySimpleDialogue(messages, 800, 0f, out content, out error))
		{
			apiSw.Stop();
			sw.Stop();
			Logger.Log("Logic", "[MemoryPerf] memory_preprocess_failed hero=" + (debugHeroId ?? "") + " mode=" + mode + " candidates=" + list.Count + " finalCount=" + finalCount + " promptChars=" + user.Length + " apiMs=" + Math.Round(apiSw.Elapsed.TotalMilliseconds, 2) + " totalMs=" + Math.Round(sw.Elapsed.TotalMilliseconds, 2) + " reason=api_failed error=" + (error ?? ""));
			ShowCompressedMemoryBlockingPopup("压缩记忆前处理失败", "记忆筛选请求失败：" + (error ?? "未知错误") + "\n\n请修复前处理 API 后重试。");
			return false;
		}
		else
		{
			apiSw.Stop();
		}
		if (!TryParseMemoryPreprocessIds(content, list.Select((MemoryRecallCandidate x) => x.DisplayId), finalCount, out selectedIds, out var parseError))
		{
			error = BuildMemoryPreprocessFormatError(parseError, content);
			sw.Stop();
			Logger.Log("Logic", "[MemoryPerf] memory_preprocess_failed hero=" + (debugHeroId ?? "") + " mode=" + mode + " candidates=" + list.Count + " finalCount=" + finalCount + " promptChars=" + user.Length + " apiMs=" + Math.Round(apiSw.Elapsed.TotalMilliseconds, 2) + " totalMs=" + Math.Round(sw.Elapsed.TotalMilliseconds, 2) + " reason=format_error parseError=" + (parseError ?? "") + " responseLen=" + ((content ?? "").Length));
			ShowCompressedMemoryBlockingPopup("压缩记忆前处理失败", error + "\n\n请修复前处理提示词或 API 输出后重试。");
			throw new PreprocessFormatException(error);
		}
		if (selectedIds.Count < finalCount)
		{
			HashSet<int> selectedSet = new HashSet<int>(selectedIds);
			List<int> fill = list.OrderByDescending((MemoryRecallCandidate x) => x.Score).ThenByDescending((MemoryRecallCandidate x) => x.Block.GameDayIndex).Select((MemoryRecallCandidate x) => x.DisplayId).Where((int x) => !selectedSet.Contains(x)).Take(finalCount - selectedIds.Count).ToList();
			selectedIds.AddRange(fill);
		}
		if (selectedIds.Count > finalCount)
		{
			selectedIds = selectedIds.Take(finalCount).ToList();
		}
		sw.Stop();
		Logger.Log("Logic", "[MemoryPerf] memory_preprocess_done hero=" + (debugHeroId ?? "") + " mode=" + mode + " candidates=" + list.Count + " finalCount=" + finalCount + " selected=" + selectedIds.Count + " promptChars=" + user.Length + " responseLen=" + ((content ?? "").Length) + " apiMs=" + Math.Round(apiSw.Elapsed.TotalMilliseconds, 2) + " totalMs=" + Math.Round(sw.Elapsed.TotalMilliseconds, 2));
		return true;
	}

	private static bool TryParseMemoryPreprocessIds(string content, IEnumerable<int> allowedIds, int finalCount, out List<int> selectedIds, out string error)
	{
		HashSet<int> allowed = new HashSet<int>(allowedIds ?? Enumerable.Empty<int>());
		HashSet<int> seen = new HashSet<int>();
		selectedIds = new List<int>();
		error = "";
		if (allowed.Count <= 0)
		{
			error = "no_allowed_memory_ids";
			return false;
		}
		if (!AIConfigHandler.TryValidateStrictPreprocessJsonEnvelope(content, requireMemoryIds: true, requireMentionedEntities: false, out var jObject, out error))
		{
			return false;
		}
		JToken token = jObject["memory_ids"];
		if (token == null || token.Type == JTokenType.Null)
		{
			error = "missing_memory_ids";
			return false;
		}
		if (!(token is JArray jArray))
		{
			error = "memory_ids_not_array";
			return false;
		}
		if (jArray.Count <= 0)
		{
			return true;
		}
		foreach (JToken item in jArray)
		{
			if (item == null || item.Type == JTokenType.Null)
			{
				continue;
			}
			string raw = (item?.ToString() ?? "").Trim().TrimStart('#');
			if (!int.TryParse(raw, out var result))
			{
				error = "memory_id_not_integer";
				selectedIds.Clear();
				return false;
			}
			if (!allowed.Contains(result))
			{
				continue;
			}
			if (seen.Add(result))
			{
				selectedIds.Add(result);
			}
		}
		return true;
	}

	private static string BuildMemoryPreprocessFormatError(string reason, string content)
	{
		string detail = "（API响应格式错误）压缩记忆前处理返回格式错误：" + (string.IsNullOrWhiteSpace(reason) ? "unknown" : reason.Trim()) + "。必须只输出一个 JSON 对象，并包含 rule_codes 和 memory_ids 数组。";
		return LlmRetryPrompt.BuildFailureDetail(detail, content);
	}

	private void ShowCompressedMemoryBlockingPopup(string title, string message)
	{
		try
		{
			Logger.Log("CompressedMemory", "[BLOCK] " + title + " :: " + (message ?? ""));
			if (_memorySummaryFailurePopupActive)
			{
				return;
			}
			_memorySummaryFailurePopupActive = true;
			InformationManager.ShowInquiry(new InquiryData(title, message ?? "", isAffirmativeOptionShown: true, isNegativeOptionShown: false, "知道了", "", delegate
			{
				_memorySummaryFailurePopupActive = false;
			}, null), pauseGameActiveState: true);
		}
		catch
		{
			_memorySummaryFailurePopupActive = false;
		}
	}

	private List<ConversationMessage> BuildUncompressedMemoryRoleMessages(Hero hero, int targetAgentIndex = -1, bool includeCurrentActiveSceneSession = false)
	{
		if (hero == null)
		{
			return new List<ConversationMessage>();
		}
		string heroName = (hero.Name?.ToString() ?? "NPC").Trim();
		if (string.IsNullOrWhiteSpace(heroName))
		{
			heroName = "NPC";
		}
		return BuildUncompressedMemoryRoleMessagesById(GetMemoryHeroId(hero), heroName, targetAgentIndex, includeCurrentActiveSceneSession);
	}

	private List<ConversationMessage> BuildUncompressedMemoryRoleMessagesById(string memoryId, string memoryName, int targetAgentIndex = -1, bool includeCurrentActiveSceneSession = false)
	{
		Stopwatch sw = Stopwatch.StartNew();
		List<ConversationMessage> result = new List<ConversationMessage>();
		string normalizedMemoryId = NormalizeMemoryHeroId(memoryId);
		if (!IsMemoryEntityEligibleForCompressedMemory(normalizedMemoryId))
		{
			return result;
		}
		List<DailyMemoryDraft> drafts = LoadDailyMemoryDraftsById(normalizedMemoryId);
		if (drafts == null || drafts.Count <= 0)
		{
			sw.Stop();
			Logger.Log("Logic", "[MemoryPerf] uncompressed_memory_done hero=" + normalizedMemoryId + " drafts=0 messages=0 agent=" + targetAgentIndex + " includeCurrentSession=" + includeCurrentActiveSceneSession + " ms=" + Math.Round(sw.Elapsed.TotalMilliseconds, 2));
			if (IsNonHeroMemoryId(normalizedMemoryId))
			{
				LogNonHeroMemoryTrace("stage=uncompressed_build_done memoryId=" + normalizedMemoryId + " drafts=0 draftLines=0 messages=0 agent=" + targetAgentIndex + " includeCurrentSession=" + includeCurrentActiveSceneSession + " ms=" + Math.Round(sw.Elapsed.TotalMilliseconds, 2));
			}
			return result;
		}
		int currentDay = GetCurrentGameDayIndexSafe();
		int currentSceneSessionId = includeCurrentActiveSceneSession ? -1 : GetCurrentSceneSessionIdForDailyMemorySuppression();
		int currentDialogueSessionId = GetCurrentNativeConversationMemorySessionIdForSuppression();
		string currentMemorySessionKey = !includeCurrentActiveSceneSession && (currentSceneSessionId >= 0 || currentDialogueSessionId >= 0)
			? BuildCurrentMemorySessionKey(currentSceneSessionId, currentDialogueSessionId)
			: "";
		string targetName = string.IsNullOrWhiteSpace(memoryName) ? "NPC" : memoryName.Trim();
		foreach (DailyMemoryDraft draft in drafts.Where((DailyMemoryDraft x) => x != null).OrderBy((DailyMemoryDraft x) => x.GameDayIndex))
		{
			bool isToday = draft.GameDayIndex == currentDay;
			bool hasAfefLines = HasDailyMemoryDraftAfefLines(draft);
			if (!isToday && (HasCompressedMemoryBlock(normalizedMemoryId, draft.GameDayIndex) || (!draft.HasLlmDialogue && !hasAfefLines)))
			{
				continue;
			}
			foreach (DailyMemoryLine line in draft.Lines ?? new List<DailyMemoryLine>())
			{
				if (line == null || string.IsNullOrWhiteSpace(line.Text))
				{
					continue;
				}
				if (isToday && IsCurrentActiveMemorySessionLine(line, currentMemorySessionKey))
				{
					continue;
				}
				ConversationMessage message = BuildUncompressedMemoryConversationMessage(line, targetName, targetAgentIndex);
				if (message != null)
				{
					result.Add(message);
				}
			}
		}
		int rawMessageCount = result.Count;
		int historyLineLimit = DuelSettings.GetDailyConversationHistoryLineLimitForExternal();
		result = KeepUncompressedFactsAndRecentConversationMessages(result, historyLineLimit);
		sw.Stop();
		Logger.Log("Logic", "[MemoryPerf] uncompressed_memory_done hero=" + normalizedMemoryId + " drafts=" + drafts.Count + " rawMessages=" + rawMessageCount + " messages=" + result.Count + " historyLineLimit=" + historyLineLimit + " agent=" + targetAgentIndex + " includeCurrentSession=" + includeCurrentActiveSceneSession + " ms=" + Math.Round(sw.Elapsed.TotalMilliseconds, 2));
		if (IsNonHeroMemoryId(normalizedMemoryId))
		{
			LogNonHeroMemoryTrace("stage=uncompressed_build_done memoryId=" + normalizedMemoryId + " drafts=" + drafts.Count + " draftLines=" + CountDailyMemoryDraftLines(drafts) + " rawMessages=" + rawMessageCount + " messages=" + result.Count + " historyLineLimit=" + historyLineLimit + " agent=" + targetAgentIndex + " includeCurrentSession=" + includeCurrentActiveSceneSession + " currentDay=" + currentDay + " suppressedSceneSession=" + currentSceneSessionId + " suppressedDialogueSession=" + currentDialogueSessionId + " ms=" + Math.Round(sw.Elapsed.TotalMilliseconds, 2));
		}
		return result;
	}

	private static List<ConversationMessage> KeepUncompressedFactsAndRecentConversationMessages(List<ConversationMessage> messages, int maxConversationMessages)
	{
		if (messages == null || messages.Count == 0)
		{
			return messages ?? new List<ConversationMessage>();
		}
		int limit = Math.Max(DuelSettings.DailyConversationHistoryLineLimitMin, Math.Min(DuelSettings.DailyConversationHistoryLineLimitMax, maxConversationMessages));
		int conversationCount = 0;
		for (int i = 0; i < messages.Count; i++)
		{
			ConversationMessage message = messages[i];
			if (message != null && !string.Equals((message.Role ?? "").Trim(), "system", StringComparison.OrdinalIgnoreCase))
			{
				conversationCount++;
			}
		}
		int removeCount = conversationCount - limit;
		if (removeCount <= 0)
		{
			return messages;
		}
		List<ConversationMessage> result = new List<ConversationMessage>(messages.Count - removeCount);
		for (int i = 0; i < messages.Count; i++)
		{
			ConversationMessage message = messages[i];
			bool isFact = message != null && string.Equals((message.Role ?? "").Trim(), "system", StringComparison.OrdinalIgnoreCase);
			if (!isFact && removeCount > 0)
			{
				removeCount--;
				continue;
			}
			result.Add(message);
		}
		return result;
	}

	private static ConversationMessage BuildUncompressedMemoryConversationMessage(DailyMemoryLine line, string memoryName, int targetAgentIndex)
	{
		if (line == null || string.IsNullOrWhiteSpace(line.Text))
		{
			return null;
		}
		string text = (line.Text ?? "").Replace("\r", "").Trim();
		string speaker = string.IsNullOrWhiteSpace(line.Speaker) ? (line.IsAfef ? "AFEF" : "记录") : line.Speaker.Trim();
		string npcName = string.IsNullOrWhiteSpace(memoryName) ? "NPC" : memoryName.Trim();
		string role = "user";
		int speakerAgentIndex = -1;
		int targetIndex = line.TargetAgentIndex >= 0 ? line.TargetAgentIndex : targetAgentIndex;
		string targetName = string.IsNullOrWhiteSpace(line.TargetName) ? npcName : line.TargetName.Trim();
		if (line.IsAfef)
		{
			role = "system";
			speaker = "AFEF";
			speakerAgentIndex = -1;
			targetIndex = -1;
			targetName = "";
		}
		else if (TryParseDailyMemorySceneShoutLine(text, out var heardSpeaker, out var heardContent))
		{
			role = "assistant";
			speaker = string.IsNullOrWhiteSpace(heardSpeaker) ? "某NPC" : heardSpeaker.Trim();
			text = string.IsNullOrWhiteSpace(heardContent) ? text : heardContent.Trim();
			speakerAgentIndex = -1;
			targetIndex = -1;
			targetName = "";
		}
		else if (IsDailyMemoryLineNpcSpeech(line, npcName))
		{
			role = "assistant";
			speaker = npcName;
			speakerAgentIndex = targetAgentIndex;
			targetIndex = -1;
			targetName = "";
		}
		else if (!IsDailyMemoryLinePlayerSpeech(line, npcName))
		{
			role = "assistant";
			speakerAgentIndex = -1;
			targetIndex = -1;
			targetName = "";
		}
		return new ConversationMessage
		{
			GameDayIndex = line.GameDayIndex,
			GameDate = line.GameDate ?? "",
			GameHour = MBMath.ClampInt(line.GameHour, 0, 23),
			Scene = ResolveMemoryLineSceneForPrompt(line),
			Role = role,
			Content = text,
			SpeakerName = speaker,
			SpeakerAgentIndex = speakerAgentIndex,
			TargetAgentIndex = targetIndex,
			TargetName = targetName,
			PlayerDistanceMeters = -1f
		};
	}

	private static bool IsDailyMemoryLineNpcSpeech(DailyMemoryLine line, string npcName)
	{
		if (line == null)
		{
			return false;
		}
		string speaker = (line.Speaker ?? "").Trim();
		string name = (npcName ?? "").Trim();
		if (!string.IsNullOrWhiteSpace(speaker) && !string.IsNullOrWhiteSpace(name) && string.Equals(speaker, name, StringComparison.OrdinalIgnoreCase))
		{
			return true;
		}
		string text = (line.Text ?? "").Trim();
		return !string.IsNullOrWhiteSpace(name) && (text.StartsWith(name + ":", StringComparison.Ordinal) || text.StartsWith(name + "：", StringComparison.Ordinal));
	}

	private static bool IsDailyMemoryLinePlayerSpeech(DailyMemoryLine line, string npcName)
	{
		if (line == null)
		{
			return false;
		}
		string speaker = (line.Speaker ?? "").Trim();
		if (IsLikelyPlayerHistorySpeaker(speaker))
		{
			return true;
		}
		string text = (line.Text ?? "").Trim();
		string name = (npcName ?? "").Trim();
		if (!string.IsNullOrWhiteSpace(name) && (text.Contains("对" + name + "说") || text.Contains("对" + name + "喊") || text.Contains("向" + name + "说") || text.Contains("向" + name + "喊")))
		{
			return true;
		}
		return text.StartsWith("玩家", StringComparison.Ordinal);
	}

	private static bool TryParseDailyMemorySceneShoutLine(string rawText, out string speaker, out string content)
	{
		speaker = "";
		content = "";
		string text = (rawText ?? "").Trim();
		if (!text.StartsWith("[场景喊话]", StringComparison.Ordinal))
		{
			return false;
		}
		string body = text.Substring("[场景喊话]".Length).Trim();
		if (string.IsNullOrWhiteSpace(body))
		{
			return true;
		}
		int delimiter = FindDialogueHistorySpeakerDelimiter(body);
		if (delimiter > 0)
		{
			speaker = body.Substring(0, delimiter).Trim();
			content = body.Substring(delimiter + 1).Trim();
		}
		else
		{
			content = body;
		}
		return true;
	}

	private static int GetCurrentSceneSessionIdForDailyMemorySuppression()
	{
		try
		{
			if (Mission.Current?.Scene == null)
			{
				return -1;
			}
			try
			{
				if (!ShoutUtils.IsInValidScene())
				{
					return -1;
				}
				return ShoutBehavior.GetCurrentSceneHistorySessionIdForExternal();
			}
			catch
			{
				return -1;
			}
		}
		catch
		{
			return -1;
		}
	}

	private static bool IsCurrentActiveMemorySessionLine(DailyMemoryLine line, string currentMemorySessionKey)
	{
		if (line == null)
		{
			return false;
		}
		string lineSessionKey = (line.MemorySessionKey ?? "").Trim();
		string activeSessionKey = (currentMemorySessionKey ?? "").Trim();
		if (string.IsNullOrWhiteSpace(lineSessionKey) || string.IsNullOrWhiteSpace(activeSessionKey))
		{
			return false;
		}
		return string.Equals(lineSessionKey, activeSessionKey, StringComparison.OrdinalIgnoreCase);
	}

	private string BuildMemoryOverviewContext(Hero hero)
	{
		return BuildMemoryOverviewContextById(GetMemoryHeroId(hero));
