	private string BuildMemoryOverviewContextById(string memoryId)
	{
		string heroId = NormalizeMemoryHeroId(memoryId);
		if (!IsMemoryEntityEligibleForCompressedMemory(heroId))
		{
			return "";
		}
		List<CompressedMemoryBlock> blocks = LoadCompressedMemoryBlocksById(heroId);
		MemoryOverviewState state = GetMemoryOverviewState(heroId);
		if (state != null && !string.IsNullOrWhiteSpace(state.LastError) && blocks != null && blocks.Count >= GetMemoryOverviewStartBlockCountFromSettings() && HasMemoryOverviewPendingBlocks(heroId, blocks))
		{
			return "【过往记忆总览】\n过往记忆总览正在整理，暂不可引用总览细节。";
		}
		if (state != null && !string.IsNullOrWhiteSpace(state.Summary))
		{
			return "【过往记忆总览】\n" + state.Summary.Trim();
		}
		if (blocks == null || blocks.Count < GetMemoryOverviewStartBlockCountFromSettings())
		{
			return "";
		}
		return "【过往记忆总览】\n过往记忆总览正在整理，暂不可引用总览细节。";
	}

	private string BuildCompressedMemoryContext(Hero hero, string currentInput, string secondaryInput)
	{
		return BuildCompressedMemoryContextById(GetMemoryHeroId(hero), currentInput, secondaryInput);
	}

	private string BuildCompressedMemoryContextById(string memoryId, string currentInput, string secondaryInput)
	{
		Stopwatch sw = Stopwatch.StartNew();
		string heroId = NormalizeMemoryHeroId(memoryId);
		List<CompressedMemoryBlock> list = LoadCompressedMemoryBlocksById(heroId);
		if (list == null || list.Count <= 0)
		{
			sw.Stop();
			Logger.Log("Logic", "[MemoryPerf] compressed_context_done hero=" + heroId + " blocks=0 candidates=0 final=0 chars=0 ms=" + Math.Round(sw.Elapsed.TotalMilliseconds, 2));
			return "";
		}
		int finalCount = GetMemoryFinalInjectCountFromSettings();
		int candidateLimit = GetMemoryCandidateLimitFromSettings();
		List<MemoryRecallCandidate> candidates;
		Logger.Log("Logic", "[MemoryPerf] compressed_context_start hero=" + heroId + " blocks=" + list.Count + " finalCount=" + finalCount + " candidateLimit=" + candidateLimit + " currentLen=" + ((currentInput ?? "").Length) + " secondaryLen=" + ((secondaryInput ?? "").Length));
		if (list.Count <= finalCount)
		{
			candidates = list.OrderBy((CompressedMemoryBlock x) => x.GameDayIndex).ThenBy((CompressedMemoryBlock x) => x.StartHour).Select((CompressedMemoryBlock x) => new MemoryRecallCandidate
			{
				Block = x,
				Score = 1.0
			}).ToList();
			AssignMemoryCandidateDisplayIds(candidates);
		}
		else
		{
			CompressedMemoryBlock latestBlock = list.OrderByDescending((CompressedMemoryBlock x) => x.GameDayIndex).ThenByDescending((CompressedMemoryBlock x) => x.EndHour).ThenByDescending((CompressedMemoryBlock x) => x.StartHour).ThenByDescending((CompressedMemoryBlock x) => x.CreatedUtcTicks).FirstOrDefault();
			string latestBlockId = (latestBlock?.Id ?? "").Trim();
			int selectableFinalCount = Math.Max(0, finalCount - ((latestBlock != null) ? 1 : 0));
			int selectableCandidateLimit = Math.Max(selectableFinalCount, candidateLimit - ((latestBlock != null) ? 1 : 0));
			List<CompressedMemoryBlock> selectableBlocks = list.Where((CompressedMemoryBlock x) => x != null && (latestBlock == null || !string.Equals((x.Id ?? "").Trim(), latestBlockId, StringComparison.OrdinalIgnoreCase))).ToList();
			candidates = new List<MemoryRecallCandidate>();
			List<DailyMemoryDraft> drafts = LoadDailyMemoryDraftsById(heroId);
			if (selectableFinalCount > 0 && selectableBlocks.Count > 0)
			{
				if (!TryBuildMemoryRecallCandidates(null, selectableBlocks, currentInput, secondaryInput, drafts, selectableCandidateLimit, out candidates, out var error))
				{
					Logger.Log("CompressedMemory", "[ERROR] recall failed hero=" + heroId + " error=" + error);
					sw.Stop();
					Logger.Log("Logic", "[MemoryPerf] compressed_context_failed hero=" + heroId + " reason=recall_failed blocks=" + list.Count + " selectable=" + selectableBlocks.Count + " ms=" + Math.Round(sw.Elapsed.TotalMilliseconds, 2));
					return "";
				}
				if (candidates.Count > selectableFinalCount)
				{
					if (!TrySelectMemoryIdsWithPreprocess(candidates, selectableFinalCount, currentInput, secondaryInput, out var selectedIds, out var error2))
					{
						Logger.Log("CompressedMemory", "[ERROR] preprocess failed hero=" + heroId + " error=" + error2);
						sw.Stop();
						Logger.Log("Logic", "[MemoryPerf] compressed_context_failed hero=" + heroId + " reason=preprocess_failed blocks=" + list.Count + " candidates=" + candidates.Count + " selectableFinal=" + selectableFinalCount + " ms=" + Math.Round(sw.Elapsed.TotalMilliseconds, 2));
						return "";
					}
					HashSet<int> selected = new HashSet<int>(selectedIds);
					candidates = candidates.Where((MemoryRecallCandidate x) => selected.Contains(x.DisplayId)).OrderBy((MemoryRecallCandidate x) => x.Block.GameDayIndex).ThenBy((MemoryRecallCandidate x) => x.Block.StartHour).ToList();
				}
			}
			if (latestBlock != null)
			{
				candidates.Add(new MemoryRecallCandidate
				{
					Block = latestBlock,
					Score = double.MaxValue
				});
			}
		}
		if (candidates.Count <= 0)
		{
			sw.Stop();
			Logger.Log("Logic", "[MemoryPerf] compressed_context_done hero=" + heroId + " blocks=" + list.Count + " candidates=0 final=0 chars=0 ms=" + Math.Round(sw.Elapsed.TotalMilliseconds, 2));
			return "";
		}
		StringBuilder stringBuilder = new StringBuilder();
		stringBuilder.AppendLine("你想起之前的对话与互动");
		int num = 1;
		foreach (MemoryRecallCandidate candidate in candidates.OrderBy((MemoryRecallCandidate x) => x.Block.GameDayIndex).ThenBy((MemoryRecallCandidate x) => x.Block.StartHour))
		{
			CompressedMemoryBlock block = candidate.Block;
			if (block == null)
			{
				continue;
			}
			string text = string.IsNullOrWhiteSpace(block.GameDate) ? ("第" + block.GameDayIndex + "日") : block.GameDate.Trim();
			string text2 = StripMemoryTitleDateTime(block.RichTitle);
			if (string.IsNullOrWhiteSpace(text2))
			{
				text2 = "往日对话记忆";
			}
			stringBuilder.AppendLine(num + "#标题：" + text + FormatCompressedMemoryAgeSuffix(block) + " " + FormatMemoryHourRange(block.StartHour, block.EndHour) + " " + text2);
			stringBuilder.AppendLine("内容：");
			stringBuilder.AppendLine((block.Summary ?? "").Trim());
			stringBuilder.AppendLine("AFEF行为补充：");
			if (block.AfefLines != null && block.AfefLines.Count > 0)
			{
				foreach (string item in block.AfefLines)
				{
					if (!string.IsNullOrWhiteSpace(item))
					{
						stringBuilder.AppendLine(FormatPastAfefLineForPrompt(item));
					}
				}
			}
			else
			{
				stringBuilder.AppendLine("无");
			}
			stringBuilder.AppendLine();
			num++;
		}
		string result = stringBuilder.ToString().TrimEnd();
		sw.Stop();
		Logger.Log("Logic", "[MemoryPerf] compressed_context_done hero=" + heroId + " blocks=" + list.Count + " candidates=" + candidates.Count + " final=" + (num - 1) + " chars=" + result.Length + " ms=" + Math.Round(sw.Elapsed.TotalMilliseconds, 2));
		return result;
	}

	private static string FormatPastAfefLineForPrompt(string text)
	{
		string value = (text ?? "").Trim();
		if (string.IsNullOrWhiteSpace(value))
		{
			return "";
		}
		if (value.StartsWith("【过往行为】", StringComparison.Ordinal) || value.StartsWith("【当下行为】", StringComparison.Ordinal))
		{
			return value;
		}
		return "【过往行为】" + value;
	}

	private string BuildHistoryContext(Hero hero, int maxLines = 0, string currentInput = null, string secondaryInput = null, bool includeCurrentActiveSceneSession = false)
	{
		if (hero == null)
		{
			return "";
		}
		return BuildHistoryContextById(GetMemoryHeroId(hero), hero.Name?.ToString() ?? "NPC", maxLines, currentInput, secondaryInput, includeCurrentActiveSceneSession);
	}

	private string BuildHistoryContextById(string memoryId, string memoryName, int maxLines = 0, string currentInput = null, string secondaryInput = null, bool includeCurrentActiveSceneSession = false)
	{
		string normalizedMemoryId = NormalizeMemoryHeroId(memoryId);
		if (!IsMemoryEntityEligibleForCompressedMemory(normalizedMemoryId))
		{
			return "";
		}
		try
		{
			Stopwatch sw = Stopwatch.StartNew();
			int memoryBlockCount = LoadCompressedMemoryBlocksById(normalizedMemoryId).Count;
			int dailyDraftCount = LoadDailyMemoryDraftsById(normalizedMemoryId).Count;
			StringBuilder stringBuilder = new StringBuilder(4096);
			string memoryOverviewContext = BuildMemoryOverviewContextById(normalizedMemoryId);
			if (!string.IsNullOrWhiteSpace(memoryOverviewContext))
			{
				stringBuilder.AppendLine(memoryOverviewContext);
				stringBuilder.AppendLine();
			}
			string compressedMemoryContext = BuildCompressedMemoryContextById(normalizedMemoryId, currentInput, secondaryInput);
			if (!string.IsNullOrWhiteSpace(compressedMemoryContext))
			{
				stringBuilder.AppendLine(compressedMemoryContext);
				stringBuilder.AppendLine();
			}
			string text4 = stringBuilder.ToString().TrimEnd();
			sw.Stop();
			Logger.Log("DialogueHistory", string.Format("compressed_context hero={0} chars={1} blocks={2} drafts={3}", normalizedMemoryId, text4.Length, memoryBlockCount, dailyDraftCount));
			Logger.Log("Logic", "[MemoryPerf] history_context_done hero=" + normalizedMemoryId + " blocks=" + memoryBlockCount + " drafts=" + dailyDraftCount + " overviewChars=" + ((memoryOverviewContext ?? "").Length) + " compressedChars=" + ((compressedMemoryContext ?? "").Length) + " totalChars=" + text4.Length + " npcRecall=" + (!string.IsNullOrWhiteSpace(secondaryInput)) + " includeCurrentSession=" + includeCurrentActiveSceneSession + " ms=" + Math.Round(sw.Elapsed.TotalMilliseconds, 2));
			if (IsNonHeroMemoryId(normalizedMemoryId))
			{
				LogNonHeroMemoryTrace("stage=history_context_done memoryId=" + normalizedMemoryId + " blocks=" + memoryBlockCount + " drafts=" + dailyDraftCount + " overviewChars=" + ((memoryOverviewContext ?? "").Length) + " compressedChars=" + ((compressedMemoryContext ?? "").Length) + " totalChars=" + text4.Length + " npcRecall=" + (!string.IsNullOrWhiteSpace(secondaryInput)) + " includeCurrentSession=" + includeCurrentActiveSceneSession + " ms=" + Math.Round(sw.Elapsed.TotalMilliseconds, 2));
			}
			Logger.Obs("History", "build_context", new Dictionary<string, object>
			{
				["heroId"] = normalizedMemoryId,
				["memoryBlocks"] = memoryBlockCount,
				["dailyDrafts"] = dailyDraftCount,
				["npcRecall"] = !string.IsNullOrWhiteSpace(secondaryInput),
				["chars"] = text4.Length
			});
			Logger.Metric("history.build_context");
			return text4;
		}
		catch (Exception ex)
		{
			Logger.Log("DialogueHistory", "[错误] 构建上下文失败: " + ex.Message);
			Logger.Obs("History", "build_context_error", new Dictionary<string, object>
			{
				["message"] = ex.Message,
				["type"] = ex.GetType().Name
			});
			Logger.Metric("history.build_context", ok: false);
			return "";
		}
	}

