	private EventRecordEntry FindEventRecordById(string eventId)
	{
		string text = (eventId ?? "").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return null;
		}
		return SanitizeEventRecordEntries(_eventRecordEntries).FirstOrDefault((EventRecordEntry x) => x != null && string.Equals((x.EventId ?? "").Trim(), text, StringComparison.OrdinalIgnoreCase));
	}

	private bool TryLoadEventDataFromImportDir(string importDir, out EventImportPayload payload, out string error)
	{
		payload = new EventImportPayload();
		error = "";
		try
		{
			string text = Path.Combine(importDir, "event_data");
			string text2 = Directory.Exists(text) ? text : importDir;
			string path = Path.Combine(text2, "WorldOpeningSummary.json");
			if (File.Exists(path))
			{
				payload.HasWorldSummaryFile = true;
				EventWorldOpeningSummaryJson eventWorldOpeningSummaryJson = ReadJson<EventWorldOpeningSummaryJson>(path);
				payload.WorldSummary = (eventWorldOpeningSummaryJson?.Summary ?? "").Trim();
			}
			string path2 = Path.Combine(text2, "KingdomOpeningSummaries.json");
			if (File.Exists(path2))
			{
				payload.HasKingdomSummariesFile = true;
				Dictionary<string, string> dictionary = ReadJson<Dictionary<string, string>>(path2) ?? new Dictionary<string, string>();
				foreach (KeyValuePair<string, string> item in dictionary)
				{
					string text3 = (item.Key ?? "").Trim();
					if (!string.IsNullOrWhiteSpace(text3))
					{
						payload.KingdomSummaries[text3] = (item.Value ?? "").Trim();
					}
				}
			}
			string path3 = Path.Combine(text2, "EventRecords.json");
			if (File.Exists(path3))
			{
				payload.HasEventRecordsFile = true;
				List<EventRecordEntry> source = ReadJson<List<EventRecordEntry>>(path3) ?? new List<EventRecordEntry>();
				payload.EventRecords = SanitizeEventRecordEntries(source);
			}
			if (!payload.HasWorldSummaryFile && !payload.HasKingdomSummariesFile && !payload.HasEventRecordsFile)
			{
				error = "找不到 event_data\\WorldOpeningSummary.json、event_data\\KingdomOpeningSummaries.json 或 event_data\\EventRecords.json。";
				return false;
			}
			return true;
		}
		catch (Exception ex)
		{
			error = ex.Message;
			return false;
		}
	}

	private void ApplyImportedEventData(EventImportPayload payload, bool overwriteExisting)
	{
		if (payload == null)
		{
			return;
		}
		if (payload.HasWorldSummaryFile && (overwriteExisting || string.IsNullOrWhiteSpace(_eventWorldOpeningSummary)))
		{
			_eventWorldOpeningSummary = (payload.WorldSummary ?? "").Trim();
		}
		if (payload.HasKingdomSummariesFile)
		{
			if (_eventKingdomOpeningSummaries == null)
			{
				_eventKingdomOpeningSummaries = new Dictionary<string, string>();
			}
			foreach (KeyValuePair<string, string> item in payload.KingdomSummaries)
			{
				string text = (item.Key ?? "").Trim();
				if (string.IsNullOrWhiteSpace(text))
				{
					continue;
				}
				string text2 = (item.Value ?? "").Trim();
				if (overwriteExisting)
				{
					if (string.IsNullOrWhiteSpace(text2))
					{
						_eventKingdomOpeningSummaries.Remove(text);
					}
					else
					{
						_eventKingdomOpeningSummaries[text] = text2;
					}
				}
				else if (!_eventKingdomOpeningSummaries.ContainsKey(text) && !string.IsNullOrWhiteSpace(text2))
				{
					_eventKingdomOpeningSummaries[text] = text2;
				}
			}
		}
		if (payload.HasEventRecordsFile)
		{
			string previousWorldWeeklyProductsFingerprint = BuildPublishedWorldWeeklyProductsFingerprint();
			if (_eventRecordEntries == null)
			{
				_eventRecordEntries = new List<EventRecordEntry>();
			}
			if (overwriteExisting)
			{
				Dictionary<string, EventRecordEntry> dictionary = new Dictionary<string, EventRecordEntry>(StringComparer.OrdinalIgnoreCase);
				foreach (EventRecordEntry eventRecordEntry in _eventRecordEntries)
				{
					string text3 = (eventRecordEntry?.EventId ?? "").Trim();
					if (!string.IsNullOrWhiteSpace(text3))
					{
						dictionary[text3] = eventRecordEntry;
					}
				}
				foreach (EventRecordEntry eventRecordEntry2 in payload.EventRecords)
				{
					string text4 = (eventRecordEntry2?.EventId ?? "").Trim();
					if (!string.IsNullOrWhiteSpace(text4))
					{
						dictionary[text4] = eventRecordEntry2;
					}
				}
				_eventRecordEntries = SanitizeEventRecordEntries(dictionary.Values.ToList());
			}
			else
			{
				HashSet<string> hashSet = new HashSet<string>(_eventRecordEntries.Where((EventRecordEntry x) => x != null && !string.IsNullOrWhiteSpace(x.EventId)).Select((EventRecordEntry x) => x.EventId.Trim()), StringComparer.OrdinalIgnoreCase);
				foreach (EventRecordEntry eventRecordEntry3 in payload.EventRecords)
				{
					string text5 = (eventRecordEntry3?.EventId ?? "").Trim();
					if (!string.IsNullOrWhiteSpace(text5) && hashSet.Add(text5))
					{
						_eventRecordEntries.Add(eventRecordEntry3);
					}
				}
				_eventRecordEntries = SanitizeEventRecordEntries(_eventRecordEntries);
			}
			if (!string.Equals(previousWorldWeeklyProductsFingerprint, BuildPublishedWorldWeeklyProductsFingerprint(), StringComparison.Ordinal))
			{
				Interlocked.Increment(ref _publishedWorldWeeklyHistoryRevision);
			}
			// Imported report records may add timeline entries while the archive window is already open.
			NotifyWorldMessageWeeklyTimelineChanged();
		}
	}

	private NpcActionEntry ResolveEventMaterialNpcAction(EventMaterialReference material)
	{
		if (material == null || string.IsNullOrWhiteSpace(material.HeroId))
		{
			return null;
		}
		Hero hero = Hero.FindFirst((Hero h) => h != null && string.Equals((h.StringId ?? "").Trim(), (material.HeroId ?? "").Trim(), StringComparison.OrdinalIgnoreCase));
		if (hero == null)
		{
			return null;
		}
		List<NpcActionEntry> devNpcActionEntries = GetDevNpcActionEntries(hero, material.RecentOnly);
		if (devNpcActionEntries == null || devNpcActionEntries.Count == 0)
		{
			return null;
		}
		NpcActionEntry npcActionEntry = devNpcActionEntries.FirstOrDefault((NpcActionEntry x) => x != null && (!material.ActionDay.HasValue || x.Day == material.ActionDay.Value) && (!material.ActionOrder.HasValue || x.Order == material.ActionOrder.Value) && (string.IsNullOrWhiteSpace(material.ActionStableKey) || string.Equals((x.StableKey ?? "").Trim(), material.ActionStableKey.Trim(), StringComparison.OrdinalIgnoreCase)));
		if (npcActionEntry != null)
		{
			return npcActionEntry;
		}
		if (!string.IsNullOrWhiteSpace(material.ActionStableKey))
		{
			npcActionEntry = devNpcActionEntries.FirstOrDefault((NpcActionEntry x) => x != null && string.Equals((x.StableKey ?? "").Trim(), material.ActionStableKey.Trim(), StringComparison.OrdinalIgnoreCase));
		}
		return npcActionEntry;
	}

	private static string TranslateEventKindForDev(string eventKind)
	{
		switch ((eventKind ?? "").Trim().ToLowerInvariant())
		{
		case "world":
			return "世界事件";
		case "kingdom":
			return "王国事件";
		case "player_local":
			return "玩家周边事件";
		default:
			return string.IsNullOrWhiteSpace(eventKind) ? "未分类事件" : eventKind.Trim();
		}
	}

	private static string TranslateEventMaterialTypeForDev(string materialType)
	{
		string text = (materialType ?? "").Trim().ToLowerInvariant();
		if (text.StartsWith("prompt_agg_", StringComparison.OrdinalIgnoreCase))
		{
			return "周报聚合素材";
		}
		switch (text)
		{
		case "world_opening_summary":
			return "世界开局概要";
		case "kingdom_opening_summary":
			return "王国开局概要";
		case "kingdom_current_ruler":
			return "当前统治者";
		case "npc_recent_action":
			return "NPC近期行动";
		case "npc_major_action":
			return "NPC重大行动";
		case "raw_text":
			return "原始文本素材";
		default:
			return string.IsNullOrWhiteSpace(materialType) ? "未分类素材" : materialType.Trim();
		}
	}

	private static string ResolveSettlementDisplay(string settlementId)
	{
		string text = (settlementId ?? "").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return "";
		}
		try
		{
			Settlement settlement = Settlement.Find(text);
			if (settlement != null)
			{
				string text2 = settlement.Name?.ToString() ?? "";
				if (!string.IsNullOrWhiteSpace(text2))
				{
					return text2;
				}
			}
		}
		catch
		{
		}
		return text;
	}

	private void OpenDevWeeklyEventMaterialPreviewMenu()
	{
		List<WeeklyEventMaterialPreviewGroup> list = BuildWeeklyEventMaterialPreviewGroups();
		List<InquiryElement> list2 = new List<InquiryElement>();
		list2.Add(new InquiryElement("back", "返回", null));
		foreach (WeeklyEventMaterialPreviewGroup item in list)
		{
			list2.Add(new InquiryElement(item, BuildWeeklyEventMaterialPreviewGroupLabel(item), null));
		}
		MultiSelectionInquiryData data = new MultiSelectionInquiryData("本周事件素材预览", BuildWeeklyEventMaterialPreviewMenuDescription(list), list2, isExitShown: true, 0, 1, "查看", "返回", delegate(List<InquiryElement> selected)
		{
			if (selected == null || selected.Count == 0)
			{
				OpenDevWeeklyReportPromptPreviewMenu();
			}
			else if (selected[0].Identifier is string text && text == "back")
			{
				OpenDevWeeklyReportPromptPreviewMenu();
			}
			else if (selected[0].Identifier is WeeklyEventMaterialPreviewGroup weeklyEventMaterialPreviewGroup)
			{
				OpenDevWeeklyEventMaterialPreviewGroupDetail(weeklyEventMaterialPreviewGroup, 0);
			}
			else
			{
				OpenDevWeeklyEventMaterialPreviewMenu();
			}
		}, delegate
		{
			OpenDevEventEditorMenu();
		});
		MBInformationManager.ShowMultiSelectionInquiry(data);
	}

	private string BuildWeeklyEventMaterialPreviewMenuDescription(List<WeeklyEventMaterialPreviewGroup> groups)
	{
		int currentGameDayIndexSafe = GetCurrentGameDayIndexSafe();
		int num = Math.Max(0, currentGameDayIndexSafe - currentGameDayIndexSafe % 7);
		int num2 = Math.Max(1, currentGameDayIndexSafe / 7 + 1);
		int num3 = (groups != null) ? groups.Sum((WeeklyEventMaterialPreviewGroup x) => (x?.PromptMaterials?.Count).GetValueOrDefault()) : 0;
		StringBuilder stringBuilder = new StringBuilder();
		stringBuilder.AppendLine("这里展示“如果现在生成本周事件”，系统会拿去喂给事件生成器的素材池。");
		stringBuilder.AppendLine("当前按世界事件与各王国事件分组展示。");
		stringBuilder.AppendLine(" ");
		stringBuilder.AppendLine("当前周数：第 " + num2 + " 周");
		stringBuilder.AppendLine("当前取材区间：第 " + num + " 日 到 第 " + currentGameDayIndexSafe + " 日");
		stringBuilder.AppendLine("分组数量：" + ((groups != null) ? groups.Count : 0));
		stringBuilder.AppendLine("素材总数：" + num3);
		stringBuilder.AppendLine(" ");
		stringBuilder.AppendLine("当前已接入的素材：世界开局概要、王国开局概要、本周 NPC 行动。");
		return stringBuilder.ToString().TrimEnd();
	}

	private static string BuildWeeklyEventMaterialPreviewGroupLabel(WeeklyEventMaterialPreviewGroup group)
	{
		if (group == null)
		{
			return "无效分组";
		}
		string text = string.IsNullOrWhiteSpace(group.Summary) ? "" : BuildDevSummaryPreview(group.Summary, 44);
		int count = (group.Materials != null) ? group.Materials.Count : 0;
		int count2 = (group.PromptMaterials != null) ? group.PromptMaterials.Count : 0;
		string text2 = count + " / " + count2 + " 条素材";
		string text3 = string.Equals((group.OutputMode).ToString(), WeeklyReportOutputMode.TitleShortTagsOnly.ToString(), StringComparison.OrdinalIgnoreCase) ? "短" : "全";
		return (group.Title ?? "未命名分组") + " [" + text3 + " | " + text2 + "]" + (string.IsNullOrWhiteSpace(text) ? "" : (" " + text));
	}

	private List<WeeklyEventMaterialPreviewGroup> BuildWeeklyEventMaterialPreviewGroups()
	{
		int currentGameDayIndexSafe = GetCurrentGameDayIndexSafe();
		int num = Math.Max(0, currentGameDayIndexSafe - currentGameDayIndexSafe % 7);
		return BuildWeeklyEventMaterialPreviewGroups(num, currentGameDayIndexSafe);
	}

	private List<WeeklyEventMaterialPreviewGroup> BuildWeeklyEventMaterialPreviewGroups(int startDay, int endDay)
	{
		List<WeeklyEventMaterialPreviewGroup> list = new List<WeeklyEventMaterialPreviewGroup>();
		Dictionary<string, Hero> actionHeroLookup = BuildWeeklyNpcActionHeroLookup();
		list.Add(BuildWorldWeeklyEventMaterialPreviewGroup(startDay, endDay, actionHeroLookup));
		foreach (Kingdom devEditableKingdom in GetDevEditableKingdoms())
		{
			if (!IsKingdomEligibleForWeeklyReport(devEditableKingdom))
			{
				continue;
			}
			WeeklyEventMaterialPreviewGroup item = BuildKingdomWeeklyEventMaterialPreviewGroup(devEditableKingdom, startDay, endDay, actionHeroLookup);
			list.Add(item);
		}
		foreach (WeeklyEventMaterialPreviewGroup item2 in list)
		{
			ApplyWeeklyPromptMaterialAggregation(item2);
		}
		List<string> list2 = GetKingdomIdsByPlayerProximity(list.Where((WeeklyEventMaterialPreviewGroup x) => string.Equals((x.GroupKind ?? "").Trim(), "kingdom", StringComparison.OrdinalIgnoreCase)).Select((WeeklyEventMaterialPreviewGroup x) => x.KingdomId)).Where((string x) => !string.IsNullOrWhiteSpace(x)).Select((string x) => x.Trim()).Distinct(StringComparer.OrdinalIgnoreCase).Take(3).ToList();
		if (list2.Count == 0)
		{
			list2 = list.Where((WeeklyEventMaterialPreviewGroup x) => string.Equals((x.GroupKind ?? "").Trim(), "kingdom", StringComparison.OrdinalIgnoreCase)).Select((WeeklyEventMaterialPreviewGroup x) => (x.KingdomId ?? "").Trim()).Where((string x) => !string.IsNullOrWhiteSpace(x)).Distinct(StringComparer.OrdinalIgnoreCase).Take(3).ToList();
		}
		HashSet<string> hashSet = new HashSet<string>((list2 ?? new List<string>()).Where((string x) => !string.IsNullOrWhiteSpace(x)).Select((string x) => x.Trim()), StringComparer.OrdinalIgnoreCase);
		foreach (WeeklyEventMaterialPreviewGroup item2 in list)
		{
			bool flag = string.Equals((item2?.GroupKind ?? "").Trim(), "kingdom", StringComparison.OrdinalIgnoreCase);
			bool flag2 = flag && !hashSet.Contains((item2?.KingdomId ?? "").Trim());
			PrepareWeeklyPromptMaterialsForGroup(item2, flag2);
		}
		return list;
	}

	private static void PrepareWeeklyPromptMaterialsForGroup(WeeklyEventMaterialPreviewGroup group, bool shortOnly)
	{
		if (group == null)
		{
			return;
		}
		group.OutputMode = shortOnly ? WeeklyReportOutputMode.TitleShortTagsOnly : WeeklyReportOutputMode.FullReport;
		group.IncludePreviousReportInPrompt = !shortOnly;
		group.PromptMaterials = shortOnly ? BuildWeeklyPromptMaterialsShort(group) : BuildWeeklyPromptMaterialsFull(group);
		if (group.PromptMaterials == null)
		{
			group.PromptMaterials = new List<EventMaterialReference>();
		}
	}

	private static List<EventMaterialReference> BuildWeeklyPromptMaterialsFull(WeeklyEventMaterialPreviewGroup group)
	{
		List<EventMaterialReference> source = OrderWeeklyPreviewMaterials(group?.Materials).Where((EventMaterialReference x) => x != null).Select(CloneEventMaterialReference).ToList();
		return BuildWeeklyPromptMaterialsWithResolvedVillageRaids(source);
	}

	private static List<EventMaterialReference> BuildWeeklyPromptMaterialsWithResolvedVillageRaids(List<EventMaterialReference> source)
	{
		List<EventMaterialReference> list = new List<EventMaterialReference>();
		Dictionary<string, List<EventMaterialReference>> dictionary = new Dictionary<string, List<EventMaterialReference>>(StringComparer.OrdinalIgnoreCase);
		int num = 0;
		foreach (EventMaterialReference item in OrderWeeklyPreviewMaterials(source).Where((EventMaterialReference x) => x != null))
		{
			if (!IsWeeklyPromptVillageRaidMaterial(item))
			{
				list.Add(item);
				continue;
			}
			string text = ResolveWeeklyPromptVillageRaidKey(item);
			if (string.IsNullOrWhiteSpace(text))
			{
				text = "unknown_village_raid_" + num++;
			}
			if (!dictionary.TryGetValue(text, out var value))
			{
				value = new List<EventMaterialReference>();
				dictionary[text] = value;
			}
			value.Add(item);
		}
		foreach (List<EventMaterialReference> item2 in dictionary.Values.Where((List<EventMaterialReference> x) => x != null && x.Count > 0).OrderBy((List<EventMaterialReference> x) => x.Min((EventMaterialReference y) => y?.ActionDay ?? int.MaxValue)).ThenBy((List<EventMaterialReference> x) => x.Min((EventMaterialReference y) => y?.ActionSequence ?? int.MaxValue)).ThenBy((List<EventMaterialReference> x) => ResolveWeeklyPromptVillageRaidKey(x[0]), StringComparer.OrdinalIgnoreCase))
		{
			EventMaterialReference eventMaterialReference = BuildWeeklyPromptResolvedVillageRaidMaterial(item2);
			if (eventMaterialReference != null)
			{
				list.Add(eventMaterialReference);
			}
		}
		return OrderWeeklyPreviewMaterials(list).ToList();
	}

	private static EventMaterialReference BuildWeeklyPromptResolvedVillageRaidMaterial(List<EventMaterialReference> source)
	{
		List<EventMaterialReference> list = OrderWeeklyPreviewMaterials(source).Where((EventMaterialReference x) => x != null).ToList();
		if (list.Count == 0)
		{
			return null;
		}
		EventMaterialReference eventMaterialReference = CloneEventMaterialReference(list[0]);
		string text = ResolveWeeklyPromptVillageRaidKey(eventMaterialReference);
		string text2 = ResolveSettlementDisplay(eventMaterialReference.SettlementId);
		if (string.IsNullOrWhiteSpace(text2))
		{
			text2 = string.IsNullOrWhiteSpace(text) ? "某村庄" : text;
		}
		List<EventMaterialReference> list2 = list.Where(IsWeeklyPromptVillageRaidCompletionMaterial).ToList();
		List<string> list3 = new List<string>();
		foreach (EventMaterialReference item in list2)
		{
			list3.Add(text2 + "：" + GetWeeklyPromptVillageRaidOutcomeMaterialText(ResolveWeeklyPromptVillageRaidOutcome(item)));
		}
		bool flag = IsWeeklyPromptVillageRaidStartedMaterial(list[list.Count - 1]);
		if (list2.Count == 0)
		{
			list3.Add(text2 + "：正在遭到掠夺，截止本期没有结算结果，不能写为掠夺成功。");
		}
		else if (flag)
		{
			list3.Add(text2 + "：随后又遭到掠夺，截止本期没有结算结果，不能写为掠夺成功。");
		}
		eventMaterialReference.MaterialType = "prompt_resolved_village_raid";
		eventMaterialReference.Label = "村庄掠夺结算 - " + text2;
		eventMaterialReference.SnapshotText = "[村庄掠夺结算]\n- " + string.Join("\n- ", list3);
		eventMaterialReference.ActionKind = "prompt_resolved:village_raid";
		eventMaterialReference.ActionStableKey = "prompt_resolved_village_raid:" + text;
		eventMaterialReference.SourceMaterialCount = list.Count;
		eventMaterialReference.ActionDay = list.Min((EventMaterialReference x) => x?.ActionDay ?? int.MaxValue);
		eventMaterialReference.ActionSequence = list.Min((EventMaterialReference x) => x?.ActionSequence ?? int.MaxValue);
		foreach (EventMaterialReference item2 in list.Skip(1))
		{
			AppendMaterialReferenceIds(item2, eventMaterialReference);
		}
		return eventMaterialReference;
	}

	private static bool IsWeeklyPromptVillageRaidStartedMaterial(EventMaterialReference material)
	{
		string text = (material?.ActionStableKey ?? "").Trim();
		return text.StartsWith("village_raid_started:", StringComparison.OrdinalIgnoreCase) || (material?.Label ?? "").Trim().StartsWith("掠夺开始", StringComparison.OrdinalIgnoreCase);
	}

	private static bool IsWeeklyPromptVillageRaidCompletionMaterial(EventMaterialReference material)
	{
		string text = (material?.ActionStableKey ?? "").Trim();
		return text.StartsWith("raid_completed:", StringComparison.OrdinalIgnoreCase) || (material?.Label ?? "").Trim().StartsWith("掠夺结果", StringComparison.OrdinalIgnoreCase);
	}

	private static string GetWeeklyPromptVillageRaidOutcomeMaterialText(string outcome)
	{
		switch ((outcome ?? "").Trim())
		{
		case "success":
			return "掠夺成功，村庄确已被成功掠夺。";
		case "defended":
			return "掠夺被击退，入侵者未能成功掠夺村庄。";
		case "aborted":
			return "掠夺中止，入侵者未能成功掠夺村庄。";
		default:
			return "掠夺已结束但结果未确认，不能写为掠夺成功。";
		}
	}

	private static List<EventMaterialReference> BuildWeeklyPromptMaterialsShort(WeeklyEventMaterialPreviewGroup group)
	{
		List<EventMaterialReference> list = new List<EventMaterialReference>();
		List<EventMaterialReference> list2 = OrderWeeklyPreviewMaterials(group?.Materials).Where((EventMaterialReference x) => x != null).ToList();
		List<EventMaterialReference> settlementStatsMaterials = list2.Where(IsWeeklyPromptSettlementStatsMaterial).ToList();
		List<EventMaterialReference> villageRaidMaterials = list2.Where(IsWeeklyPromptVillageRaidMaterial).ToList();
		bool flag = false;
		bool flag2 = false;
		foreach (EventMaterialReference item in list2)
		{
			if (IsWeeklyPromptTournamentMaterial(item))
			{
				continue;
			}
			if (IsWeeklyPromptOpeningSummaryMaterial(item))
			{
				continue;
			}
			if (IsWeeklyPromptSettlementStatsMaterial(item))
			{
				if (!flag)
				{
					EventMaterialReference eventMaterialReference2 = BuildWeeklyPromptShortSettlementStatsMaterial(settlementStatsMaterials, group);
					if (eventMaterialReference2 != null)
					{
						list.Add(eventMaterialReference2);
					}
					flag = true;
				}
				continue;
			}
			if (IsWeeklyPromptVillageRaidMaterial(item))
			{
				if (!flag2)
				{
					EventMaterialReference eventMaterialReference3 = BuildWeeklyPromptShortVillageRaidMaterial(villageRaidMaterials, group);
					if (eventMaterialReference3 != null)
					{
						list.Add(eventMaterialReference3);
					}
					flag2 = true;
				}
				continue;
			}
			EventMaterialReference eventMaterialReference = BuildWeeklyPromptShortMaterial(item, group);
			if (eventMaterialReference != null)
			{
				list.Add(eventMaterialReference);
			}
		}
		return OrderWeeklyPreviewMaterials(list).ToList();
	}

	private static bool IsWeeklyPromptTournamentMaterial(EventMaterialReference material)
	{
		if (material == null)
		{
			return false;
		}
		string text = (material.MaterialType ?? "").Trim();
		string text2 = (material.ActionStableKey ?? "").Trim();
		string text3 = (material.Label ?? "").Trim();
		return string.Equals(text, "raw_text", StringComparison.OrdinalIgnoreCase) && (text2.StartsWith("tournament_finished:", StringComparison.OrdinalIgnoreCase) || text3.StartsWith("竞技大会结算", StringComparison.OrdinalIgnoreCase));
	}

