		string text2 = ResolveHeroDisplay(!string.IsNullOrWhiteSpace(item?.ActorHeroId) ? item.ActorHeroId : (!string.IsNullOrWhiteSpace(item?.HeroId) ? item.HeroId : item?.TargetHeroId));
		return (text2 ?? "").Trim();
