	private string BuildWeeklyReportFullOnDemandUserPrompt(WeeklyEventMaterialPreviewGroup group, int weekIndex)
	{
		WeeklyReportPromptProfile weeklyReportPromptProfile = GetWeeklyReportPromptProfile();
