	private string GetPreviousWeeklyReportText(WeeklyEventMaterialPreviewGroup group, int currentWeekIndex)
	{
		string text = (group?.GroupKind ?? "").Trim();
		string text2 = (group?.KingdomId ?? "").Trim();
		EventRecordEntry eventRecordEntry = SanitizeEventRecordEntries(_eventRecordEntries).FirstOrDefault((EventRecordEntry x) => x != null && x.WeekIndex == currentWeekIndex - 1 && string.Equals((x.EventKind ?? "").Trim(), text, StringComparison.OrdinalIgnoreCase) && string.Equals((x.ScopeKingdomId ?? "").Trim(), text2, StringComparison.OrdinalIgnoreCase));
		if (eventRecordEntry == null)
		{
			return "无";
		}
		string text3 = BuildFallbackWeeklyReportShortSummary(eventRecordEntry.ShortSummary);
		if (string.IsNullOrWhiteSpace(text3))
		{
			text3 = BuildFallbackWeeklyReportShortSummary(eventRecordEntry.Summary);
		}
		if (string.IsNullOrWhiteSpace(text3))
		{
			return "无";
		}
		return NeutralizeWeeklyReportScenarioName(BuildWeeklyEpicWeekLabel(eventRecordEntry.WeekIndex) + "短摘要：" + text3);
	}

	private static string BuildWeeklyReportMaterialLines(WeeklyEventMaterialPreviewGroup group)
	{
		return AnnotateWeeklyReportRulerInMaterialText(BuildWeeklyReportMaterialLines(group?.Materials), group);
	}

	private static string BuildWeeklyReportMaterialLines(List<EventMaterialReference> materials)
	{
		List<EventMaterialReference> list = OrderWeeklyPreviewMaterials(materials).ToList();
		if (list.Count == 0)
		{
			return "无可用素材。";
		}
		StringBuilder stringBuilder = new StringBuilder();
		foreach (EventMaterialReference item in list)
		{
			if (item == null)
			{
				continue;
			}
			string weeklyReportMaterialLine = BuildWeeklyReportMaterialLine(item);
			if (!string.IsNullOrWhiteSpace(weeklyReportMaterialLine))
			{
				stringBuilder.AppendLine("- " + weeklyReportMaterialLine.Trim());
			}
		}
		string text = stringBuilder.ToString().TrimEnd();
		return string.IsNullOrWhiteSpace(text) ? "无可用素材。" : text;
	}

	private static string BuildWeeklyReportMaterialLine(EventMaterialReference material)
	{
		if (material == null)
		{
			return "";
		}
		string text = (material.MaterialType ?? "").Trim().ToLowerInvariant();
		if (text == "world_opening_summary")
		{
			return PlayerNotorietyBehavior.RenderPlayerNamedReferenceForExternal("世界开局概要：" + NeutralizeWeeklyReportScenarioName(material.SnapshotText));
		}
		if (text == "kingdom_opening_summary")
		{
			return PlayerNotorietyBehavior.RenderPlayerNamedReferenceForExternal(ResolveKingdomDisplay(material.KingdomId) + "的开局概要：" + NeutralizeWeeklyReportScenarioName(material.SnapshotText));
		}
		string text2 = PlayerNotorietyBehavior.RenderPlayerNamedReferenceForExternal(NeutralizeWeeklyReportScenarioName(material.SnapshotText));
		if (!string.IsNullOrWhiteSpace(text2))
		{
			return text2;
		}
		return PlayerNotorietyBehavior.RenderPlayerNamedReferenceForExternal(NeutralizeWeeklyReportScenarioName(material.Label));
	}

