	private async Task<WeeklyReportGenerationResult> GenerateWeeklyReportsMinuteBurstAsyncInternal(List<WeeklyEventMaterialPreviewGroup> list, int weekIndex, int startDay, int endDay, string displayLabel, bool openViewerWhenDone, bool queueBlockingPopupOnFatalFailure, bool isAutoGeneration, IEnumerable<string> popupCandidateKingdomIdsOverride = null, List<WeeklyReportBatchRequest> preparedBatches = null, long runtimeGeneration = 0L)
	{
		WeeklyReportGenerationResult generationResult = new WeeklyReportGenerationResult();
		if (runtimeGeneration <= 0L)
		{
			runtimeGeneration = SaveRuntimeGuard.CaptureGeneration();
		}
		if (SaveRuntimeGuard.IsStale(runtimeGeneration, "weekly_report_before_prepare"))
		{
			return generationResult;
		}
		list = (list ?? new List<WeeklyEventMaterialPreviewGroup>()).Where((WeeklyEventMaterialPreviewGroup x) => x != null && IsWeeklyReportGroupEligible(x)).ToList();
		if (list.Count == 0)
		{
			InformationManager.DisplayMessage(new InformationMessage("当前没有可生成周报的分组。"));
			if (openViewerWhenDone)
			{
				OpenDevEventEditorMenu();
			}
			generationResult.Completed = true;
			return generationResult;
		}
		List<string> failureMessages = new List<string>();
		List<string> list2 = (popupCandidateKingdomIdsOverride ?? Enumerable.Empty<string>()).Where((string x) => !string.IsNullOrWhiteSpace(x)).Select((string x) => x.Trim()).Distinct(StringComparer.OrdinalIgnoreCase).ToList();
		if (list2.Count == 0)
		{
			list2 = list.Where((WeeklyEventMaterialPreviewGroup x) => x != null && string.Equals((x.GroupKind ?? "").Trim(), "kingdom", StringComparison.OrdinalIgnoreCase) && x.OutputMode != WeeklyReportOutputMode.TitleShortTagsOnly).Select((WeeklyEventMaterialPreviewGroup x) => (x.KingdomId ?? "").Trim()).Where((string x) => !string.IsNullOrWhiteSpace(x)).Distinct(StringComparer.OrdinalIgnoreCase).ToList();
		}
		Dictionary<string, WeeklyEventMaterialPreviewGroup> groupMap = BuildWeeklyReportGroupMap(list);
		List<WeeklyReportBatchRequest> batches = (preparedBatches ?? new List<WeeklyReportBatchRequest>()).Where((WeeklyReportBatchRequest x) => x != null && x.Groups != null && x.Groups.Count > 0).ToList();
		if (batches.Count == 0)
		{
			batches = BuildWeeklyReportBatchRequests(list, weekIndex, startDay, endDay);
		}
		int burstSize = Math.Max(1, GetWeeklyReportRequestsPerMinute());
		int totalWaves = Math.Max(1, (int)Math.Ceiling((double)batches.Count / (double)burstSize));
		List<Task<WeeklyReportBatchExecutionResult>> runningTasks = new List<Task<WeeklyReportBatchExecutionResult>>();
		InformationManager.DisplayMessage(new InformationMessage("开始生成" + displayLabel + "，共 " + list.Count + " 条周报目标，" + batches.Count + " 个批次；将按分钟整批发送，每分钟同时发送 " + burstSize + " 个请求。"));
		for (int i = 0; i < batches.Count; i += burstSize)
		{
			if (SaveRuntimeGuard.IsStale(runtimeGeneration, "weekly_report_before_wave"))
			{
				return generationResult;
			}
			List<WeeklyReportBatchRequest> wave = batches.Skip(i).Take(burstSize).Where((WeeklyReportBatchRequest x) => x != null && x.Groups != null && x.Groups.Count > 0).ToList();
			if (wave.Count == 0)
			{
				continue;
			}
			int waveIndex = i / burstSize + 1;
			string waveLabel = string.Join(" | ", wave.Select(BuildWeeklyReportBatchDisplayLabel).Where((string x) => !string.IsNullOrWhiteSpace(x)));
			Logger.Log("EventWeeklyReport", "[BATCH-WAVE] " + displayLabel + " wave " + waveIndex + "/" + totalWaves + " launch count=" + wave.Count + " :: " + waveLabel);
			InformationManager.DisplayMessage(new InformationMessage("周报批次 " + waveIndex + "/" + totalWaves + " 已发出，共 " + wave.Count + " 个请求。"));
			for (int j = 0; j < wave.Count; j++)
			{
				runningTasks.Add(ExecuteWeeklyReportBatchAsync(wave[j], i + j, 3));
			}
			if (i + burstSize < batches.Count)
			{
				await Task.Delay(60000);
				if (SaveRuntimeGuard.IsStale(runtimeGeneration, "weekly_report_after_wave_delay"))
				{
					return generationResult;
				}
			}
		}
		WeeklyReportBatchExecutionResult[] completed = await Task.WhenAll(runningTasks);
		if (SaveRuntimeGuard.IsStale(runtimeGeneration, "weekly_report_before_commit_enqueue"))
		{
			return generationResult;
		}
		return await EnqueueWeeklyReportCommitAsync(list, weekIndex, startDay, endDay, displayLabel, openViewerWhenDone, queueBlockingPopupOnFatalFailure, isAutoGeneration, list2, groupMap, completed, runtimeGeneration);
#if false
		int successCount = 0;
		int failureCount = 0;
		List<WeeklyEventMaterialPreviewGroup> failedGroups = new List<WeeklyEventMaterialPreviewGroup>();
		foreach (WeeklyReportBatchExecutionResult execution in completed.OrderBy((WeeklyReportBatchExecutionResult x) => x.BatchIndex))
		{
			WeeklyReportBatchRequest batch = execution?.Batch;
			WeeklyReportBatchRequestResult batchResult = execution?.Result ?? new WeeklyReportBatchRequestResult
			{
				Success = false,
				FailureReason = "Batch execution returned no result.",
				Blocks = new List<WeeklyReportBatchBlockResult>(),
				MissingReportIds = new List<string>()
			};
			CaptureWeeklyReportBatchDevPreview(batch, batchResult);
			HashSet<string> parsedReportIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
			foreach (WeeklyReportBatchBlockResult block in batchResult.Blocks ?? new List<WeeklyReportBatchBlockResult>())
			{
				if (block == null || !block.Parsed || string.IsNullOrWhiteSpace(block.ReportId) || !parsedReportIds.Add(block.ReportId))
				{
					continue;
				}
				if (!groupMap.TryGetValue(block.ReportId, out var group) || group == null)
				{
					continue;
				}
				UpsertWeeklyReportEventRecord(group, weekIndex, block.Title, block.ShortSummary, block.Report, block.TagText, batchResult.PromptPreview);
				TryNotifyNearestKingdomWeeklyReportGenerated(group, weekIndex, list2, block.Title, block.Report, ref nearestKingdomWeeklyReportNotified);
				successCount++;
			}
			List<WeeklyEventMaterialPreviewGroup> missingGroups = new List<WeeklyEventMaterialPreviewGroup>();
			foreach (string reportId in batchResult.MissingReportIds ?? new List<string>())
			{
				if (!parsedReportIds.Contains(reportId) && groupMap.TryGetValue(reportId, out var missingGroup) && missingGroup != null)
				{
					missingGroups.Add(missingGroup);
				}
			}
			if (!batchResult.Success && missingGroups.Count == 0)
			{
				foreach (WeeklyEventMaterialPreviewGroup group2 in batch?.Groups ?? new List<WeeklyEventMaterialPreviewGroup>())
				{
					string reportId2 = BuildWeeklyReportGroupReportId(group2);
					if (!string.IsNullOrWhiteSpace(reportId2) && !parsedReportIds.Contains(reportId2))
					{
						missingGroups.Add(group2);
					}
				}
			}
			if (missingGroups.Count > 0)
			{
				failureCount += missingGroups.Count;
				failedGroups.AddRange(missingGroups.Where((WeeklyEventMaterialPreviewGroup x) => x != null));
				failureMessages.Add(BuildWeeklyReportBatchDisplayLabel(batch) + "：批量请求失败，未回退到单个王国请求 - " + (batchResult.FailureReason ?? "未知错误"));
			}
		}
		failedGroups = failedGroups.Where((WeeklyEventMaterialPreviewGroup x) => x != null).Distinct().ToList();
		if (failureMessages.Count > 0)
		{
			Logger.Log("EventWeeklyReport", string.Join("\n", failureMessages));
		}
		if (failedGroups.Count > 0)
		{
			WeeklyEventMaterialPreviewGroup firstFailedGroup = failedGroups.FirstOrDefault();
			WeeklyReportRequestResult failedRequest = new WeeklyReportRequestResult
			{
				Success = false,
				FailureReason = failureMessages.FirstOrDefault() ?? "批量请求失败。",
				AttemptsUsed = 3
			};
			generationResult.SuccessCount = successCount;
			generationResult.FailureCount = failureCount;
			generationResult.BlockedByFatalFailure = true;
			generationResult.RetryContext = CreateWeeklyReportRetryContext(failedGroups, weekIndex, startDay, endDay, displayLabel, openViewerWhenDone, isAutoGeneration, firstFailedGroup, failedRequest, list2);
			InformationManager.DisplayMessage(new InformationMessage(displayLabel + " 生成中止：有 " + failureCount + " 条周报目标批量失败，未回退到单个王国请求。"));
			if (queueBlockingPopupOnFatalFailure)
			{
				QueueWeeklyReportFailurePopup(generationResult.RetryContext, showImmediate: true);
			}
			return generationResult;
		}
		InformationManager.DisplayMessage(new InformationMessage(displayLabel + " 生成完成：成功 " + successCount + " 条，失败 " + failureCount + " 条。"));
		if (openViewerWhenDone)
		{
			OpenDevEventViewerMenu(0);
		}
		generationResult.SuccessCount = successCount;
		generationResult.FailureCount = failureCount;
		generationResult.Completed = true;
		return generationResult;
#endif
	}

	private Task<WeeklyReportGenerationResult> EnqueueWeeklyReportCommitAsync(List<WeeklyEventMaterialPreviewGroup> groups, int weekIndex, int startDay, int endDay, string displayLabel, bool openViewerWhenDone, bool queueBlockingPopupOnFatalFailure, bool isAutoGeneration, List<string> popupCandidateKingdomIds, Dictionary<string, WeeklyEventMaterialPreviewGroup> groupMap, IEnumerable<WeeklyReportBatchExecutionResult> executions, long runtimeGeneration)
	{
		TaskCompletionSource<WeeklyReportGenerationResult> completionSource = new TaskCompletionSource<WeeklyReportGenerationResult>();
		PendingWeeklyReportCommitContext context = new PendingWeeklyReportCommitContext
		{
			RuntimeGeneration = runtimeGeneration,
			WeekIndex = weekIndex,
			StartDay = startDay,
			EndDay = endDay,
			DisplayLabel = (displayLabel ?? "").Trim(),
			OpenViewerWhenDone = openViewerWhenDone,
			QueueBlockingPopupOnFatalFailure = queueBlockingPopupOnFatalFailure,
			IsAutoGeneration = isAutoGeneration,
			PopupCandidateKingdomIds = (popupCandidateKingdomIds ?? new List<string>()).Where((string x) => !string.IsNullOrWhiteSpace(x)).Select((string x) => x.Trim()).Distinct(StringComparer.OrdinalIgnoreCase).ToList(),
			Groups = (groups ?? new List<WeeklyEventMaterialPreviewGroup>()).Where((WeeklyEventMaterialPreviewGroup x) => x != null).ToList(),
			GroupMap = groupMap ?? BuildWeeklyReportGroupMap(groups),
			Executions = (executions ?? Enumerable.Empty<WeeklyReportBatchExecutionResult>()).Where((WeeklyReportBatchExecutionResult x) => x != null).OrderBy((WeeklyReportBatchExecutionResult x) => x.BatchIndex).ToList(),
			CompletionSource = completionSource
		};
		lock (_pendingWeeklyReportCommitLock)
		{
			_pendingWeeklyReportCommits.Enqueue(context);
			Volatile.Write(ref _hasPendingWeeklyReportCommits, 1);
		}
		return completionSource.Task;
	}

	private bool ProcessPendingWeeklyReportCommits()
	{
		if (Volatile.Read(ref _hasPendingWeeklyReportCommits) == 0)
		{
			return false;
		}
		bool hadWork = false;
		double budgetMs = GetDailyMaintenanceFrameBudgetMs();
		long startTimestamp = Stopwatch.GetTimestamp();
		while (!IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
		{
			PendingWeeklyReportCommitContext context = null;
			lock (_pendingWeeklyReportCommitLock)
			{
				if (_pendingWeeklyReportCommits.Count > 0)
				{
					context = _pendingWeeklyReportCommits.Peek();
				}
				else
				{
					Volatile.Write(ref _hasPendingWeeklyReportCommits, 0);
				}
			}
			if (context == null)
			{
				return hadWork;
			}
			hadWork = true;
			if (!ProcessPendingWeeklyReportCommitContext(context, startTimestamp, budgetMs))
			{
				return true;
			}
			lock (_pendingWeeklyReportCommitLock)
			{
				if (_pendingWeeklyReportCommits.Count > 0 && ReferenceEquals(_pendingWeeklyReportCommits.Peek(), context))
				{
					_pendingWeeklyReportCommits.Dequeue();
				}
				if (_pendingWeeklyReportCommits.Count == 0)
				{
					Volatile.Write(ref _hasPendingWeeklyReportCommits, 0);
				}
			}
		}
		return hadWork;
	}

	private bool ProcessPendingWeeklyReportCommitContext(PendingWeeklyReportCommitContext context, long startTimestamp, double budgetMs)
	{
		if (context == null)
		{
			return true;
		}
		try
		{
			if (context.RuntimeGeneration > 0L && SaveRuntimeGuard.IsStale(context.RuntimeGeneration, "weekly_report_commit"))
			{
				CompletePendingWeeklyReportCommit(context, new WeeklyReportGenerationResult());
				return true;
			}
			if (context.GroupMap == null)
			{
				using (PerfProbe.Scope("MyBehavior.WeeklyReportCommit.BuildGroupMap"))
				{
					context.GroupMap = BuildWeeklyReportGroupMap(context.Groups);
				}
			}
			List<WeeklyReportBatchExecutionResult> executions = context.Executions ?? new List<WeeklyReportBatchExecutionResult>();
			while (context.ExecutionIndex < executions.Count && !IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
			{
				WeeklyReportBatchExecutionResult execution = executions[context.ExecutionIndex];
				WeeklyReportBatchRequest batch = execution?.Batch;
				WeeklyReportBatchRequestResult batchResult = execution?.Result ?? new WeeklyReportBatchRequestResult
				{
					Success = false,
					FailureReason = "Batch execution returned no result.",
					Blocks = new List<WeeklyReportBatchBlockResult>(),
					MissingReportIds = new List<string>()
				};
				if (!context.CurrentPreviewCaptured)
				{
					using (PerfProbe.Scope("MyBehavior.WeeklyReportCommit.CapturePreview"))
					{
						CaptureWeeklyReportBatchDevPreview(batch, batchResult);
					}
					context.CurrentPreviewCaptured = true;
					if (IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
					{
						return false;
					}
				}
				if (context.CurrentParsedReportIds == null)
				{
					context.CurrentParsedReportIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
				}
				List<WeeklyReportBatchBlockResult> blocks = batchResult.Blocks ?? new List<WeeklyReportBatchBlockResult>();
				while (context.BlockIndex < blocks.Count && !IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
				{
					WeeklyReportBatchBlockResult block = blocks[context.BlockIndex];
					if (block != null && block.Parsed && !string.IsNullOrWhiteSpace(block.ReportId) && !context.CurrentParsedReportIds.Contains(block.ReportId) && context.GroupMap.TryGetValue(block.ReportId, out var group) && group != null)
					{
						if (context.CurrentBlockCommit == null)
						{
							using (PerfProbe.Scope("MyBehavior.WeeklyReportCommit.PrepareRecordMaterials"))
							{
								context.CurrentBlockCommit = CreatePendingWeeklyReportBlockCommit(group, block, batchResult.PromptPreview);
							}
						}
						if (!ProcessPendingWeeklyReportBlockCommit(context, startTimestamp, budgetMs))
						{
							return false;
						}
						context.CurrentParsedReportIds.Add(block.ReportId);
						TryQueueWeeklyReportMapNoticeForGeneratedReport(group, context.WeekIndex, ResolveWeeklyReportNoticeNearestKingdomId(context), context.WeeklyReportNoticeEventIdsQueued);
						context.SuccessCount++;
					}
					context.BlockIndex++;
					if (IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
					{
						return false;
					}
				}
				if (IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
				{
					return false;
				}
				using (PerfProbe.Scope("MyBehavior.WeeklyReportCommit.FinalizeBatch"))
				{
					FinalizePendingWeeklyReportCommitBatch(context, batch, batchResult);
				}
				context.ExecutionIndex++;
				context.BlockIndex = 0;
				context.CurrentPreviewCaptured = false;
				context.CurrentParsedReportIds = null;
				context.CurrentBlockCommit = null;
			}
			if (context.ExecutionIndex < executions.Count)
			{
				return false;
			}
			using (PerfProbe.Scope("MyBehavior.WeeklyReportCommit.FinalizeContext"))
			{
				FinalizePendingWeeklyReportCommitContext(context);
			}
			return true;
		}
		catch (Exception ex)
		{
			Logger.Log("EventWeeklyReport", "[ERROR] deferred weekly report commit failed: " + ex);
			CompletePendingWeeklyReportCommit(context, new WeeklyReportGenerationResult
			{
				FailureCount = Math.Max(1, context.FailureCount),
				BlockedByFatalFailure = true
			});
			return true;
		}
	}

	private static PendingWeeklyReportBlockCommit CreatePendingWeeklyReportBlockCommit(WeeklyEventMaterialPreviewGroup group, WeeklyReportBatchBlockResult block, string promptText)
	{
		return new PendingWeeklyReportBlockCommit
		{
			Group = group,
			ReportId = (block?.ReportId ?? "").Trim(),
			Title = block?.Title ?? "",
			ShortSummary = block?.ShortSummary ?? "",
			Report = block?.Report ?? "",
			TagText = block?.TagText ?? "",
			PromptText = promptText ?? "",
			OrderedMaterials = OrderWeeklyPreviewMaterials(group?.Materials).Where((EventMaterialReference x) => x != null).ToList(),
			ClonedMaterials = new List<EventMaterialReference>()
		};
	}

	private bool ProcessPendingWeeklyReportBlockCommit(PendingWeeklyReportCommitContext context, long startTimestamp, double budgetMs)
	{
		PendingWeeklyReportBlockCommit pending = context?.CurrentBlockCommit;
		if (pending == null)
		{
			return true;
		}
		while (pending.MaterialIndex < pending.OrderedMaterials.Count && !IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
		{
			using (PerfProbe.Scope("MyBehavior.WeeklyReportCommit.CloneMaterial"))
			{
				EventMaterialReference material = CloneEventMaterialReference(pending.OrderedMaterials[pending.MaterialIndex]);
				if (material != null)
				{
					pending.ClonedMaterials.Add(material);
				}
				pending.MaterialIndex++;
			}
		}
		if (pending.MaterialIndex < pending.OrderedMaterials.Count)
		{
			return false;
		}
		if (IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
		{
			return false;
		}
		using (PerfProbe.Scope("MyBehavior.WeeklyReportCommit.WriteRecord"))
		{
			UpsertWeeklyReportEventRecord(pending.Group, context.WeekIndex, pending.Title, pending.ShortSummary, pending.Report, pending.TagText, pending.PromptText, pending.ClonedMaterials, sanitizeAfter: false);
		}
		context.CurrentBlockCommit = null;
		return true;
	}

	private void FinalizePendingWeeklyReportCommitBatch(PendingWeeklyReportCommitContext context, WeeklyReportBatchRequest batch, WeeklyReportBatchRequestResult batchResult)
	{
		if (context == null)
		{
			return;
		}
		HashSet<string> parsedReportIds = context.CurrentParsedReportIds ?? new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		Dictionary<string, WeeklyEventMaterialPreviewGroup> groupMap = context.GroupMap ?? BuildWeeklyReportGroupMap(context.Groups);
		List<WeeklyEventMaterialPreviewGroup> missingGroups = new List<WeeklyEventMaterialPreviewGroup>();
		foreach (string reportId in batchResult?.MissingReportIds ?? new List<string>())
		{
			if (!string.IsNullOrWhiteSpace(reportId) && !parsedReportIds.Contains(reportId) && groupMap.TryGetValue(reportId, out var missingGroup) && missingGroup != null)
			{
				missingGroups.Add(missingGroup);
			}
		}
		if (batchResult != null && !batchResult.Success && missingGroups.Count == 0)
		{
			foreach (WeeklyEventMaterialPreviewGroup group in batch?.Groups ?? new List<WeeklyEventMaterialPreviewGroup>())
			{
				string reportId = BuildWeeklyReportGroupReportId(group);
				if (!string.IsNullOrWhiteSpace(reportId) && !parsedReportIds.Contains(reportId))
				{
					missingGroups.Add(group);
				}
			}
		}
		if (missingGroups.Count <= 0)
		{
			return;
		}
		context.FailureCount += missingGroups.Count;
		context.FailedGroups.AddRange(missingGroups.Where((WeeklyEventMaterialPreviewGroup x) => x != null));
		context.FailureMessages.Add(BuildWeeklyReportBatchDisplayLabel(batch) + "：批量请求未恢复出可用周报区块 - " + (batchResult?.FailureReason ?? "未知错误"));
	}

	private void FinalizePendingWeeklyReportCommitContext(PendingWeeklyReportCommitContext context)
	{
		if (context == null)
		{
			return;
		}
		List<WeeklyEventMaterialPreviewGroup> failedGroups = (context.FailedGroups ?? new List<WeeklyEventMaterialPreviewGroup>()).Where((WeeklyEventMaterialPreviewGroup x) => x != null).Distinct().ToList();
		if (context.FailureMessages != null && context.FailureMessages.Count > 0)
		{
			Logger.Log("EventWeeklyReport", string.Join("\n", context.FailureMessages));
		}
		WeeklyReportGenerationResult result = new WeeklyReportGenerationResult
		{
			SuccessCount = context.SuccessCount,
			FailureCount = context.FailureCount
		};
		if (failedGroups.Count > 0)
		{
			WeeklyEventMaterialPreviewGroup firstFailedGroup = failedGroups.FirstOrDefault();
			WeeklyReportRequestResult failedRequest = new WeeklyReportRequestResult
			{
				Success = false,
				FailureReason = context.FailureMessages?.FirstOrDefault() ?? "Batch request failed.",
				AttemptsUsed = 3
			};
			result.BlockedByFatalFailure = true;
			result.RetryContext = CreateWeeklyReportRetryContext(failedGroups, context.WeekIndex, context.StartDay, context.EndDay, context.DisplayLabel, context.OpenViewerWhenDone, context.IsAutoGeneration, firstFailedGroup, failedRequest, context.PopupCandidateKingdomIds);
			InformationManager.DisplayMessage(new InformationMessage(context.DisplayLabel + " generation paused: " + context.FailureCount + " weekly report target(s) failed."));
			if (context.QueueBlockingPopupOnFatalFailure)
			{
				QueueWeeklyReportFailurePopup(result.RetryContext, showImmediate: true);
			}
			CompletePendingWeeklyReportCommit(context, result);
			return;
		}
		InformationManager.DisplayMessage(new InformationMessage(context.DisplayLabel + " generation completed: success " + context.SuccessCount + ", failed " + context.FailureCount + "."));
		if (context.OpenViewerWhenDone)
		{
			OpenDevEventViewerMenu(0);
		}
		result.Completed = true;
		CompletePendingWeeklyReportCommit(context, result);
	}

	private static void CompletePendingWeeklyReportCommit(PendingWeeklyReportCommitContext context, WeeklyReportGenerationResult result)
	{
		try
		{
			context?.CompletionSource?.TrySetResult(result ?? new WeeklyReportGenerationResult());
		}
		catch
		{
		}
	}

	private static string ResolveNearestWeeklyReportKingdomId(IEnumerable<string> kingdomIds)
	{
		List<string> list = (kingdomIds ?? Enumerable.Empty<string>()).Where((string x) => !string.IsNullOrWhiteSpace(x)).Select((string x) => x.Trim()).Distinct(StringComparer.OrdinalIgnoreCase).ToList();
		if (list.Count == 0)
		{
			return "";
		}
		List<string> kingdomIdsByPlayerProximity = GetKingdomIdsByPlayerProximity(list);
		string text = kingdomIdsByPlayerProximity.FirstOrDefault((string x) => !string.IsNullOrWhiteSpace(x));
		if (!string.IsNullOrWhiteSpace(text))
		{
			return text.Trim();
		}
		return (list[0] ?? "").Trim();
	}

	private static string ResolveWeeklyReportNoticeNearestKingdomId(PendingWeeklyReportCommitContext context)
	{
		if (context == null)
		{
			return "";
		}
		if (!context.WeeklyReportNoticeNearestKingdomResolved)
		{
			context.WeeklyReportNoticeNearestKingdomId = ResolveNearestWeeklyReportKingdomId(context.PopupCandidateKingdomIds);
			context.WeeklyReportNoticeNearestKingdomResolved = true;
		}
		return context.WeeklyReportNoticeNearestKingdomId ?? "";
	}

	private static bool CanPublishWeeklyReportMapNotification()
	{
		try
		{
			return Mission.Current == null && Game.Current?.GameStateManager?.ActiveState is MapState && MapScreen.Instance?.MapNotificationView != null;
		}
		catch
		{
			return false;
		}
	}

	private bool TryEnsureWeeklyReportMapNotificationRegistered()
	{
		try
		{
			MapNotificationView mapNotificationView = MapScreen.Instance?.MapNotificationView;
			if (mapNotificationView == null)
			{
				return false;
			}
			if (!ReferenceEquals(_weeklyReportRegisteredMapNotificationView, mapNotificationView))
			{
				_weeklyReportNoticeEventIdsShownThisSession.Clear();
				mapNotificationView.RegisterMapNotificationType(typeof(AnimusForgeWeeklyReportMapNotification), typeof(AnimusForgeWeeklyReportMapNotificationItemVM));
				_weeklyReportRegisteredMapNotificationView = mapNotificationView;
			}
			return true;
		}
		catch (Exception ex)
		{
			Logger.Log("EventWeeklyReport", "[WARN] register weekly report map notification failed: " + ex.Message);
			return false;
		}
	}

	private void TryPublishUnreadWeeklyReportMapNotifications()
	{
		if (_unreadWeeklyReportNoticeEventIds == null || _unreadWeeklyReportNoticeEventIds.Count == 0 || !IsWeeklyReportMapNotificationEnabled())
		{
			return;
		}
		NormalizeUnreadWeeklyReportNoticesForCurrentPolicy();
		if (_unreadWeeklyReportNoticeEventIds.Count == 0 || !CanPublishWeeklyReportMapNotification() || !TryEnsureWeeklyReportMapNotificationRegistered())
		{
			return;
		}
		_unreadWeeklyReportNoticeEventIds = SanitizeUnreadWeeklyReportNoticeEventIds(_unreadWeeklyReportNoticeEventIds);
		foreach (string eventId in _unreadWeeklyReportNoticeEventIds.ToList())
		{
			if (_weeklyReportNoticeEventIdsShownThisSession.Contains(eventId))
			{
				continue;
			}
			EventRecordEntry eventRecordEntry = FindWeeklyReportRecordById(eventId);
			if (eventRecordEntry == null)
			{
				MarkWeeklyReportNoticeRead(eventId);
				continue;
			}
			MBInformationManager.AddNotice(new AnimusForgeWeeklyReportMapNotification(eventId, BuildWeeklyReportNoticeTitle(eventRecordEntry), BuildWeeklyReportNoticeDescription(eventRecordEntry)));
			_weeklyReportNoticeEventIdsShownThisSession.Add(eventId);
		}
	}

	private void QueueWeeklyReportMapNotice(string eventId)
	{
		if (!IsWeeklyReportMapNotificationEnabled())
		{
			return;
		}
		string text = (eventId ?? "").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return;
		}
		if (_unreadWeeklyReportNoticeEventIds == null)
		{
			_unreadWeeklyReportNoticeEventIds = new List<string>();
		}
		if (!_unreadWeeklyReportNoticeEventIds.Any((string x) => string.Equals((x ?? "").Trim(), text, StringComparison.OrdinalIgnoreCase)))
		{
			_unreadWeeklyReportNoticeEventIds.Add(text);
		}
	}

	private void NormalizeUnreadWeeklyReportNoticesForCurrentPolicy()
	{
		if (_weeklyReportNoticeQueueNormalizedForCurrentPolicy)
		{
			return;
		}
		try
		{
			List<string> unreadEventIds = SanitizeUnreadWeeklyReportNoticeEventIds(_unreadWeeklyReportNoticeEventIds);
			Dictionary<int, List<EventRecordEntry>> kingdomReportsByWeek = new Dictionary<int, List<EventRecordEntry>>();
			foreach (string eventId in unreadEventIds)
			{
				EventRecordEntry entry = FindWeeklyReportRecordById(eventId);
				if (entry == null || !string.Equals((entry.EventKind ?? "").Trim(), "kingdom", StringComparison.OrdinalIgnoreCase))
				{
					continue;
				}
				if (!kingdomReportsByWeek.TryGetValue(entry.WeekIndex, out List<EventRecordEntry> entries))
				{
					entries = new List<EventRecordEntry>();
					kingdomReportsByWeek[entry.WeekIndex] = entries;
				}
				entries.Add(entry);
			}
			HashSet<string> retainedEventIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
			foreach (List<EventRecordEntry> entries in kingdomReportsByWeek.Values)
			{
				string nearestKingdomId = ResolveNearestWeeklyReportKingdomId(entries.Select((EventRecordEntry x) => x?.ScopeKingdomId));
				EventRecordEntry nearestEntry = entries.FirstOrDefault((EventRecordEntry x) => string.Equals((x?.ScopeKingdomId ?? "").Trim(), nearestKingdomId, StringComparison.OrdinalIgnoreCase));
				if (nearestEntry != null)
				{
					retainedEventIds.Add(nearestEntry.EventId ?? "");
				}
			}
			_unreadWeeklyReportNoticeEventIds = unreadEventIds.Where((string x) => retainedEventIds.Contains(x)).ToList();
		}
		catch (Exception ex)
		{
			Logger.Log("EventWeeklyReport", "[WARN] normalize legacy weekly report notices failed: " + ex.Message);
		}
		finally
		{
			_weeklyReportNoticeQueueNormalizedForCurrentPolicy = true;
		}
	}

	private static bool IsWeeklyReportMapNotificationEnabled()
	{
		return DuelSettings.IsWeeklyReportMapNotificationEnabled();
	}

	private void OnMapNoticeRemoved(InformationData data)
	{
		if (!ReferenceEquals(Instance, this))
		{
			return;
		}
		if (data is AnimusForgeWeeklyReportMapNotification weeklyReportMapNotification)
		{
			MarkWeeklyReportNoticeRead(weeklyReportMapNotification.EventId);
		}
	}

	private void MarkWeeklyReportNoticeRead(string eventId)
	{
		string text = (eventId ?? "").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return;
		}
		_weeklyReportNoticeEventIdsShownThisSession.Remove(text);
		if (_unreadWeeklyReportNoticeEventIds == null || _unreadWeeklyReportNoticeEventIds.Count == 0)
		{
			return;
		}
		_unreadWeeklyReportNoticeEventIds = _unreadWeeklyReportNoticeEventIds.Where((string x) => !string.Equals((x ?? "").Trim(), text, StringComparison.OrdinalIgnoreCase)).ToList();
	}

	internal bool OpenWeeklyReportNoticeFromMap(string eventId)
	{
		string text = (eventId ?? "").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return false;
		}
		EventRecordEntry eventRecordEntry = FindWeeklyReportRecordById(text);
		if (eventRecordEntry == null)
		{
			InformationManager.DisplayMessage(new InformationMessage("这条周报记录已经不存在。"));
			MarkWeeklyReportNoticeRead(text);
			return true;
		}
		bool hasFullReport = !string.IsNullOrWhiteSpace(eventRecordEntry.Summary);
		string bodyText = BuildWeeklyReportPopupBodyText(eventRecordEntry);
		bool flag = DevWeeklyReportPopup.Show(BuildWeeklyReportNoticeTitle(eventRecordEntry), BuildWeeklyReportPopupSubtitle(eventRecordEntry), bodyText, null, "", useChronicleColumns: hasFullReport, useShortReportLayout: !hasFullReport, showCloseButton: false, minimumDwellSeconds: 10.0, onMinimumDwellMet: delegate
		{
			TryAwardWeeklyReportReadingXp(text);
		});
		if (flag)
		{
			MarkWeeklyReportNoticeRead(text);
		}
		else
		{
			InformationManager.DisplayMessage(new InformationMessage("打开周报失败。"));
		}
		return flag;
	}

	private void TryAwardWeeklyReportReadingXp(string eventId)
	{
		string text = (eventId ?? "").Trim();
		if (string.IsNullOrWhiteSpace(text) || !text.StartsWith("weekly_report:", StringComparison.OrdinalIgnoreCase))
		{
			return;
		}
		if (_weeklyReportReadingXpClaimedEventIds == null)
		{
			_weeklyReportReadingXpClaimedEventIds = new List<string>();
		}
		if (_weeklyReportReadingXpClaimedEventIds.Any((string x) => string.Equals((x ?? "").Trim(), text, StringComparison.OrdinalIgnoreCase)))
		{
			return;
		}
		DuelSettings settings = DuelSettings.GetSettings();
		if (settings == null || !settings.EnableWeeklyReportReadingXpReward)
		{
			return;
		}
		int xpPerHundred = Math.Max(0, Math.Min(100, settings.WeeklyReportReadingXpPerHundredChars));
		int skillCap = Math.Max(0, Math.Min(500, settings.WeeklyReportReadingXpSkillCap));
		if (xpPerHundred <= 0 || skillCap <= 0)
		{
			return;
		}
		Hero mainHero = Hero.MainHero;
		if (mainHero == null)
		{
			return;
		}
		if (!CanAwardWeeklyReportReadingXp(mainHero, out string ineligibleReason))
		{
			Logger.Log("EventWeeklyReport", "[ReadingXp] skipped eventId=" + text + " reason=" + ineligibleReason);
			return;
		}
		EventRecordEntry eventRecordEntry = FindWeeklyReportRecordById(text);
		if (eventRecordEntry == null)
		{
			return;
		}
		string bodyText = BuildWeeklyReportPopupBodyText(eventRecordEntry);
		WeeklyReportSectionSplit split = WeeklyReportTextHelper.SplitChronicleBody(bodyText);
		int leadershipXp;
		int charmXp;
		int stewardXp;
		if (split.HasExplicitSections)
		{
			leadershipXp = CalculateWeeklyReportReadingXp(WeeklyReportTextHelper.CountMeaningfulUnits(split.MilitaryEventsText), xpPerHundred, skillCap);
			charmXp = CalculateWeeklyReportReadingXp(WeeklyReportTextHelper.CountMeaningfulUnits(split.DiplomaticAffairsText), xpPerHundred, skillCap);
			stewardXp = CalculateWeeklyReportReadingXp(WeeklyReportTextHelper.CountMeaningfulUnits(split.DomesticRealmText), xpPerHundred, skillCap);
		}
		else
		{
			int sharedXp = CalculateWeeklyReportReadingXp(WeeklyReportTextHelper.CountMeaningfulUnits(split.NormalizedBodyText), xpPerHundred, skillCap);
			leadershipXp = sharedXp;
			charmXp = sharedXp;
			stewardXp = sharedXp;
		}
		if (leadershipXp <= 0 && charmXp <= 0 && stewardXp <= 0)
		{
			return;
		}
		_weeklyReportReadingXpClaimedEventIds.Add(text);
		NormalizeWeeklyReportReadingXpPendingBatch();
		_weeklyReportReadingXpPendingCount++;
		_weeklyReportReadingXpPendingCharm += charmXp;
		_weeklyReportReadingXpPendingLeadership += leadershipXp;
		_weeklyReportReadingXpPendingSteward += stewardXp;
		Logger.Log("EventWeeklyReport", "[ReadingXp] accumulated eventId=" + text + " pending_count=" + _weeklyReportReadingXpPendingCount + "/" + WeeklyReportReadingXpBatchSize + " charm+=" + charmXp + " leadership+=" + leadershipXp + " steward+=" + stewardXp + " pending_charm=" + _weeklyReportReadingXpPendingCharm + " pending_leadership=" + _weeklyReportReadingXpPendingLeadership + " pending_steward=" + _weeklyReportReadingXpPendingSteward + " per100=" + xpPerHundred + " cap=" + skillCap);
		if (_weeklyReportReadingXpPendingCount < WeeklyReportReadingXpBatchSize)
		{
			return;
		}
		int batchCount = _weeklyReportReadingXpPendingCount;
		int batchCharm = _weeklyReportReadingXpPendingCharm;
		int batchLeadership = _weeklyReportReadingXpPendingLeadership;
		int batchSteward = _weeklyReportReadingXpPendingSteward;
		if (!TryAwardWeeklyReportReadingXpBatch(mainHero, batchLeadership, batchCharm, batchSteward, out string awardFailureReason))
		{
			Logger.Log("EventWeeklyReport", "[ReadingXp][WARN] batch_award_failed count=" + batchCount + " charm=" + batchCharm + " leadership=" + batchLeadership + " steward=" + batchSteward + " reason=" + awardFailureReason);
			return;
		}
		_weeklyReportReadingXpPendingCount = 0;
		_weeklyReportReadingXpPendingCharm = 0;
		_weeklyReportReadingXpPendingLeadership = 0;
		_weeklyReportReadingXpPendingSteward = 0;
		InformationManager.DisplayMessage(new InformationMessage("周报研读突破：累计研读 " + batchCount + " 篇，魅力 +" + batchCharm + "，统御 +" + batchLeadership + "，管理 +" + batchSteward + "。"));
		Logger.Log("EventWeeklyReport", "[ReadingXp] batch_awarded count=" + batchCount + " charm=" + batchCharm + " leadership=" + batchLeadership + " steward=" + batchSteward);
	}

	private static bool CanAwardWeeklyReportReadingXp(Hero hero, out string reason)
	{
		reason = "";
		if (hero == null)
		{
			reason = "hero_null";
			return false;
		}
		if (hero.HeroDeveloper == null)
		{
			reason = "hero_developer_null";
			return false;
		}
		try
		{
			if (hero.IsChild)
			{
				reason = "main_hero_under_age age=" + Math.Round(hero.Age, 2);
				return false;
			}
		}
		catch (Exception ex)
		{
			reason = "age_check_failed " + ex.Message;
			return false;
		}
		return true;
	}

	private static bool TryAwardWeeklyReportReadingXpBatch(Hero hero, int leadershipXp, int charmXp, int stewardXp, out string failureReason)
	{
		failureReason = "";
		if (!CanAwardWeeklyReportReadingXp(hero, out failureReason))
		{
			return false;
		}
		try
		{
			if (leadershipXp > 0)
			{
				hero.AddSkillXp(DefaultSkills.Leadership, leadershipXp);
			}
			if (charmXp > 0)
			{
				hero.AddSkillXp(DefaultSkills.Charm, charmXp);
			}
			if (stewardXp > 0)
			{
				hero.AddSkillXp(DefaultSkills.Steward, stewardXp);
			}
			return true;
		}
		catch (Exception ex)
		{
			failureReason = ex.GetType().Name + ": " + ex.Message;
			return false;
		}
	}

	private void NormalizeWeeklyReportReadingXpPendingBatch()
	{
		_weeklyReportReadingXpPendingCount = Math.Max(0, _weeklyReportReadingXpPendingCount);
		_weeklyReportReadingXpPendingCharm = Math.Max(0, _weeklyReportReadingXpPendingCharm);
		_weeklyReportReadingXpPendingLeadership = Math.Max(0, _weeklyReportReadingXpPendingLeadership);
		_weeklyReportReadingXpPendingSteward = Math.Max(0, _weeklyReportReadingXpPendingSteward);
		if (_weeklyReportReadingXpPendingCount == 0)
		{
			_weeklyReportReadingXpPendingCharm = 0;
			_weeklyReportReadingXpPendingLeadership = 0;
			_weeklyReportReadingXpPendingSteward = 0;
		}
	}

	private static int CalculateWeeklyReportReadingXp(int meaningfulUnitCount, int xpPerHundred, int skillCap)
	{
		if (meaningfulUnitCount <= 0 || xpPerHundred <= 0 || skillCap <= 0)
		{
			return 0;
		}
		int xp = (int)Math.Round((double)meaningfulUnitCount * xpPerHundred / 100.0, MidpointRounding.AwayFromZero);
		return Math.Max(0, Math.Min(skillCap, xp));
	}

	private static string BuildWeeklyReportNoticeTitle(EventRecordEntry entry)
	{
		string text = (entry?.Title ?? "").Trim();
		if (!string.IsNullOrWhiteSpace(text))
		{
			return text;
		}
		return BuildWeeklyReportBrowserDefaultTitle(entry?.EventKind, entry?.ScopeKingdomId, entry?.WeekIndex ?? 0);
	}

	private static string BuildWeeklyReportPopupBodyText(EventRecordEntry entry)
	{
		if (entry == null)
		{
			return "当前周报正文为空。";
		}
		string text = (entry.Summary ?? "").Trim();
		if (!string.IsNullOrWhiteSpace(text))
		{
			return text;
		}
		text = (entry.ShortSummary ?? "").Trim();
		return string.IsNullOrWhiteSpace(text) ? "当前周报正文为空。" : text;
	}

	private static string BuildWeeklyReportPopupSubtitle(EventRecordEntry entry)
	{
		if (entry == null)
		{
			return "";
		}
		string text = string.Equals((entry.EventKind ?? "").Trim(), "world", StringComparison.OrdinalIgnoreCase) ? "世界周报" : ResolveKingdomDisplay(entry.ScopeKingdomId);
		if (string.IsNullOrWhiteSpace(text))
		{
			text = "王国周报";
		}
		return text + " · " + BuildWeeklyEpicWeekLabel(entry.WeekIndex);
	}

	private static string BuildWeeklyReportNoticeDescription(EventRecordEntry entry)
	{
		string text = BuildWeeklyReportPopupSubtitle(entry);
		return string.IsNullOrWhiteSpace(text) ? "点击查看当前周报。" : ("点击查看：" + text);
	}

	private static string BuildWeeklyReportEventId(string eventKind, int weekIndex, string scopeKingdomId)
	{
		return "weekly_report:" + (eventKind ?? "").Trim().ToLowerInvariant() + ":" + Math.Max(0, weekIndex) + ":" + ((scopeKingdomId ?? "").Trim());
	}

	private static List<string> SanitizeUnreadWeeklyReportNoticeEventIds(IEnumerable<string> source)
	{
		return SanitizeWeeklyReportEventIds(source);
	}

	private static List<string> SanitizeWeeklyReportReadingXpClaimedEventIds(IEnumerable<string> source)
	{
		return SanitizeWeeklyReportEventIds(source);
	}

	private static List<string> SanitizeWeeklyReportEventIds(IEnumerable<string> source)
	{
		return (source ?? Enumerable.Empty<string>()).Where((string x) => !string.IsNullOrWhiteSpace(x)).Select((string x) => x.Trim()).Where((string x) => x.StartsWith("weekly_report:", StringComparison.OrdinalIgnoreCase)).Distinct(StringComparer.OrdinalIgnoreCase).ToList();
	}

	private void TryQueueWeeklyReportMapNoticeForGeneratedReport(WeeklyEventMaterialPreviewGroup group, int weekIndex, string nearestKingdomId, HashSet<string> queuedEventIds)
	{
		if (group == null || weekIndex <= 0)
		{
			return;
		}
		if (!string.Equals((group.GroupKind ?? "").Trim(), "kingdom", StringComparison.OrdinalIgnoreCase) || group.OutputMode == WeeklyReportOutputMode.TitleShortTagsOnly)
		{
			return;
		}
		string kingdomId = (group.KingdomId ?? "").Trim();
		if (string.IsNullOrWhiteSpace(kingdomId) || string.IsNullOrWhiteSpace(nearestKingdomId) || !string.Equals(kingdomId, nearestKingdomId, StringComparison.OrdinalIgnoreCase))
		{
			return;
		}
		string eventId = BuildWeeklyReportEventId("kingdom", weekIndex, kingdomId);
		if (queuedEventIds != null && !queuedEventIds.Add(eventId))
		{
			return;
		}
		QueueWeeklyReportMapNotice(eventId);
	}

