	private void OpenHeroPersonaRerollConfirmation(Hero npc, Action onClosed)
	{
		if (npc == null)
		{
			return;
		}
		GetNpcPersonaStrings(npc, out var personality, out var background);
		string name = npc.Name?.ToString() ?? "NPC";
		StringBuilder description = new StringBuilder();
		description.AppendLine("将调用辅助 API，为该 Hero 重新生成一套个性与历史背景。");
		description.AppendLine();
		description.AppendLine("当前个性：" + (string.IsNullOrWhiteSpace(personality) ? "未设置" : "已设置，将被覆盖"));
		description.AppendLine("当前历史背景：" + (string.IsNullOrWhiteSpace(background) ? "未设置" : "已设置，将被覆盖"));
		description.AppendLine("音色 ID 不会改变。生成失败时会保留当前数据。");
		InformationManager.ShowInquiry(new InquiryData("确认重生个性背景 - " + name, description.ToString().TrimEnd(), isAffirmativeOptionShown: true, isNegativeOptionShown: true, "确认生成", "取消", delegate
		{
			_ = RunHeroPersonaRerollAsync(npc, onClosed);
		}, delegate
		{
			InvokePersonaRerollClosed(onClosed);
		}), pauseGameActiveState: true);
	}

	private async Task RunHeroPersonaRerollAsync(Hero npc, Action onClosed)
	{
		if (npc == null)
		{
			return;
		}
		long runtimeGeneration = SaveRuntimeGuard.CaptureGeneration();
		string name = npc.Name?.ToString() ?? "NPC";
		InformationManager.ShowInquiry(new InquiryData("正在重生个性背景", "正在为 " + name + " 生成新的人设。\n\n完成前请稍候；只有生成并解析成功后才会覆盖旧数据。", isAffirmativeOptionShown: false, isNegativeOptionShown: false, "", "", null, null), pauseGameActiveState: true);
		Logger.Log("NpcPersona", "[REROLL] Request started for " + (npc.StringId ?? "") + ".");
		string failureDetail;
		try
		{
			failureDetail = await GenerateNpcPersonaAsync(npc, ignoreRetryCooldown: true, overwriteExisting: true);
		}
		catch (Exception ex)
		{
			failureDetail = LlmRetryPrompt.BuildFailureDetail(ex.Message, "");
		}
		if (SaveRuntimeGuard.IsStale(runtimeGeneration, "npc_persona_dev_reroll_ui"))
		{
			return;
		}
		InformationManager.HideInquiry();
		if (string.IsNullOrWhiteSpace(failureDetail))
		{
			EncyclopediaHeroPersonaPatch.QueueRefreshForHero(npc.StringId);
			InformationManager.DisplayMessage(new InformationMessage(name + " 的个性与历史背景已重新生成；音色 ID 保持不变。"));
			InvokePersonaRerollClosed(onClosed);
			return;
		}
		Logger.Log("NpcPersona", "[REROLL][WARN] Request failed for " + (npc.StringId ?? "") + ": " + failureDetail);
		InformationManager.ShowInquiry(new InquiryData("重生个性背景失败", "旧个性、历史背景与音色 ID 均未改动。\n\n" + failureDetail.Trim(), isAffirmativeOptionShown: true, isNegativeOptionShown: false, onClosed == null ? "关闭" : "返回编辑器", "", delegate
		{
			InvokePersonaRerollClosed(onClosed);
		}, null), pauseGameActiveState: true);
	}

	private static void InvokePersonaRerollClosed(Action onClosed)
	{
		try
		{
			onClosed?.Invoke();
		}
		catch (Exception ex)
		{
			Logger.Log("NpcPersona", "[REROLL][WARN] Completion callback failed: " + ex.Message);
		}
	}

	private static string BuildDevHistoryPreview(string line, int maxLen = 56)
	{
		if (string.IsNullOrWhiteSpace(line))
		{
			return "（空）";
		}
		StringBuilder stringBuilder = new StringBuilder(line.Length);
		bool flag = false;
		foreach (char c in line)
		{
			if (char.IsWhiteSpace(c))
			{
				if (!flag)
				{
					stringBuilder.Append(' ');
					flag = true;
				}
			}
			else
			{
				stringBuilder.Append(c);
				flag = false;
			}
		}
		string text = stringBuilder.ToString().Trim();
		if (text.Length <= maxLen)
		{
			return text;
		}
		return text.Substring(0, Math.Max(1, maxLen)) + "...";
	}

	private static void ShowDevLargeTextOrInquiry(string title, string subtitle, string body, Action onClose, string closeText = "返回")
	{
		string safeBody = string.IsNullOrWhiteSpace(body) ? "（无数据）" : body.Trim();
		if (DevLargeSelectionPopup.ShowText(title, subtitle, safeBody, onClose, closeText))
		{
			return;
		}
		InformationManager.ShowInquiry(new InquiryData(title ?? "AnimusForge", BuildDevLargeFallbackDescription(subtitle, safeBody), isAffirmativeOptionShown: true, isNegativeOptionShown: false, closeText ?? "返回", "", onClose, null), pauseGameActiveState: true);
	}

	private static void ShowDevLargeSelectionOrInquiry(string title, string subtitle, string body, List<DevLargeSelectionPopup.Option> options, Action<string> onSelect, Action onCancel, string affirmativeText = "进入", string cancelText = "返回")
	{
		options = options ?? new List<DevLargeSelectionPopup.Option>();
		string safeBody = string.IsNullOrWhiteSpace(body) ? "请选择要执行的操作。" : body.Trim();
		if (DevLargeSelectionPopup.Show(title, subtitle, safeBody, options, onSelect, onCancel, cancelText))
		{
			return;
		}
		if (options.Count == 0)
		{
			ShowDevLargeTextOrInquiry(title, subtitle, safeBody, onCancel, cancelText);
			return;
		}
		List<InquiryElement> list = options.Select((DevLargeSelectionPopup.Option x) => new InquiryElement(x.Id, BuildDevLargeFallbackOptionText(x), null)).ToList();
		MultiSelectionInquiryData data = new MultiSelectionInquiryData(title ?? "AnimusForge", BuildDevLargeFallbackDescription(subtitle, safeBody), list, isExitShown: true, 0, 1, affirmativeText ?? "进入", cancelText ?? "返回", delegate(List<InquiryElement> selected)
		{
			if (selected == null || selected.Count == 0)
			{
				onCancel?.Invoke();
				return;
			}
			onSelect?.Invoke(selected[0].Identifier as string ?? "");
		}, delegate
		{
			onCancel?.Invoke();
		});
		MBInformationManager.ShowMultiSelectionInquiry(data);
	}

	private static void ShowDevLargeConfirmOrInquiry(string title, string subtitle, string body, string confirmText, string cancelText, Action onConfirm, Action onCancel)
	{
		List<DevLargeSelectionPopup.Option> options = new List<DevLargeSelectionPopup.Option>
		{
			new DevLargeSelectionPopup.Option("__confirm__", confirmText ?? "确认", isDanger: true, isPrimary: true)
		};
		ShowDevLargeSelectionOrInquiry(title, subtitle, body, options, delegate(string id)
		{
			if (string.Equals(id, "__confirm__", StringComparison.Ordinal))
			{
				onConfirm?.Invoke();
			}
			else
			{
				onCancel?.Invoke();
			}
		}, onCancel, confirmText ?? "确认", cancelText ?? "取消");
	}

	private static string BuildDevLargeFallbackDescription(string subtitle, string body)
	{
		string text = (subtitle ?? "").Trim();
		string text2 = (body ?? "").Trim();
		if (string.IsNullOrEmpty(text))
		{
			return text2;
		}
		if (string.IsNullOrEmpty(text2))
		{
			return text;
		}
		return text + "\n\n" + text2;
	}

	private static string BuildDevLargeFallbackOptionText(DevLargeSelectionPopup.Option option)
	{
		if (option == null)
		{
			return "";
		}
		string title = (option.TitleText ?? "").Trim();
		string detail = BuildDevHistoryPreview(option.DetailText, 90);
		if (string.IsNullOrWhiteSpace(option.DetailText))
		{
			return title;
		}
		return title + " - " + detail;
	}

	private static bool TryParseDevSelectionInt(string id, string prefix, out int value)
	{
		value = 0;
		if (string.IsNullOrWhiteSpace(id) || prefix == null || !id.StartsWith(prefix, StringComparison.Ordinal))
		{
			return false;
		}
		return int.TryParse(id.Substring(prefix.Length), out value);
	}

	private void OpenDevCompressedMemoryMenu(Hero npc)
	{
		if (npc == null)
		{
			return;
		}
		_devEditingHero = npc;
		List<DailyMemoryDraft> drafts = LoadDailyMemoryDrafts(npc);
		List<CompressedMemoryBlock> blocks = LoadCompressedMemoryBlocks(npc);
		string heroId = GetMemoryHeroId(npc);
		int queueCount = (_memorySummaryQueue ?? new List<MemorySummaryJob>()).Count((MemorySummaryJob x) => x != null && string.Equals(NormalizeMemoryHeroId(x.HeroId), heroId, StringComparison.OrdinalIgnoreCase));
		int overviewQueueCount = (_memoryOverviewQueue ?? new List<MemoryOverviewJob>()).Count((MemoryOverviewJob x) => x != null && string.Equals(NormalizeMemoryHeroId(x.HeroId), heroId, StringComparison.OrdinalIgnoreCase));
		MemoryOverviewState overviewState = GetMemoryOverviewState(heroId);
		int rawLineCount = (drafts ?? new List<DailyMemoryDraft>()).Sum((DailyMemoryDraft x) => (x?.Lines?.Count).GetValueOrDefault());
		string name = npc.Name?.ToString() ?? "NPC";
		StringBuilder body = new StringBuilder();
		body.AppendLine("新压缩记忆体系数据：");
		body.AppendLine("今日/待总结原始历史：" + (drafts?.Count ?? 0) + " 天，" + rawLineCount + " 行");
		body.AppendLine("压缩记忆块：" + (blocks?.Count ?? 0) + " 块");
		body.AppendLine("待总结队列：" + queueCount + " 项");
		body.AppendLine("记忆大总结：" + ((overviewState != null && !string.IsNullOrWhiteSpace(overviewState.Summary)) ? ("已生成，纳入 " + (overviewState.IncludedBlockIds?.Count ?? 0) + " 块") : "未生成") + "；待更新队列：" + overviewQueueCount + " 项");
		body.AppendLine();
		body.AppendLine("旧 _dialogueHistory_v2 不再参与主链路记忆注入。");
		List<InquiryElement> list = new List<InquiryElement>
		{
			new InquiryElement("raw", "查看今日/待总结原始历史", null),
			new InquiryElement("edit_raw", "编辑今日/待总结原始历史", null),
			new InquiryElement("blocks", "查看压缩记忆块", null),
			new InquiryElement("edit_blocks", "编辑压缩记忆块", null),
			new InquiryElement("overview", "查看记忆大总结", null),
			new InquiryElement("edit_overview", "编辑记忆大总结", null),
			new InquiryElement("queue", "查看待总结队列", null),
			new InquiryElement("clear", "清空该NPC新记忆数据", null),
			new InquiryElement("process", "手动触发总结队列", null),
			new InquiryElement("back", "返回", null)
		};
		MultiSelectionInquiryData data = new MultiSelectionInquiryData("压缩记忆管理 - " + name, body.ToString().TrimEnd(), list, isExitShown: true, 0, 1, "执行", "返回", OnDevCompressedMemoryMenuSelected, delegate
		{
			ShowDevEditInquiry(npc);
		});
		MBInformationManager.ShowMultiSelectionInquiry(data);
	}

	private void OnDevCompressedMemoryMenuSelected(List<InquiryElement> selected)
	{
		Hero npc = _devEditingHero;
		if (npc == null)
		{
			return;
		}
		if (selected == null || selected.Count == 0 || selected[0].Identifier == null)
		{
			OpenDevCompressedMemoryMenu(npc);
			return;
		}
		switch (selected[0].Identifier as string)
		{
		case "raw":
			ShowDevCompressedMemoryText(npc, "原始历史", BuildDevCompressedMemoryRawText(npc));
			break;
		case "edit_raw":
			OpenDevDailyMemoryDraftList(npc, 0, _devDailyMemorySearchQuery);
			break;
		case "blocks":
			ShowDevCompressedMemoryText(npc, "压缩记忆块", BuildDevCompressedMemoryBlockText(npc));
			break;
		case "edit_blocks":
			OpenDevCompressedMemoryBlockList(npc, 0, _devCompressedMemorySearchQuery);
			break;
		case "overview":
			ShowDevCompressedMemoryText(npc, "记忆大总结", BuildDevMemoryOverviewText(npc));
			break;
		case "edit_overview":
			OpenDevMemoryOverviewEditor(npc);
			break;
		case "queue":
			ShowDevCompressedMemoryText(npc, "待总结队列", BuildDevCompressedMemoryQueueText(npc));
			break;
		case "clear":
			ConfirmDevClearCompressedMemory(npc);
			break;
		case "process":
			TrySealPastDailyMemoryDrafts();
			QueueAllMemoryOverviewCandidatesForDeferredScan();
			ProcessMemoryOverviewCandidateScanBudget(0L, double.MaxValue);
			TryStartMemorySummaryQueue();
			InformationManager.DisplayMessage(new InformationMessage("已触发压缩记忆总结队列检查。"));
			OpenDevCompressedMemoryMenu(npc);
			break;
		default:
			ShowDevEditInquiry(npc);
			break;
		}
	}

