	{
		string name = npc?.Name?.ToString() ?? "NPC";
		ShowDevLargeTextOrInquiry("压缩记忆管理 - " + title + " - " + name, "", string.IsNullOrWhiteSpace(text) ? "（无数据）" : text.Trim(), delegate
		{
			OpenDevCompressedMemoryMenu(npc);
		});
