	private void OpenDevDailyMemoryLineHourEditor(Hero npc, int dayIndex, int lineIndex, int returnPage, string returnQuery)
	{
		DailyMemoryLine line = FindDevDailyMemoryLine(LoadDailyMemoryDrafts(npc), dayIndex, lineIndex);
		if (line == null)
		{
			OpenDevDailyMemoryLineList(npc, dayIndex, returnPage, returnQuery);
			return;
		}
		InformationManager.ShowTextInquiry(new TextInquiryData("编辑未压缩记忆小时", BuildDevDailyMemoryLineSubtitle(line) + "\n请输入 0~23 的整数。", isAffirmativeOptionShown: true, isNegativeOptionShown: true, "保存", "返回", delegate(string input)
		{
			if (!int.TryParse((input ?? "").Trim(), out var hour) || hour < 0 || hour > 23)
			{
				InformationManager.DisplayMessage(new InformationMessage("请输入 0~23 的整数。"));
				OpenDevDailyMemoryLineHourEditor(npc, dayIndex, lineIndex, returnPage, returnQuery);
				return;
			}
			ApplyDevDailyMemoryLineMutation(npc, dayIndex, lineIndex, returnPage, returnQuery, delegate(DailyMemoryDraft draft, DailyMemoryLine target)
			{
				target.GameHour = hour;
			}, "未压缩记忆小时已更新。");
		}, delegate
		{
			OpenDevDailyMemoryLineEditor(npc, dayIndex, lineIndex, returnPage, returnQuery);
		}, shouldInputBeObfuscated: false, null, line.GameHour.ToString()));
	}

	private void ToggleDevDailyMemoryLineAfef(Hero npc, int dayIndex, int lineIndex, int returnPage, string returnQuery)
	{
		ApplyDevDailyMemoryLineMutation(npc, dayIndex, lineIndex, returnPage, returnQuery, delegate(DailyMemoryDraft draft, DailyMemoryLine target)
		{
			target.IsAfef = !target.IsAfef;
			if (target.IsAfef)
			{
				target.IsLlmDialogue = false;
				if (string.IsNullOrWhiteSpace(target.Speaker) || string.Equals(target.Speaker.Trim(), "手动", StringComparison.OrdinalIgnoreCase))
				{
					target.Speaker = "AFEF";
				}
			}
			else if (string.Equals((target.Speaker ?? "").Trim(), "AFEF", StringComparison.OrdinalIgnoreCase))
			{
				target.Speaker = "手动";
			}
		}, "未压缩记忆行类型已更新。");
	}

	private void ToggleDevDailyMemoryLineLlm(Hero npc, int dayIndex, int lineIndex, int returnPage, string returnQuery)
	{
		DailyMemoryLine line = FindDevDailyMemoryLine(LoadDailyMemoryDrafts(npc), dayIndex, lineIndex);
		if (line != null && line.IsAfef)
		{
			InformationManager.DisplayMessage(new InformationMessage("AFEF 行不能标记为 LLM 对话。"));
			OpenDevDailyMemoryLineEditor(npc, dayIndex, lineIndex, returnPage, returnQuery);
			return;
		}
		ApplyDevDailyMemoryLineMutation(npc, dayIndex, lineIndex, returnPage, returnQuery, delegate(DailyMemoryDraft draft, DailyMemoryLine target)
		{
			target.IsLlmDialogue = !target.IsLlmDialogue;
		}, "未压缩记忆 LLM 标记已更新。");
	}

	private void OpenDevAddDailyMemoryLine(Hero npc, int dayIndex, bool isAfef, int returnPage, string returnQuery)
	{
		DailyMemoryDraft draft = FindDevDailyMemoryDraft(LoadDailyMemoryDrafts(npc), dayIndex);
		if (draft == null)
		{
			OpenDevDailyMemoryDraftList(npc, returnPage, returnQuery);
			return;
		}
		string name = npc?.Name?.ToString() ?? "NPC";
		DevTextEditorHelper.ShowLongTextEditor(isAfef ? ("新增AFEF行 - " + name) : ("新增普通记忆行 - " + name), BuildDevDailyMemoryDraftSubtitle(draft), "请输入新增行正文；留空=取消。", "", delegate(string input)
		{
			string text = NormalizeDevCompressedMemoryMultilineInput(input);
			if (string.IsNullOrWhiteSpace(text))
			{
				OpenDevDailyMemoryDraftEditor(npc, dayIndex, returnPage, returnQuery);
				return;
			}
			List<DailyMemoryDraft> drafts = LoadDailyMemoryDrafts(npc);
			DailyMemoryDraft targetDraft = FindDevDailyMemoryDraft(drafts, dayIndex);
			if (targetDraft == null)
			{
				OpenDevDailyMemoryDraftList(npc, returnPage, returnQuery);
				return;
			}
			if (targetDraft.Lines == null)
			{
				targetDraft.Lines = new List<DailyMemoryLine>();
			}
			List<DailyMemoryLine> previousLines = CloneDevDailyMemoryLines(targetDraft.Lines);
			targetDraft.Lines.Add(new DailyMemoryLine
			{
				GameDayIndex = targetDraft.GameDayIndex,
				GameDate = targetDraft.GameDate ?? "",
				GameHour = GetDefaultDevDailyMemoryLineHour(targetDraft),
				Scene = GetDefaultDevDailyMemoryLineScene(targetDraft),
				Speaker = isAfef ? "AFEF" : "手动",
				Text = text,
				SceneSessionId = -1,
				DialogueSessionId = -1,
				MemorySessionKey = "dev:" + Guid.NewGuid().ToString("N"),
				IsAfef = isAfef,
				IsLlmDialogue = !isAfef
			});
			SaveDevDailyMemoryDraftsAfterEdit(npc, drafts, dayIndex, "add_line", previousLines);
			InformationManager.DisplayMessage(new InformationMessage("已新增未压缩记忆行。"));
			OpenDevDailyMemoryLineList(npc, dayIndex, returnPage, returnQuery);
		}, delegate
		{
			OpenDevDailyMemoryDraftEditor(npc, dayIndex, returnPage, returnQuery);
		}, "保存", "返回");
	}

	private void ConfirmDevDeleteDailyMemoryLine(Hero npc, int dayIndex, int lineIndex, int returnPage, string returnQuery)
	{
		DailyMemoryLine line = FindDevDailyMemoryLine(LoadDailyMemoryDrafts(npc), dayIndex, lineIndex);
		if (line == null)
		{
			OpenDevDailyMemoryLineList(npc, dayIndex, returnPage, returnQuery);
			return;
		}
		ShowDevLargeConfirmOrInquiry("确认删除未压缩记忆行", BuildDevDailyMemoryLineSubtitle(line), "正文：\n" + (string.IsNullOrWhiteSpace(line.Text) ? "（空）" : line.Text.Trim()) + "\n\n此操作不可撤销，是否继续？", "确认删除", "取消", delegate
		{
			ApplyDevDailyMemoryDraftMutation(npc, dayIndex, delegate(DailyMemoryDraft draft)
			{
				if (draft.Lines != null && lineIndex >= 0 && lineIndex < draft.Lines.Count)
				{
					draft.Lines.RemoveAt(lineIndex);
				}
			}, "delete_line", "已删除未压缩记忆行。", returnPage, returnQuery, returnToDraftEditor: false);
		}, delegate
		{
			OpenDevDailyMemoryLineEditor(npc, dayIndex, lineIndex, returnPage, returnQuery);
		});
	}

	private void ConfirmDevDeleteDailyMemoryDraft(Hero npc, int dayIndex, int returnPage, string returnQuery)
	{
		DailyMemoryDraft draft = FindDevDailyMemoryDraft(LoadDailyMemoryDrafts(npc), dayIndex);
		if (draft == null)
		{
			OpenDevDailyMemoryDraftList(npc, returnPage, returnQuery);
			return;
		}
		ShowDevLargeConfirmOrInquiry("确认删除未压缩记忆", BuildDevDailyMemoryDraftSubtitle(draft), "将删除该日全部未压缩原始历史，并移除同日待总结队列。\n此操作不可撤销，是否继续？", "确认删除", "取消", delegate
		{
			List<DailyMemoryDraft> drafts = LoadDailyMemoryDrafts(npc);
			DailyMemoryDraft targetDraft = FindDevDailyMemoryDraft(drafts, dayIndex);
			List<DailyMemoryLine> previousLines = CloneDevDailyMemoryLines(targetDraft?.Lines);
			drafts.RemoveAll((DailyMemoryDraft x) => x != null && x.GameDayIndex == dayIndex);
			SaveDevDailyMemoryDraftsAfterEdit(npc, drafts, dayIndex, "delete_draft", previousLines);
			InformationManager.DisplayMessage(new InformationMessage("已删除该日未压缩记忆。"));
			OpenDevDailyMemoryDraftList(npc, returnPage, returnQuery);
		}, delegate
		{
			OpenDevDailyMemoryDraftEditor(npc, dayIndex, returnPage, returnQuery);
		});
	}

	private void ApplyDevDailyMemoryLineMutation(Hero npc, int dayIndex, int lineIndex, int returnPage, string returnQuery, Action<DailyMemoryDraft, DailyMemoryLine> mutate, string successMessage)
	{
		List<DailyMemoryDraft> drafts = LoadDailyMemoryDrafts(npc);
		DailyMemoryDraft draft = FindDevDailyMemoryDraft(drafts, dayIndex);
		if (draft == null || draft.Lines == null || lineIndex < 0 || lineIndex >= draft.Lines.Count)
		{
			InformationManager.DisplayMessage(new InformationMessage("找不到要编辑的未压缩记忆行。"));
			OpenDevDailyMemoryLineList(npc, dayIndex, returnPage, returnQuery);
			return;
		}
		DailyMemoryLine line = draft.Lines[lineIndex];
		List<DailyMemoryLine> previousLines = CloneDevDailyMemoryLines(draft.Lines);
		mutate?.Invoke(draft, line);
		SaveDevDailyMemoryDraftsAfterEdit(npc, drafts, dayIndex, "edit_line", previousLines);
		InformationManager.DisplayMessage(new InformationMessage(successMessage ?? "未压缩记忆行已更新。"));
		if (FindDevDailyMemoryDraft(LoadDailyMemoryDrafts(npc), dayIndex) == null)
		{
			OpenDevDailyMemoryDraftList(npc, returnPage, returnQuery);
		}
		else if (FindDevDailyMemoryLine(LoadDailyMemoryDrafts(npc), dayIndex, lineIndex) == null)
		{
			OpenDevDailyMemoryLineList(npc, dayIndex, returnPage, returnQuery);
		}
		else
		{
			OpenDevDailyMemoryLineEditor(npc, dayIndex, lineIndex, returnPage, returnQuery);
		}
	}

	private void ApplyDevDailyMemoryDraftMutation(Hero npc, int dayIndex, Action<DailyMemoryDraft> mutate, string reason, string successMessage, int returnPage, string returnQuery, bool returnToDraftEditor)
	{
		List<DailyMemoryDraft> drafts = LoadDailyMemoryDrafts(npc);
		DailyMemoryDraft draft = FindDevDailyMemoryDraft(drafts, dayIndex);
		if (draft == null)
		{
			OpenDevDailyMemoryDraftList(npc, returnPage, returnQuery);
			return;
		}
		List<DailyMemoryLine> previousLines = CloneDevDailyMemoryLines(draft.Lines);
		mutate?.Invoke(draft);
		SaveDevDailyMemoryDraftsAfterEdit(npc, drafts, dayIndex, reason, previousLines);
		if (!string.IsNullOrWhiteSpace(successMessage))
		{
			InformationManager.DisplayMessage(new InformationMessage(successMessage));
		}
		if (returnToDraftEditor && FindDevDailyMemoryDraft(LoadDailyMemoryDrafts(npc), dayIndex) != null)
		{
			OpenDevDailyMemoryDraftEditor(npc, dayIndex, returnPage, returnQuery);
		}
		else if (FindDevDailyMemoryDraft(LoadDailyMemoryDrafts(npc), dayIndex) != null)
		{
			OpenDevDailyMemoryLineList(npc, dayIndex, returnPage, returnQuery);
		}
		else
		{
			OpenDevDailyMemoryDraftList(npc, returnPage, returnQuery);
		}
	}

	private void SaveDevDailyMemoryDraftsAfterEdit(Hero npc, List<DailyMemoryDraft> drafts, int affectedDayIndex, string reason, List<DailyMemoryLine> previousLines = null)
	{
		string heroId = GetMemoryHeroId(npc);
		foreach (DailyMemoryDraft draft in drafts ?? new List<DailyMemoryDraft>())
		{
			NormalizeDevDailyMemoryDraftForSave(npc, draft);
		}
		SaveDailyMemoryDrafts(npc, drafts);
		if (previousLines != null)
		{
			DailyMemoryDraft currentDraft = FindDevDailyMemoryDraft(LoadDailyMemoryDrafts(npc), affectedDayIndex);
			SyncDialogueHistoryForDailyMemoryDraftEdit(npc, affectedDayIndex, previousLines, CloneDevDailyMemoryLines(currentDraft?.Lines), reason);
		}
		if (FindDevDailyMemoryDraft(LoadDailyMemoryDrafts(npc), affectedDayIndex) == null && _memorySummaryQueue != null)
		{
			_memorySummaryQueue.RemoveAll((MemorySummaryJob x) => x != null && string.Equals(NormalizeMemoryHeroId(x.HeroId), heroId, StringComparison.OrdinalIgnoreCase) && x.GameDayIndex == affectedDayIndex);
		}
		Logger.Log("CompressedMemory", "manual_raw_edit hero=" + heroId + " day=" + affectedDayIndex + " reason=" + (reason ?? ""));
	}

	private void SyncDialogueHistoryForDailyMemoryDraftEdit(Hero npc, int affectedDayIndex, IEnumerable<DailyMemoryLine> previousLines, IEnumerable<DailyMemoryLine> currentLines, string reason)
	{
		if (npc == null || affectedDayIndex < 0 || previousLines == null)
		{
			return;
		}
		try
		{
			List<DailyMemoryLine> oldLines = CloneDevDailyMemoryLines(previousLines);
			List<DailyMemoryLine> newLines = CloneDevDailyMemoryLines(currentLines);
			Dictionary<string, int> oldCounts = BuildDailyMemorySyncLineCounts(oldLines);
			Dictionary<string, int> newCounts = BuildDailyMemorySyncLineCounts(newLines);
			Dictionary<string, int> removeCounts = BuildDailyMemorySyncCountDelta(oldCounts, newCounts);
			Dictionary<string, int> addCounts = BuildDailyMemorySyncCountDelta(newCounts, oldCounts);
			if (removeCounts.Count == 0 && addCounts.Count == 0)
			{
				return;
			}
			List<DialogueDay> records = LoadDialogueHistory(npc);
			DialogueDay day = records.FirstOrDefault((DialogueDay x) => x != null && x.GameDayIndex == affectedDayIndex);
			int removedCount = 0;
			if (day != null)
			{
				removedCount = RemoveDialogueHistoryLinesByCounts(day, removeCounts);
				if (day.Lines == null || day.Lines.Count == 0)
				{
					records.Remove(day);
					day = null;
				}
			}
			List<string> addedLines = BuildDailyMemorySyncAddedDialogueLines(newLines, addCounts);
			if (addedLines.Count > 0)
			{
				if (day == null)
				{
					day = new DialogueDay
					{
						GameDayIndex = affectedDayIndex,
						GameDate = ResolveDailyMemorySyncGameDate(affectedDayIndex, newLines, oldLines)
					};
					records.Add(day);
				}
				if (day.Lines == null)
				{
					day.Lines = new List<string>();
				}
				day.Lines.AddRange(addedLines);
			}
			if (removedCount > 0 || addedLines.Count > 0)
			{
				records = records.Where((DialogueDay x) => x != null && x.Lines != null && x.Lines.Count > 0).OrderBy((DialogueDay x) => x.GameDayIndex).ToList();
				SaveDialogueHistory(npc, records);
				ShoutBehavior.ClearNativeConversationSessionHistoryForExternal(npc, npc.CharacterObject, npc.Name?.ToString(), affectedDayIndex);
				Logger.Log("CompressedMemory", "sync_raw_edit_dialogue_history hero=" + GetMemoryHeroId(npc) + " day=" + affectedDayIndex + " removed=" + removedCount + " added=" + addedLines.Count + " reason=" + (reason ?? ""));
			}
		}
		catch (Exception ex)
		{
			Logger.Log("CompressedMemory", "[WARN] sync_raw_edit_dialogue_history failed: " + ex.Message);
		}
	}

	private static List<DailyMemoryLine> CloneDevDailyMemoryLines(IEnumerable<DailyMemoryLine> lines)
	{
		List<DailyMemoryLine> result = new List<DailyMemoryLine>();
		foreach (DailyMemoryLine line in lines ?? Enumerable.Empty<DailyMemoryLine>())
		{
			if (line == null)
			{
				continue;
			}
			result.Add(new DailyMemoryLine
			{
				GameDayIndex = line.GameDayIndex,
				GameDate = line.GameDate ?? "",
				GameHour = line.GameHour,
				Scene = line.Scene ?? "",
				Speaker = line.Speaker ?? "",
				Text = line.Text ?? "",
				SceneSessionId = line.SceneSessionId,
				DialogueSessionId = line.DialogueSessionId,
				TargetAgentIndex = line.TargetAgentIndex,
				TargetName = line.TargetName ?? "",
				MemorySessionKey = line.MemorySessionKey ?? "",
				IsAfef = line.IsAfef,
				IsLlmDialogue = line.IsLlmDialogue
			});
		}
		return result;
	}

	private static Dictionary<string, int> BuildDailyMemorySyncLineCounts(IEnumerable<DailyMemoryLine> lines)
	{
		Dictionary<string, int> result = new Dictionary<string, int>(StringComparer.Ordinal);
		foreach (DailyMemoryLine line in lines ?? Enumerable.Empty<DailyMemoryLine>())
		{
			string key = NormalizeDialogueHistoryLineForDailyMemorySync(line?.Text);
			if (string.IsNullOrWhiteSpace(key))
			{
				continue;
			}
			if (!result.ContainsKey(key))
			{
				result[key] = 0;
			}
			result[key]++;
		}
		return result;
	}

	private static Dictionary<string, int> BuildDailyMemorySyncCountDelta(Dictionary<string, int> source, Dictionary<string, int> target)
	{
		Dictionary<string, int> result = new Dictionary<string, int>(StringComparer.Ordinal);
		foreach (KeyValuePair<string, int> item in source ?? new Dictionary<string, int>(StringComparer.Ordinal))
		{
			int targetCount = 0;
			target?.TryGetValue(item.Key, out targetCount);
			int count = item.Value - targetCount;
			if (count > 0)
			{
				result[item.Key] = count;
			}
		}
		return result;
	}

	private static int RemoveDialogueHistoryLinesByCounts(DialogueDay day, Dictionary<string, int> removeCounts)
	{
		if (day?.Lines == null || removeCounts == null || removeCounts.Count == 0)
		{
			return 0;
		}
		int removed = 0;
		for (int i = 0; i < day.Lines.Count; i++)
		{
			string key = NormalizeDialogueHistoryLineForDailyMemorySync(day.Lines[i]);
			if (string.IsNullOrWhiteSpace(key) || !removeCounts.TryGetValue(key, out var remaining) || remaining <= 0)
			{
				continue;
			}
			day.Lines.RemoveAt(i);
			i--;
			removed++;
			removeCounts[key] = remaining - 1;
		}
		return removed;
	}

	private static List<string> BuildDailyMemorySyncAddedDialogueLines(IEnumerable<DailyMemoryLine> currentLines, Dictionary<string, int> addCounts)
	{
		List<string> result = new List<string>();
		if (addCounts == null || addCounts.Count == 0)
		{
			return result;
		}
		foreach (DailyMemoryLine line in currentLines ?? Enumerable.Empty<DailyMemoryLine>())
		{
			string key = NormalizeDialogueHistoryLineForDailyMemorySync(line?.Text);
			if (string.IsNullOrWhiteSpace(key) || !addCounts.TryGetValue(key, out var remaining) || remaining <= 0)
			{
				continue;
			}
			result.Add(BuildDialogueHistoryLineForDailyMemorySync(line));
			addCounts[key] = remaining - 1;
		}
		return result;
	}

	private static string BuildDialogueHistoryLineForDailyMemorySync(DailyMemoryLine line)
	{
		string text = NormalizeDialogueHistoryLineForDailyMemorySync(line?.Text);
		if (string.IsNullOrWhiteSpace(text))
		{
			return "";
		}
		int sceneSessionId = line?.SceneSessionId ?? -1;
		return sceneSessionId >= 0 ? TagSceneSessionHistoryLine(text, sceneSessionId) : text;
	}

	private static string NormalizeDialogueHistoryLineForDailyMemorySync(string line)
	{
		string text = (line ?? "").Replace("\r", "").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return "";
		}
		TryStripSceneSessionHistoryMarker(text, out text, out var _);
		return (text ?? "").Replace("\r", "").Trim();
	}

	private static string ResolveDailyMemorySyncGameDate(int dayIndex, IEnumerable<DailyMemoryLine> currentLines, IEnumerable<DailyMemoryLine> previousLines)
	{
		foreach (DailyMemoryLine line in currentLines ?? Enumerable.Empty<DailyMemoryLine>())
		{
			if (line != null && line.GameDayIndex == dayIndex && !string.IsNullOrWhiteSpace(line.GameDate))
			{
				return line.GameDate.Trim();
			}
		}
		foreach (DailyMemoryLine line in previousLines ?? Enumerable.Empty<DailyMemoryLine>())
		{
			if (line != null && line.GameDayIndex == dayIndex && !string.IsNullOrWhiteSpace(line.GameDate))
			{
				return line.GameDate.Trim();
			}
		}
		try
		{
			if ((int)CampaignTime.Now.ToDays == dayIndex)
			{
				return CampaignTime.Now.ToString();
			}
		}
		catch
		{
		}
		return "";
	}

	private static void NormalizeDevDailyMemoryDraftForSave(Hero npc, DailyMemoryDraft draft)
	{
		if (draft == null)
		{
			return;
		}
		draft.HeroId = GetMemoryHeroId(npc);
		draft.HeroName = npc?.Name?.ToString() ?? draft.HeroName ?? "";
		draft.GameDate = (draft.GameDate ?? "").Trim();
		draft.LastSummaryError = (draft.LastSummaryError ?? "").Trim();
		if (draft.WeeklyMaterialTriggers != null)
		{
			foreach (WeeklyMemoryMaterialTrigger trigger in draft.WeeklyMaterialTriggers)
			{
				if (trigger != null)
				{
					trigger.MemoryId = draft.HeroId;
					trigger.GameDayIndex = draft.GameDayIndex;
					trigger.GameDate = string.IsNullOrWhiteSpace(trigger.GameDate) ? draft.GameDate : trigger.GameDate;
				}
			}
		}
		draft.WeeklyMaterialTriggers = SanitizeWeeklyMemoryMaterialTriggers(draft.WeeklyMaterialTriggers);
		if (draft.Lines == null)
		{
			draft.Lines = new List<DailyMemoryLine>();
		}
		foreach (DailyMemoryLine line in draft.Lines)
		{
			if (line == null)
			{
				continue;
			}
			line.GameDayIndex = draft.GameDayIndex;
			line.GameDate = string.IsNullOrWhiteSpace(line.GameDate) ? draft.GameDate : line.GameDate.Trim();
			line.GameHour = MBMath.ClampInt(line.GameHour, 0, 23);
			line.Scene = (line.Scene ?? "").Trim();
			line.Speaker = (line.Speaker ?? "").Trim();
			line.Text = NormalizeDevCompressedMemoryMultilineInput(line.Text);
			line.MemorySessionKey = (line.MemorySessionKey ?? "").Trim();
			if (line.IsAfef)
			{
				line.IsLlmDialogue = false;
			}
			if (string.IsNullOrWhiteSpace(line.Speaker))
			{
				line.Speaker = line.IsAfef ? "AFEF" : "手动";
			}
		}
		draft.HasLlmDialogue = draft.Lines.Any((DailyMemoryLine x) => x != null && x.IsLlmDialogue && !x.IsAfef && !string.IsNullOrWhiteSpace(x.Text));
	}

	private static DailyMemoryDraft FindDevDailyMemoryDraft(List<DailyMemoryDraft> drafts, int dayIndex)
	{
		return (drafts ?? new List<DailyMemoryDraft>()).FirstOrDefault((DailyMemoryDraft x) => x != null && x.GameDayIndex == dayIndex);
	}

	private static DailyMemoryLine FindDevDailyMemoryLine(List<DailyMemoryDraft> drafts, int dayIndex, int lineIndex)
	{
		DailyMemoryDraft draft = FindDevDailyMemoryDraft(drafts, dayIndex);
		if (draft?.Lines == null || lineIndex < 0 || lineIndex >= draft.Lines.Count)
		{
			return null;
		}
		return draft.Lines[lineIndex];
	}

	private static bool IsDevDailyMemoryDraftMatch(DailyMemoryDraft draft, string[] terms)
	{
		if (draft == null)
		{
			return false;
		}
		if (terms == null || terms.Length <= 0)
		{
			return true;
		}
		string haystack = BuildDevDailyMemoryDraftSearchText(draft).ToLowerInvariant();
		foreach (string term in terms)
		{
			string text = (term ?? "").Trim().ToLowerInvariant();
			if (!string.IsNullOrWhiteSpace(text) && !haystack.Contains(text))
			{
				return false;
			}
		}
		return true;
	}

	private static string BuildDevDailyMemoryDraftSearchText(DailyMemoryDraft draft)
	{
		StringBuilder sb = new StringBuilder();
		if (draft == null)
		{
			return "";
		}
		sb.AppendLine(draft.HeroName ?? "");
		sb.AppendLine(draft.GameDate ?? "");
		sb.AppendLine(draft.GameDayIndex.ToString());
		foreach (DailyMemoryLine line in draft.Lines ?? new List<DailyMemoryLine>())
		{
			sb.AppendLine(BuildDailyMemoryLineForPrompt(line));
		}
		sb.AppendLine(BuildDevWeeklyMemoryMaterialTriggerText(draft.WeeklyMaterialTriggers));
		return sb.ToString();
	}

	private static string BuildDevDailyMemoryDraftListLabel(DailyMemoryDraft draft)
	{
		if (draft == null)
		{
			return "（空）";
		}
		string date = string.IsNullOrWhiteSpace(draft.GameDate) ? ("第" + draft.GameDayIndex + "日") : draft.GameDate.Trim();
		string flags = (draft.QueuedForSummary ? " 已入队" : "") + (string.IsNullOrWhiteSpace(draft.LastSummaryError) ? "" : " 有错误") + (((draft.WeeklyMaterialTriggers?.Count).GetValueOrDefault() > 0) ? (" 周报素材x" + draft.WeeklyMaterialTriggers.Count) : "");
		return date + " | " + ((draft.Lines?.Count).GetValueOrDefault()) + " 行" + flags + " | " + BuildDevHistoryPreview((draft.Lines ?? new List<DailyMemoryLine>()).Select((DailyMemoryLine x) => x?.Text).FirstOrDefault((string x) => !string.IsNullOrWhiteSpace(x)), 64);
	}

	private static string BuildDevDailyMemoryDraftSubtitle(DailyMemoryDraft draft)
	{
		if (draft == null)
		{
			return "";
		}
		string date = string.IsNullOrWhiteSpace(draft.GameDate) ? ("第" + draft.GameDayIndex + "日") : draft.GameDate.Trim();
		return "日期：" + date + "\n行数：" + ((draft.Lines?.Count).GetValueOrDefault()) + "\n周报素材触发器：" + ((draft.WeeklyMaterialTriggers?.Count).GetValueOrDefault()) + "\n已入总结队列：" + (draft.QueuedForSummary ? "是" : "否") + "\n最近总结错误：" + BuildDevStoredErrorReference(draft.LastSummaryError);
	}

	private static string BuildDevStoredErrorReference(string error)
	{
		// 开发菜单会在返回和翻页时反复重建；这里只放固定短提示，避免历史 API 原文再次挤占操作项。
		return string.IsNullOrWhiteSpace(error) ? "无" : "已记录（详情已在触发时显示于左下角）";
	}

	private static string BuildDevDailyMemoryDraftEditorDescription(DailyMemoryDraft draft)
	{
		if (draft == null)
		{
			return "找不到未压缩记忆。";
		}
		StringBuilder sb = new StringBuilder();
		sb.AppendLine(BuildDevDailyMemoryDraftSubtitle(draft));
		sb.AppendLine("普通行：" + (draft.Lines ?? new List<DailyMemoryLine>()).Count((DailyMemoryLine x) => x != null && !x.IsAfef));
		sb.AppendLine("AFEF行：" + (draft.Lines ?? new List<DailyMemoryLine>()).Count((DailyMemoryLine x) => x != null && x.IsAfef));
		string triggerText = BuildDevWeeklyMemoryMaterialTriggerText(draft.WeeklyMaterialTriggers);
		if (!string.IsNullOrWhiteSpace(triggerText))
		{
			sb.AppendLine("周报素材：");
			sb.AppendLine(triggerText);
		}
		sb.AppendLine("预览：" + BuildDevHistoryPreview((draft.Lines ?? new List<DailyMemoryLine>()).Select((DailyMemoryLine x) => x?.Text).FirstOrDefault((string x) => !string.IsNullOrWhiteSpace(x)), 180));
		return sb.ToString().TrimEnd();
	}

	private static string BuildDevWeeklyMemoryMaterialTriggerText(IEnumerable<WeeklyMemoryMaterialTrigger> triggers)
	{
		List<WeeklyMemoryMaterialTrigger> list = SanitizeWeeklyMemoryMaterialTriggers(triggers);
		if (list.Count == 0)
		{
			return "";
		}
		StringBuilder sb = new StringBuilder();
		foreach (WeeklyMemoryMaterialTrigger trigger in list.Take(8))
		{
			List<string> labels = (trigger.Tags ?? new List<string>()).Select(BuildWeeklyMemoryMaterialTagLabel).Where((string x) => !string.IsNullOrWhiteSpace(x)).Distinct(StringComparer.OrdinalIgnoreCase).ToList();
			sb.Append("- 王国=").Append(trigger.FootholdKingdomId ?? "")
				.Append(" session=").Append(trigger.SceneSessionId >= 0 ? ("scene:" + trigger.SceneSessionId) : (trigger.DialogueSessionId >= 0 ? ("dialogue:" + trigger.DialogueSessionId) : "none"))
				.Append(" value=").Append(Math.Max(0L, trigger.EstimatedValueDenars))
				.Append(" tags=").Append(labels.Count > 0 ? string.Join("、", labels) : string.Join("、", trigger.Tags ?? new List<string>()));
			if (!string.IsNullOrWhiteSpace(trigger.TriggerReason))
			{
				sb.Append(" reason=").Append(trigger.TriggerReason.Trim());
			}
			sb.AppendLine();
		}
		if (list.Count > 8)
		{
			sb.AppendLine("- ...还有 " + (list.Count - 8) + " 条");
		}
		return sb.ToString().TrimEnd();
	}

	private static string BuildDevDailyMemoryLineListLabel(DailyMemoryLine line)
	{
		if (line == null)
		{
			return "（空）";
		}
		string type = line.IsAfef ? "AFEF" : (line.IsLlmDialogue ? "LLM" : "普通");
		string speaker = string.IsNullOrWhiteSpace(line.Speaker) ? (line.IsAfef ? "AFEF" : "手动") : line.Speaker.Trim();
		return MBMath.ClampInt(line.GameHour, 0, 23) + "时 | " + type + " | " + speaker + " | " + BuildDevHistoryPreview(line.Text, 90);
	}

	private static string BuildDevDailyMemoryLineSubtitle(DailyMemoryLine line)
	{
		if (line == null)
		{
			return "";
		}
		string date = string.IsNullOrWhiteSpace(line.GameDate) ? ("第" + line.GameDayIndex + "日") : line.GameDate.Trim();
		return "日期：" + date + " " + MBMath.ClampInt(line.GameHour, 0, 23) + "时\n场景：" + (string.IsNullOrWhiteSpace(line.Scene) ? "未知场景" : line.Scene.Trim()) + "\n说话人：" + (string.IsNullOrWhiteSpace(line.Speaker) ? (line.IsAfef ? "AFEF" : "手动") : line.Speaker.Trim()) + "\n类型：" + (line.IsAfef ? "AFEF" : (line.IsLlmDialogue ? "LLM对话" : "普通"));
	}

	private static string BuildDevDailyMemoryLineDescription(DailyMemoryLine line)
	{
		if (line == null)
		{
			return "找不到未压缩记忆行。";
		}
		return BuildDevDailyMemoryLineSubtitle(line) + "\n\n正文：\n" + (string.IsNullOrWhiteSpace(line.Text) ? "（空）" : line.Text.Trim());
	}

	private static int GetDefaultDevDailyMemoryLineHour(DailyMemoryDraft draft)
	{
		DailyMemoryLine latest = (draft?.Lines ?? new List<DailyMemoryLine>()).LastOrDefault((DailyMemoryLine x) => x != null);
		if (latest != null)
		{
			return MBMath.ClampInt(latest.GameHour, 0, 23);
		}
		if (draft != null && draft.GameDayIndex == GetCurrentGameDayIndexSafe())
		{
			return GetCurrentHourOfDaySafeForPrompt();
		}
		return 12;
	}

	private static string GetDefaultDevDailyMemoryLineScene(DailyMemoryDraft draft)
	{
		string text = (draft?.Lines ?? new List<DailyMemoryLine>()).LastOrDefault((DailyMemoryLine x) => x != null && !string.IsNullOrWhiteSpace(x.Scene))?.Scene;
		if (!string.IsNullOrWhiteSpace(text))
		{
			return text.Trim();
		}
		return ResolveCurrentMemorySceneLabel();
	}

	private void OpenDevMemoryOverviewEditor(Hero npc)
	{
		if (npc == null)
		{
			return;
		}
		string heroId = GetMemoryHeroId(npc);
		if (string.IsNullOrWhiteSpace(heroId))
		{
			OpenDevCompressedMemoryMenu(npc);
			return;
		}
		MemoryOverviewState state = GetMemoryOverviewState(heroId);
		List<CompressedMemoryBlock> blocks = LoadCompressedMemoryBlocks(npc);
		string name = npc.Name?.ToString() ?? "NPC";
		string subtitle = "当前压缩记忆块：" + (blocks?.Count ?? 0) + " 块；已纳入：" + (state?.IncludedBlockIds?.Count ?? 0) + " 块。\n保存非空内容后，会把当前所有压缩记忆块标记为已纳入，避免被待更新队列立即覆盖。";
		DevTextEditorHelper.ShowLongTextEditor("编辑记忆大总结 - " + name, subtitle, "请输入新的过往记忆总览；留空=清空并等待重新生成。", state?.Summary ?? "", delegate(string input)
		{
			ApplyDevMemoryOverviewInput(npc, input);
		}, delegate
		{
			OpenDevCompressedMemoryMenu(npc);
		}, "保存", "返回");
	}

	private void ApplyDevMemoryOverviewInput(Hero npc, string input)
	{
		string heroId = GetMemoryHeroId(npc);
		if (string.IsNullOrWhiteSpace(heroId))
		{
			OpenDevCompressedMemoryMenu(npc);
			return;
		}
		if (_memoryOverviewStates == null)
		{
			_memoryOverviewStates = new Dictionary<string, MemoryOverviewState>(StringComparer.OrdinalIgnoreCase);
		}
		if (_memoryOverviewQueue == null)
		{
			_memoryOverviewQueue = new List<MemoryOverviewJob>();
		}
		string summary = NormalizeDevCompressedMemoryMultilineInput(input);
		if (string.IsNullOrWhiteSpace(summary))
		{
			_memoryOverviewStates.Remove(heroId);
			_memoryOverviewQueue.RemoveAll((MemoryOverviewJob x) => x != null && string.Equals(NormalizeMemoryHeroId(x.HeroId), heroId, StringComparison.OrdinalIgnoreCase));
			TryEnqueueMemoryOverviewForHero(npc, LoadCompressedMemoryBlocks(npc));
			Logger.Log("MemoryOverview", "manual_overview_clear hero=" + heroId);
			InformationManager.DisplayMessage(new InformationMessage("已清空记忆大总结，并重新检查待整理队列。"));
			OpenDevCompressedMemoryMenu(npc);
			return;
		}
		List<string> includedBlockIds = SanitizeCompressedMemoryBlocks(LoadCompressedMemoryBlocks(npc)).Select(GetDevCompressedMemoryBlockId).Where((string x) => !string.IsNullOrWhiteSpace(x)).Distinct(StringComparer.OrdinalIgnoreCase).ToList();
		MemoryOverviewState state = GetMemoryOverviewState(heroId) ?? new MemoryOverviewState();
		state.HeroId = heroId;
		state.HeroName = npc.Name?.ToString() ?? state.HeroName ?? "NPC";
		state.Summary = summary;
		state.IncludedBlockIds = includedBlockIds;
		state.UpdatedUtcTicks = DateTime.UtcNow.Ticks;
		state.LastError = "";
		_memoryOverviewStates[heroId] = SanitizeMemoryOverviewState(state);
		_memoryOverviewQueue.RemoveAll((MemoryOverviewJob x) => x != null && string.Equals(NormalizeMemoryHeroId(x.HeroId), heroId, StringComparison.OrdinalIgnoreCase));
		Logger.Log("MemoryOverview", "manual_overview_save hero=" + heroId + " blocks=" + includedBlockIds.Count);
		InformationManager.DisplayMessage(new InformationMessage("记忆大总结已更新。"));
		OpenDevCompressedMemoryMenu(npc);
	}

	private void OpenDevCompressedMemoryBlockList(Hero npc, int page, string query)
	{
		if (npc == null)
		{
			return;
		}
		_devEditingHero = npc;
		page = Math.Max(0, page);
		string q = (query ?? "").Trim();
		_devCompressedMemorySearchQuery = q;
		_devCompressedMemoryBlockPage = page;
		List<CompressedMemoryBlock> blocks = SanitizeCompressedMemoryBlocks(LoadCompressedMemoryBlocks(npc));
		if (blocks == null || blocks.Count <= 0)
		{
			InformationManager.DisplayMessage(new InformationMessage("该NPC当前没有压缩记忆块。"));
			OpenDevCompressedMemoryMenu(npc);
			return;
		}
		string[] terms = SplitDevCompressedMemorySearchTerms(q);
		List<Tuple<int, CompressedMemoryBlock>> filtered = new List<Tuple<int, CompressedMemoryBlock>>();
		for (int i = 0; i < blocks.Count; i++)
		{
			CompressedMemoryBlock block = blocks[i];
			if (IsDevCompressedMemoryBlockMatch(block, terms))
			{
				filtered.Add(new Tuple<int, CompressedMemoryBlock>(i + 1, block));
			}
		}
		const int pageSize = 40;
		int pageCount = Math.Max(1, (filtered.Count + pageSize - 1) / pageSize);
		if (page >= pageCount)
		{
			page = pageCount - 1;
			_devCompressedMemoryBlockPage = page;
		}
		List<DevLargeSelectionPopup.Option> options = new List<DevLargeSelectionPopup.Option>();
		options.Add(new DevLargeSelectionPopup.Option("__search__", "搜索压缩记忆块", isPrimary: true));
		if (!string.IsNullOrWhiteSpace(q))
		{
			options.Add(new DevLargeSelectionPopup.Option("__clear__", "清空搜索"));
		}
		if (page > 0)
		{
			options.Add(new DevLargeSelectionPopup.Option("__prev__", "上一页"));
		}
		if (page + 1 < pageCount)
		{
			options.Add(new DevLargeSelectionPopup.Option("__next__", "下一页"));
		}
		foreach (Tuple<int, CompressedMemoryBlock> item in filtered.Skip(page * pageSize).Take(pageSize))
		{
			string blockId = GetDevCompressedMemoryBlockId(item.Item2);
			if (!string.IsNullOrWhiteSpace(blockId))
			{
				options.Add(new DevLargeSelectionPopup.Option(blockId, BuildDevCompressedMemoryBlockListLabel(item.Item2, item.Item1)));
			}
		}
		string name = npc.Name?.ToString() ?? "NPC";
		string descriptionText = "选择一个压缩记忆块进入编辑选项。\n压缩记忆块：" + blocks.Count + " 块；当前结果：" + filtered.Count + " 块；第 " + (page + 1) + "/" + pageCount + " 页。";
		if (!string.IsNullOrWhiteSpace(q))
		{
			descriptionText += "\n当前搜索：" + BuildDevHistoryPreview(q, 80);
		}
		if (filtered.Count <= 0)
		{
			descriptionText += "\n\n没有匹配结果。";
		}
		ShowDevLargeSelectionOrInquiry("编辑压缩记忆块 - " + name, "压缩记忆块列表", descriptionText, options, delegate(string selectedId)
		{
			if (string.IsNullOrWhiteSpace(selectedId))
			{
				OpenDevCompressedMemoryBlockList(npc, page, q);
				return;
			}
			switch (selectedId)
			{
			case "__search__":
				InformationManager.ShowTextInquiry(new TextInquiryData("搜索压缩记忆块", "输入关键词，可匹配标题、正文、场景、AFEF、日期或记忆块ID。", isAffirmativeOptionShown: true, isNegativeOptionShown: true, "搜索", "返回", delegate(string input)
				{
					OpenDevCompressedMemoryBlockList(npc, 0, input);
				}, delegate
				{
					OpenDevCompressedMemoryBlockList(npc, page, q);
				}, shouldInputBeObfuscated: false, null, q));
				break;
			case "__clear__":
				OpenDevCompressedMemoryBlockList(npc, 0, null);
				break;
			case "__prev__":
				OpenDevCompressedMemoryBlockList(npc, page - 1, q);
				break;
			case "__next__":
				OpenDevCompressedMemoryBlockList(npc, page + 1, q);
				break;
			default:
				OpenDevCompressedMemoryBlockEditor(npc, selectedId, page, q);
				break;
			}
		}, delegate
		{
			OpenDevCompressedMemoryMenu(npc);
		}, "进入", "返回");
	}

	private void OpenDevCompressedMemoryBlockEditor(Hero npc, string blockId, int returnPage, string returnQuery)
	{
		if (npc == null)
		{
			return;
		}
		_devEditingHero = npc;
		List<CompressedMemoryBlock> blocks = LoadCompressedMemoryBlocks(npc);
		CompressedMemoryBlock block = FindDevCompressedMemoryBlock(blocks, blockId);
		if (block == null)
		{
			InformationManager.DisplayMessage(new InformationMessage("找不到要编辑的压缩记忆块。"));
			OpenDevCompressedMemoryBlockList(npc, returnPage, returnQuery);
			return;
		}
		string name = npc.Name?.ToString() ?? "NPC";
		List<DevLargeSelectionPopup.Option> options = new List<DevLargeSelectionPopup.Option>
		{
			new DevLargeSelectionPopup.Option("summary", "编辑正文", "打开大编辑框修改记忆块正文；留空=清空正文。", isPrimary: true),
			new DevLargeSelectionPopup.Option("title", "编辑标题", "打开大编辑框修改富标题；留空=清空标题。"),
			new DevLargeSelectionPopup.Option("scenes", "编辑场景列表", "打开大编辑框逐行修改场景；最多保留16项。"),
			new DevLargeSelectionPopup.Option("afef", "编辑AFEF行", "打开大编辑框逐行修改 AFEF；最多保留80项。"),
			new DevLargeSelectionPopup.Option("delete", "删除该记忆块", "删除后会清空该NPC的记忆大总结并重新排队整理。", isDanger: true),
			new DevLargeSelectionPopup.Option("back", "返回列表")
		};
		ShowDevLargeSelectionOrInquiry("记忆块 - " + name, BuildDevCompressedMemoryBlockSubtitle(block), BuildDevCompressedMemoryBlockEditorBody(block), options, delegate(string selectedId)
		{
			if (string.IsNullOrWhiteSpace(selectedId))
			{
				OpenDevCompressedMemoryBlockEditor(npc, blockId, returnPage, returnQuery);
				return;
			}
			switch (selectedId)
			{
			case "title":
				OpenDevCompressedMemoryBlockTitleEditor(npc, blockId, returnPage, returnQuery);
				break;
			case "summary":
				OpenDevCompressedMemoryBlockSummaryEditor(npc, blockId, returnPage, returnQuery);
				break;
			case "scenes":
				OpenDevCompressedMemoryBlockScenesEditor(npc, blockId, returnPage, returnQuery);
				break;
			case "afef":
				OpenDevCompressedMemoryBlockAfefEditor(npc, blockId, returnPage, returnQuery);
				break;
			case "delete":
				ConfirmDevDeleteCompressedMemoryBlock(npc, blockId, returnPage, returnQuery);
				break;
			case "back":
				OpenDevCompressedMemoryBlockList(npc, returnPage, returnQuery);
				break;
			default:
				OpenDevCompressedMemoryBlockEditor(npc, blockId, returnPage, returnQuery);
				break;
			}
		}, delegate
		{
			OpenDevCompressedMemoryBlockList(npc, returnPage, returnQuery);
		}, "进入", "返回");
	}

