	private void OpenFolderPicker(string title, bool isExport, ExportImportScope scope, Action onReturn, string heroId)
	{
		if (onReturn == null)
		{
			onReturn = ReturnToDevRootMenu;
		}
		string playerExportsRootPath = GetPlayerExportsRootPath();
		Directory.CreateDirectory(playerExportsRootPath);
		List<InquiryElement> list = new List<InquiryElement>();
		list.Add(new InquiryElement("__input__", "手动输入文件夹名…", null));
		if (!isExport)
		{
			list.Add(new InquiryElement("__latest__", "使用最新导出（自动）", null));
		}
		try
		{
			DirectoryInfo directoryInfo = new DirectoryInfo(playerExportsRootPath);
			List<DirectoryInfo> list2 = (from d in directoryInfo.GetDirectories()
				orderby d.LastWriteTimeUtc descending
				select d).ToList();
			foreach (DirectoryInfo item in list2)
			{
				string title2 = item.Name + "  (" + item.LastWriteTime.ToString("yyyy-MM-dd HH:mm") + ")";
				list.Add(new InquiryElement(item.Name, title2, null));
			}
		}
		catch
		{
		}
		string descriptionText = (isExport ? "选择要导出的目标文件夹（可覆盖已有）。" : "选择要导入的来源文件夹。");
		MultiSelectionInquiryData data = new MultiSelectionInquiryData(title, descriptionText, list, isExitShown: true, 0, 1, "选择", "返回", delegate(List<InquiryElement> selected)
		{
			if (selected == null || selected.Count == 0)
			{
				onReturn();
			}
			else
			{
				string text = selected[0].Identifier as string;
				if (text == "__input__")
				{
					InformationManager.ShowTextInquiry(new TextInquiryData(isExport ? "输入导出文件夹名" : "输入导入文件夹名", isExport ? "留空=自动时间戳；输入已存在名称=覆盖导出。" : "留空=自动选择最新导出。", isAffirmativeOptionShown: true, isNegativeOptionShown: true, "确定", "取消", delegate(string input)
					{
						if (string.IsNullOrEmpty(heroId))
						{
							ResolveAndRunExportImport(isExport, scope, input);
						}
						else
						{
							ResolveAndRunExportImportForHero(isExport, scope, input, heroId);
						}
						onReturn();
					}, delegate
					{
						onReturn();
					}));
				}
				else if (!isExport && text == "__latest__")
				{
					if (string.IsNullOrEmpty(heroId))
					{
						ResolveAndRunExportImport(isExport: false, scope, "");
					}
					else
					{
						ResolveAndRunExportImportForHero(isExport: false, scope, "", heroId);
					}
					onReturn();
				}
				else
				{
					if (string.IsNullOrEmpty(heroId))
					{
						ResolveAndRunExportImport(isExport, scope, text);
					}
					else
					{
						ResolveAndRunExportImportForHero(isExport, scope, text, heroId);
					}
					onReturn();
				}
			}
		}, delegate
		{
			onReturn();
		});
		MBInformationManager.ShowMultiSelectionInquiry(data);
	}

	private void ResolveAndRunExportImport(bool isExport, ExportImportScope scope, string folderName)
	{
		if (isExport)
		{
			Action run = delegate
			{
				if (scope == ExportImportScope.All)
				{
					ExportAllData(folderName);
				}
				else if (scope == ExportImportScope.HeroNpcAll)
				{
					ExportHeroNpcAllData(folderName);
				}
				else if (scope == ExportImportScope.PersonalityBackground)
				{
					ExportPersonaData(folderName);
				}
				else if (scope == ExportImportScope.UnnamedPersona)
				{
					ExportUnnamedPersonaData(folderName);
				}
				else if (scope == ExportImportScope.DialogueHistory)
				{
					ExportDialogueHistoryData(folderName);
				}
				else if (scope == ExportImportScope.Debt)
				{
					ExportDebtData(folderName);
				}
				else if (scope == ExportImportScope.EventData)
				{
					ExportEventData(folderName);
				}
				else if (scope == ExportImportScope.Knowledge)
				{
					ExportKnowledgeData(folderName);
				}
				else if (scope == ExportImportScope.VoiceMapping)
				{
					ExportVoiceMappingData(folderName);
				}
			};
			string value = SanitizeFolderName(folderName);
			if (!string.IsNullOrEmpty(value))
			{
				string playerExportsRootPath = GetPlayerExportsRootPath();
				Directory.CreateDirectory(playerExportsRootPath);
				string path = ResolveExportFolderName(folderName);
				string text = Path.Combine(playerExportsRootPath, path);
				if (IsDirectoryNonEmpty(text))
				{
					ShowOverwriteExportInquiry("导出文件夹已存在", "目标文件夹已存在且包含内容：\n" + text + "\n是否覆盖导出？", delegate
					{
						run();
					}, delegate
					{
						ResolveAndRunExportImport(isExport: true, scope, "");
					}, delegate
					{
					});
					return;
				}
			}
			run();
		}
		else if (scope == ExportImportScope.All)
		{
			ImportAllData(folderName);
		}
		else if (scope == ExportImportScope.HeroNpcAll)
		{
			ImportHeroNpcAllData(folderName);
		}
		else if (scope == ExportImportScope.PersonalityBackground)
		{
			ImportPersonaData(folderName);
		}
		else if (scope == ExportImportScope.UnnamedPersona)
		{
			ImportUnnamedPersonaData(folderName);
		}
		else if (scope == ExportImportScope.DialogueHistory)
		{
			ImportDialogueHistoryData(folderName);
		}
		else if (scope == ExportImportScope.Debt)
		{
			ImportDebtData(folderName);
		}
		else if (scope == ExportImportScope.EventData)
		{
			ImportEventData(folderName);
		}
		else if (scope == ExportImportScope.Knowledge)
		{
			ImportKnowledgeData(folderName);
		}
		else if (scope == ExportImportScope.VoiceMapping)
		{
			ImportVoiceMappingData(folderName);
		}
	}

	private void ResolveAndRunExportImportForHero(bool isExport, ExportImportScope scope, string folderName, string heroId)
	{
		string id = (heroId ?? "").Trim();
		if (string.IsNullOrEmpty(id))
		{
			InformationManager.DisplayMessage(new InformationMessage("该NPC缺少编号，无法导入导出。"));
		}
		else if (isExport)
		{
			Action run = delegate
			{
				if (scope == ExportImportScope.PersonalityBackground)
				{
					ExportSingleNpcPersonaData(folderName, id);
				}
				else if (scope == ExportImportScope.DialogueHistory)
				{
					ExportSingleNpcDialogueHistoryData(folderName, id);
				}
				else if (scope == ExportImportScope.Debt)
				{
					ExportSingleNpcDebtData(folderName, id);
				}
			};
			string value = SanitizeFolderName(folderName);
			if (!string.IsNullOrEmpty(value))
			{
				string playerExportsRootPath = GetPlayerExportsRootPath();
				Directory.CreateDirectory(playerExportsRootPath);
				string path = ResolveExportFolderName(folderName);
				string text = Path.Combine(playerExportsRootPath, path);
				if (IsDirectoryNonEmpty(text))
				{
					ShowOverwriteExportInquiry("导出文件夹已存在", "目标文件夹已存在且包含内容：\n" + text + "\n是否覆盖导出？", delegate
					{
						run();
					}, delegate
					{
						ResolveAndRunExportImportForHero(isExport: true, scope, "", id);
					}, delegate
					{
					});
					return;
				}
			}
			run();
		}
		else if (scope == ExportImportScope.PersonalityBackground)
		{
			ImportSingleNpcPersonaData(folderName, id);
		}
		else if (scope == ExportImportScope.DialogueHistory)
		{
			ImportSingleNpcDialogueHistoryData(folderName, id);
		}
		else if (scope == ExportImportScope.Debt)
		{
			ImportSingleNpcDebtData(folderName, id);
		}
	}

	private void ExportSingleNpcPersonaData(string folderName, string heroId)
	{
		try
		{
			string playerExportsRootPath = GetPlayerExportsRootPath();
			Directory.CreateDirectory(playerExportsRootPath);
			string path = ResolveExportFolderName(folderName);
			string text = Path.Combine(playerExportsRootPath, path);
			Directory.CreateDirectory(text);
			string text2 = Path.Combine(text, "personality_background");
			Directory.CreateDirectory(text2);
			NpcPersonaProfile value = null;
			if (_npcPersonaProfiles != null)
			{
				_npcPersonaProfiles.TryGetValue(heroId, out value);
			}
			if (value == null)
			{
				value = new NpcPersonaProfile();
			}
			if (!TryPrepareNpcPersonaProfileForWrite(heroId, value))
			{
				value = new NpcPersonaProfile();
				StampNpcPersonaProfile(heroId, value);
			}
			string path2 = Path.Combine(text2, BuildNpcDataFileName(heroId));
			WriteJson(path2, value);
			InformationManager.DisplayMessage(new InformationMessage("导出完成：" + text));
		}
		catch (Exception ex)
		{
			InformationManager.DisplayMessage(new InformationMessage("导出失败：" + ex.Message));
		}
	}

	private void ExportSingleNpcDialogueHistoryData(string folderName, string heroId)
	{
		try
		{
			string playerExportsRootPath = GetPlayerExportsRootPath();
			Directory.CreateDirectory(playerExportsRootPath);
			string path = ResolveExportFolderName(folderName);
			string text = Path.Combine(playerExportsRootPath, path);
			Directory.CreateDirectory(text);
			string text2 = Path.Combine(text, "compressed_memory");
			Directory.CreateDirectory(text2);
			CompressedMemoryExportBundle value = BuildCompressedMemoryExportBundle(heroId);
			string path2 = Path.Combine(text2, BuildNpcDataFileName(heroId));
			WriteJson(path2, value);
			InformationManager.DisplayMessage(new InformationMessage("导出完成：" + text));
		}
		catch (Exception ex)
		{
			InformationManager.DisplayMessage(new InformationMessage("导出失败：" + ex.Message));
		}
	}

	private CompressedMemoryExportBundle BuildCompressedMemoryExportBundle(string heroId)
	{
		string text = NormalizeMemoryHeroId(heroId);
		CompressedMemoryExportBundle compressedMemoryExportBundle = new CompressedMemoryExportBundle();
		if (!string.IsNullOrWhiteSpace(text))
		{
			if (_dailyMemoryDrafts != null && _dailyMemoryDrafts.TryGetValue(text, out var drafts) && drafts != null)
			{
				compressedMemoryExportBundle.DailyDrafts = SanitizeDailyMemoryDrafts(drafts);
			}
			if (_compressedMemoryBlocks != null && _compressedMemoryBlocks.TryGetValue(text, out var blocks) && blocks != null)
			{
				compressedMemoryExportBundle.Blocks = SanitizeCompressedMemoryBlocks(blocks);
			}
			compressedMemoryExportBundle.SummaryQueue = SanitizeMemorySummaryQueue((_memorySummaryQueue ?? new List<MemorySummaryJob>()).Where((MemorySummaryJob x) => x != null && string.Equals(NormalizeMemoryHeroId(x.HeroId), text, StringComparison.OrdinalIgnoreCase)));
			MemoryOverviewState overviewState = GetMemoryOverviewState(text);
			if (overviewState != null)
			{
				compressedMemoryExportBundle.Overview = SanitizeMemoryOverviewState(overviewState);
			}
			compressedMemoryExportBundle.OverviewQueue = SanitizeMemoryOverviewQueue((_memoryOverviewQueue ?? new List<MemoryOverviewJob>()).Where((MemoryOverviewJob x) => x != null && string.Equals(NormalizeMemoryHeroId(x.HeroId), text, StringComparison.OrdinalIgnoreCase)));
		}
		return compressedMemoryExportBundle;
	}

	private bool ApplyCompressedMemoryExportBundle(string heroId, CompressedMemoryExportBundle bundle, bool overwriteExisting)
	{
		string text = NormalizeMemoryHeroId(heroId);
		if (string.IsNullOrWhiteSpace(text) || bundle == null)
		{
			return false;
		}
		if (_dailyMemoryDrafts == null)
		{
			_dailyMemoryDrafts = new Dictionary<string, List<DailyMemoryDraft>>(StringComparer.OrdinalIgnoreCase);
		}
		if (_compressedMemoryBlocks == null)
		{
			_compressedMemoryBlocks = new Dictionary<string, List<CompressedMemoryBlock>>(StringComparer.OrdinalIgnoreCase);
		}
		if (_memorySummaryQueue == null)
		{
			_memorySummaryQueue = new List<MemorySummaryJob>();
		}
		if (_memoryOverviewStates == null)
		{
			_memoryOverviewStates = new Dictionary<string, MemoryOverviewState>(StringComparer.OrdinalIgnoreCase);
		}
		if (_memoryOverviewQueue == null)
		{
			_memoryOverviewQueue = new List<MemoryOverviewJob>();
		}
		List<DailyMemoryDraft> drafts = SanitizeDailyMemoryDrafts(bundle.DailyDrafts);
		List<CompressedMemoryBlock> blocks = SanitizeCompressedMemoryBlocks(bundle.Blocks);
		List<MemorySummaryJob> queue = SanitizeMemorySummaryQueue(bundle.SummaryQueue);
		MemoryOverviewState overview = SanitizeMemoryOverviewState(bundle.Overview);
		List<MemoryOverviewJob> overviewQueue = SanitizeMemoryOverviewQueue(bundle.OverviewQueue);
		if (overwriteExisting)
		{
			_dailyMemoryDrafts.Remove(text);
			_compressedMemoryBlocks.Remove(text);
			_memorySummaryQueue.RemoveAll((MemorySummaryJob x) => x != null && string.Equals(NormalizeMemoryHeroId(x.HeroId), text, StringComparison.OrdinalIgnoreCase));
			_memoryOverviewStates.Remove(text);
			_memoryOverviewQueue.RemoveAll((MemoryOverviewJob x) => x != null && string.Equals(NormalizeMemoryHeroId(x.HeroId), text, StringComparison.OrdinalIgnoreCase));
		}
		if (drafts.Count > 0 && (overwriteExisting || !_dailyMemoryDrafts.ContainsKey(text)))
		{
			foreach (DailyMemoryDraft draft in drafts)
			{
				draft.HeroId = text;
			}
			_dailyMemoryDrafts[text] = drafts;
		}
		if (blocks.Count > 0 && (overwriteExisting || !_compressedMemoryBlocks.ContainsKey(text)))
		{
			foreach (CompressedMemoryBlock block in blocks)
			{
				block.HeroId = text;
				if (string.IsNullOrWhiteSpace(block.Id))
				{
					block.Id = BuildCompressedMemoryBlockId(text, block.GameDayIndex);
				}
			}
			_compressedMemoryBlocks[text] = blocks;
			MarkMemoryOverviewDirty(text);
		}
		if (queue.Count > 0 && overwriteExisting)
		{
			foreach (MemorySummaryJob job in queue)
			{
				job.HeroId = text;
				_memorySummaryQueue.Add(job);
			}
			_memorySummaryQueue = SanitizeMemorySummaryQueue(_memorySummaryQueue);
		}
		if (overview != null && (!string.IsNullOrWhiteSpace(overview.Summary) || !string.IsNullOrWhiteSpace(overview.LastError)) && (overwriteExisting || !_memoryOverviewStates.ContainsKey(text)))
		{
			overview.HeroId = text;
			_memoryOverviewStates[text] = SanitizeMemoryOverviewState(overview);
		}
		if (overviewQueue.Count > 0 && overwriteExisting)
		{
			foreach (MemoryOverviewJob job in overviewQueue)
			{
				job.HeroId = text;
				_memoryOverviewQueue.Add(job);
			}
			_memoryOverviewQueue = SanitizeMemoryOverviewQueue(_memoryOverviewQueue);
		}
		return true;
	}

	private bool HasCompressedMemoryDataForHero(string heroId)
	{
		string text = NormalizeMemoryHeroId(heroId);
		if (string.IsNullOrWhiteSpace(text))
		{
			return false;
		}
		if (_dailyMemoryDrafts != null && _dailyMemoryDrafts.ContainsKey(text))
		{
			return true;
		}
		if (_compressedMemoryBlocks != null && _compressedMemoryBlocks.ContainsKey(text))
		{
			return true;
		}
		if ((_memorySummaryQueue ?? new List<MemorySummaryJob>()).Any((MemorySummaryJob x) => x != null && string.Equals(NormalizeMemoryHeroId(x.HeroId), text, StringComparison.OrdinalIgnoreCase)))
		{
			return true;
		}
		if (_memoryOverviewStates != null && _memoryOverviewStates.ContainsKey(text))
		{
			return true;
		}
		return (_memoryOverviewQueue ?? new List<MemoryOverviewJob>()).Any((MemoryOverviewJob x) => x != null && string.Equals(NormalizeMemoryHeroId(x.HeroId), text, StringComparison.OrdinalIgnoreCase));
	}

